def document_has_v1_applied_sections(document=None) -> bool:
    """Return True when a document has a v1 AppliedSectionSet result."""

    doc = document or (getattr(App, "ActiveDocument", None) if App is not None else None)
    return find_v1_applied_section_set(doc) is not None


def build_document_corridor_model(document=None, *, project=None, corridor_id: str = "corridor:main"):
    """Build a CorridorModel result from the document's v1 AppliedSectionSet."""

    doc = document or (getattr(App, "ActiveDocument", None) if App is not None else None)
    if doc is None:
        raise RuntimeError("No active document.")
    applied_obj = find_v1_applied_section_set(doc)
    applied_section_set = to_applied_section_set(applied_obj)
    if applied_section_set is None:
        raise RuntimeError("A v1 AppliedSectionSet is required before Build Corridor.")
    region_obj = find_v1_region_model(doc)
    return CorridorModelService().build(
        CorridorModelBuildRequest(
            project_id=_project_id(project or find_project(doc)),
            corridor_id=corridor_id,
            applied_section_set=applied_section_set,
            region_model_ref=str(getattr(region_obj, "RegionModelId", "") or ""),
        )
    )


def build_document_corridor_surface_model(
    document=None,
    *,
    project=None,
    corridor_model=None,
    surface_model_id: str = "surface:main",
):
    """Build the first corridor-derived SurfaceModel result from Applied Sections."""

    doc = document or (getattr(App, "ActiveDocument", None) if App is not None else None)
    if doc is None:
        raise RuntimeError("No active document.")
    applied_obj = find_v1_applied_section_set(doc)
    applied_section_set = to_applied_section_set(applied_obj)
    if applied_section_set is None:
        raise RuntimeError("A v1 AppliedSectionSet is required before corridor surfaces.")
    corridor = corridor_model or build_document_corridor_model(doc, project=project)
    transition_model = to_surface_transition_model(find_v1_surface_transition_model(doc))
    return CorridorSurfaceService().build(
        CorridorSurfaceBuildRequest(
            project_id=_project_id(project or find_project(doc)),
            corridor=corridor,
            applied_section_set=applied_section_set,
            surface_model_id=surface_model_id,
            surface_transition_model=transition_model,
        )
    )


def build_document_structure_output_package(
    document=None,
    *,
    project=None,
    corridor_model=None,
    structure_solid_output_id: str = "structure-solids:main",
    quantity_model_id: str = "quantities:structures",
    exchange_output_id: str = "exchange:structure-solids",
    exchange_format: str = "ifc",
    package_kind: str = "structure_geometry",
) -> StructureOutputPackageBuildResult:
    """Build structure solids, derived quantities, and one normalized exchange package."""

    doc = document or (getattr(App, "ActiveDocument", None) if App is not None else None)
    if doc is None:
        raise RuntimeError("No active document.")
    applied_obj = find_v1_applied_section_set(doc)
    applied_section_set = to_applied_section_set(applied_obj)
    if applied_section_set is None:
        raise RuntimeError("A v1 AppliedSectionSet is required before structure outputs.")
    structure_model = to_structure_model(find_v1_structure_model(doc))
    if structure_model is None:
        raise RuntimeError("A v1 StructureModel is required before structure outputs.")

    prj = project or find_project(doc)
    project_id = _project_id(prj)
    corridor = corridor_model or build_document_corridor_model(doc, project=prj)
    structure_solid_output = StructureSolidOutputService().build(
        StructureSolidBuildRequest(
            project_id=project_id,
            corridor=corridor,
            structure_model=structure_model,
            applied_section_set=applied_section_set,
            structure_solid_output_id=structure_solid_output_id,
        )
    )
    quantity_model = QuantityBuildService().build(
        QuantityBuildRequest(
            project_id=project_id,
            corridor=corridor,
            quantity_model_id=quantity_model_id,
            applied_section_set=applied_section_set,
            structure_solid_output=structure_solid_output,
            structure_model=structure_model,
        )
    )
    quantity_output = QuantityOutputMapper().map_quantity_model(quantity_model)
    section_outputs = [
        SectionOutputMapper().map_applied_section(section)
        for section in list(getattr(applied_section_set, "sections", []) or [])
    ]
    exchange_output = ExchangeOutputMapper().map_output_package(
        ExchangePackageRequest(
            project_id=project_id,
            exchange_output_id=exchange_output_id,
            format=exchange_format,
            package_kind=package_kind,
            outputs=[structure_solid_output, quantity_output, *section_outputs],
        )
    )
    return StructureOutputPackageBuildResult(
        corridor_model=corridor,
        structure_solid_output=structure_solid_output,
        quantity_model=quantity_model,
        quantity_output=quantity_output,
        exchange_output=exchange_output,
        section_outputs=section_outputs,
    )


def structure_output_package_summary(result: StructureOutputPackageBuildResult) -> dict[str, object]:
    """Return display-ready counts and ids for a built structure output package."""

    solid_rows = list(getattr(result.structure_solid_output, "solid_rows", []) or [])
    solid_segment_rows = list(getattr(result.structure_solid_output, "solid_segment_rows", []) or [])
    export_diagnostics = list(getattr(result.structure_solid_output, "diagnostic_rows", []) or [])
    quantity_fragments = list(getattr(result.quantity_model, "fragment_rows", []) or [])
    exchange_refs = list(getattr(result.exchange_output, "output_refs", []) or [])
    payload_metadata = getattr(result.exchange_output, "payload_metadata", {}) or {}
    active_structure_refs = sorted(
        {
            str(getattr(row, "structure_id", "") or "")
            for row in solid_rows
            if str(getattr(row, "structure_id", "") or "")
        }
    )
    return {
        "corridor_id": str(getattr(result.corridor_model, "corridor_id", "") or ""),
        "structure_solid_output_id": str(getattr(result.structure_solid_output, "structure_solid_output_id", "") or ""),
        "solid_count": len(solid_rows),
        "active_structure_refs": active_structure_refs,
        "active_structure_count": len(active_structure_refs),
        "solid_segment_count": len(solid_segment_rows),
        "export_readiness_status": _export_readiness_status(export_diagnostics),
        "export_diagnostic_count": len(export_diagnostics),
        "quantity_model_id": str(getattr(result.quantity_model, "quantity_model_id", "") or ""),
        "quantity_fragment_count": len(quantity_fragments),
        "section_output_count": len(list(getattr(result, "section_outputs", []) or [])),
        "source_context_count": int(payload_metadata.get("source_context_count", 0) or 0),
        "side_slope_source_context_count": int(payload_metadata.get("side_slope_source_context_count", 0) or 0),
        "bench_source_context_count": int(payload_metadata.get("bench_source_context_count", 0) or 0),
        "exchange_output_id": str(getattr(result.exchange_output, "exchange_output_id", "") or ""),
        "exchange_format": str(getattr(result.exchange_output, "format", "") or ""),
        "exchange_output_count": len(exchange_refs),
    }


def _export_readiness_status(diagnostics: list[object]) -> str:
    severities = {str(getattr(row, "severity", "") or "").strip().lower() for row in list(diagnostics or [])}
    if "error" in severities:
        return "error"
    if "warning" in severities:
        return "warning"
    return "ready"


def _notify_progress(progress_callback, value: int, text: str) -> None:
    if not callable(progress_callback):
        return
    try:
        progress_callback(value, text)
    except TypeError:
        try:
            progress_callback(value)
        except Exception:
            pass
    except Exception:
        pass


def apply_v1_structure_output_package(*, document=None, project=None, package_result=None):
    """Persist a built structure output package as a v1 ExchangePackage object."""

    doc = document or (getattr(App, "ActiveDocument", None) if App is not None else None)
    if doc is None:
        raise RuntimeError("No active document.")
    prj = project or find_project(doc)
    if package_result is None:
        package_result = build_document_structure_output_package(doc, project=prj)
    obj = create_or_update_v1_exchange_package_object(
        document=doc,
        project=prj,
        package_result=package_result,
    )
    try:
        doc.recompute()
    except Exception:
        pass
    return obj


def export_document_structure_output_package_json(
    path: str,
    *,
    document=None,
    project=None,
    exchange_package=None,
) -> dict[str, object]:
    """Export the current persisted structure exchange package to JSON."""

    doc = document or (getattr(App, "ActiveDocument", None) if App is not None else None)
    if doc is None:
        raise RuntimeError("No active document.")
    package_obj = find_v1_exchange_package(doc, preferred_exchange_package=exchange_package)
    if package_obj is None:
        package_obj = apply_v1_structure_output_package(document=doc, project=project)
    return export_exchange_package_to_json(path, package_obj)


def export_document_structure_output_package_ifc(
    path: str,
    *,
    document=None,
    project=None,
    exchange_package=None,
) -> dict[str, object]:
    """Export the current persisted structure exchange package to IFC4 STEP."""

    doc = document or (getattr(App, "ActiveDocument", None) if App is not None else None)
    if doc is None:
        raise RuntimeError("No active document.")
    package_obj = find_v1_exchange_package(doc, preferred_exchange_package=exchange_package)
    if package_obj is None:
        package_obj = apply_v1_structure_output_package(document=doc, project=project)
    return export_exchange_package_to_ifc(path, package_obj)


def apply_v1_corridor_model(
    *,
    document=None,
    project=None,
    corridor_model=None,
    build_surfaces: bool = True,
    show_daylight_contact_markers: bool = True,
    supplemental_sampling_enabled: bool = True,
    supplemental_sampling_max_spacing: float = SUPPLEMENTAL_SAMPLING_MAX_SPACING,
    supplemental_sampling_tangent_delta_deg: float = SUPPLEMENTAL_FRAME_TANGENT_DELTA_THRESHOLD_DEG,
    supplemental_sampling_chord_deviation: float = SUPPLEMENTAL_FRAME_CHORD_DEVIATION_THRESHOLD,
    progress_callback=None,
):
    """Persist result stages in one transaction and perform one deliberate recompute."""

    doc = document or (getattr(App, "ActiveDocument", None) if App is not None else None)
    if doc is None:
        raise RuntimeError("No active document.")
    with ProjectDocumentAdapter(doc).transaction("Build v1 corridor", recompute=True):
        return _apply_v1_corridor_model_in_transaction(
            document=doc,
            project=project,
            corridor_model=corridor_model,
            build_surfaces=build_surfaces,
            show_daylight_contact_markers=show_daylight_contact_markers,
            supplemental_sampling_enabled=supplemental_sampling_enabled,
            supplemental_sampling_max_spacing=supplemental_sampling_max_spacing,
            supplemental_sampling_tangent_delta_deg=supplemental_sampling_tangent_delta_deg,
            supplemental_sampling_chord_deviation=supplemental_sampling_chord_deviation,
            progress_callback=progress_callback,
        )


def _apply_v1_corridor_model_in_transaction(
    *,
    document=None,
    project=None,
    corridor_model=None,
    build_surfaces: bool = True,
    show_daylight_contact_markers: bool = True,
    supplemental_sampling_enabled: bool = True,
    supplemental_sampling_max_spacing: float = SUPPLEMENTAL_SAMPLING_MAX_SPACING,
    supplemental_sampling_tangent_delta_deg: float = SUPPLEMENTAL_FRAME_TANGENT_DELTA_THRESHOLD_DEG,
    supplemental_sampling_chord_deviation: float = SUPPLEMENTAL_FRAME_CHORD_DEVIATION_THRESHOLD,
    progress_callback=None,
):
    """Persist a v1 CorridorModel result object."""

    doc = document or (getattr(App, "ActiveDocument", None) if App is not None else None)
    if doc is None:
        raise RuntimeError("No active document.")
    _notify_progress(progress_callback, 40, "Preparing project tree...")
    prj = project or find_project(doc)
    if prj is None:
        try:
            prj = doc.addObject("App::DocumentObjectGroupPython", "CorridorRoadProject")
        except Exception:
            prj = doc.addObject("App::FeaturePython", "CorridorRoadProject")
        CorridorRoadProject(prj)
        prj.Label = "Parametric Road Project"
    ensure_project_properties(prj)
    ensure_project_tree(prj, include_references=False)
    if corridor_model is None:
        _notify_progress(progress_callback, 45, "Building model...")
        corridor_model = build_document_corridor_model(doc, project=prj)
    surface_model = None
    if build_surfaces:
        _notify_progress(progress_callback, 50, "Building corridor surfaces...")
        surface_model = build_document_corridor_surface_model(doc, project=prj, corridor_model=corridor_model)
        corridor_model.surface_build_refs = [str(getattr(surface_model, "surface_model_id", "") or "surface:main")]
    _notify_progress(progress_callback, 65, "Writing CorridorModel object...")
    obj = _persist_incremental_corridor_model(doc, prj, corridor_model)
    if surface_model is not None:
        _notify_progress(progress_callback, 70, "Writing SurfaceModel object...")
        _persist_incremental_surface_model(doc, prj, surface_model)
        _notify_progress(progress_callback, 74, "Creating centerline preview...")
        create_corridor_centerline_3d_preview(
            document=doc,
            project=prj,
            corridor_model=corridor_model,
            applied_section_set_ref=str(getattr(corridor_model, "applied_section_set_ref", "") or ""),
            supplemental_sampling_max_spacing=supplemental_sampling_max_spacing,
            supplemental_sampling_tangent_delta_deg=supplemental_sampling_tangent_delta_deg,
            supplemental_sampling_chord_deviation=supplemental_sampling_chord_deviation,
        )
        _notify_progress(progress_callback, 78, "Creating design surface preview...")
        create_corridor_design_surface_preview(
            document=doc,
            project=prj,
            corridor_model=corridor_model,
            surface_model=surface_model,
            supplemental_sampling_enabled=supplemental_sampling_enabled,
            supplemental_sampling_max_spacing=supplemental_sampling_max_spacing,
            supplemental_sampling_tangent_delta_deg=supplemental_sampling_tangent_delta_deg,
            supplemental_sampling_chord_deviation=supplemental_sampling_chord_deviation,
        )
        _notify_progress(progress_callback, 80, "Creating Region surface objects...")
        create_corridor_region_surface_previews(
            document=doc,
            project=prj,
            corridor_model=corridor_model,
            surface_model=surface_model,
            supplemental_sampling_enabled=supplemental_sampling_enabled,
            supplemental_sampling_max_spacing=supplemental_sampling_max_spacing,
            supplemental_sampling_tangent_delta_deg=supplemental_sampling_tangent_delta_deg,
            supplemental_sampling_chord_deviation=supplemental_sampling_chord_deviation,
        )
        _notify_progress(progress_callback, 81, "Creating intersection surface preview...")
        create_corridor_intersection_surface_preview(
            document=doc,
            project=prj,
            corridor_model=corridor_model,
            surface_model=surface_model,
        )
        _notify_progress(progress_callback, 82, "Creating subgrade surface preview...")
        create_corridor_subgrade_surface_preview(
            document=doc,
            project=prj,
            corridor_model=corridor_model,
            surface_model=surface_model,
            supplemental_sampling_enabled=supplemental_sampling_enabled,
            supplemental_sampling_max_spacing=supplemental_sampling_max_spacing,
            supplemental_sampling_tangent_delta_deg=supplemental_sampling_tangent_delta_deg,
            supplemental_sampling_chord_deviation=supplemental_sampling_chord_deviation,
        )
        _notify_progress(progress_callback, 86, "Creating slope face preview...")
        create_corridor_daylight_surface_preview(
            document=doc,
            project=prj,
            corridor_model=corridor_model,
            surface_model=surface_model,
            show_daylight_contact_markers=show_daylight_contact_markers,
            supplemental_sampling_enabled=supplemental_sampling_enabled,
            supplemental_sampling_max_spacing=supplemental_sampling_max_spacing,
            supplemental_sampling_tangent_delta_deg=supplemental_sampling_tangent_delta_deg,
            supplemental_sampling_chord_deviation=supplemental_sampling_chord_deviation,
        )
        _notify_progress(progress_callback, 90, "Creating drainage preview...")
        create_corridor_drainage_surface_preview(
            document=doc,
            project=prj,
            corridor_model=corridor_model,
            surface_model=surface_model,
            supplemental_sampling_enabled=supplemental_sampling_enabled,
            supplemental_sampling_max_spacing=supplemental_sampling_max_spacing,
            supplemental_sampling_tangent_delta_deg=supplemental_sampling_tangent_delta_deg,
            supplemental_sampling_chord_deviation=supplemental_sampling_chord_deviation,
        )
        _notify_progress(progress_callback, 91, "Creating Subassembly kind review objects...")
        create_corridor_subassembly_kind_review_previews(
            document=doc,
            project=prj,
        )
        _notify_progress(progress_callback, 92, "Creating transition span markers...")
        create_corridor_surface_transition_span_markers(
            document=doc,
            project=prj,
            corridor_model=corridor_model,
            surface_model=surface_model,
        )
    _notify_progress(progress_callback, 94, "Finalizing document transaction...")
    return obj


def _persist_incremental_corridor_model(document, project, corridor_model):
    existing = find_v1_corridor_model(document)
    previous_model = to_corridor_model(existing) if existing is not None else None
    previous_record = read_incremental_record(existing) if existing is not None else None
    service = IncrementalRebuildService()
    decision = service.decide(
        stage_name="corridor_model",
        service_version="corridor-model-persistence:1",
        engineering_input=corridor_model,
        previous_record=previous_record,
    )
    execution = service.execute(
        decision=decision,
        service_version="corridor-model-persistence:1",
        builder=lambda: corridor_model,
        previous_result=previous_model,
        previous_record=previous_record,
        consumed_source_refs=tuple(getattr(corridor_model, "source_refs", ()) or ()),
        consumed_result_refs=(str(getattr(corridor_model, "applied_section_set_ref", "") or ""),),
    )
    if decision.reuse_previous:
        return existing
    obj = create_or_update_v1_corridor_model_object(document=document, project=project, corridor_model=execution.result)
    write_incremental_record(obj, execution.record)
    return obj


def _persist_incremental_surface_model(document, project, surface_model):
    existing = find_v1_surface_model(document)
    previous_model = to_surface_model(existing) if existing is not None else None
    previous_record = read_incremental_record(existing) if existing is not None else None
    service = IncrementalRebuildService()
    decision = service.decide(
        stage_name="surface_model",
        service_version="surface-model-persistence:1",
        engineering_input=surface_model,
        previous_record=previous_record,
    )
    execution = service.execute(
        decision=decision,
        service_version="surface-model-persistence:1",
        builder=lambda: surface_model,
        previous_result=previous_model,
        previous_record=previous_record,
        consumed_source_refs=tuple(getattr(surface_model, "source_refs", ()) or ()),
        consumed_result_refs=(str(getattr(surface_model, "corridor_id", "") or ""),),
    )
    if decision.reuse_previous:
        return existing
    obj = create_or_update_v1_surface_model_object(document=document, project=project, surface_model=execution.result)
    write_incremental_record(obj, execution.record)
    return obj


def corridor_build_review_rows(document=None) -> list[dict[str, object]]:
    """Return display-ready Build Corridor result rows from document preview objects."""

    doc = document or (getattr(App, "ActiveDocument", None) if App is not None else None)
    applied_summary = corridor_applied_sections_review_summary(doc)
    rows: list[dict[str, object]] = []
    intersection_preview = _corridor_build_preview_object(doc, "intersection") if doc is not None else None
    is_roundabout_preview = (
        str(getattr(intersection_preview, "IntersectionKind", "") or "").strip().lower() == "roundabout"
    )
    for role, title, object_name in CORRIDOR_BUILD_REVIEW_OBJECTS:
        if is_roundabout_preview and role == "intersection_tie_slope":
            continue
        obj = doc.getObject(object_name) if doc is not None else None
        diagnostic = _corridor_build_preview_diagnostic_object(doc, role)
        row = _corridor_build_review_row(role, title, object_name, obj, diagnostic=diagnostic, document=doc)
        row = _with_subassembly_surface_role_review_note(row, doc)
        rows.append(
            _with_applied_section_review_summary(
                row,
                applied_summary,
            )
        )
        if role == "intersection_slope":
            upper_panel_row = _corridor_intersection_upper_slope_face_panel_review_row(doc)
            if upper_panel_row is not None:
                rows.append(
                    _with_applied_section_review_summary(
                        upper_panel_row,
                        applied_summary,
                    )
                )
        if role == "intersection":
            readiness_row = _corridor_intersection_surface_replacement_readiness_row(doc)
            if readiness_row is not None:
                rows.append(
                    _with_applied_section_review_summary(
                        readiness_row,
                        applied_summary,
                    )
                )
            tie_in_row = _corridor_intersection_tie_in_continuity_row(doc)
            if tie_in_row is not None:
                rows.append(
                    _with_applied_section_review_summary(
                        tie_in_row,
                        applied_summary,
                    )
                )
            grading_row = _corridor_intersection_grading_ownership_row(doc)
            if grading_row is not None:
                rows.append(
                    _with_applied_section_review_summary(
                        grading_row,
                        applied_summary,
                    )
                )
            drainage_handoff_row = _corridor_intersection_drainage_handoff_gate_row(doc)
            if drainage_handoff_row is not None:
                rows.append(
                    _with_applied_section_review_summary(
                        drainage_handoff_row,
                        applied_summary,
                    )
                )
            for roundabout_row in _corridor_roundabout_build_review_rows(doc):
                rows.append(
                    _with_applied_section_review_summary(
                        roundabout_row,
                        applied_summary,
                    )
                )
    return rows


def _corridor_roundabout_build_review_rows(document=None) -> list[dict[str, object]]:
    """Return roundabout-specific Results tab rows from generated output contracts."""

    doc = document or (getattr(App, "ActiveDocument", None) if App is not None else None)
    if doc is None:
        return []
    intersection_obj = _corridor_build_preview_object(doc, "intersection")
    if str(getattr(intersection_obj, "IntersectionKind", "") or "").strip().lower() != "roundabout":
        return []
    rows: list[dict[str, object]] = []

    rows.append(
        _corridor_roundabout_review_row(
            role="roundabout_circulatory",
            title="Roundabout Circulatory Surface",
            object_name="V1CorridorIntersectionSurfacePreview",
            obj=intersection_obj,
            notes=_join_review_notes(
                "roundabout annular circulatory surface",
                f"boundary={getattr(intersection_obj, 'PatchSurfaceBoundaryStrategy', '')}",
                f"triangulation={getattr(intersection_obj, 'PatchTriangulationMode', '')}",
            ),
        )
    )
    connector_obj = None
    apron_obj = doc.getObject("V1CorridorRoundaboutApronSurfacePreview")
    if apron_obj is not None:
        rows.append(
            _corridor_roundabout_review_row(
                role="roundabout_apron",
                title="Roundabout Apron Surface",
                object_name="V1CorridorRoundaboutApronSurfacePreview",
                obj=apron_obj,
                notes=_join_review_notes(
                    "roundabout annular apron surface",
                    f"boundary={getattr(apron_obj, 'PatchSurfaceBoundaryStrategy', '')}",
                    f"triangulation={getattr(apron_obj, 'PatchTriangulationMode', '')}",
                ),
            )
        )
    subgrade_obj = doc.getObject("V1CorridorRoundaboutSubgradeSurfacePreview")
    if subgrade_obj is not None:
        rows.append(
            _corridor_roundabout_review_row(
                role="roundabout_subgrade",
                title="Roundabout Subgrade Surface",
                object_name="V1CorridorRoundaboutSubgradeSurfacePreview",
                obj=subgrade_obj,
                notes=_join_review_notes(
                    "roundabout dedicated subgrade surface",
                    f"boundary={getattr(subgrade_obj, 'PatchSurfaceBoundaryStrategy', '')}",
                    f"triangulation={getattr(subgrade_obj, 'PatchTriangulationMode', '')}",
                ),
            )
        )
    slope_face_obj = doc.getObject("V1CorridorRoundaboutSlopeFaceSurfacePreview")
    breakline_status = "ready"
    if any(
        int(getattr(candidate, "SharedBreaklineGeometryMismatchCount", 0) or 0)
        or int(getattr(candidate, "SharedBreaklineMeshMismatchCount", 0) or 0)
        or int(getattr(candidate, "SharedBreaklineMissingConsumerCount", 0) or 0)
        for candidate in (connector_obj, apron_obj, subgrade_obj, slope_face_obj)
        if candidate is not None
    ):
        breakline_status = "warning"
    if apron_obj is None or subgrade_obj is None or slope_face_obj is None:
        breakline_status = "missing"
    rows.append(
        {
            "role": "roundabout_breakline_readiness",
            "result": "Roundabout Breakline Readiness",
            "object_name": str(getattr(slope_face_obj, "Name", "") or ""),
            "object_label": str(getattr(slope_face_obj, "Label", "") or ""),
            "status": breakline_status,
            "vertex_count": "",
            "triangle_or_point_count": "",
            "output_path": "roundabout_shared_breakline_contract",
            "notes": _join_review_notes(
                f"apron={getattr(apron_obj, 'SharedBreaklineAuditStatus', '')}" if apron_obj is not None else "apron=missing",
                f"subgrade={getattr(subgrade_obj, 'SharedBreaklineAuditStatus', '')}" if subgrade_obj is not None else "subgrade=missing",
                f"slope_face={getattr(slope_face_obj, 'SharedBreaklineAuditStatus', '')}" if slope_face_obj is not None else "slope_face=missing",
                "entry/exit connector, splitter-island, transitional entry/exit, and generic tie-slope outputs are disabled for roundabout generalization",
                "Recommended Action: Review roundabout source policy and rebuild if any roundabout output is missing.",
            ),
        }
    )
    return rows


def _corridor_roundabout_review_row(
    *,
    role: str,
    title: str,
    object_name: str,
    obj,
    notes: str,
) -> dict[str, object]:
    vertex_count = int(getattr(obj, "VertexCount", 0) or 0) if obj is not None else 0
    triangle_count = int(getattr(obj, "TriangleCount", 0) or 0) if obj is not None else 0
    status = "ready" if vertex_count > 0 and triangle_count > 0 else "missing"
    return {
        "role": role,
        "result": title,
        "object_name": str(getattr(obj, "Name", "") or object_name),
        "object_label": str(getattr(obj, "Label", "") or ""),
        "status": status,
        "vertex_count": vertex_count if obj is not None else "",
        "triangle_or_point_count": triangle_count if obj is not None else "",
        "output_path": "roundabout_output_contract" if obj is not None else "",
        "notes": notes or ("Roundabout output has not been built yet." if obj is None else ""),
    }


def corridor_shared_breakline_audit_rows(document=None) -> list[dict[str, object]]:
    """Return panel-friendly shared breakline audit rows from built preview objects."""

    doc = document or (getattr(App, "ActiveDocument", None) if App is not None else None)
    if doc is None:
        return []
    rows: list[dict[str, object]] = []
    for role, title, object_name in CORRIDOR_BUILD_REVIEW_OBJECTS:
        obj = _corridor_build_preview_object(doc, role)
        if obj is None:
            continue
        result_id = str(getattr(obj, "SharedBreaklineResultId", "") or "")
        audit_status = str(getattr(obj, "SharedBreaklineAuditStatus", "") or "")
        has_roundabout_clip_boundary = bool(
            str(getattr(obj, "RoundaboutClipBoundaryStatus", "") or "")
            or str(getattr(obj, "RoundaboutClipBoundaryRole", "") or "")
        )
        if not result_id and not audit_status and not has_roundabout_clip_boundary:
            continue
        geometry_match = int(getattr(obj, "SharedBreaklineGeometryMatchCount", 0) or 0)
        geometry_mismatch = int(getattr(obj, "SharedBreaklineGeometryMismatchCount", 0) or 0)
        mesh_match = int(getattr(obj, "SharedBreaklineMeshMatchCount", 0) or 0)
        mesh_mismatch = int(getattr(obj, "SharedBreaklineMeshMismatchCount", 0) or 0)
        missing = int(getattr(obj, "SharedBreaklineMissingConsumerCount", 0) or 0)
        mismatch = int(getattr(obj, "SharedBreaklineMismatchCount", 0) or 0)
        reversed_count = int(getattr(obj, "SharedBreaklineReversedEdgeCount", 0) or 0)
        consumed = int(getattr(obj, "SharedBreaklineConsumedCount", 0) or 0)
        total = int(getattr(obj, "SharedBreaklineCount", 0) or 0)
        boundary_loop_ref_count = int(getattr(obj, "SharedBreaklineBoundaryLoopRefCount", 0) or 0)
        boundary_loop_constraint_segments = int(getattr(obj, "SharedBreaklineBoundaryLoopConstraintSegmentCount", 0) or 0)
        boundary_loop_constraint_edges = int(getattr(obj, "SharedBreaklineBoundaryLoopConstraintEdgeCount", 0) or 0)
        boundary_loop_constraint_refs = [
            str(value or "")
            for value in list(getattr(obj, "SharedBreaklineBoundaryLoopConstraintRefs", []) or [])
            if str(value or "")
        ]
        boundary_loop_constraint_role_summary = str(
            getattr(obj, "SharedBreaklineBoundaryLoopConstraintRoleSummary", "") or ""
        )
        boundary_loop_ownership_status = str(getattr(obj, "IntersectionBoundaryLoopOwnershipStatus", "") or "")
        boundary_loop_ownership_notes = str(getattr(obj, "IntersectionBoundaryLoopOwnershipNotes", "") or "")
        exclusion_tested_triangles = int(getattr(obj, "IntersectionExclusionTestedTriangleCount", 0) or 0)
        exclusion_clipped_triangles = int(getattr(obj, "IntersectionExclusionClippedTriangleCount", 0) or 0)
        exclusion_boundary_crossings = int(getattr(obj, "IntersectionExclusionBoundaryCrossingTriangleCount", 0) or 0)
        exclusion_near_boundary_kept = int(getattr(obj, "IntersectionExclusionNearBoundaryKeptTriangleCount", 0) or 0)
        exclusion_max_kept_boundary_distance = float(getattr(obj, "IntersectionExclusionMaxKeptBoundaryDistance", 0.0) or 0.0)
        exclusion_clip_ratio = float(getattr(obj, "IntersectionExclusionClipRatio", 0.0) or 0.0)
        boundary_loop_near_kept_warning = _boundary_loop_near_kept_warning(
            role,
            near_kept_count=exclusion_near_boundary_kept,
            tested_triangle_count=exclusion_tested_triangles,
        )
        cell_count = int(getattr(obj, "IntersectionSlopeFaceCellCount", 0) or 0)
        cell_ready = int(getattr(obj, "IntersectionSlopeFaceCellReadyCount", 0) or 0)
        cell_open = int(getattr(obj, "IntersectionSlopeFaceCellOpenCount", 0) or 0)
        cell_missing_edge = int(getattr(obj, "IntersectionSlopeFaceCellMissingEdgeCount", 0) or 0)
        cell_triangles = int(getattr(obj, "IntersectionSlopeFaceCellTriangleCount", 0) or 0)
        graph_status = str(getattr(obj, "IntersectionSharedBoundaryGraphStatus", "") or "")
        graph_nodes = int(getattr(obj, "IntersectionSharedBoundaryGraphNodeCount", 0) or 0)
        graph_edges = int(getattr(obj, "IntersectionSharedBoundaryGraphEdgeCount", 0) or 0)
        graph_cells = int(getattr(obj, "IntersectionSharedBoundaryGraphCellCount", 0) or 0)
        graph_consumed_edges = int(getattr(obj, "IntersectionSharedBoundaryGraphConsumedEdgeCount", 0) or 0)
        graph_duplicate_edges = int(getattr(obj, "IntersectionSharedBoundaryGraphDuplicateEdgeCount", 0) or 0)
        graph_missing_consumers = int(getattr(obj, "IntersectionSharedBoundaryGraphMissingConsumerCount", 0) or 0)
        graph_source_segment_splits = int(getattr(obj, "IntersectionSharedBoundaryGraphSourceSegmentSplitCount", 0) or 0)
        graph_open_cells = int(getattr(obj, "IntersectionSharedBoundaryGraphOpenCellCount", 0) or 0)
        graph_not_snapped = int(getattr(obj, "IntersectionSharedBoundaryGraphNotSnappedCount", 0) or 0)
        graph_endpoint_mismatches = int(getattr(obj, "IntersectionSharedBoundaryGraphEndpointMismatchCount", 0) or 0)
        transition_qa_status = str(getattr(obj, "IntersectionBoundaryLoopTransitionQAStatus", "") or "")
        transition_qa_notes = str(getattr(obj, "IntersectionBoundaryLoopTransitionQANotes", "") or "")
        roundabout_clip_boundary_status = str(getattr(obj, "RoundaboutClipBoundaryStatus", "") or "")
        roundabout_clip_boundary_role = str(getattr(obj, "RoundaboutClipBoundaryRole", "") or "")
        raw_roundabout_actual_clip_roles = getattr(obj, "RoundaboutActualClipBoundaryRoles", "")
        if isinstance(raw_roundabout_actual_clip_roles, str):
            roundabout_actual_clip_boundary_roles = [
                value.strip()
                for value in raw_roundabout_actual_clip_roles.split(",")
                if value.strip()
            ]
        else:
            roundabout_actual_clip_boundary_roles = [
                str(value or "").strip()
                for value in list(raw_roundabout_actual_clip_roles or [])
                if str(value or "").strip()
            ]
        roundabout_clip_boundary_result_id = str(getattr(obj, "RoundaboutClipBoundaryResultId", "") or "")
        roundabout_clip_mode = str(getattr(obj, "RoundaboutOwnershipClipMode", "") or "")
        roundabout_clip_reason_summary = str(getattr(obj, "RoundaboutOwnershipClipReasonSummary", "") or "")
        roundabout_clip_boundary_loop_count = int(getattr(obj, "RoundaboutClipBoundaryLoopCount", 0) or 0)
        roundabout_clip_boundary_segment_count = int(getattr(obj, "RoundaboutClipBoundarySegmentCount", 0) or 0)
        roundabout_clip_boundary_approach_leg_count = int(getattr(obj, "RoundaboutClipBoundaryApproachLegCount", 0) or 0)
        roundabout_clip_boundary_approach_leg_roles = [
            str(value or "")
            for value in list(getattr(obj, "RoundaboutClipBoundaryApproachLegRoles", []) or [])
            if str(value or "")
        ]
        roundabout_clip_boundary_approach_leg_source = str(getattr(obj, "RoundaboutClipBoundaryApproachLegSource", "") or "")
        roundabout_clip_boundary_loop_refs = [
            str(value or "")
            for value in list(getattr(obj, "RoundaboutClipBoundaryLoopRefs", []) or [])
            if str(value or "")
        ]
        roundabout_clip_boundary_segment_refs = [
            str(value or "")
            for value in list(getattr(obj, "RoundaboutClipBoundarySegmentRefs", []) or [])
            if str(value or "")
        ]
        roundabout_clip_boundary_diagnostics = [
            str(value or "")
            for value in list(getattr(obj, "RoundaboutClipBoundaryDiagnostics", []) or [])
            if str(value or "")
        ]
        cell_audit_rows = [
            str(value or "")
            for value in list(getattr(obj, "IntersectionSlopeFaceCellAuditRows", []) or [])
            if str(value or "")
        ]
        graph_audit_rows = [
            str(value or "")
            for value in list(getattr(obj, "IntersectionSharedBoundaryGraphAuditRows", []) or [])
            if str(value or "")
        ]
        graph_refs = [
            str(value or "")
            for value in list(getattr(obj, "IntersectionSharedBoundaryGraphRefs", []) or [])
            if str(value or "")
        ]
        notes = "; ".join(str(value or "") for value in list(getattr(obj, "SharedBreaklineAuditNotes", []) or []) if str(value or ""))
        if not notes:
            notes = str(getattr(obj, "SharedBreaklineAuditSummary", "") or "")
        if cell_count or cell_open or cell_missing_edge:
            cell_note = (
                f"cell_audit=count={cell_count}; ready={cell_ready}; open={cell_open}; "
                f"missing_edge={cell_missing_edge}; triangles={cell_triangles}"
            )
            notes = _join_review_notes(notes, cell_note)
        if graph_status or graph_nodes or graph_edges or graph_cells:
            graph_note = (
                f"shared_boundary_graph=status={graph_status or 'missing'}; nodes={graph_nodes}; "
                f"edges={graph_edges}; consumed_edges={graph_consumed_edges}; cells={graph_cells}; duplicate_edges={graph_duplicate_edges}; "
                f"missing_consumers={graph_missing_consumers}; source_segment_splits={graph_source_segment_splits}; open_cells={graph_open_cells}; "
                f"endpoint_mismatches={graph_endpoint_mismatches}; not_snapped={graph_not_snapped}"
            )
            notes = _join_review_notes(notes, graph_note)
        if boundary_loop_ref_count or boundary_loop_constraint_segments or boundary_loop_constraint_edges:
            notes = _join_review_notes(
                notes,
                (
                    "boundary_loop_handoff="
                    f"refs={boundary_loop_ref_count}; "
                    f"constraint_segments={boundary_loop_constraint_segments}; "
                    f"constraint_edges={boundary_loop_constraint_edges}"
                ),
            )
            if boundary_loop_constraint_role_summary:
                notes = _join_review_notes(
                    notes,
                    f"boundary_loop_constraint_roles={boundary_loop_constraint_role_summary}",
                )
        if boundary_loop_ownership_status:
            notes = _join_review_notes(
                notes,
                f"boundary_loop_ownership={boundary_loop_ownership_status}; {boundary_loop_ownership_notes}",
            )
        if boundary_loop_near_kept_warning:
            notes = _join_review_notes(
                notes,
                (
                    "boundary_loop_near_kept_warning="
                    f"near_kept={exclusion_near_boundary_kept}; "
                    f"tested={exclusion_tested_triangles}; "
                    f"threshold={_boundary_loop_near_kept_warning_threshold(exclusion_tested_triangles)}"
                ),
            )
        if transition_qa_status:
            notes = _join_review_notes(
                notes,
                f"boundary_loop_transition_qa={transition_qa_status}; {transition_qa_notes}",
            )
        if roundabout_clip_boundary_role or roundabout_clip_boundary_status:
            notes = _join_review_notes(
                notes,
                (
                    "roundabout_clip_boundary="
                    f"{roundabout_clip_boundary_role or 'missing'}:{roundabout_clip_boundary_status or 'missing'}; "
                    f"loops={roundabout_clip_boundary_loop_count}; "
                    f"segments={roundabout_clip_boundary_segment_count}; "
                    f"approach_legs={roundabout_clip_boundary_approach_leg_count}; "
                    f"approach_roles={','.join(roundabout_clip_boundary_approach_leg_roles) if roundabout_clip_boundary_approach_leg_roles else 'none'}; "
                    f"mode={roundabout_clip_mode or 'missing'}; "
                    f"actual_clip_roles={','.join(roundabout_actual_clip_boundary_roles) if roundabout_actual_clip_boundary_roles else 'none'}; "
                    f"reasons={roundabout_clip_reason_summary or 'none'}; "
                    f"diagnostics={','.join(roundabout_clip_boundary_diagnostics) if roundabout_clip_boundary_diagnostics else 'none'}"
                ),
            )
        status = _normalize_corridor_build_review_status(audit_status or str(getattr(obj, "SharedBreaklineStatus", "") or "missing"), default="missing")
        substantive_warning = bool(
            geometry_mismatch
            or mesh_mismatch
            or missing
            or mismatch
            or reversed_count
            or cell_open
            or cell_missing_edge
            or graph_duplicate_edges
            or graph_missing_consumers
            or graph_source_segment_splits
            or graph_open_cells
            or graph_not_snapped
            or graph_endpoint_mismatches
        )
        if substantive_warning:
            status = "warning"
        if boundary_loop_ref_count and not boundary_loop_constraint_edges:
            substantive_warning = True
            status = "warning"
        if boundary_loop_near_kept_warning:
            substantive_warning = True
            status = "warning"
        if not substantive_warning and status == "warning":
            status = "ready"
        action = _shared_breakline_recommended_action(
            geometry_mismatch_count=geometry_mismatch,
            mesh_mismatch_count=mesh_mismatch,
            missing_consumer_count=missing,
            mismatch_count=mismatch,
            reversed_edge_count=reversed_count,
            cell_open_count=cell_open,
            cell_missing_edge_count=cell_missing_edge,
            graph_duplicate_edge_count=graph_duplicate_edges,
            graph_missing_consumer_count=graph_missing_consumers,
            graph_source_segment_split_count=graph_source_segment_splits,
            graph_open_cell_count=graph_open_cells,
            graph_not_snapped_count=graph_not_snapped,
            graph_endpoint_mismatch_count=graph_endpoint_mismatches,
            graph_foreign_edge_count=0,
            graph_pair_missing_count=0,
            notes=notes,
        )
        rows.append(
            {
                "role": role,
                "surface": title,
                "object_name": str(getattr(obj, "Name", "") or object_name),
                "object_label": str(getattr(obj, "Label", "") or object_name),
                "status": status,
                "result_id": result_id,
                "material_summary": str(getattr(obj, "SharedBreaklineMaterialSummary", "") or ""),
                "role_summary": str(getattr(obj, "SharedBreaklineRoleSummary", "") or ""),
                "consumed": consumed,
                "total": total,
                "geometry_match_count": geometry_match,
                "geometry_mismatch_count": geometry_mismatch,
                "mesh_match_count": mesh_match,
                "mesh_mismatch_count": mesh_mismatch,
                "missing_consumer_count": missing,
                "mismatch_count": mismatch,
                "reversed_edge_count": reversed_count,
                "boundary_loop_ref_count": boundary_loop_ref_count,
                "boundary_loop_constraint_segment_count": boundary_loop_constraint_segments,
                "boundary_loop_constraint_edge_count": boundary_loop_constraint_edges,
                "boundary_loop_constraint_refs": boundary_loop_constraint_refs,
                "boundary_loop_ownership_status": boundary_loop_ownership_status,
                "boundary_loop_ownership_notes": boundary_loop_ownership_notes,
                "roundabout_clip_boundary_status": roundabout_clip_boundary_status,
                "roundabout_clip_boundary_role": roundabout_clip_boundary_role,
                "roundabout_actual_clip_boundary_roles": roundabout_actual_clip_boundary_roles,
                "roundabout_clip_boundary_result_id": roundabout_clip_boundary_result_id,
                "roundabout_clip_mode": roundabout_clip_mode,
                "roundabout_clip_reason_summary": roundabout_clip_reason_summary,
                "roundabout_clip_boundary_loop_count": roundabout_clip_boundary_loop_count,
                "roundabout_clip_boundary_segment_count": roundabout_clip_boundary_segment_count,
                "roundabout_clip_boundary_approach_leg_count": roundabout_clip_boundary_approach_leg_count,
                "roundabout_clip_boundary_approach_leg_roles": roundabout_clip_boundary_approach_leg_roles,
                "roundabout_clip_boundary_approach_leg_source": roundabout_clip_boundary_approach_leg_source,
                "roundabout_clip_boundary_loop_refs": roundabout_clip_boundary_loop_refs,
                "roundabout_clip_boundary_segment_refs": roundabout_clip_boundary_segment_refs,
                "roundabout_clip_boundary_diagnostics": roundabout_clip_boundary_diagnostics,
                "intersection_exclusion_tested_triangle_count": exclusion_tested_triangles,
                "intersection_exclusion_clipped_triangle_count": exclusion_clipped_triangles,
                "intersection_exclusion_boundary_crossing_triangle_count": exclusion_boundary_crossings,
                "intersection_exclusion_near_boundary_kept_triangle_count": exclusion_near_boundary_kept,
                "intersection_exclusion_max_kept_boundary_distance": exclusion_max_kept_boundary_distance,
                "intersection_exclusion_clip_ratio": exclusion_clip_ratio,
                "boundary_loop_near_kept_warning": boundary_loop_near_kept_warning,
                "cell_count": cell_count,
                "cell_ready_count": cell_ready,
                "cell_open_count": cell_open,
                "cell_missing_edge_count": cell_missing_edge,
                "cell_triangle_count": cell_triangles,
                "cell_audit_rows": cell_audit_rows,
                "graph_status": graph_status,
                "graph_node_count": graph_nodes,
                "graph_edge_count": graph_edges,
                "graph_consumed_edge_count": graph_consumed_edges,
                "graph_cell_count": graph_cells,
                "graph_duplicate_edge_count": graph_duplicate_edges,
                "graph_missing_consumer_count": graph_missing_consumers,
                "graph_source_segment_split_count": graph_source_segment_splits,
                "graph_open_cell_count": graph_open_cells,
                "graph_not_snapped_count": graph_not_snapped,
                "graph_endpoint_mismatch_count": graph_endpoint_mismatches,
                "graph_audit_rows": graph_audit_rows,
                "graph_refs": graph_refs,
                "graph_foreign_edge_count": 0,
                "graph_foreign_edge_notes": "",
                "graph_pair_match_count": 0,
                "graph_pair_missing_count": 0,
                "graph_pair_notes": "",
                "solid_readiness_status": str(getattr(obj, "SharedBreaklineSolidReadinessStatus", "") or ""),
                "solid_open_end_count": int(getattr(obj, "SharedBreaklineSolidOpenEndCount", 0) or 0),
                "solid_duplicate_edge_count": int(getattr(obj, "SharedBreaklineSolidDuplicateEdgeCount", 0) or 0),
                "solid_non_manifold_node_count": int(getattr(obj, "SharedBreaklineSolidNonManifoldNodeCount", 0) or 0),
                "recommended_action": action,
                "notes": notes,
            }
        )
    return _shared_boundary_graph_pair_audit_rows(_shared_boundary_graph_consumer_audit_rows(rows))


def _shared_boundary_graph_pair_audit_rows(rows: list[dict[str, object]]) -> list[dict[str, object]]:
    """Mark whether adjacent surfaces consume the same canonical graph edge ids."""

    if not rows:
        return []
    rows_by_role = {str(row.get("role", "") or ""): row for row in rows}
    role_edge_ids: dict[str, set[str]] = {}
    for row in rows:
        for raw in list(row.get("graph_audit_rows", []) or []):
            parsed = _parse_intersection_shared_boundary_graph_audit_row(raw)
            if not parsed or str(parsed.get("row_kind", "") or "") != "edge":
                continue
            role = str(parsed.get("role", "") or "")
            edge_id = str(parsed.get("row_id", "") or "")
            if role and edge_id:
                role_edge_ids.setdefault(role, set()).add(edge_id)
    expected_pairs = (
        ("patch_to_design_surface", "intersection", "design"),
        ("patch_to_intersection_slope_face", "intersection", "intersection_slope"),
        ("curb_return_to_intersection_slope_face", "intersection", "intersection_slope"),
        ("intersection_slope_face_to_design_surface", "design", "intersection_slope"),
        ("intersection_slope_face_to_corridor_slope_face", "daylight", "intersection_slope"),
        ("main_road_tie", "intersection", "intersection_slope"),
    )
    pair_notes_by_role: dict[str, list[str]] = {}
    pair_match_by_role: dict[str, int] = {}
    pair_missing_by_role: dict[str, int] = {}
    for edge_role, first_role, second_role in expected_pairs:
        first = rows_by_role.get(first_role)
        second = rows_by_role.get(second_role)
        edge_ids = role_edge_ids.get(edge_role, set())
        if first is None or second is None or not edge_ids:
            continue
        first_refs = {str(value or "") for value in list(first.get("graph_refs", []) or []) if str(value or "")}
        second_refs = {str(value or "") for value in list(second.get("graph_refs", []) or []) if str(value or "")}
        shared = edge_ids.intersection(first_refs).intersection(second_refs)
        target_roles = (first_role, second_role)
        if shared:
            for role in target_roles:
                pair_match_by_role[role] = int(pair_match_by_role.get(role, 0) or 0) + len(shared)
                pair_notes_by_role.setdefault(role, []).append(f"pair_match:{edge_role}:{first_role}<->{second_role}:{len(shared)}")
        else:
            for role in target_roles:
                pair_missing_by_role[role] = int(pair_missing_by_role.get(role, 0) or 0) + 1
                pair_notes_by_role.setdefault(role, []).append(f"pair_missing:{edge_role}:{first_role}<->{second_role}")
    output: list[dict[str, object]] = []
    for row in rows:
        role = str(row.get("role", "") or "")
        updated = dict(row)
        pair_match = int(pair_match_by_role.get(role, 0) or 0)
        pair_missing = int(pair_missing_by_role.get(role, 0) or 0)
        pair_notes = "; ".join(pair_notes_by_role.get(role, []))
        updated["graph_pair_match_count"] = pair_match
        updated["graph_pair_missing_count"] = pair_missing
        updated["graph_pair_notes"] = pair_notes
        if pair_notes:
            updated["notes"] = _join_review_notes(str(updated.get("notes", "") or ""), f"graph_pair_audit={pair_notes}")
        if pair_missing:
            updated["status"] = "warning"
            updated["recommended_action"] = "Review Shared Boundary Graph consumer pairs, then rebuild surfaces"
        output.append(updated)
    return output


def _shared_boundary_graph_consumer_audit_rows(rows: list[dict[str, object]]) -> list[dict[str, object]]:
    """Mark graph refs that are not owned by the surface consumer represented by a row."""

    if not rows:
        return []
    consumer_by_role = {
        "design": "design_surface",
        "intersection": "intersection_surface",
        "daylight": "slope_face_surface",
        "intersection_slope": "intersection_slope_face_surface",
    }
    edge_consumers: dict[str, set[str]] = {}
    for row in rows:
        for raw in list(row.get("graph_audit_rows", []) or []):
            parsed = _parse_intersection_shared_boundary_graph_audit_row(raw)
            if not parsed or str(parsed.get("row_kind", "") or "") != "edge":
                continue
            edge_id = str(parsed.get("row_id", "") or "")
            consumers = {
                str(value or "").strip()
                for value in str(parsed.get("refs", "") or "").split(",")
                if str(value or "").strip()
            }
            if edge_id:
                edge_consumers.setdefault(edge_id, set()).update(consumers)
    output: list[dict[str, object]] = []
    for row in rows:
        updated = dict(row)
        role = str(row.get("role", "") or "")
        consumer_ref = consumer_by_role.get(role, "")
        graph_refs = {str(value or "") for value in list(row.get("graph_refs", []) or []) if str(value or "")}
        foreign_refs = []
        if consumer_ref:
            for edge_ref in sorted(graph_refs):
                consumers = edge_consumers.get(edge_ref)
                if not consumers or consumer_ref not in consumers:
                    foreign_refs.append(edge_ref)
        updated["graph_foreign_edge_count"] = len(foreign_refs)
        updated["graph_foreign_edge_notes"] = "; ".join(
            f"shared_boundary_surface_owns_foreign_edge:{role}:{edge_ref}"
            for edge_ref in foreign_refs
        )
        if foreign_refs:
            updated["status"] = "warning"
            updated["recommended_action"] = "Review Shared Boundary Graph consumer ownership, then rebuild surfaces"
            updated["notes"] = _join_review_notes(
                str(updated.get("notes", "") or ""),
                str(updated.get("graph_foreign_edge_notes", "") or ""),
            )
        output.append(updated)
    return output


def _parse_shared_boundary_graph_pair_notes(notes: str) -> list[dict[str, object]]:
    """Parse graph pair audit notes into panel detail rows."""

    rows: list[dict[str, object]] = []
    for raw in str(notes or "").split(";"):
        text = str(raw or "").strip()
        if not text:
            continue
        parts = text.split(":")
        if len(parts) < 3 or parts[0] not in {"pair_match", "pair_missing"}:
            continue
        pair_parts = parts[2].split("<->", 1)
        if len(pair_parts) != 2:
            continue
        match_count = 0
        if parts[0] == "pair_match" and len(parts) >= 4:
            try:
                match_count = int(parts[3] or 0)
            except Exception:
                match_count = 0
        rows.append(
            {
                "status": "ready" if parts[0] == "pair_match" else "missing",
                "edge_role": parts[1],
                "first_role": pair_parts[0],
                "second_role": pair_parts[1],
                "match_count": match_count,
            }
        )
    return rows


def _shared_breakline_recommended_action(
    *,
    geometry_mismatch_count: int,
    missing_consumer_count: int,
    mismatch_count: int,
    reversed_edge_count: int,
    mesh_mismatch_count: int = 0,
    cell_open_count: int = 0,
    cell_missing_edge_count: int = 0,
    graph_duplicate_edge_count: int = 0,
    graph_missing_consumer_count: int = 0,
    graph_source_segment_split_count: int = 0,
    graph_open_cell_count: int = 0,
    graph_not_snapped_count: int = 0,
    graph_endpoint_mismatch_count: int = 0,
    graph_foreign_edge_count: int = 0,
    graph_pair_missing_count: int = 0,
    notes: str = "",
) -> str:
    if int(graph_pair_missing_count or 0) > 0:
        return "Review Shared Boundary Graph consumer pairs, then rebuild surfaces"
    if int(graph_foreign_edge_count or 0) > 0:
        return "Review Shared Boundary Graph consumer ownership, then rebuild surfaces"
    if int(graph_endpoint_mismatch_count or 0) > 0 or int(graph_not_snapped_count or 0) > 0:
        return "Rebuild Shared Boundary Graph from canonical source edges"
    if int(graph_source_segment_split_count or 0) > 0:
        return "Unify shared boundary source segments, then rebuild surfaces"
    if int(graph_duplicate_edge_count or 0) > 0 or int(graph_missing_consumer_count or 0) > 0 or int(graph_open_cell_count or 0) > 0:
        return "Review Shared Boundary Graph, then rebuild surfaces"
    if int(cell_open_count or 0) > 0 or int(cell_missing_edge_count or 0) > 0:
        return "Review Intersection Slope Face cells, then rebuild"
    if int(mismatch_count or 0) > 0:
        return "Review Intersection Source"
    if int(missing_consumer_count or 0) > 0:
        return "Rebuild Build Parametric"
    role_action = _shared_breakline_recommended_action_from_notes(notes)
    if role_action:
        return role_action
    if int(mesh_mismatch_count or 0) > 0:
        return "Rebuild constrained surface mesh"
    if int(geometry_mismatch_count or 0) > 0:
        return "Rebuild Applied Sections, then Build Parametric"
    if int(reversed_edge_count or 0) > 0:
        return "Monitor; check Watertight normals if needed"
    return "No action needed"


def _shared_breakline_recommended_action_from_notes(notes: str) -> str:
    text = str(notes or "")
    if not text:
        return ""
    if "patch-to-slope-face" in text or "patch_to_slope_face" in text:
        return "Rebuild Intersection and Slope Face constraints"
    if "curb_return_to_slope_face" in text or "curb-return-to-slope-face" in text:
        return "Rebuild Intersection and Slope Face constraints"
    if "patch-to-design" in text or "patch_to_design" in text:
        return "Rebuild Intersection and Design constraints"
    if "curb_return_to_pavement" in text or "curb-return-to-pavement" in text:
        return "Rebuild Intersection and Design constraints"
    if "curb_return_to_shoulder" in text or "curb-return-to-shoulder" in text:
        return "Rebuild Intersection and Design constraints"
    if "patch-to-shoulder" in text or "patch_to_shoulder" in text:
        return "Rebuild Intersection and Design constraints"
    if "shoulder-to-slope-face" in text or "shoulder_to_slope_face" in text:
        return "Rebuild Applied Sections, then constrained surfaces"
    if "curb_return_inner" in text or "curb-return-inner" in text or "curb_return_outer" in text or "curb-return-outer" in text:
        return "Rebuild Intersection curb-return constraints"
    if (
        "region-transition" in text
        or "region_start_boundary" in text
        or "region_end_boundary" in text
        or "assembly_change_boundary" in text
        or "surface_transition_boundary" in text
    ):
        return "Review Region spans, then Build Parametric"
    if (
        "control_area_entry" in text
        or "control-area-entry" in text
        or "control_area_exit" in text
        or "control-area-exit" in text
        or "region_to_intersection_control" in text
        or "region-to-intersection-control" in text
    ):
        return "Review Intersection control areas and Region spans, then Build Parametric"
    if (
        "lane_to_lane" in text
        or "lane_to_shoulder" in text
        or "shoulder_edge" in text
        or "shoulder_to_side_slope" in text
        or "side_slope_to_daylight" in text
    ):
        return "Rebuild Applied Sections, then constrained surfaces"
    if (
        "intersection_gutter_handoff" in text
        or "intersection-gutter-handoff" in text
        or "intersection_ditch_handoff" in text
        or "intersection-ditch-handoff" in text
        or "low_point_flow_split" in text
        or "low-point-flow-split" in text
        or "drainage_capture_edge" in text
        or "drainage-capture-edge" in text
    ):
        return "Review Intersection Drainage source, then rebuild Intersection"
    if (
        "corridor_gutter_handoff" in text
        or "corridor-ditch-handoff" in text
        or "corridor_ditch_handoff" in text
        or "corridor-gutter-handoff" in text
    ):
        return "Review Drainage source, then rebuild Applied Sections"
    return ""


def corridor_shared_breakline_audit_summary(document=None) -> dict[str, object]:
    rows = corridor_shared_breakline_audit_rows(document)
    if not rows:
        return {
            "status": "missing",
            "title": "Shared breakline audit not available",
            "notes": "Build Parametric has not produced shared breakline audit metadata yet.",
            "issue_count": 0,
        }
    issue_rows = [
        row for row in rows
        if _shared_breakline_audit_summary_issue_reasons(row)
    ]
    graph_notes = _shared_boundary_graph_summary_notes(rows)
    if not issue_rows:
        return {
            "status": "ready",
            "title": "No shared breakline issues",
            "notes": _join_review_notes(
                f"{len(rows)} audited surface(s); contract and mesh endpoints match the shared breakline contract.",
                graph_notes,
            ),
            "issue_count": 0,
        }
    mismatch_count = sum(int(row.get("geometry_mismatch_count", 0) or 0) for row in issue_rows)
    mesh_mismatch_count = sum(int(row.get("mesh_mismatch_count", 0) or 0) for row in issue_rows)
    missing_count = sum(int(row.get("missing_consumer_count", 0) or 0) for row in issue_rows)
    shared_mismatch_count = sum(int(row.get("mismatch_count", 0) or 0) for row in issue_rows)
    reversed_count = sum(int(row.get("reversed_edge_count", 0) or 0) for row in issue_rows)
    cell_open_count = sum(int(row.get("cell_open_count", 0) or 0) for row in issue_rows)
    cell_missing_edge_count = sum(int(row.get("cell_missing_edge_count", 0) or 0) for row in issue_rows)
    graph_duplicate_edge_count = sum(int(row.get("graph_duplicate_edge_count", 0) or 0) for row in issue_rows)
    graph_missing_consumer_count = sum(int(row.get("graph_missing_consumer_count", 0) or 0) for row in issue_rows)
    graph_open_cell_count = sum(int(row.get("graph_open_cell_count", 0) or 0) for row in issue_rows)
    graph_endpoint_mismatch_count = sum(int(row.get("graph_endpoint_mismatch_count", 0) or 0) for row in issue_rows)
    graph_not_snapped_count = sum(int(row.get("graph_not_snapped_count", 0) or 0) for row in issue_rows)
    graph_foreign_edge_count = sum(int(row.get("graph_foreign_edge_count", 0) or 0) for row in issue_rows)
    graph_pair_missing_count = sum(int(row.get("graph_pair_missing_count", 0) or 0) for row in issue_rows)
    status_warning_count = sum(
        1 for row in issue_rows
        if str(row.get("status", "") or "").strip().lower() not in {"", "ready"}
    )
    boundary_loop_missing_constraint_count = sum(
        1 for row in issue_rows
        if int(row.get("boundary_loop_ref_count", 0) or 0)
        and not int(row.get("boundary_loop_constraint_edge_count", 0) or 0)
    )
    boundary_loop_ownership_warning_count = sum(
        1 for row in issue_rows
        if str(row.get("boundary_loop_ownership_status", "") or "").strip().lower()
        not in {"", "ready"}
    )
    boundary_loop_near_kept_warning_count = sum(
        1 for row in issue_rows
        if bool(row.get("boundary_loop_near_kept_warning", False))
    )
    return {
        "status": "warning",
        "title": f"Shared breakline issues found: {len(issue_rows)} surface(s)",
        "notes": _join_review_notes(
            (
                f"geometry_mismatch={mismatch_count}; mesh_mismatch={mesh_mismatch_count}; "
                f"missing_consumer={missing_count}; mismatch={shared_mismatch_count}; reversed={reversed_count}; "
                f"cell_open={cell_open_count}; "
                f"cell_missing_edge={cell_missing_edge_count}; graph_duplicate_edge={graph_duplicate_edge_count}; "
                f"graph_missing_consumer={graph_missing_consumer_count}; graph_open_cell={graph_open_cell_count}; "
                f"graph_endpoint_mismatch={graph_endpoint_mismatch_count}; graph_not_snapped={graph_not_snapped_count}; "
                f"graph_foreign_edge={graph_foreign_edge_count}; "
                f"graph_pair_missing={graph_pair_missing_count}; status_warning={status_warning_count}; "
                f"boundary_loop_missing_constraint={boundary_loop_missing_constraint_count}; "
                f"boundary_loop_ownership_warning={boundary_loop_ownership_warning_count}; "
                f"boundary_loop_near_kept_warning={boundary_loop_near_kept_warning_count}"
            ),
            graph_notes,
        ),
        "issue_count": len(issue_rows),
    }


def _shared_breakline_audit_summary_issue_reasons(row: dict[str, object]) -> list[str]:
    reasons: list[str] = []
    count_fields = {
        "geometry_mismatch": "geometry_mismatch_count",
        "mesh_mismatch": "mesh_mismatch_count",
        "missing_consumer": "missing_consumer_count",
        "mismatch": "mismatch_count",
        "reversed": "reversed_edge_count",
        "cell_open": "cell_open_count",
        "cell_missing_edge": "cell_missing_edge_count",
        "graph_duplicate_edge": "graph_duplicate_edge_count",
        "graph_missing_consumer": "graph_missing_consumer_count",
        "graph_open_cell": "graph_open_cell_count",
        "graph_endpoint_mismatch": "graph_endpoint_mismatch_count",
        "graph_not_snapped": "graph_not_snapped_count",
        "graph_foreign_edge": "graph_foreign_edge_count",
        "graph_pair_missing": "graph_pair_missing_count",
    }
    for reason, field_name in count_fields.items():
        if int(row.get(field_name, 0) or 0):
            reasons.append(reason)
    if int(row.get("boundary_loop_ref_count", 0) or 0) and not int(row.get("boundary_loop_constraint_edge_count", 0) or 0):
        reasons.append("boundary_loop_missing_constraint")
    if bool(row.get("boundary_loop_near_kept_warning", False)):
        reasons.append("boundary_loop_near_kept")
    return reasons


def _shared_boundary_graph_summary_notes(rows: list[dict[str, object]]) -> str:
    graph_rows = [
        row for row in list(rows or [])
        if int(row.get("graph_node_count", 0) or 0)
        or int(row.get("graph_edge_count", 0) or 0)
        or int(row.get("graph_cell_count", 0) or 0)
        or str(row.get("graph_status", "") or "")
    ]
    if not graph_rows:
        return "Shared Boundary Graph: not available"
    statuses = {
        str(row.get("graph_status", "") or "missing").strip() or "missing"
        for row in graph_rows
    }
    node_count = max(int(row.get("graph_node_count", 0) or 0) for row in graph_rows)
    edge_count = max(int(row.get("graph_edge_count", 0) or 0) for row in graph_rows)
    cell_count = max(int(row.get("graph_cell_count", 0) or 0) for row in graph_rows)
    consumed_count = sum(int(row.get("graph_consumed_edge_count", 0) or 0) for row in graph_rows)
    duplicate_count = sum(int(row.get("graph_duplicate_edge_count", 0) or 0) for row in graph_rows)
    missing_consumer_count = sum(int(row.get("graph_missing_consumer_count", 0) or 0) for row in graph_rows)
    open_cell_count = sum(int(row.get("graph_open_cell_count", 0) or 0) for row in graph_rows)
    endpoint_mismatch_count = sum(int(row.get("graph_endpoint_mismatch_count", 0) or 0) for row in graph_rows)
    not_snapped_count = sum(int(row.get("graph_not_snapped_count", 0) or 0) for row in graph_rows)
    foreign_edge_count = sum(int(row.get("graph_foreign_edge_count", 0) or 0) for row in graph_rows)
    pair_missing_count = sum(int(row.get("graph_pair_missing_count", 0) or 0) for row in graph_rows)
    graph_issue_count = (
        duplicate_count
        + missing_consumer_count
        + open_cell_count
        + endpoint_mismatch_count
        + not_snapped_count
        + foreign_edge_count
        + pair_missing_count
    )
    graph_status = "ready" if statuses == {"ready"} and graph_issue_count == 0 else "warning"
    return (
        f"Shared Boundary Graph: {graph_status}; nodes={node_count}; edges={edge_count}; cells={cell_count}; "
        f"surface_consumed_edges={consumed_count}; duplicate={duplicate_count}; missing_consumer={missing_consumer_count}; "
        f"open_cells={open_cell_count}; endpoint_mismatch={endpoint_mismatch_count}; not_snapped={not_snapped_count}; "
        f"foreign_edges={foreign_edge_count}; pair_missing={pair_missing_count}"
    )


INTERSECTION_TIE_SLOPE_WINDOW_GENERIC_BREAKLINE_ROLES = (
    "intersection_tie_slope_window_outer",
    "intersection_tie_slope_window_inner",
    "intersection_tie_slope_window_start_cap",
    "intersection_tie_slope_window_end_cap",
)

INTERSECTION_TIE_SLOPE_WINDOW_APPROACH_BREAKLINE_ROLES = (
    "intersection_tie_slope_approach_outer",
    "intersection_tie_slope_to_curb_return_approach",
    "intersection_tie_slope_approach_start_cap",
    "intersection_tie_slope_approach_end_cap",
)

INTERSECTION_TIE_SLOPE_WINDOW_SUPPLEMENTAL_BREAKLINE_ROLES = (
    "intersection_tie_slope_supplemental_outer",
    "intersection_tie_slope_supplemental_inner",
    "intersection_tie_slope_supplemental_start_cap",
    "intersection_tie_slope_supplemental_end_cap",
)

INTERSECTION_TIE_SLOPE_WINDOW_ENDPOINT_BREAKLINE_ROLES = (
    "intersection_tie_slope_supplemental_outer",
    "intersection_tie_slope_supplemental_endpoint",
    "intersection_tie_slope_supplemental_start_cap",
    "intersection_tie_slope_supplemental_end_cap",
)

INTERSECTION_TIE_SLOPE_WINDOW_BREAKLINE_ROLES = (
    *INTERSECTION_TIE_SLOPE_WINDOW_GENERIC_BREAKLINE_ROLES,
    *INTERSECTION_TIE_SLOPE_WINDOW_APPROACH_BREAKLINE_ROLES,
    *INTERSECTION_TIE_SLOPE_WINDOW_SUPPLEMENTAL_BREAKLINE_ROLES,
    *INTERSECTION_TIE_SLOPE_WINDOW_ENDPOINT_BREAKLINE_ROLES,
)


def _intersection_tie_slope_window_breakline_roles_for_row(row: dict[str, object]) -> tuple[str, str, str, str]:
    extent_role = str(row.get("supplemental_extent_role", "") or "").strip().lower()
    if extent_role == "supplemental_endpoint_pair":
        return INTERSECTION_TIE_SLOPE_WINDOW_ENDPOINT_BREAKLINE_ROLES
    if extent_role == "intersection_supplemental_pair":
        return INTERSECTION_TIE_SLOPE_WINDOW_SUPPLEMENTAL_BREAKLINE_ROLES
    if str(row.get("cell_role", "") or "") == "curb_return_approach_pair":
        return INTERSECTION_TIE_SLOPE_WINDOW_APPROACH_BREAKLINE_ROLES
    return INTERSECTION_TIE_SLOPE_WINDOW_GENERIC_BREAKLINE_ROLES


def _intersection_tie_slope_window_role_counts_from_audit_row(row: dict[str, object]) -> dict[str, int]:
    role_counts = {
        role: count
        for role, count in _shared_breakline_summary_count_items(str(row.get("role_summary", "") or ""))
        if role in INTERSECTION_TIE_SLOPE_WINDOW_BREAKLINE_ROLES
    }
    return role_counts


def _roundabout_clip_boundary_consumer_pairs(surface_role: str, boundary_role: str) -> list[str]:
    role = str(surface_role or "").strip().lower()
    boundary = str(boundary_role or "").strip().lower()
    if role == "design" or boundary == "roundabout_approach_clip_boundary":
        return [
            "Design Surface <-> Roundabout Circulatory Surface",
            "Design Surface <-> Roundabout Apron Surface",
            "Approach Shoulder Review <-> Roundabout Apron Surface",
        ]
    if role == "subgrade" or boundary == "roundabout_subgrade_clip_boundary":
        return ["Subgrade Surface <-> Roundabout Subgrade Surface"]
    if role == "daylight" or boundary == "roundabout_slope_handoff_boundary":
        return [
            "Slope Face Surface <-> Roundabout Slope Face Surface",
            "Side Slope Review <-> Roundabout Slope Face Surface",
        ]
    return ["Roundabout Clip Boundary <-> Ordinary Surface"]


def _roundabout_clip_boundary_leg_segment_refs(segment_refs: object, approach_role: str) -> list[str]:
    refs = [str(value or "") for value in list(segment_refs or []) if str(value or "")]
    role = str(approach_role or "").strip()
    if not role:
        return refs
    tokens = {
        role,
        role.replace("-", "_"),
        role.replace("_", "-"),
    }
    filtered = [ref for ref in refs if any(token and token in ref for token in tokens)]
    return filtered or refs


def shared_breakline_audit_display_rows(rows: list[dict[str, object]], *, include_internal: bool = False) -> list[dict[str, object]]:
    """Return panel-friendly shared breakline audit rows.

    The default panel view is intentionally compact. It keeps the audited
    surface rows and hides implementation detail rows such as graph edges,
    graph cells, role expansions, and slope-face cell internals. Tests and
    developer diagnostics can opt into those rows with ``include_internal``.
    """

    output: list[dict[str, object]] = []
    for row in list(rows or []):
        surface_row = dict(row)
        surface_row["row_kind"] = "surface"
        output.append(surface_row)
        if not include_internal:
            continue
        for role, count in _shared_breakline_summary_count_items(str(row.get("role_summary", "") or "")):
            detail = dict(row)
            detail["row_kind"] = "role"
            detail["surface"] = f"  Role: {role}"
            detail["consumed"] = count
            detail["total"] = count
            detail["material_summary"] = str(row.get("material_summary", "") or "")
            detail["role_summary"] = f"{role}={count}"
            detail["breakline_role_filter"] = role
            detail["recommended_action"] = _shared_breakline_recommended_action_from_notes(role) or str(row.get("recommended_action", "") or "")
            output.append(detail)
        tie_slope_window_counts = _intersection_tie_slope_window_role_counts_from_audit_row(row)
        if tie_slope_window_counts:
            consumed = sum(tie_slope_window_counts.values())
            required_roles: list[str] = []
            if any(int(tie_slope_window_counts.get(role, 0) or 0) > 0 for role in INTERSECTION_TIE_SLOPE_WINDOW_GENERIC_BREAKLINE_ROLES):
                required_roles.extend(INTERSECTION_TIE_SLOPE_WINDOW_GENERIC_BREAKLINE_ROLES)
            if any(int(tie_slope_window_counts.get(role, 0) or 0) > 0 for role in INTERSECTION_TIE_SLOPE_WINDOW_APPROACH_BREAKLINE_ROLES):
                required_roles.extend(INTERSECTION_TIE_SLOPE_WINDOW_APPROACH_BREAKLINE_ROLES)
            if not required_roles:
                required_roles = list(INTERSECTION_TIE_SLOPE_WINDOW_BREAKLINE_ROLES)
            missing_roles = [
                role for role in required_roles
                if int(tie_slope_window_counts.get(role, 0) or 0) <= 0
            ]
            detail = dict(row)
            detail["row_kind"] = "intersection_tie_slope_window"
            detail["surface"] = "  Intersection Tie Slope Window Handoff"
            detail["status"] = "warning" if missing_roles else "ready"
            detail["consumed"] = consumed
            detail["total"] = max(consumed, len(required_roles))
            detail["material_summary"] = "intersection_tie_slope_window"
            detail["role_summary"] = ", ".join(
                f"{role}={int(tie_slope_window_counts.get(role, 0) or 0)}"
                for role in INTERSECTION_TIE_SLOPE_WINDOW_BREAKLINE_ROLES
            )
            detail["breakline_role_filter"] = "intersection_tie_slope_window"
            detail["recommended_action"] = (
                "Review Applied Section window candidates, then rebuild Tie Slope"
                if missing_roles
                else "No action needed"
            )
            detail["notes"] = _join_review_notes(
                str(detail.get("notes", "") or ""),
                (
                    "intersection_tie_slope_window_handoff="
                    f"roles={len(tie_slope_window_counts)}; consumed={consumed}; "
                    f"missing_roles={','.join(missing_roles) if missing_roles else 'none'}; "
                    "source=applied_section_context_transition_window"
                ),
            )
            output.append(detail)
        boundary_loop_ref_count = int(row.get("boundary_loop_ref_count", 0) or 0)
        boundary_loop_constraint_segments = int(row.get("boundary_loop_constraint_segment_count", 0) or 0)
        boundary_loop_constraint_edges = int(row.get("boundary_loop_constraint_edge_count", 0) or 0)
        exclusion_tested_triangles = int(row.get("intersection_exclusion_tested_triangle_count", 0) or 0)
        exclusion_clipped_triangles = int(row.get("intersection_exclusion_clipped_triangle_count", 0) or 0)
        exclusion_boundary_crossings = int(row.get("intersection_exclusion_boundary_crossing_triangle_count", 0) or 0)
        exclusion_near_boundary_kept = int(row.get("intersection_exclusion_near_boundary_kept_triangle_count", 0) or 0)
        exclusion_clip_ratio = float(row.get("intersection_exclusion_clip_ratio", 0.0) or 0.0)
        boundary_loop_near_kept_warning = bool(row.get("boundary_loop_near_kept_warning", False))
        if boundary_loop_ref_count or boundary_loop_constraint_segments or boundary_loop_constraint_edges:
            detail = dict(row)
            detail["row_kind"] = "boundary_loop_handoff"
            detail["surface"] = "  Boundary Loop Handoff"
            ownership_status = str(row.get("boundary_loop_ownership_status", "") or "")
            detail["status"] = (
                "warning"
                if boundary_loop_ref_count and not boundary_loop_constraint_edges
                or boundary_loop_near_kept_warning
                else ownership_status
                if ownership_status and ownership_status != "missing"
                else "ready"
            )
            detail["consumed"] = boundary_loop_constraint_edges
            detail["total"] = max(boundary_loop_ref_count, boundary_loop_constraint_segments, boundary_loop_constraint_edges)
            detail["material_summary"] = "intersection_boundary_loop"
            detail["role_summary"] = (
                f"refs={boundary_loop_ref_count}, "
                f"constraint_segments={boundary_loop_constraint_segments}, "
                f"constraint_edges={boundary_loop_constraint_edges}, "
                f"ownership={ownership_status or 'not_checked'}, "
                f"clip={exclusion_clipped_triangles}/{exclusion_tested_triangles}, "
                f"crossing={exclusion_boundary_crossings}, near_kept={exclusion_near_boundary_kept}, "
                f"ratio={exclusion_clip_ratio:.3f}"
            )
            detail["breakline_role_filter"] = "intersection_boundary_loop"
            detail["graph_edge_refs"] = _shared_boundary_graph_edge_refs_from_audit_row(
                row,
                source_ref_filter="intersection-boundary-loop",
            )
            if boundary_loop_near_kept_warning:
                detail["recommended_action"] = "Review boundary-loop clipping residuals, then rebuild constrained surfaces"
            elif str(detail["status"]) == "warning":
                detail["recommended_action"] = "Rebuild boundary-loop constrained surfaces"
            else:
                detail["recommended_action"] = "No action needed"
            detail["notes"] = _join_review_notes(
                str(detail.get("notes", "") or ""),
                (
                    "boundary_loop_handoff="
                    f"refs={boundary_loop_ref_count}; "
                    f"constraint_segments={boundary_loop_constraint_segments}; "
                    f"constraint_edges={boundary_loop_constraint_edges}"
                ),
                str(row.get("boundary_loop_ownership_notes", "") or ""),
            )
            output.append(detail)
        roundabout_clip_boundary_role = str(row.get("roundabout_clip_boundary_role", "") or "")
        roundabout_clip_boundary_status = str(row.get("roundabout_clip_boundary_status", "") or "")
        roundabout_actual_clip_boundary_roles = [
            str(value or "").strip()
            for value in list(row.get("roundabout_actual_clip_boundary_roles", []) or [])
            if str(value or "").strip()
        ]
        roundabout_clip_boundary_is_diagnostic_only = bool(
            roundabout_clip_boundary_role
            and roundabout_actual_clip_boundary_roles
            and roundabout_clip_boundary_role not in set(roundabout_actual_clip_boundary_roles)
        )
        roundabout_clip_mode = str(row.get("roundabout_clip_mode", "") or "")
        roundabout_clip_reason_summary = str(row.get("roundabout_clip_reason_summary", "") or "")
        roundabout_clip_boundary_loop_count = int(row.get("roundabout_clip_boundary_loop_count", 0) or 0)
        roundabout_clip_boundary_segment_count = int(row.get("roundabout_clip_boundary_segment_count", 0) or 0)
        roundabout_clip_boundary_approach_leg_count = int(row.get("roundabout_clip_boundary_approach_leg_count", 0) or 0)
        roundabout_clip_boundary_approach_leg_roles = [
            str(value or "")
            for value in list(row.get("roundabout_clip_boundary_approach_leg_roles", []) or [])
            if str(value or "")
        ]
        roundabout_clip_boundary_approach_leg_source = str(row.get("roundabout_clip_boundary_approach_leg_source", "") or "")
        if roundabout_clip_boundary_role or roundabout_clip_boundary_status:
            consumer_pairs = _roundabout_clip_boundary_consumer_pairs(
                str(row.get("role", "") or ""),
                roundabout_clip_boundary_role,
            )
            detail = dict(row)
            detail["row_kind"] = (
                "roundabout_clip_boundary_diagnostic"
                if roundabout_clip_boundary_is_diagnostic_only
                else "roundabout_clip_boundary"
            )
            detail["surface"] = (
                "  Roundabout Diagnostic Boundary"
                if roundabout_clip_boundary_is_diagnostic_only
                else "  Roundabout Clip Boundary"
            )
            detail["status"] = roundabout_clip_boundary_status or "missing"
            detail["consumed"] = roundabout_clip_boundary_segment_count
            detail["total"] = max(roundabout_clip_boundary_segment_count, roundabout_clip_boundary_loop_count)
            detail["material_summary"] = (
                "roundabout_diagnostic_boundary"
                if roundabout_clip_boundary_is_diagnostic_only
                else "roundabout_clip_boundary"
            )
            detail["role_summary"] = (
                f"role={roundabout_clip_boundary_role or 'missing'}, "
                f"loops={roundabout_clip_boundary_loop_count}, "
                f"segments={roundabout_clip_boundary_segment_count}, "
                f"approach_legs={roundabout_clip_boundary_approach_leg_count}, "
                f"approach_roles={','.join(roundabout_clip_boundary_approach_leg_roles) if roundabout_clip_boundary_approach_leg_roles else 'none'}, "
                f"mode={roundabout_clip_mode or 'missing'}, "
                f"actual_clip_roles={','.join(roundabout_actual_clip_boundary_roles) if roundabout_actual_clip_boundary_roles else 'none'}, "
                f"reasons={roundabout_clip_reason_summary or 'none'}, "
                f"consumer_pairs={' | '.join(consumer_pairs)}"
            )
            detail["breakline_role_filter"] = (
                ""
                if roundabout_clip_boundary_is_diagnostic_only
                else roundabout_clip_boundary_role or "roundabout_clip_boundary"
            )
            detail["graph_edge_refs"] = (
                []
                if roundabout_clip_boundary_is_diagnostic_only
                else list(row.get("roundabout_clip_boundary_segment_refs", []) or [])
            )
            detail["recommended_action"] = (
                "No action needed - diagnostic handoff boundary is not used for ordinary surface clipping"
                if roundabout_clip_boundary_is_diagnostic_only
                else
                "Review roundabout clip boundary loops, then rebuild ordinary surfaces"
                if str(detail["status"]) != "ready"
                else "No action needed"
            )
            detail["notes"] = _join_review_notes(
                str(detail.get("notes", "") or ""),
                (
                    "roundabout_clip_boundary_handoff="
                    f"result={str(row.get('roundabout_clip_boundary_result_id', '') or '')}; "
                    f"role={roundabout_clip_boundary_role or 'missing'}; "
                    f"status={roundabout_clip_boundary_status or 'missing'}; "
                    f"loops={roundabout_clip_boundary_loop_count}; "
                    f"segments={roundabout_clip_boundary_segment_count}; "
                    f"approach_legs={roundabout_clip_boundary_approach_leg_count}; "
                    f"approach_roles={','.join(roundabout_clip_boundary_approach_leg_roles) if roundabout_clip_boundary_approach_leg_roles else 'none'}; "
                    f"approach_source={roundabout_clip_boundary_approach_leg_source or 'missing'}; "
                    f"mode={roundabout_clip_mode or 'missing'}; "
                    f"actual_clip_roles={','.join(roundabout_actual_clip_boundary_roles) if roundabout_actual_clip_boundary_roles else 'none'}; "
                    f"diagnostic_only={'yes' if roundabout_clip_boundary_is_diagnostic_only else 'no'}; "
                    f"reasons={roundabout_clip_reason_summary or 'none'}; "
                    f"consumer_pairs={' | '.join(consumer_pairs)}"
                ),
            )
            output.append(detail)
            if roundabout_clip_boundary_is_diagnostic_only:
                continue
            leg_roles = roundabout_clip_boundary_approach_leg_roles or ["unassigned"]
            per_leg_total = (
                max(1, roundabout_clip_boundary_segment_count // len(leg_roles))
                if leg_roles
                else roundabout_clip_boundary_segment_count
            )
            for approach_role in leg_roles:
                leg_detail = dict(row)
                leg_detail["row_kind"] = "roundabout_clip_boundary_leg"
                leg_detail["surface"] = f"  Roundabout Clip Boundary - {approach_role}"
                leg_status = roundabout_clip_boundary_status or "missing"
                if (
                    int(row.get("geometry_mismatch_count", 0) or 0)
                    or int(row.get("mesh_mismatch_count", 0) or 0)
                    or int(row.get("missing_consumer_count", 0) or 0)
                ):
                    leg_status = "warning"
                leg_detail["status"] = leg_status
                leg_detail["consumed"] = per_leg_total if leg_status == "ready" else 0
                leg_detail["total"] = max(1, per_leg_total)
                leg_detail["material_summary"] = "roundabout_clip_boundary_leg"
                leg_detail["role_summary"] = (
                    f"role={roundabout_clip_boundary_role or 'missing'}, "
                    f"approach_role={approach_role}, "
                    f"mode={roundabout_clip_mode or 'missing'}, "
                    f"consumer_pairs={' | '.join(consumer_pairs)}"
                )
                leg_detail["breakline_role_filter"] = f"{roundabout_clip_boundary_role or 'roundabout_clip_boundary'}:{approach_role}"
                leg_detail["graph_edge_refs"] = _roundabout_clip_boundary_leg_segment_refs(
                    row.get("roundabout_clip_boundary_segment_refs", []),
                    approach_role,
                )
                leg_detail["recommended_action"] = (
                    "Review this roundabout approach clip boundary, then rebuild ordinary surfaces"
                    if str(leg_detail["status"]) != "ready"
                    else "No action needed"
                )
                leg_detail["notes"] = _join_review_notes(
                    str(leg_detail.get("notes", "") or ""),
                    (
                        "roundabout_clip_boundary_leg_handoff="
                        f"result={str(row.get('roundabout_clip_boundary_result_id', '') or '')}; "
                        f"role={roundabout_clip_boundary_role or 'missing'}; "
                        f"approach_role={approach_role}; "
                        f"status={roundabout_clip_boundary_status or 'missing'}; "
                        f"segments={per_leg_total}; "
                        f"approach_source={roundabout_clip_boundary_approach_leg_source or 'missing'}; "
                        f"consumer_pairs={' | '.join(consumer_pairs)}"
                    ),
                )
                output.append(leg_detail)
        graph_edge_count = int(row.get("graph_edge_count", 0) or 0)
        graph_cell_count = int(row.get("graph_cell_count", 0) or 0)
        if graph_edge_count or graph_cell_count or str(row.get("graph_status", "") or ""):
            detail = dict(row)
            detail["row_kind"] = "graph"
            detail["surface"] = "  Shared Boundary Graph"
            detail["status"] = (
                "warning"
                if int(row.get("graph_duplicate_edge_count", 0) or 0)
                or int(row.get("graph_missing_consumer_count", 0) or 0)
                or int(row.get("graph_open_cell_count", 0) or 0)
                or int(row.get("graph_endpoint_mismatch_count", 0) or 0)
                or int(row.get("graph_not_snapped_count", 0) or 0)
                or int(row.get("graph_foreign_edge_count", 0) or 0)
                or int(row.get("graph_pair_missing_count", 0) or 0)
                else str(row.get("graph_status", "") or "ready")
            )
            detail["consumed"] = int(row.get("graph_consumed_edge_count", 0) or graph_edge_count)
            detail["total"] = graph_edge_count
            detail["material_summary"] = "intersection_shared_boundary_graph"
            detail["graph_edge_refs"] = _shared_boundary_graph_edge_refs_from_audit_row(row)
            detail["role_summary"] = (
                f"nodes={int(row.get('graph_node_count', 0) or 0)}, "
                f"edges={graph_edge_count}, consumed_edges={int(row.get('graph_consumed_edge_count', 0) or 0)}, cells={graph_cell_count}, "
                f"duplicate_edges={int(row.get('graph_duplicate_edge_count', 0) or 0)}, "
                f"missing_consumers={int(row.get('graph_missing_consumer_count', 0) or 0)}, "
                f"open_cells={int(row.get('graph_open_cell_count', 0) or 0)}, "
                f"endpoint_mismatch={int(row.get('graph_endpoint_mismatch_count', 0) or 0)}, "
                f"not_snapped={int(row.get('graph_not_snapped_count', 0) or 0)}, "
                f"foreign_edges={int(row.get('graph_foreign_edge_count', 0) or 0)}, "
                f"pair_missing={int(row.get('graph_pair_missing_count', 0) or 0)}"
            )
            detail["breakline_role_filter"] = "intersection_shared_boundary_graph"
            detail["recommended_action"] = (
                "Review Shared Boundary Graph, then rebuild surfaces"
                if str(detail["status"]) == "warning"
                else "No action needed"
            )
            if str(row.get("graph_pair_notes", "") or ""):
                detail["notes"] = _join_review_notes(
                    str(detail.get("notes", "") or ""),
                    f"graph_pair_audit={row.get('graph_pair_notes', '')}",
                )
            if str(row.get("graph_foreign_edge_notes", "") or ""):
                detail["notes"] = _join_review_notes(
                    str(detail.get("notes", "") or ""),
                    str(row.get("graph_foreign_edge_notes", "") or ""),
                    )
            output.append(detail)
            output.extend(_boundary_loop_owner_summary_display_rows(row))
            for pair_note in _parse_shared_boundary_graph_pair_notes(str(row.get("graph_pair_notes", "") or "")):
                pair_detail = dict(row)
                pair_detail["row_kind"] = "graph_pair"
                pair_detail["surface"] = f"    Graph Pair: {pair_note['edge_role']}"
                pair_detail["status"] = "warning" if pair_note["status"] == "missing" else "ready"
                pair_detail["consumed"] = int(pair_note.get("match_count", 0) or 0)
                pair_detail["total"] = 1
                pair_detail["material_summary"] = "intersection_shared_boundary_graph_pair"
                pair_detail["role_summary"] = f"{pair_note['first_role']}<->{pair_note['second_role']}"
                pair_detail["breakline_role_filter"] = "intersection_shared_boundary_graph_pair"
                pair_detail["graph_edge_refs"] = _shared_boundary_graph_edge_refs_from_audit_row(
                    row,
                    role_filter=str(pair_note.get("edge_role", "") or ""),
                )
                pair_detail["recommended_action"] = (
                    "Review this graph consumer pair, then rebuild surfaces"
                    if pair_note["status"] == "missing"
                    else "No action needed"
                )
                pair_detail["notes"] = _join_review_notes(
                    f"edge_role={pair_note['edge_role']}",
                    f"surface_pair={pair_note['first_role']}<->{pair_note['second_role']}",
                    f"status={pair_note['status']}",
                )
                output.append(pair_detail)
        for raw_graph in list(row.get("graph_audit_rows", []) or []):
            parsed = _parse_intersection_shared_boundary_graph_audit_row(raw_graph)
            if parsed is None:
                continue
            is_internal_seam = (
                str(parsed.get("row_kind", "") or "") == "edge"
                and _intersection_shared_boundary_graph_edge_role_is_internal_seam(str(parsed.get("role", "") or ""))
            )
            if (
                str(parsed.get("row_kind", "") or "") == "edge"
                and _intersection_boundary_loop_source_refs(str(parsed.get("source_refs", "") or ""))
            ):
                owner_refs = _intersection_boundary_owner_source_refs(str(parsed.get("source_refs", "") or ""))
                owner_consumers = _intersection_boundary_owner_consumer_summary(
                    owner_refs,
                    str(parsed.get("refs", "") or ""),
                )
                owner_missing_consumers = _intersection_boundary_owner_missing_consumer_summary(
                    owner_refs,
                    str(parsed.get("role", "") or ""),
                    str(parsed.get("refs", "") or ""),
                )
                boundary_detail = dict(row)
                boundary_detail["row_kind"] = "graph_boundary_loop"
                boundary_detail["surface"] = f"    Boundary Loop Edge: {parsed['role']}"
                boundary_detail["status"] = (
                    "warning"
                    if str(parsed.get("diagnostics", "") or "") or owner_missing_consumers
                    else "ready"
                )
                boundary_detail["consumed"] = 0 if str(boundary_detail["status"]) == "warning" else 1
                boundary_detail["total"] = 1
                boundary_detail["material_summary"] = "intersection_boundary_loop"
                boundary_detail["role_summary"] = str(parsed.get("refs", "") or "")
                boundary_detail["breakline_role_filter"] = "intersection_boundary_loop"
                boundary_detail["graph_edge_refs"] = [str(parsed.get("row_id", "") or "")]
                boundary_detail["recommended_action"] = (
                    "Review boundary-loop shared consumers, then rebuild surfaces"
                    if str(boundary_detail["status"]) == "warning"
                    else "No action needed"
                )
                boundary_detail["notes"] = _join_review_notes(
                    f"edge_id={parsed.get('row_id', '')}",
                    f"edge_role={parsed.get('role', '')}",
                    f"source_refs={parsed.get('source_refs', '')}",
                    f"owner_refs={','.join(owner_refs)}" if owner_refs else "",
                    f"owner_consumers={owner_consumers}" if owner_consumers else "",
                    f"owner_missing_consumers={owner_missing_consumers}" if owner_missing_consumers else "",
                    f"consumers={parsed.get('refs', '')}",
                    f"diagnostics={parsed.get('diagnostics', '')}" if parsed.get("diagnostics", "") else "",
                )
                output.append(boundary_detail)
            if is_internal_seam:
                seam_detail = dict(row)
                seam_detail["row_kind"] = "graph_internal_seam"
                seam_detail["surface"] = f"    Internal Seam: {parsed['role']}"
                seam_detail["status"] = "warning" if str(parsed.get("diagnostics", "") or "") else "ready"
                seam_detail["consumed"] = 0 if str(seam_detail["status"]) == "warning" else 1
                seam_detail["total"] = 1
                seam_detail["material_summary"] = "intersection_shared_boundary_graph_internal_seam"
                seam_detail["role_summary"] = str(parsed.get("refs", "") or "")
                seam_detail["breakline_role_filter"] = "intersection_shared_boundary_graph_internal_seam"
                seam_detail["graph_edge_refs"] = [str(parsed.get("row_id", "") or "")]
                seam_detail["recommended_action"] = (
                    "Review internal cell closure seam, then rebuild surfaces"
                    if str(seam_detail["status"]) == "warning"
                    else "No action needed"
                )
                seam_detail["notes"] = _join_review_notes(
                    f"edge_id={parsed.get('row_id', '')}",
                    f"edge_role={parsed.get('role', '')}",
                    f"consumers={parsed.get('refs', '')}",
                    f"diagnostics={parsed.get('diagnostics', '')}" if parsed.get("diagnostics", "") else "",
                )
                output.append(seam_detail)
            graph_detail = dict(row)
            graph_detail["row_kind"] = f"graph_{parsed['row_kind']}"
            graph_detail["surface"] = f"    Graph {parsed['row_kind']}: {parsed['role']}"
            graph_detail["status"] = "warning" if str(parsed.get("diagnostics", "") or "") or int(parsed.get("open_count", 0) or 0) else "ready"
            graph_detail["consumed"] = 0 if str(graph_detail["status"]) == "warning" else 1
            graph_detail["total"] = 1
            graph_detail["material_summary"] = "intersection_shared_boundary_graph"
            graph_detail["role_summary"] = str(parsed.get("refs", "") or "")
            graph_detail["breakline_role_filter"] = "intersection_shared_boundary_graph"
            if str(parsed.get("row_kind", "") or "") == "edge":
                graph_detail["graph_edge_refs"] = [str(parsed.get("row_id", "") or "")]
            elif str(parsed.get("row_kind", "") or "") == "cell":
                graph_detail["graph_edge_refs"] = [
                    value.strip()
                    for value in str(parsed.get("refs", "") or "").split(",")
                    if value.strip()
                ]
            graph_detail["recommended_action"] = (
                "Review this graph boundary, then rebuild surfaces"
                if str(graph_detail["status"]) == "warning"
                else "No action needed"
            )
            graph_detail["notes"] = _join_review_notes(
                f"id={parsed.get('row_id', '')}",
                f"refs={parsed.get('refs', '')}" if parsed.get("refs", "") else "",
                f"diagnostics={parsed.get('diagnostics', '')}" if parsed.get("diagnostics", "") else "",
            )
            output.append(graph_detail)
        cell_count = int(row.get("cell_count", 0) or 0)
        if cell_count:
            detail = dict(row)
            detail["row_kind"] = "cell"
            detail["surface"] = "  Cell Audit: Intersection Slope Face"
            detail["consumed"] = int(row.get("cell_ready_count", 0) or 0)
            detail["total"] = cell_count
            detail["material_summary"] = "intersection_slope_face_cell"
            detail["role_summary"] = (
                f"ready={int(row.get('cell_ready_count', 0) or 0)}, "
                f"open={int(row.get('cell_open_count', 0) or 0)}, "
                f"missing_edge={int(row.get('cell_missing_edge_count', 0) or 0)}, "
                f"triangles={int(row.get('cell_triangle_count', 0) or 0)}"
            )
            detail["breakline_role_filter"] = "intersection_slope_face_cell"
            detail["recommended_action"] = (
                "Review Intersection Slope Face cells, then rebuild"
                if int(row.get("cell_open_count", 0) or 0) or int(row.get("cell_missing_edge_count", 0) or 0)
                else "No action needed"
            )
            output.append(detail)
            for raw_cell in list(row.get("cell_audit_rows", []) or []):
                parsed = _parse_intersection_slope_face_cell_audit_row(raw_cell)
                if parsed is None:
                    continue
                cell_detail = dict(row)
                cell_detail["row_kind"] = "cell_detail"
                cell_detail["surface"] = f"    Cell: {parsed['cell_role']}"
                cell_detail["status"] = "warning" if int(parsed.get("open_count", 0) or 0) or int(parsed.get("missing_edge_count", 0) or 0) else str(parsed.get("status", "") or "ready")
                cell_detail["consumed"] = 0 if str(cell_detail["status"]) == "warning" else 1
                cell_detail["total"] = 1
                cell_detail["material_summary"] = "intersection_slope_face_cell"
                cell_detail["role_summary"] = str(parsed.get("boundary_refs", "") or "")
                cell_detail["breakline_role_filter"] = "intersection_slope_face_cell"
                cell_detail["recommended_action"] = (
                    "Review this cell boundary refs, then rebuild"
                    if str(cell_detail["status"]) == "warning"
                    else "No action needed"
                )
                cell_detail["notes"] = _join_review_notes(
                    f"cell_id={parsed.get('cell_id', '')}",
                    f"open={parsed.get('open_count', 0)}",
                    f"missing_edge={parsed.get('missing_edge_count', 0)}",
                    f"points={parsed.get('point_count', 0)}",
                    f"diagnostics={parsed.get('diagnostics', '')}" if parsed.get("diagnostics", "") else "",
                )
                output.append(cell_detail)
    return output


def _breakline_audit_surface_row_focuses_source_only(row: dict[str, object]) -> bool:
    """Return True when a surface summary row should not create overlay geometry."""

    if str(row.get("row_kind", "") or "") not in {"", "surface"}:
        return False
    role = str(row.get("role", "") or "")
    if role in {"intersection", "intersection_slope"}:
        return True
    if role in {"design", "subgrade", "daylight"} and (
        str(row.get("roundabout_clip_boundary_role", "") or "")
        or str(row.get("roundabout_clip_boundary_status", "") or "")
    ):
        return True
    return False


def _boundary_loop_near_kept_warning(role: str, *, near_kept_count: int, tested_triangle_count: int) -> bool:
    if str(role or "") not in {"design", "daylight"}:
        return False
    if int(tested_triangle_count or 0) <= 0:
        return False
    return int(near_kept_count or 0) >= _boundary_loop_near_kept_warning_threshold(tested_triangle_count)


def _boundary_loop_near_kept_warning_threshold(tested_triangle_count: int) -> int:
    return max(30, int(math.ceil(float(tested_triangle_count or 0) * 0.50)))


def _intersection_shared_boundary_graph_edge_role_is_internal_seam(role: str) -> bool:
    return str(role or "") in {"upper_transition_internal_seam", "cell_closure_internal_seam"}


def _boundary_loop_owner_summary_display_rows(row: dict[str, object]) -> list[dict[str, object]]:
    owner_rows: dict[str, dict[str, object]] = {}
    for raw_graph in list(row.get("graph_audit_rows", []) or []):
        parsed = _parse_intersection_shared_boundary_graph_audit_row(raw_graph)
        if (
            parsed is None
            or str(parsed.get("row_kind", "") or "") != "edge"
            or not _intersection_boundary_loop_source_refs(str(parsed.get("source_refs", "") or ""))
        ):
            continue
        owner_refs = _intersection_boundary_owner_source_refs(str(parsed.get("source_refs", "") or ""))
        if not owner_refs:
            continue
        consumers = {
            str(value or "").strip()
            for value in str(parsed.get("refs", "") or "").split(",")
            if str(value or "").strip()
        }
        missing_summary = _intersection_boundary_owner_missing_consumer_summary(
            owner_refs,
            str(parsed.get("role", "") or ""),
            str(parsed.get("refs", "") or ""),
        )
        for owner_ref in owner_refs:
            owner = owner_rows.setdefault(
                owner_ref,
                {"edge_count": 0, "consumers": set(), "missing": [], "roles": set(), "edge_refs": []},
            )
            owner["edge_count"] = int(owner.get("edge_count", 0) or 0) + 1
            owner["consumers"].update(consumers)
            owner["roles"].add(str(parsed.get("role", "") or ""))
            owner["edge_refs"].append(str(parsed.get("row_id", "") or ""))
            if missing_summary:
                owner["missing"].append(missing_summary)
    output: list[dict[str, object]] = []
    for owner_ref in sorted(owner_rows):
        owner = owner_rows[owner_ref]
        missing = _unique_text_values([str(value or "") for value in list(owner.get("missing", []) or []) if str(value or "")])
        consumers = sorted(str(value or "") for value in owner.get("consumers", set()) if str(value or ""))
        roles = sorted(str(value or "") for value in owner.get("roles", set()) if str(value or ""))
        edge_refs = _unique_text_values([str(value or "") for value in list(owner.get("edge_refs", []) or []) if str(value or "")])
        detail = dict(row)
        detail["row_kind"] = "graph_boundary_owner"
        detail["surface"] = f"    Boundary Owner: {owner_ref}"
        detail["status"] = "warning" if missing else "ready"
        detail["consumed"] = int(owner.get("edge_count", 0) or 0)
        detail["total"] = int(owner.get("edge_count", 0) or 0)
        detail["material_summary"] = "intersection_boundary_owner"
        detail["role_summary"] = (
            f"edges={int(owner.get('edge_count', 0) or 0)}, "
            f"roles={','.join(roles)}, consumers={'+'.join(consumers) if consumers else 'none'}"
        )
        detail["breakline_role_filter"] = "intersection_boundary_owner"
        detail["graph_edge_refs"] = edge_refs
        detail["recommended_action"] = (
            "Review owner boundary-loop consumers, then rebuild surfaces"
            if missing
            else "No action needed"
        )
        detail["notes"] = _join_review_notes(
            f"owner_ref={owner_ref}",
            f"edge_refs={','.join(edge_refs)}",
            f"roles={','.join(roles)}",
            f"consumers={'+'.join(consumers) if consumers else 'none'}",
            f"owner_missing_consumers={';'.join(missing)}" if missing else "",
        )
        output.append(detail)
    return output


def _shared_boundary_graph_edge_refs_from_audit_row(
    row: dict[str, object],
    *,
    role_filter: str = "",
    source_ref_filter: str = "",
) -> list[str]:
    refs: list[str] = []
    role_text = str(role_filter or "").strip()
    source_text = str(source_ref_filter or "").strip()
    for raw_graph in list(row.get("graph_audit_rows", []) or []):
        parsed = _parse_intersection_shared_boundary_graph_audit_row(raw_graph)
        if parsed is None or str(parsed.get("row_kind", "") or "") != "edge":
            continue
        if role_text and str(parsed.get("role", "") or "") != role_text:
            continue
        if source_text and source_text not in str(parsed.get("source_refs", "") or ""):
            continue
        edge_id = str(parsed.get("row_id", "") or "").strip()
        if edge_id:
            refs.append(edge_id)
    return _unique_text_values(refs)


def _attach_intersection_boundary_owner_preview_metadata(obj, graph_audit_rows: list[str]) -> None:
    if obj is None:
        return
    owner_rows = _boundary_loop_owner_summary_display_rows({"graph_audit_rows": list(graph_audit_rows or [])})
    owner_refs: list[str] = []
    serialized_rows: list[str] = []
    warning_count = 0
    ready_count = 0
    for row in owner_rows:
        notes = str(row.get("notes", "") or "")
        owner_ref = ""
        for part in notes.split(";"):
            text = str(part or "").strip()
            if text.startswith("owner_ref="):
                owner_ref = text.split("=", 1)[1].strip()
                break
        if owner_ref:
            owner_refs.append(owner_ref)
        status = str(row.get("status", "") or "missing")
        if status == "ready":
            ready_count += 1
        else:
            warning_count += 1
        serialized_rows.append(
            "|".join(
                [
                    _audit_field(owner_ref),
                    _audit_field(status),
                    _audit_field(str(row.get("consumed", "") or "0")),
                    _audit_field(str(row.get("total", "") or "0")),
                    _audit_field(str(row.get("role_summary", "") or "")),
                    _audit_field(notes),
                ]
            )
        )
    status = "ready" if owner_rows and warning_count == 0 else "warning" if owner_rows else "missing"
    _set_preview_property(obj, "IntersectionBoundaryOwnerStatus", status)
    _set_preview_integer_property(obj, "IntersectionBoundaryOwnerCount", len(owner_rows))
    _set_preview_integer_property(obj, "IntersectionBoundaryOwnerReadyCount", ready_count)
    _set_preview_integer_property(obj, "IntersectionBoundaryOwnerWarningCount", warning_count)
    _set_preview_string_list_property(obj, "IntersectionBoundaryOwnerRefs", _unique_text_values(owner_refs))
    _set_preview_string_list_property(obj, "IntersectionBoundaryOwnerAuditRows", serialized_rows)
    _set_preview_property(
        obj,
        "IntersectionBoundaryOwnerSummary",
        f"owners={len(owner_rows)}; ready={ready_count}; warning={warning_count}",
    )


def _attach_intersection_slope_face_owner_fill_readiness_metadata(obj) -> None:
    if obj is None:
        return
    owner_status = str(getattr(obj, "IntersectionBoundaryOwnerStatus", "") or "")
    owner_count = int(getattr(obj, "IntersectionBoundaryOwnerCount", 0) or 0)
    triangle_count = int(getattr(obj, "TriangleCount", 0) or 0)
    cell_triangles = int(getattr(obj, "IntersectionSlopeFaceCellTriangleCount", 0) or 0)
    perimeter_triangles = int(getattr(obj, "CurbReturnSlopeFacePerimeterTriangleCount", 0) or 0)
    graph_triangles = int(getattr(obj, "IntersectionSharedBoundaryGraphSurfaceTriangleCount", 0) or 0)
    transition_triangles = int(getattr(obj, "IntersectionBoundaryLoopTransitionTriangleCount", 0) or 0)
    strip_triangles = int(getattr(obj, "IntersectionSlopeFaceBoundaryStripTriangleCount", 0) or 0)
    upper_panel_triangles = int(getattr(obj, "IntersectionUpperSlopeFacePanelTriangleCount", 0) or 0)
    graph_surface_boundary_refs = {
        str(value or "").strip()
        for value in list(getattr(obj, "IntersectionSharedBoundaryGraphSurfaceBoundaryRefs", []) or [])
        if str(value or "").strip()
    }
    linked_owner_refs: list[str] = []
    unlinked_owner_refs: list[str] = []
    for raw in list(getattr(obj, "IntersectionBoundaryOwnerAuditRows", []) or []):
        owner_ref, edge_refs = _parse_intersection_boundary_owner_audit_row_for_fill(raw)
        if not owner_ref:
            continue
        if edge_refs and graph_surface_boundary_refs.intersection(edge_refs):
            linked_owner_refs.append(owner_ref)
        else:
            unlinked_owner_refs.append(owner_ref)
    diagnostics: list[str] = []
    if owner_status != "ready":
        diagnostics.append(f"owner_status={owner_status or 'missing'}")
    if owner_count <= 0:
        diagnostics.append("owner_refs_missing")
    if triangle_count <= 0:
        diagnostics.append("surface_triangles_missing")
    if max(cell_triangles, perimeter_triangles, graph_triangles, transition_triangles, strip_triangles, upper_panel_triangles) <= 0:
        diagnostics.append("owner_fill_components_missing")
    status = "ready" if not diagnostics else "warning"
    linked_count = len(_unique_text_values(linked_owner_refs))
    unlinked_count = len(_unique_text_values(unlinked_owner_refs))
    graph_fill_link_status = (
        "ready"
        if linked_count > 0
        else "not_applicable"
        if graph_triangles > 0 and graph_surface_boundary_refs
        else "missing"
        if graph_triangles > 0
        else "not_evaluated"
    )
    summary = (
        f"owner_status={owner_status or 'missing'}; owners={owner_count}; triangles={triangle_count}; "
        f"cell_triangles={cell_triangles}; perimeter_triangles={perimeter_triangles}; "
        f"graph_triangles={graph_triangles}; transition_triangles={transition_triangles}; "
        f"strip_triangles={strip_triangles}; upper_panel_triangles={upper_panel_triangles}; "
        f"graph_link_status={graph_fill_link_status}; "
        f"graph_boundary_refs={len(graph_surface_boundary_refs)}; graph_linked_owners={linked_count}; "
        f"graph_unlinked_owners={unlinked_count}; "
        f"diagnostics={';'.join(diagnostics) if diagnostics else 'none'}"
    )
    _set_preview_property(obj, "IntersectionSlopeFaceOwnerFillReadinessStatus", status)
    _set_preview_property(obj, "IntersectionSlopeFaceOwnerFillReadinessSummary", summary)
    _set_preview_integer_property(obj, "IntersectionSlopeFaceOwnerFillTriangleCount", triangle_count)
    _set_preview_integer_property(
        obj,
        "IntersectionSlopeFaceOwnerFillComponentTriangleCount",
        cell_triangles + perimeter_triangles + graph_triangles + transition_triangles + strip_triangles + upper_panel_triangles,
    )
    _set_preview_property(obj, "IntersectionSlopeFaceOwnerGraphFillLinkStatus", graph_fill_link_status)
    _set_preview_integer_property(obj, "IntersectionSlopeFaceOwnerGraphFillBoundaryRefCount", len(graph_surface_boundary_refs))
    _set_preview_integer_property(obj, "IntersectionSlopeFaceOwnerGraphFillLinkedCount", linked_count)
    _set_preview_integer_property(obj, "IntersectionSlopeFaceOwnerGraphFillUnlinkedCount", unlinked_count)
    _set_preview_string_list_property(obj, "IntersectionSlopeFaceOwnerGraphFillLinkedRefs", _unique_text_values(linked_owner_refs))
    _set_preview_string_list_property(obj, "IntersectionSlopeFaceOwnerGraphFillUnlinkedRefs", _unique_text_values(unlinked_owner_refs))


def _parse_intersection_boundary_owner_audit_row_for_fill(raw: object) -> tuple[str, set[str]]:
    parts = str(raw or "").split("|")
    if len(parts) < 6:
        return ("", set())
    owner_ref = str(parts[0] or "").strip()
    notes = str(parts[5] or "")
    edge_refs: set[str] = set()
    for part in notes.split(";"):
        text = str(part or "").strip()
        if not text.startswith("edge_refs="):
            continue
        for value in text.split("=", 1)[1].split(","):
            ref = str(value or "").strip()
            if ref:
                edge_refs.add(ref)
    return (owner_ref, edge_refs)


def _shared_breakline_summary_count_items(summary: str) -> list[tuple[str, int]]:
    items: list[tuple[str, int]] = []
    for part in str(summary or "").split(","):
        text = str(part or "").strip()
        if not text or "=" not in text:
            continue
        key, value = text.split("=", 1)
        key = key.strip()
        try:
            count = int(str(value or "0").strip() or 0)
        except Exception:
            count = 0
        if key:
            items.append((key, count))
    return items


def corridor_build_review_outcome_matrix() -> list[dict[str, str]]:
    """Return the deterministic Build Parametric review status meanings."""

    return [
        {"status": str(status), "meaning": str(meaning)}
        for status, meaning in CORRIDOR_BUILD_REVIEW_OUTCOME_MATRIX
    ]


def _with_subassembly_surface_role_review_note(row: dict[str, object], document) -> dict[str, object]:
    surface_role = _review_surface_role_for_result_role(str(row.get("role", "") or ""))
    if not surface_role:
        return row
    note = _subassembly_surface_role_review_note(document, surface_role=surface_role)
    if not note:
        return row
    output = dict(row)
    existing = str(output.get("notes", "") or "").strip()
    output["notes"] = f"{existing} | {note}" if existing else note
    return output


def _review_surface_role_for_result_role(role: str) -> str:
    if role == "design":
        return "design_surface"
    if role == "subgrade":
        return "subgrade_surface"
    if role == "daylight":
        return "slope_face_surface"
    if role == "drainage":
        return "drainage_surface"
    return ""


def _subassembly_surface_role_review_note(document, *, surface_role: str) -> str:
    applied = to_applied_section_set(find_v1_applied_section_set(document))
    if applied is None:
        return ""
    sections = list(getattr(applied, "sections", []) or [])
    if not sections:
        return ""
    linked_section_count = 0
    link_count = 0
    subassembly_refs: list[str] = []
    preset_refs: list[str] = []
    preset_statuses: list[str] = []
    role = str(surface_role or "").strip()
    for section in sections:
        section_has_role = False
        subassembly_by_id = {
            str(getattr(row, "subassembly_id", "") or "").strip(): row
            for row in list(getattr(section, "subassembly_rows", []) or [])
            if str(getattr(row, "subassembly_id", "") or "").strip()
        }
        for link in list(getattr(section, "subassembly_link_rows", []) or []):
            if str(getattr(link, "surface_role", "") or "").strip() != role:
                continue
            section_has_role = True
            link_count += 1
            subassembly_ref = str(getattr(link, "subassembly_ref", "") or "")
            subassembly_refs.append(subassembly_ref)
            subassembly = subassembly_by_id.get(subassembly_ref.strip())
            if subassembly is not None:
                preset_ref = str(getattr(subassembly, "preset_ref", "") or "").strip()
                preset_status = str(getattr(subassembly, "preset_status", "") or "").strip()
                if preset_ref:
                    preset_refs.append(preset_ref)
                if preset_status:
                    preset_statuses.append(preset_status)
                elif preset_ref:
                    preset_statuses.append("linked")
                else:
                    preset_statuses.append("snapshot")
        if section_has_role:
            linked_section_count += 1
    if not link_count:
        return f"subassembly role={role}: not linked; legacy point-role fallback"
    refs = _unique_refs(subassembly_refs)
    ref_note = f"; refs={','.join(_display_source_ref(ref) for ref in refs[:3])}" if refs else ""
    if len(refs) > 3:
        ref_note += f"; +{len(refs) - 3} more"
    preset_ref_rows = _unique_refs(preset_refs)
    preset_ref_note = f"; preset_refs={','.join(_display_source_ref(ref) for ref in preset_ref_rows[:3])}" if preset_ref_rows else ""
    if len(preset_ref_rows) > 3:
        preset_ref_note += f"; +{len(preset_ref_rows) - 3} more presets"
    preset_status_note = ""
    preset_status_counts = _text_count_map(preset_statuses)
    if preset_status_counts:
        preset_status_note = f"; preset_status={_format_count_summary(preset_status_counts)}"
    coverage = (
        f"subassembly role={role}: linked sections={linked_section_count}/{len(sections)}, "
        f"links={link_count}{ref_note}{preset_ref_note}{preset_status_note}"
    )
    if linked_section_count < len(sections):
        coverage += "; fallback used for unlinked sections"
    return coverage


def corridor_subassembly_guided_review_summary(document=None) -> dict[str, object]:
    """Return a compact summary of evaluated Assembly/Subassembly output rows."""

    doc = document or (getattr(App, "ActiveDocument", None) if App is not None else None)
    applied = to_applied_section_set(find_v1_applied_section_set(doc))
    if applied is None:
        return {
            "status": "missing",
            "focus": "Subassemblies",
            "notes": "Applied Sections are not built yet.",
        }
    sections = _station_ordered_applied_sections(applied)
    if not sections:
        return {
            "status": "missing",
            "focus": "Subassemblies",
            "notes": "No Applied Section rows are available.",
        }

    subassembly_count = 0
    point_count = 0
    link_count = 0
    shape_count = 0
    kind_counts: dict[str, int] = {}
    role_counts: dict[str, int] = {}
    preset_status_counts: dict[str, int] = {}
    diagnostic_count = 0

    for section in sections:
        subassembly_rows = list(getattr(section, "subassembly_rows", []) or [])
        point_rows = list(getattr(section, "subassembly_point_rows", []) or [])
        link_rows = list(getattr(section, "subassembly_link_rows", []) or [])
        shape_rows = list(getattr(section, "subassembly_shape_rows", []) or [])
        subassembly_count += len(subassembly_rows)
        point_count += len(point_rows)
        link_count += len(link_rows)
        shape_count += len(shape_rows)
        for row in subassembly_rows:
            kind = str(getattr(row, "kind", "") or "unknown").strip() or "unknown"
            kind_counts[kind] = kind_counts.get(kind, 0) + 1
            preset_ref = str(getattr(row, "preset_ref", "") or "").strip()
            preset_status = str(getattr(row, "preset_status", "") or "").strip()
            if not preset_status:
                preset_status = "linked" if preset_ref else "snapshot"
            preset_status_counts[preset_status] = preset_status_counts.get(preset_status, 0) + 1
            diagnostic_count += len(list(getattr(row, "diagnostics", []) or []))
        for row in link_rows:
            role = str(getattr(row, "surface_role", "") or "unassigned").strip() or "unassigned"
            role_counts[role] = role_counts.get(role, 0) + 1
            diagnostic_count += len(list(getattr(row, "diagnostics", []) or []))

    kind_note = _format_count_summary(kind_counts)
    role_note = _format_count_summary(role_counts)
    preset_note = _format_count_summary(preset_status_counts)
    ditch_count = int(kind_counts.get("ditch", 0) or 0)
    drainage_link_count = int(role_counts.get("drainage_surface", 0) or 0)
    status = "ready"
    warnings: list[str] = []
    if not subassembly_count:
        status = "missing"
        warnings.append("no evaluated subassemblies")
    if ditch_count and not drainage_link_count:
        status = "warning"
        warnings.append("ditch has no drainage_surface links")
    if diagnostic_count:
        status = "warning" if status != "missing" else status
        warnings.append(f"diagnostics={diagnostic_count}")
    notes = (
        f"sections={len(sections)}, subassemblies={subassembly_count}, "
        f"points={point_count}, links={link_count}, shapes={shape_count}; "
        f"kinds={kind_note}; roles={role_note}; presets={preset_note}"
    )
    if warnings:
        notes = f"{notes}; " + "; ".join(warnings)
    return {
        "status": status,
        "focus": "Assembly/Subassembly Surfaces",
        "notes": notes,
        "preset_status_counts": preset_status_counts,
    }


def corridor_subassembly_kind_guided_review_rows(document=None) -> list[dict[str, object]]:
    """Return guided-review rows split by evaluated Subassembly kind."""

    doc = document or (getattr(App, "ActiveDocument", None) if App is not None else None)
    applied = to_applied_section_set(find_v1_applied_section_set(doc))
    if applied is None:
        return []
    sections = _station_ordered_applied_sections(applied)
    summaries: dict[str, dict[str, object]] = {}
    for section in sections:
        rows = {
            str(getattr(row, "subassembly_id", "") or "").strip(): row
            for row in list(getattr(section, "subassembly_rows", []) or [])
            if str(getattr(row, "subassembly_id", "") or "").strip()
        }
        link_rows = list(getattr(section, "subassembly_link_rows", []) or [])
        shape_rows = list(getattr(section, "subassembly_shape_rows", []) or [])
        for subassembly_id, subassembly in rows.items():
            kind = str(getattr(subassembly, "kind", "") or "unknown").strip() or "unknown"
            summary = summaries.setdefault(
                kind,
                {
                    "kind": kind,
                    "section_count": 0,
                    "subassembly_count": 0,
                    "point_count": 0,
                    "link_count": 0,
                    "shape_count": 0,
                    "surface_roles": {},
                    "preset_statuses": {},
                    "preset_refs": [],
                    "diagnostic_count": 0,
                },
            )
            summary["section_count"] = int(summary.get("section_count", 0) or 0) + 1
            summary["subassembly_count"] = int(summary.get("subassembly_count", 0) or 0) + 1
            preset_ref = str(getattr(subassembly, "preset_ref", "") or "").strip()
            preset_status = str(getattr(subassembly, "preset_status", "") or "").strip()
            if not preset_status:
                preset_status = "linked" if preset_ref else "snapshot"
            preset_statuses = summary.setdefault("preset_statuses", {})
            preset_statuses[preset_status] = int(preset_statuses.get(preset_status, 0) or 0) + 1
            if preset_ref:
                preset_refs = summary.setdefault("preset_refs", [])
                if preset_ref not in preset_refs:
                    preset_refs.append(preset_ref)
            summary["diagnostic_count"] = int(summary.get("diagnostic_count", 0) or 0) + len(list(getattr(subassembly, "diagnostics", []) or []))
            point_count = 0
            for point in list(getattr(section, "subassembly_point_rows", []) or []):
                if str(getattr(point, "subassembly_ref", "") or "").strip() == subassembly_id:
                    point_count += 1
                    summary["diagnostic_count"] = int(summary.get("diagnostic_count", 0) or 0) + len(list(getattr(point, "diagnostics", []) or []))
            summary["point_count"] = int(summary.get("point_count", 0) or 0) + point_count
            for link in link_rows:
                if str(getattr(link, "subassembly_ref", "") or "").strip() != subassembly_id:
                    continue
                summary["link_count"] = int(summary.get("link_count", 0) or 0) + 1
                role = str(getattr(link, "surface_role", "") or "unassigned").strip() or "unassigned"
                role_counts = summary.setdefault("surface_roles", {})
                role_counts[role] = int(role_counts.get(role, 0) or 0) + 1
                summary["diagnostic_count"] = int(summary.get("diagnostic_count", 0) or 0) + len(list(getattr(link, "diagnostics", []) or []))
            for shape in shape_rows:
                if str(getattr(shape, "subassembly_ref", "") or "").strip() == subassembly_id:
                    summary["shape_count"] = int(summary.get("shape_count", 0) or 0) + 1

    rows: list[dict[str, object]] = []
    ordered_kinds = [
        kind
        for kind in SUBASSEMBLY_GUIDED_REVIEW_KIND_ORDER
        if kind in summaries
    ] + sorted(kind for kind in summaries if kind not in SUBASSEMBLY_GUIDED_REVIEW_KIND_ORDER)
    for kind in ordered_kinds:
        # Side Slope is reviewed through its accepted daylight/intersection result,
        # not through partial Applied Section point rows.
        if kind == "side_slope":
            continue
        summary = summaries[kind]
        roles = dict(summary.get("surface_roles", {}) or {})
        preset_statuses = dict(summary.get("preset_statuses", {}) or {})
        preset_refs = list(summary.get("preset_refs", []) or [])
        status = "ready"
        warnings: list[str] = []
        if int(summary.get("link_count", 0) or 0) <= 0:
            status = "warning"
            warnings.append("no evaluated links")
        if kind in {"ditch", "lined_ditch", "gutter"} and int(roles.get("drainage_surface", 0) or 0) <= 0:
            status = "warning"
            warnings.append("no drainage_surface links")
        if int(summary.get("diagnostic_count", 0) or 0) > 0:
            status = "warning"
            warnings.append(f"diagnostics={int(summary.get('diagnostic_count', 0) or 0)}")
        notes = (
            f"sections={int(summary.get('section_count', 0) or 0)}, "
            f"points={int(summary.get('point_count', 0) or 0)}, "
            f"links={int(summary.get('link_count', 0) or 0)}, "
            f"shapes={int(summary.get('shape_count', 0) or 0)}; "
            f"roles={_format_count_summary(roles)}; "
            f"presets={_format_count_summary(preset_statuses)}"
        )
        if preset_refs:
            notes = f"{notes}; preset_refs={_format_count_summary({ref: 1 for ref in preset_refs})}"
        if warnings:
            notes = f"{notes}; " + "; ".join(warnings)
        rows.append(
            {
                "step_id": f"subassembly_kind:{kind}",
                "title": f"3. {_subassembly_kind_display_name(kind)}",
                "roles": ["centerline", "design", "daylight", "drainage"],
                "status": status,
                "focus": f"{_subassembly_kind_display_name(kind)} Subassembly",
                "notes": notes,
                "preset_statuses": preset_statuses,
                "preset_refs": preset_refs,
            }
        )
    return rows


def _subassembly_kind_display_name(kind: str) -> str:
    text = str(kind or "unknown").strip() or "unknown"
    return " ".join(part.capitalize() for part in text.replace("-", "_").split("_") if part)


def _format_count_summary(counts: dict[str, int], *, limit: int = 5) -> str:
    if not counts:
        return "none"
    rows = sorted(((str(key), int(value)) for key, value in counts.items()), key=lambda item: (-item[1], item[0]))
    text = ", ".join(f"{_display_source_ref(key)}:{value}" for key, value in rows[:limit])
    if len(rows) > limit:
        text += f", +{len(rows) - limit} more"
    return text


def _text_count_map(values: list[str] | tuple[str, ...]) -> dict[str, int]:
    counts: dict[str, int] = {}
    for value in list(values or []):
        text = str(value or "").strip()
        if not text:
            continue
        counts[text] = counts.get(text, 0) + 1
    return counts


def corridor_slope_face_issue_rows(document=None) -> list[dict[str, str]]:
    """Return station-side slope-face issue rows from the corridor daylight preview."""

    doc = document or (getattr(App, "ActiveDocument", None) if App is not None else None)
    obj = doc.getObject("V1CorridorDaylightSurfacePreview") if doc is not None else None
    if obj is None:
        return []
    rows: list[dict[str, str]] = []
    for text in list(getattr(obj, "SlopeFaceIssueRows", []) or []):
        row = _parse_slope_face_issue_row_text(str(text or ""))
        if row:
            row.setdefault("owner_context", "Ordinary road")
            rows.append(row)
    if not rows:
        rows = _parse_slope_face_issue_summary_text(str(getattr(obj, "SlopeFaceIssueStations", "") or ""))
    for row in rows:
        row.setdefault("owner_context", "Ordinary road")
        row["review_status"] = _slope_face_issue_review_status(row)
    return rows


def corridor_build_guided_review_steps(
    document=None,
    *,
    supplemental_sampling_enabled: bool = True,
    supplemental_sampling_max_spacing: float = SUPPLEMENTAL_SAMPLING_MAX_SPACING,
    supplemental_sampling_tangent_delta_deg: float = SUPPLEMENTAL_FRAME_TANGENT_DELTA_THRESHOLD_DEG,
    supplemental_sampling_chord_deviation: float = SUPPLEMENTAL_FRAME_CHORD_DEVIATION_THRESHOLD,
) -> list[dict[str, object]]:
    """Return ordered guided-review rows for the Build Corridor panel."""

    doc = document or (getattr(App, "ActiveDocument", None) if App is not None else None)
    review_by_role = {str(row.get("role", "") or ""): row for row in corridor_build_review_rows(doc)}
    issue_count = len(corridor_slope_face_issue_rows(doc))
    drainage_flow_summary = corridor_drainage_flow_review_summary(doc)
    intersection_summary = corridor_intersection_review_summary(doc)
    subassembly_kind_rows = corridor_subassembly_kind_guided_review_rows(doc)
    rows: list[dict[str, object]] = []
    for step_id, title, roles, default_notes in CORRIDOR_BUILD_GUIDED_REVIEW_STEPS:
        if step_id == "slope_issues":
            daylight = review_by_role.get("daylight", {})
            intersection_slope = review_by_role.get("intersection_slope", {})
            base_status = str(daylight.get("status", "missing") or "missing")
            intersection_status = str(intersection_slope.get("status", "missing") or "missing")
            if base_status == "error" or intersection_status == "error":
                status = "error"
            elif (base_status == "ready" or intersection_status == "ready") and issue_count:
                status = "warning"
            elif base_status == "ready" or intersection_status == "ready":
                status = "ready"
            else:
                status = intersection_status if intersection_status not in {"missing", "empty"} else base_status
            intersection_count = intersection_slope.get("triangle_or_point_count", "")
            intersection_note = f"; intersection slope triangles={intersection_count}" if intersection_count not in {"", None} else ""
            boundary_review_note = _slope_face_boundary_guided_review_suffix(daylight, intersection_slope)
            notes = f"{issue_count} Side Slope diagnostic(s) to review{intersection_note}." if issue_count else f"No Side Slope fallback diagnostics{intersection_note}."
            if boundary_review_note:
                notes = f"{notes} {boundary_review_note}"
            if intersection_status == "ready" and base_status == "ready":
                focus = "Intersection and Corridor Slope Face Surfaces"
            elif intersection_status == "ready":
                focus = "Intersection Slope Face Surface"
            elif base_status == "ready":
                focus = "Slope Face Surface"
            else:
                focus = "Side Slope Result Diagnostic"
        else:
            primary_role = str(list(roles)[-1] if roles else "")
            source = review_by_role.get(primary_role, {})
            status = str(source.get("status", "missing") or "missing")
            notes = default_notes if status == "ready" else str(source.get("notes", "") or "Not built yet.")
            focus = str(source.get("result", title) or title)
            output_path = str(source.get("output_path", "") or "")
            if step_id == "drainage":
                drainage = corridor_drainage_review_summary(doc)
                status = str(drainage.get("status", status) or status)
                notes = str(drainage.get("notes", notes) or notes)
                focus = "Drainage Surface" if source.get("status") == "ready" else "Drainage Diagnostics"
            elif step_id == "drainage_flow":
                status = str(drainage_flow_summary.get("status", status) or status)
                notes = str(drainage_flow_summary.get("notes", default_notes) or default_notes)
                focus = str(drainage_flow_summary.get("focus", "Drainage Flow") or "Drainage Flow")
            elif step_id == "intersections":
                intersection_source = review_by_role.get("intersection", source)
                status = str(intersection_summary.get("status", status) or status)
                notes = str(intersection_summary.get("notes", default_notes) or default_notes)
                focus = str(intersection_summary.get("focus", "Intersections") or "Intersections")
                output_path = str(intersection_source.get("output_path", output_path) or output_path)
        rows.append(
            {
                "step_id": step_id,
                "title": title,
                "roles": list(roles),
                "status": status,
                "focus": focus,
                "output_path": output_path if step_id != "slope_issues" else str(intersection_slope.get("output_path", "") or daylight.get("output_path", "") or ""),
                "notes": notes,
            }
        )
        if step_id == "design":
            rows.extend(subassembly_kind_rows)
    return rows


def _slope_face_boundary_guided_review_suffix(*review_rows: dict[str, object]) -> str:
    boundary_note = _slope_face_boundary_review_note_from_rows(*review_rows)
    if not boundary_note:
        return ""
    return f"boundary_review=intersection_slope_face_boundary_result; {boundary_note}"


def _slope_face_boundary_review_note_from_rows(*review_rows: dict[str, object]) -> str:
    for row in review_rows:
        notes = str((row or {}).get("notes", "") or "")
        marker = "slope_face_boundary="
        index = notes.find(marker)
        if index < 0:
            continue
        tail = notes[index:].strip()
        if " | " in tail:
            tail = tail.split(" | ", 1)[0].strip()
        return tail
    return ""


def _applied_section_supplemental_consumption_summary(applied_section_set) -> dict[str, object]:
    rows = list(getattr(applied_section_set, "station_rows", []) or [])
    kind_counts: dict[str, int] = {}
    supplemental_count = 0
    for row in rows:
        kind = str(getattr(row, "kind", "") or "regular_sample").strip() or "regular_sample"
        kind_counts[kind] = kind_counts.get(kind, 0) + 1
        if "supplemental" in kind.lower():
            supplemental_count += 1
    total = len(rows)
    return {
        "source_section_count": max(total - supplemental_count, 0),
        "supplemental_section_count": supplemental_count,
        "total_section_count": total,
        "kind_counts": kind_counts,
    }


def _format_build_parametric_duration(seconds: float) -> str:
    value = max(0.0, float(seconds or 0.0))
    if value < 10.0:
        return "<10 sec"
    if value < 60.0:
        return f"{int(round(value / 5.0) * 5)} sec"
    minutes = value / 60.0
    if minutes < 10.0:
        return f"{minutes:.1f} min"
    return f"{int(round(minutes))} min"


def _build_parametric_supplemental_apply_estimate(applied_section_set) -> dict[str, object]:
    summary = _applied_section_supplemental_consumption_summary(applied_section_set)
    source_count = int(summary.get("source_section_count", 0) or 0)
    supplemental_count = int(summary.get("supplemental_section_count", 0) or 0)
    total_count = int(summary.get("total_section_count", 0) or 0)
    if supplemental_count <= 0 or total_count <= 0:
        return {
            "source_section_count": source_count,
            "supplemental_section_count": supplemental_count,
            "total_section_count": total_count,
            "min_seconds": 0.0,
            "max_seconds": 0.0,
            "message": "",
        }
    min_seconds = (
        BUILD_PARAMETRIC_ESTIMATE_BASE_SECONDS
        + (total_count * BUILD_PARAMETRIC_ESTIMATE_MIN_PER_SECTION_SECONDS)
        + (supplemental_count * BUILD_PARAMETRIC_ESTIMATE_MIN_PER_SUPPLEMENTAL_SECONDS)
    )
    max_seconds = (
        BUILD_PARAMETRIC_ESTIMATE_BASE_SECONDS
        + (total_count * BUILD_PARAMETRIC_ESTIMATE_MAX_PER_SECTION_SECONDS)
        + (supplemental_count * BUILD_PARAMETRIC_ESTIMATE_MAX_PER_SUPPLEMENTAL_SECONDS)
    )
    min_text = _format_build_parametric_duration(min_seconds)
    max_text = _format_build_parametric_duration(max_seconds)
    duration_text = min_text if min_text == max_text else f"{min_text} - {max_text}"
    return {
        "source_section_count": source_count,
        "supplemental_section_count": supplemental_count,
        "total_section_count": total_count,
        "min_seconds": min_seconds,
        "max_seconds": max_seconds,
        "duration_text": duration_text,
        "message": (
            "Supplemental Applied Sections detected.\n"
            f"Applied Sections: source {source_count}, supplemental {supplemental_count}, total {total_count}\n"
            f"Estimated Build Parametric time: about {duration_text}\n"
            "Dense supplemental rows can slow surface, drainage, and breakline review generation."
        ),
    }


def _build_parametric_compatibility_supplemental_sampling_enabled(
    document=None,
    *,
    applied_section_set=None,
    supplemental_sampling_max_spacing: float = SUPPLEMENTAL_SAMPLING_MAX_SPACING,
    supplemental_sampling_tangent_delta_deg: float = SUPPLEMENTAL_FRAME_TANGENT_DELTA_THRESHOLD_DEG,
    supplemental_sampling_chord_deviation: float = SUPPLEMENTAL_FRAME_CHORD_DEVIATION_THRESHOLD,
) -> bool:
    """Return false because Build Corridor no longer creates hidden supplemental frames."""

    return False


def _build_corridor_potential_supplemental_sampling_summary(
    document=None,
    *,
    applied_section_set=None,
    supplemental_sampling_max_spacing: float = SUPPLEMENTAL_SAMPLING_MAX_SPACING,
    supplemental_sampling_tangent_delta_deg: float = SUPPLEMENTAL_FRAME_TANGENT_DELTA_THRESHOLD_DEG,
    supplemental_sampling_chord_deviation: float = SUPPLEMENTAL_FRAME_CHORD_DEVIATION_THRESHOLD,
) -> dict[str, object]:
    """Return diagnostic-only potential supplemental frame counts for stale AppliedSectionSet data."""

    doc = document or (getattr(App, "ActiveDocument", None) if App is not None else None)
    applied = applied_section_set or (to_applied_section_set(find_v1_applied_section_set(doc)) if doc is not None else None)
    if applied is None:
        return {}
    if int(_applied_section_supplemental_consumption_summary(applied).get("supplemental_section_count", 0) or 0) > 0:
        return {}
    sections = list(getattr(applied, "sections", []) or [])
    if len(sections) < 2:
        return {}
    try:
        return supplemental_sampling_summary(
            sections,
            max_spacing=float(supplemental_sampling_max_spacing or SUPPLEMENTAL_SAMPLING_MAX_SPACING),
            tangent_delta_threshold_deg=float(supplemental_sampling_tangent_delta_deg or SUPPLEMENTAL_FRAME_TANGENT_DELTA_THRESHOLD_DEG),
            chord_deviation_threshold=float(supplemental_sampling_chord_deviation or SUPPLEMENTAL_FRAME_CHORD_DEVIATION_THRESHOLD),
            frame_resolver=_corridor_supplemental_frame_resolver(doc),
        )
    except Exception:
        return {}


def _build_corridor_effective_hidden_supplemental_sampling_enabled(
    document=None,
    *,
    applied_section_set=None,
    requested: bool,
    supplemental_sampling_max_spacing: float = SUPPLEMENTAL_SAMPLING_MAX_SPACING,
    supplemental_sampling_tangent_delta_deg: float = SUPPLEMENTAL_FRAME_TANGENT_DELTA_THRESHOLD_DEG,
    supplemental_sampling_chord_deviation: float = SUPPLEMENTAL_FRAME_CHORD_DEVIATION_THRESHOLD,
) -> bool:
    """Build Corridor no longer performs hidden supplemental sampling."""

    return False


def corridor_intersection_review_summary(document=None) -> dict[str, object]:
    """Return a compact Build Parametric intersection readiness summary."""

    patch_summary = corridor_intersection_patch_prerequisite_summary(document)
    rows = [
        row
        for row in corridor_region_boundary_rows(document)
        if str(row.get("intersection", "") or "").strip() not in {"", "-"}
    ]
    if not rows:
        return {
            "status": "missing",
            "notes": str(patch_summary.get("notes", "") or "No intersection-controlled Region rows are available."),
            "focus": "Intersections",
        }
    diagnostic_count = sum(int(row.get("intersection_diagnostic_count", 0) or 0) for row in rows)
    patch_status = str(patch_summary.get("status", "") or "")
    patch_notes = str(patch_summary.get("notes", "") or "").strip()
    if diagnostic_count:
        return {
            "status": "warning",
            "notes": f"{len(rows)} intersection Region row(s); {diagnostic_count} intersection diagnostic(s). {patch_notes}".strip(),
            "focus": "Intersection Region diagnostics",
        }
    if patch_status in {"missing", "warning", "empty"}:
        return {
            "status": "warning" if patch_status != "missing" else "missing",
            "notes": patch_notes or f"{len(rows)} intersection-controlled Region row(s); patch prerequisites need review.",
            "focus": "Intersection Patch prerequisites",
        }
    boundary_review = _intersection_patch_boundary_review_notes(document)
    exclusion_notes = _intersection_exclusion_review_notes(document)
    grading_notes = _intersection_grading_review_notes(document)
    surface_quality_review = _intersection_surface_quality_review_notes(document)
    if int(boundary_review.get("diagnostic_count", 0) or 0) or int(surface_quality_review.get("diagnostic_count", 0) or 0):
        focus = (
            "Intersection Patch Boundary diagnostics"
            if int(boundary_review.get("diagnostic_count", 0) or 0)
            else "Intersection Surface diagnostics"
        )
        return {
            "status": "warning",
            "notes": _join_review_notes(
                patch_notes or f"{len(rows)} intersection-controlled Region row(s) reflected in Applied Sections.",
                grading_notes,
                str(surface_quality_review.get("notes", "") or ""),
                str(boundary_review.get("notes", "") or ""),
                exclusion_notes,
            ),
            "focus": focus,
        }
    return {
        "status": "ready",
        "notes": _join_review_notes(
            patch_notes or f"{len(rows)} intersection-controlled Region row(s) reflected in Applied Sections.",
            grading_notes,
            str(surface_quality_review.get("notes", "") or ""),
            str(boundary_review.get("notes", "") or ""),
            exclusion_notes,
        ),
        "focus": "Intersection Regions",
    }


def corridor_intersection_patch_prerequisite_summary(document=None) -> dict[str, object]:
    """Return display-ready readiness information for future intersection surface patches."""

    doc = document or (getattr(App, "ActiveDocument", None) if App is not None else None)
    result = corridor_intersection_patch_prerequisite_result(document)
    diagnostic_count = len(list(result.diagnostic_rows or ()))
    supplemental_summary = _intersection_supplemental_applied_section_summary(
        to_applied_section_set(find_v1_applied_section_set(doc)),
        intersection_id=str(getattr(result, "intersection_id", "") or ""),
        control_region_refs=tuple(getattr(result, "control_region_refs", ()) or ()),
    )
    supplemental_notes = str(supplemental_summary.get("notes", "") or "")
    if result.status == "ready":
        notes = (
            f"Intersection patch prerequisites ready for {result.intersection_id}; "
            f"alignments={result.participating_alignment_count}, "
            f"control regions={result.control_region_count}, "
            f"sections={result.applied_section_count}, "
            f"tie-in edges={result.tie_in_edge_count}, "
            f"boundary points={result.boundary_point_count}."
        )
    elif result.status == "warning":
        notes = (
            f"Intersection patch prerequisites partial for {result.intersection_id or 'intersection'}; "
            f"diagnostics={diagnostic_count}, alignments={result.participating_alignment_count}, "
            f"control regions={result.control_region_count}, sections={result.applied_section_count}, "
            f"tie-in edges={result.tie_in_edge_count}."
        )
    else:
        notes = "Intersection Surface Patch prerequisites are missing."
        if diagnostic_count:
            notes = f"{notes} Diagnostics: {', '.join(result.diagnostic_rows[:3])}."
    if supplemental_notes and result.intersection_id:
        notes = f"{notes} {supplemental_notes}."
    return {
        "status": result.status,
        "intersection_id": result.intersection_id,
        "intersection_kind": result.intersection_kind,
        "participating_alignment_count": result.participating_alignment_count,
        "control_region_count": result.control_region_count,
        "applied_section_count": result.applied_section_count,
        "tie_in_edge_count": result.tie_in_edge_count,
        "boundary_point_count": result.boundary_point_count,
        "diagnostic_count": diagnostic_count,
        "diagnostics": list(result.diagnostic_rows or ()),
        "notes": notes,
        "focus": "Intersection Surface Patch prerequisites",
    }


def _intersection_exclusion_review_notes(document=None) -> str:
    doc = document or (getattr(App, "ActiveDocument", None) if App is not None else None)
    if doc is None:
        return ""
    items: list[str] = []
    for role, label in (("design", "Design"), ("daylight", "Slope")):
        obj = _corridor_build_preview_object(doc, role)
        if obj is None:
            continue
        status = str(getattr(obj, "IntersectionExclusionClipStatus", "") or "")
        if not status:
            continue
        clipped = int(getattr(obj, "IntersectionExclusionClippedTriangleCount", 0) or 0)
        kept = int(getattr(obj, "IntersectionExclusionKeptTriangleCount", 0) or 0)
        exact_cut_candidates = int(getattr(obj, "IntersectionExclusionExactCutCandidateCount", 0) or 0)
        boundary_strategy = str(getattr(obj, "IntersectionExclusionBoundaryStrategy", "") or "")
        aligned = int(getattr(obj, "IntersectionExclusionPracticalBoundaryAligned", 0) or 0)
        footprint_status = str(getattr(obj, "IntersectionExclusionPracticalFootprintStatus", "") or "")
        footprint_diagnostics = [
            str(value or "")
            for value in list(getattr(obj, "IntersectionExclusionPracticalFootprintDiagnostics", []) or [])
            if str(value or "")
        ]
        action = _intersection_exclusion_practical_footprint_recommended_action(
            footprint_status,
            "; ".join(footprint_diagnostics),
        )
        suffix_parts = []
        if exact_cut_candidates:
            suffix_parts.append(f"exact-cut candidates={exact_cut_candidates}")
        if boundary_strategy:
            suffix_parts.append(f"boundary={boundary_strategy}")
        if aligned:
            suffix_parts.append("aligned=practical")
        if footprint_status and footprint_status not in {"ready", status}:
            suffix_parts.append(f"footprint={footprint_status}")
        if footprint_diagnostics:
            suffix_parts.append(footprint_diagnostics[0])
        if action:
            suffix_parts.append(f"recommended_action={action}")
        suffix = f", {', '.join(suffix_parts)}" if suffix_parts else ""
        items.append(f"{label} exclusion {status}: clipped={clipped}, kept={kept}{suffix}")
    return "; ".join(items)


def _intersection_exclusion_practical_footprint_recommended_action(status: str, diagnostics: str = "") -> str:
    status_text = str(status or "").strip().lower()
    diagnostic_text = str(diagnostics or "").strip().lower()
    if status_text in {"", "ready"}:
        return ""
    if "primary_strip_invalid" in diagnostic_text or "strip_invalid" in diagnostic_text:
        return "Review Intersection tie-in source geometry, then rebuild Applied Sections and Build Parametric"
    if "union_invalid" in diagnostic_text or "zero_area" in diagnostic_text:
        return "Review skew angle and tie-in extents, then rebuild Build Parametric"
    if status_text == "degraded":
        return "Review recovered footprint outline before accepting adjacent surface clipping"
    if status_text == "missing":
        return "Review Intersection source and rebuild before trusting adjacent surface clipping"
    return "Review practical exclusion footprint diagnostics"


def _intersection_patch_boundary_review_notes(document=None) -> dict[str, object]:
    doc = document or (getattr(App, "ActiveDocument", None) if App is not None else None)
    obj = _corridor_build_preview_object(doc, "intersection") if doc is not None else None
    if obj is None:
        return {"diagnostic_count": 0, "notes": ""}
    diagnostic_count = int(getattr(obj, "IntersectionPatchBoundaryDiagnosticCount", 0) or 0)
    hole_count = int(getattr(obj, "IntersectionPatchBoundaryHoleRingCount", 0) or 0)
    island_count = int(getattr(obj, "IntersectionPatchBoundaryIslandRingCount", 0) or 0)
    diagnostics = [str(value or "") for value in list(getattr(obj, "IntersectionPatchBoundaryDiagnostics", []) or []) if str(value or "")]
    parts: list[str] = []
    if hole_count or island_count:
        parts.append(f"patch boundary rings: holes={hole_count}, islands={island_count}")
    if diagnostic_count:
        shown = "; ".join(diagnostics[:2]) if diagnostics else f"{diagnostic_count} diagnostic(s)"
        suffix = f"; +{diagnostic_count - 2} more" if diagnostic_count > 2 else ""
        parts.append(f"patch boundary diagnostics: {shown}{suffix}")
    return {"diagnostic_count": diagnostic_count, "notes": "; ".join(parts)}


def _intersection_grading_review_notes(document=None) -> str:
    doc = document or (getattr(App, "ActiveDocument", None) if App is not None else None)
    obj = _corridor_build_preview_object(doc, "intersection") if doc is not None else None
    if obj is None:
        return ""
    policy_ref = _display_source_id(str(getattr(obj, "IntersectionGradingPolicyRef", "") or ""), "grading:")
    mode = str(getattr(obj, "IntersectionGradingMode", "") or "")
    z_delta = float(getattr(obj, "IntersectionGradingZDeltaMax", 0.0) or 0.0)
    superelevation_sources = int(getattr(obj, "IntersectionSuperelevationSourceCount", 0) or 0)
    superelevation_transitions = int(getattr(obj, "IntersectionSuperelevationTransitionCount", 0) or 0)
    parts: list[str] = []
    if policy_ref or mode:
        label = policy_ref or "default"
        parts.append(f"grading policy={label}, mode={mode or 'use_normal_superelevation'}")
    if z_delta:
        parts.append(f"max z adjustment={z_delta:.3f}m")
    if superelevation_sources or superelevation_transitions:
        parts.append(f"superelevation sources={superelevation_sources}, transitions={superelevation_transitions}")
    return "; ".join(parts)


def _intersection_surface_quality_review_notes(document=None) -> dict[str, object]:
    doc = document or (getattr(App, "ActiveDocument", None) if App is not None else None)
    obj = _corridor_build_preview_object(doc, "intersection") if doc is not None else None
    if obj is None:
        return {"diagnostic_count": 0, "notes": ""}
    surface_patch_summary = str(getattr(obj, "IntersectionSurfacePatchSummary", "") or "")
    surface_zone_output_summary = str(getattr(obj, "IntersectionSurfaceZoneOutputSummary", "") or "")
    surface_zone_output_contract_status = str(getattr(obj, "IntersectionSurfaceZoneOutputContractStatus", "") or "")
    surface_zone_output_handoff = str(getattr(obj, "IntersectionSurfaceZoneOutputDigitalTwinHandoff", "") or "")
    surface_replacement_summary = str(getattr(obj, "IntersectionSurfaceReplacementSummary", "") or "")
    surface_replacement_gate = str(getattr(obj, "IntersectionSurfaceReplacementGateStatus", "") or "")
    surface_patch_contract_status = str(getattr(obj, "IntersectionSurfacePatchOutputContractStatus", "") or "")
    surface_patch_handoff = str(getattr(obj, "IntersectionSurfacePatchDigitalTwinHandoff", "") or "")
    surface_patch_replacement_path = str(getattr(obj, "IntersectionSurfacePatchReplacementPath", "") or "")
    slope_face_surface_action = str(getattr(obj, "IntersectionSlopeFaceSurfaceRecommendedAction", "") or "")
    surface_patch_row_statuses = _surface_patch_review_status_note(obj)
    surface_patch_row_diagnostics = [
        str(value or "")
        for value in list(getattr(obj, "IntersectionSurfacePatchRowDiagnostics", []) or [])
        if str(value or "")
    ]
    triangulation_mode = str(getattr(obj, "PatchTriangulationMode", "") or "")
    boundary_strategy = str(getattr(obj, "PatchSurfaceBoundaryStrategy", "") or "")
    bbox_ratio = float(getattr(obj, "PatchBoundaryBBoxAspectRatio", 0.0) or 0.0)
    min_quality = float(getattr(obj, "PatchTriangleMinQuality", 0.0) or 0.0)
    skinny_count = int(getattr(obj, "PatchTriangleSkinnyCount", 0) or 0)
    long_edge_count = int(getattr(obj, "PatchBoundaryLongEdgeCount", 0) or 0)
    parts: list[str] = []
    diagnostics = len(surface_patch_row_diagnostics)
    if surface_patch_summary:
        parts.append(f"surface_patch={surface_patch_summary}")
    if surface_zone_output_summary:
        parts.append(f"surface_zone_output={surface_zone_output_summary}")
    if surface_zone_output_contract_status:
        parts.append(f"surface_zone_output_contract={surface_zone_output_contract_status}")
    if surface_zone_output_handoff:
        parts.append(f"surface_zone_output_handoff={surface_zone_output_handoff}")
    if surface_replacement_summary:
        parts.append(f"surface_replacement={surface_replacement_summary}")
    if surface_replacement_gate:
        parts.append(f"surface_replacement_gate={surface_replacement_gate}")
    if surface_patch_contract_status:
        parts.append(f"surface_patch_contract={surface_patch_contract_status}")
    if surface_patch_handoff:
        parts.append(f"surface_patch_handoff={surface_patch_handoff}")
    if surface_patch_replacement_path:
        parts.append(f"surface_patch_replacement={surface_patch_replacement_path}")
    if slope_face_surface_action:
        parts.append(f"intersection_slope_face_action={slope_face_surface_action}")
    if surface_patch_row_statuses:
        parts.append(f"surface_patch_rows={surface_patch_row_statuses}")
    if surface_patch_row_diagnostics:
        parts.append(f"surface_patch_row_diagnostics={len(surface_patch_row_diagnostics)}")
    if triangulation_mode:
        if triangulation_mode == "fan_fallback":
            diagnostics += 1
            parts.append(f"warning:patch triangulation={triangulation_mode}; ear clipping failed and fan fallback was used")
        else:
            parts.append(f"patch triangulation={triangulation_mode}")
    if boundary_strategy:
        parts.append(f"surface boundary={boundary_strategy}")
    if bbox_ratio:
        if bbox_ratio >= 8.0:
            diagnostics += 1
            parts.append(f"warning:patch bbox ratio={bbox_ratio:.3f}; boundary is elongated")
        else:
            parts.append(f"patch bbox ratio={bbox_ratio:.3f}")
    if min_quality:
        if min_quality < 0.08:
            diagnostics += 1
            parts.append(f"warning:patch min triangle quality={min_quality:.3f}; skinny triangle risk")
        else:
            parts.append(f"patch min triangle quality={min_quality:.3f}")
    if skinny_count:
        diagnostics += skinny_count
        parts.append(f"warning:skinny triangles={skinny_count}; improve intersection boundary/tie-in shape")
    if long_edge_count:
        parts.append(f"warning:long boundary edges={long_edge_count}; patch boundary needs more local control points")
    return {"diagnostic_count": diagnostics, "notes": "; ".join(parts)}


def _join_review_notes(*parts: str) -> str:
    return "; ".join(str(part or "").strip() for part in parts if str(part or "").strip())


def corridor_intersection_patch_prerequisite_result(document=None) -> IntersectionPatchPrerequisiteResult:
    """Evaluate whether source/result contracts are ready for an intersection surface patch."""

    doc = document or (getattr(App, "ActiveDocument", None) if App is not None else None)
    intersection_model = to_intersection_model(find_v1_intersection_model(doc))
    if intersection_model is None or not list(getattr(intersection_model, "intersection_rows", []) or []):
        return IntersectionPatchPrerequisiteResult(
            status="missing",
            diagnostic_rows=("intersection_patch_prerequisites_missing: IntersectionModel is required.",),
        )
    applied = to_applied_section_set(find_v1_applied_section_set(doc))
    if applied is None:
        first_row = list(getattr(intersection_model, "intersection_rows", []) or [None])[0]
        return IntersectionPatchPrerequisiteResult(
            status="missing",
            intersection_id=str(getattr(first_row, "intersection_id", "") or ""),
            intersection_kind=str(getattr(first_row, "intersection_kind", "") or ""),
            diagnostic_rows=("intersection_patch_prerequisites_missing: Applied Sections are required.",),
        )

    sections = _station_ordered_applied_sections(applied)
    region_rows = [
        row for row in corridor_region_boundary_rows(doc)
        if str(row.get("intersection", "") or "").strip() not in {"", "-"}
    ]
    if not region_rows:
        first_row = list(getattr(intersection_model, "intersection_rows", []) or [None])[0]
        return IntersectionPatchPrerequisiteResult(
            status="missing",
            intersection_id=str(getattr(first_row, "intersection_id", "") or ""),
            intersection_kind=str(getattr(first_row, "intersection_kind", "") or ""),
            applied_section_count=len(sections),
            diagnostic_rows=("intersection_patch_prerequisites_missing: intersection-controlled Region rows are required.",),
        )

    source_row = list(getattr(intersection_model, "intersection_rows", []) or [None])[0]
    intersection_id = str(getattr(source_row, "intersection_id", "") or str(region_rows[0].get("intersection", "") or ""))
    intersection_kind = str(getattr(source_row, "intersection_kind", "") or "")
    alignment_refs = _unique_text_values([
        str(row.get("alignment_id", "") or "")
        for row in region_rows
        if str(row.get("alignment_id", "") or "").strip()
    ])
    control_region_refs = _unique_text_values([
        str(row.get("region_id", "") or "")
        for row in region_rows
        if str(row.get("region_id", "") or "").strip()
    ])
    control_area_refs = _unique_text_values([
        str(getattr(row, "control_area_id", "") or "")
        for row in list(getattr(intersection_model, "control_area_rows", []) or [])
        if str(getattr(row, "intersection_id", "") or "") == intersection_id
    ])
    section_count = len([
        section for section in sections
        if str(getattr(section, "active_intersection_id", "") or "") == intersection_id
        or str(getattr(section, "region_id", "") or "") in set(control_region_refs)
    ])
    diagnostics: list[str] = []
    if len(alignment_refs) < 2:
        diagnostics.append("intersection_patch_prerequisites_missing: at least two participating alignments are required.")
    if len(control_region_refs) < 2:
        diagnostics.append("intersection_patch_prerequisites_missing: at least two control Regions are required.")
    if section_count < 2:
        diagnostics.append("intersection_patch_tie_in_edge_missing: Applied Sections are not available for enough control Regions.")
    boundary_point_count = max(0, len(control_region_refs) * 2)
    tie_in_result = corridor_intersection_tie_in_edge_result(
        applied,
        prerequisite=IntersectionPatchPrerequisiteResult(
            status="ready",
            intersection_id=intersection_id,
            intersection_kind=intersection_kind,
            alignment_refs=tuple(alignment_refs),
            control_region_refs=tuple(control_region_refs),
            control_area_refs=tuple(control_area_refs),
        ),
        intersection_model=intersection_model,
    )
    tie_in_edge_count = int(getattr(tie_in_result, "edge_count", 0) or 0)
    for diagnostic in list(getattr(tie_in_result, "diagnostic_rows", []) or []):
        diagnostics.append(str(diagnostic or ""))
    supplemental_summary = _intersection_supplemental_applied_section_summary(
        applied,
        intersection_id=intersection_id,
        control_region_refs=tuple(control_region_refs),
    )
    supplemental_alignments = set(supplemental_summary.get("alignment_refs", []) or [])
    missing_supplemental_alignments = [ref for ref in alignment_refs if ref not in supplemental_alignments]
    if alignment_refs and missing_supplemental_alignments:
        diagnostics.append(
            "warning:intersection_supplemental_applied_sections_missing: "
            "Build Sections should add intersection_supplemental rows for "
            + ", ".join(missing_supplemental_alignments)
            + "."
        )
    if boundary_point_count < 4:
        diagnostics.append("intersection_patch_boundary_too_few_points: control Region boundary is not sufficient for a patch.")
    status = "ready" if not _diagnostics_include_error(diagnostics) else "warning"
    return IntersectionPatchPrerequisiteResult(
        status=status,
        intersection_id=intersection_id,
        intersection_kind=intersection_kind,
        alignment_refs=tuple(alignment_refs),
        control_region_refs=tuple(control_region_refs),
        control_area_refs=tuple(control_area_refs),
        participating_alignment_count=len(alignment_refs),
        control_region_count=len(control_region_refs),
        applied_section_count=section_count,
        tie_in_edge_count=tie_in_edge_count,
        boundary_point_count=boundary_point_count,
        diagnostic_rows=tuple(diagnostics),
    )


def _intersection_supplemental_applied_section_summary(
    applied_section_set,
    *,
    intersection_id: str = "",
    control_region_refs: tuple[str, ...] = (),
) -> dict[str, object]:
    if applied_section_set is None:
        return {"count": 0, "alignment_refs": [], "notes": "intersection supplemental sections=0"}
    section_by_id = {
        str(getattr(section, "applied_section_id", "") or ""): section
        for section in list(getattr(applied_section_set, "sections", []) or [])
    }
    target_intersection = str(intersection_id or "").strip()
    target_regions = {str(value or "").strip() for value in list(control_region_refs or ()) if str(value or "").strip()}
    counts: dict[str, int] = {}
    total = 0
    for row in list(getattr(applied_section_set, "station_rows", []) or []):
        if str(getattr(row, "kind", "") or "") != "intersection_supplemental":
            continue
        section = section_by_id.get(str(getattr(row, "applied_section_id", "") or ""))
        if section is None:
            continue
        section_intersection = str(getattr(section, "active_intersection_id", "") or "").strip()
        section_region = str(getattr(section, "region_id", "") or "").strip()
        if target_intersection and section_intersection and section_intersection != target_intersection:
            continue
        if target_regions and not section_intersection and section_region not in target_regions:
            continue
        alignment_ref = str(getattr(section, "alignment_id", "") or "").strip() or "-"
        counts[alignment_ref] = int(counts.get(alignment_ref, 0) or 0) + 1
        total += 1
    alignment_refs = sorted(ref for ref in counts if ref != "-")
    if counts:
        distribution = ", ".join(f"{ref}={count}" for ref, count in sorted(counts.items()))
        notes = f"intersection supplemental sections={total} ({distribution})"
    else:
        notes = "intersection supplemental sections=0"
    return {"count": total, "alignment_refs": alignment_refs, "notes": notes}


def corridor_intersection_contract_review_rows(document=None, *, include_internal: bool = False) -> list[dict[str, object]]:
    """Return edge-network-first intersection contract rows for Build Parametric review."""

    doc = document or (getattr(App, "ActiveDocument", None) if App is not None else None)
    intersection_model = to_intersection_model(find_v1_intersection_model(doc))
    if intersection_model is None or not list(getattr(intersection_model, "intersection_rows", []) or []):
        return [
            {
                "contract_family": "intersection",
                "status": "missing",
                "row_id": "",
                "role": "",
                "source_refs": "",
                "boundary_refs": "",
                "source_status": "missing",
                "output_path": "missing_source",
                "source_diagnostics": "",
                "focus_object": "",
                "notes": "IntersectionModel is required before edge-network-first review.",
            }
        ]
    service = IntersectionEvaluationService()
    topology = service.evaluate_topology(intersection_model)
    edge_network = service.evaluate_edge_network(intersection_model, topology)
    surface_zones = service.evaluate_surface_zones(intersection_model, edge_network)
    applied = to_applied_section_set(find_v1_applied_section_set(doc))
    slope_loops = service.evaluate_slope_face_loops(intersection_model, surface_zones, edge_network, applied)
    boundary_loops = service.evaluate_boundary_loops(intersection_model, surface_zones, edge_network, slope_loops, applied)
    tie_slope_result = corridor_intersection_tie_slope_result(
        applied,
        prerequisite=corridor_intersection_patch_prerequisite_result(doc),
        intersection_model=intersection_model,
    )
    tie_slope_window_rows = _intersection_tie_slope_applied_section_window_rows(
        applied,
        prerequisite=corridor_intersection_patch_prerequisite_result(doc),
        intersection_model=intersection_model,
    )
    intersection_kind = str(getattr(topology, "intersection_kind", "") or "").strip().lower()
    if intersection_kind == "roundabout":
        tie_slope_window_rows = []
    roundabout_approach_legs = None
    if intersection_kind == "roundabout":
        roundabout_approach_legs = service.evaluate_roundabout_approach_legs(intersection_model, topology)
    corridor_clips = service.evaluate_corridor_clipping(intersection_model, topology, surface_zones)
    drainage_hints = service.evaluate_drainage_hints(intersection_model, surface_zones)
    intersection_preview = _corridor_build_preview_object(doc, "intersection")
    surface_boundary_mode = str(getattr(intersection_preview, "IntersectionSurfaceBoundaryMode", "") or "")
    surface_boundary_loop = str(getattr(intersection_preview, "IntersectionSurfaceBoundaryLoopKind", "") or "")
    surface_boundary_fallback = str(getattr(intersection_preview, "IntersectionSurfaceBoundaryFallbackReason", "") or "")
    rows: list[dict[str, object]] = []
    rows.append(
        {
            "contract_family": "topology",
            "status": topology.status,
            "row_id": topology.topology_result_id,
            "role": "control_area",
            "source_refs": ", ".join(list(getattr(topology, "source_refs", []) or [])),
            "boundary_refs": ", ".join(row.control_area_id for row in list(topology.control_area_rows or [])),
            "source_status": _intersection_contract_source_status(
                [
                    *list(getattr(topology, "anchor_rows", []) or []),
                    *list(getattr(topology, "leg_span_rows", []) or []),
                    *list(getattr(topology, "control_area_rows", []) or []),
                    *list(getattr(topology, "lane_connection_rows", []) or []),
                ]
            ),
            "source_diagnostics": _intersection_contract_source_diagnostics(
                [
                    *list(getattr(topology, "anchor_rows", []) or []),
                    *list(getattr(topology, "leg_span_rows", []) or []),
                    *list(getattr(topology, "control_area_rows", []) or []),
                    *list(getattr(topology, "lane_connection_rows", []) or []),
                ]
            ),
            "focus_object": "V1CorridorIntersectionSurfacePreview",
            "notes": (
                f"kind={getattr(topology, 'intersection_kind', '')}; "
                f"anchors={getattr(topology, 'anchor_count', 0)}; legs={topology.leg_span_count}; "
                f"corners={getattr(topology, 'corner_count', 0)}; curb_return_arcs={getattr(topology, 'curb_return_arc_count', 0)}; "
                f"leg_graph={getattr(topology, 'leg_graph_status', '')}; corner_graph={getattr(topology, 'corner_graph_status', '')}; "
                f"control areas={topology.control_area_count}; "
                f"lane connections={getattr(topology, 'lane_connection_count', 0)}; "
                f"alignments={topology.participating_alignment_count}; diagnostics={len(topology.diagnostic_rows)}"
            ),
        }
    )
    if tie_slope_window_rows:
        rows.append(
            {
                "contract_family": "intersection_tie_slope_window",
                "status": "ready" if all(str(row.get("status", "") or "") == "accepted" for row in tie_slope_window_rows) else "warning",
                "row_id": f"intersection-tie-slope-window:{str(getattr(tie_slope_result, 'intersection_id', '') or 'main')}",
                "role": "applied_section_window",
                "source_refs": ",".join(
                    _unique_text_values(
                        [
                            str(row.get("outer_applied_section_ref", "") or "")
                            for row in tie_slope_window_rows
                        ]
                        + [
                            str(row.get("inner_applied_section_ref", "") or "")
                            for row in tie_slope_window_rows
                        ]
                    )
                ),
                "boundary_refs": "applied_section_side_slope_edges",
                "source_status": "accepted" if all(str(row.get("status", "") or "") == "accepted" for row in tie_slope_window_rows) else "warning",
                "source_diagnostics": "; ".join(_intersection_tie_slope_window_diagnostics(tie_slope_window_rows)[:8]),
                "focus_object": "V1CorridorIntersectionTieSlopeSurfacePreview",
                "notes": _intersection_tie_slope_window_summary_note(tie_slope_window_rows),
                "output_path": "intersection_tie_slope_window_candidates",
            }
        )
    roundabout_boundary_readiness_row = _roundabout_boundary_readiness_contract_review_row(
        roundabout_approach_legs,
        boundary_loops,
    )
    if roundabout_boundary_readiness_row is not None:
        rows.append(roundabout_boundary_readiness_row)
    for row in list(getattr(boundary_loops, "loop_rows", []) or []):
        rows.append(
            {
                "contract_family": "boundary_loop",
                "status": _intersection_contract_display_status(str(getattr(row, "status", "") or boundary_loops.status)),
                "row_id": str(getattr(row, "loop_id", "") or ""),
                "role": str(getattr(row, "loop_role", "") or ""),
                "source_refs": ", ".join(list(getattr(row, "source_refs", ()) or ())),
                "boundary_refs": ", ".join(list(getattr(row, "segment_refs", ()) or ())),
                "source_status": str(getattr(row, "source_status", "") or "accepted"),
                "source_diagnostics": "; ".join(list(getattr(row, "diagnostics", ()) or ())),
                "focus_object": "V1CorridorIntersectionSurfacePreview",
                "notes": _join_review_notes(
                    f"kind={getattr(boundary_loops, 'intersection_kind', '')}",
                    f"surface_boundary_mode={surface_boundary_mode}" if surface_boundary_mode else "",
                    f"surface_boundary_loop={surface_boundary_loop}" if surface_boundary_loop else "",
                    f"fallback_reason={surface_boundary_fallback}" if surface_boundary_fallback else "",
                    f"closed={'yes' if bool(getattr(row, 'closed', False)) else 'no'}",
                    f"points={int(getattr(row, 'point_count', 0) or 0)}",
                    f"segments={int(getattr(row, 'segment_count', 0) or 0)}",
                    f"area={float(getattr(row, 'area_xy', 0.0) or 0.0):.3f}",
                    "consumers=" + ",".join(list(getattr(row, "consumer_roles", ()) or ())),
                    "; ".join(list(getattr(row, "diagnostics", ()) or ())),
                    str(getattr(row, "recommended_action", "") or ""),
                ),
                "output_path": "intersection_boundary_loop_result",
            }
        )
    for row in list(slope_loops.loop_rows or []):
        blocking_reasons = _intersection_slope_face_loop_row_blocking_reasons(row)
        rows.append(
            {
                "contract_family": "slope_face_loop",
                "status": _intersection_contract_display_status(str(getattr(row, "status", "") or slope_loops.status)),
                "row_id": str(getattr(row, "loop_id", "") or ""),
                "role": str(getattr(row, "loop_family", "") or ""),
                "source_refs": _join_review_notes(
                    ", ".join(list(getattr(row, "source_edge_network_refs", ()) or ())),
                    ", ".join(list(getattr(row, "source_surface_zone_refs", ()) or ())),
                    ", ".join(list(getattr(row, "source_applied_section_refs", ()) or ())),
                ),
                "boundary_refs": ", ".join(list(getattr(row, "boundary_edge_refs", ()) or ())),
                "source_status": str(getattr(row, "source_status", "") or "accepted"),
                "source_diagnostics": "; ".join(
                    _unique_text_values(
                        [
                            *[str(value or "") for value in tuple(getattr(row, "source_diagnostic_rows", ()) or ())],
                            *[str(value or "") for value in tuple(getattr(row, "diagnostics", ()) or ())],
                        ]
                    )
                ),
                "focus_object": "",
                "notes": _join_review_notes(
                    f"alignment={getattr(row, 'alignment_ref', '')}",
                    f"leg={getattr(row, 'leg_ref', '')}",
                    f"side={getattr(row, 'side', '')}",
                    f"points={getattr(row, 'point_count', 0)}",
                    "closed_xy=yes" if bool(getattr(row, "closed_xy", False)) else "closed_xy=no",
                    "self_crossing=yes" if bool(getattr(row, "self_crossing", False)) else "",
                    f"generation={getattr(row, 'surface_generation_role', '')}:{getattr(row, 'surface_generation_status', '')}",
                    "blocking=" + ",".join(blocking_reasons[:4]) if blocking_reasons else "",
                    f"source_lineage={getattr(row, 'source_lineage_status', '')}" if str(getattr(row, "source_lineage_status", "") or "") != "accepted" else "",
                    f"surface_zone_status={getattr(row, 'source_surface_zone_status', '')}" if str(getattr(row, "source_surface_zone_status", "") or "") not in {"", "accepted"} else "",
                    f"edge_network_status={getattr(row, 'source_edge_network_status', '')}" if str(getattr(row, "source_edge_network_status", "") or "") not in {"", "accepted"} else "",
                    "; ".join(list(getattr(row, "source_diagnostic_rows", ()) or ())),
                    "; ".join(list(getattr(row, "diagnostics", ()) or ())),
                    str(getattr(row, "notes", "") or ""),
                ),
            }
        )
    upper_panel_contract_row = _intersection_upper_slope_face_panel_contract_review_row(doc)
    if upper_panel_contract_row is not None:
        rows.append(upper_panel_contract_row)
    rows.extend(_intersection_slope_face_cell_contract_review_rows(doc))
    rows.extend(_intersection_shared_boundary_graph_contract_review_rows(doc))
    for row in list(corridor_clips.clip_rows or []):
        rows.append(
            {
                "contract_family": "corridor_clip",
                "status": _intersection_contract_display_status(str(getattr(row, "status", "") or corridor_clips.status)),
                "row_id": str(getattr(row, "clip_id", "") or ""),
                "role": str(getattr(row, "surface_role", "") or ""),
                "source_refs": _join_review_notes(
                    str(getattr(row, "source_control_area_ref", "") or getattr(row, "control_area_ref", "") or ""),
                    ", ".join(list(getattr(row, "source_region_refs", ()) or ())),
                ),
                "boundary_refs": ", ".join(list(getattr(row, "protected_zone_refs", ()) or ())),
                "source_status": str(getattr(row, "source_status", "") or "accepted"),
                "source_diagnostics": "; ".join(list(getattr(row, "source_diagnostic_rows", ()) or ())),
                "focus_object": "V1CorridorIntersectionExclusionZonePreview",
                "notes": _join_review_notes(
                    f"alignment={getattr(row, 'alignment_ref', '')}",
                    f"method={getattr(row, 'clip_method', '')}",
                    f"timing={getattr(row, 'clip_timing', '')}",
                    f"intent={getattr(row, 'control_area_intent_status', '')}",
                    f"lineage={getattr(row, 'region_lineage_status', '')}",
                    "; ".join(list(getattr(row, "diagnostic_rows", ()) or ())),
                    str(getattr(row, "notes", "") or ""),
                ),
            }
        )
    for row in list(drainage_hints.hint_rows or []):
        rows.append(
            {
                "contract_family": "drainage_hint",
                "status": _intersection_contract_display_status(str(getattr(row, "status", "") or drainage_hints.status)),
                "row_id": str(getattr(row, "hint_id", "") or ""),
                "role": str(getattr(row, "hint_kind", "") or ""),
                "source_refs": _join_review_notes(
                    str(getattr(row, "source_drainage_policy_ref", "") or getattr(row, "drainage_policy_ref", "") or ""),
                    str(getattr(row, "accepted_drainage_ref", "") or ""),
                    ", ".join(list(getattr(row, "source_edge_refs", ()) or ())),
                ),
                "boundary_refs": _join_review_notes(
                    str(getattr(row, "zone_ref", "") or ""),
                    ", ".join(list(getattr(row, "control_area_refs", ()) or ())),
                ),
                "source_status": str(getattr(row, "source_status", "") or "accepted"),
                "source_diagnostics": "; ".join(list(getattr(row, "source_diagnostic_rows", ()) or ())),
                "focus_object": "V1CorridorIntersectionSurfacePreview",
                "notes": _join_review_notes(
                    f"zone={getattr(row, 'zone_role', '')}",
                    f"surface={getattr(row, 'surface_role', '')}",
                    f"recommend={getattr(row, 'recommended_element_kind', '')}",
                    f"handoff={getattr(row, 'drainage_handoff_status', '')}",
                    f"review={getattr(row, 'drainage_review_status', '')}",
                    "; ".join(list(getattr(row, "diagnostic_rows", ()) or ())),
                    str(getattr(row, "notes", "") or ""),
                ),
            }
        )
    for row in rows:
        row.setdefault("output_path", "contract_consumed")
    if not include_internal:
        internal_families = {
            "edge_network",
            "surface_zone",
            "drainage_hint",
            "slope_face_loop",
            "slope_face_cell",
            "shared_boundary_graph",
        }
        rows = [
            row
            for row in rows
            if str(row.get("contract_family", "") or "") not in internal_families
        ]
    return rows


def _roundabout_boundary_readiness_contract_review_row(approach_legs, boundary_loops) -> dict[str, object] | None:
    """Expose roundabout approach clip/handoff boundary readiness in the Intersections tab."""

    if approach_legs is None or str(getattr(approach_legs, "intersection_kind", "") or "").lower() != "roundabout":
        return None
    approach_rows = list(getattr(approach_legs, "approach_leg_rows", []) or [])
    accepted_rows = [
        row
        for row in approach_rows
        if str(getattr(row, "status", "") or "").strip().lower() in {"ready", "accepted"}
    ]
    expected_count = max(4, len(accepted_rows))
    required_roles = (
        "roundabout_approach_clip_boundary",
        "roundabout_subgrade_clip_boundary",
        "roundabout_slope_handoff_boundary",
    )
    loop_rows = list(getattr(boundary_loops, "loop_rows", []) or [])
    loops_by_role: dict[str, list[object]] = {role: [] for role in required_roles}
    for row in loop_rows:
        role = str(getattr(row, "loop_role", "") or "")
        if role in loops_by_role:
            loops_by_role[role].append(row)

    missing_roles: list[str] = []
    warning_roles: list[str] = []
    error_roles: list[str] = []
    for role in required_roles:
        role_rows = loops_by_role.get(role, [])
        ready_count = len([row for row in role_rows if str(getattr(row, "status", "") or "") == "ready"])
        if ready_count < expected_count:
            missing_roles.append(f"{role}:{ready_count}/{expected_count}")
        if any(str(getattr(row, "status", "") or "") == "warning" for row in role_rows):
            warning_roles.append(role)
        if any(str(getattr(row, "status", "") or "") == "error" for row in role_rows):
            error_roles.append(role)

    role_attr_map = {
        "roundabout_approach_clip_boundary": "corridor_clip_boundary_role",
        "roundabout_subgrade_clip_boundary": "subgrade_handoff_boundary_role",
        "roundabout_slope_handoff_boundary": "slope_handoff_boundary_role",
    }
    missing_leg_role_attrs: list[str] = []
    for approach in approach_rows:
        approach_id = str(getattr(approach, "approach_leg_id", "") or "")
        for role, attr in role_attr_map.items():
            if str(getattr(approach, attr, "") or "") != role:
                missing_leg_role_attrs.append(f"{approach_id}:{role}")

    diagnostics = _unique_text_values(
        [
            *(
                ["error:roundabout_approach_leg_rows_missing"]
                if not approach_rows
                else []
            ),
            *(
                [f"warning:roundabout_approach_leg_count_below_four:{len(accepted_rows)}"]
                if len(accepted_rows) < 4
                else []
            ),
            *[f"warning:roundabout_boundary_role_missing:{value}" for value in missing_roles],
            *[f"warning:roundabout_boundary_role_warning:{value}" for value in warning_roles],
            *[f"error:roundabout_boundary_role_error:{value}" for value in error_roles],
            *[f"error:roundabout_approach_leg_boundary_role_missing:{value}" for value in missing_leg_role_attrs],
        ]
    )
    status = "error" if any(str(value).startswith("error:") for value in diagnostics) else (
        "warning" if missing_roles or warning_roles or any(str(value).startswith("warning:") for value in diagnostics) else "ready"
    )
    source_status = "error" if status == "error" else ("warning" if status == "warning" else "accepted")
    role_summary = ", ".join(
        f"{role}={len([row for row in loops_by_role.get(role, []) if str(getattr(row, 'status', '') or '') == 'ready'])}/{expected_count}"
        for role in required_roles
    )
    approach_roles = _unique_text_values(
        [str(getattr(row, "approach_role", "") or "") for row in approach_rows]
    )
    source_refs = _unique_text_values(
        [
            str(getattr(approach_legs, "approach_leg_result_id", "") or ""),
            *[str(getattr(row, "approach_leg_id", "") or "") for row in approach_rows],
        ]
    )
    boundary_refs = _unique_text_values(
        [
            str(getattr(row, "loop_id", "") or "")
            for role in required_roles
            for row in loops_by_role.get(role, [])
        ]
    )
    return {
        "contract_family": "roundabout_boundary_readiness",
        "status": status,
        "row_id": f"roundabout-boundary-readiness:{str(getattr(approach_legs, 'intersection_id', '') or 'main')}",
        "role": "approach_clip_and_slope_handoff",
        "source_refs": ", ".join(source_refs),
        "boundary_refs": ", ".join(boundary_refs),
        "source_status": source_status,
        "source_diagnostics": "; ".join(diagnostics),
        "focus_object": "",
        "notes": _join_review_notes(
            f"approach_legs={len(accepted_rows)}/{expected_count}",
            f"approach_roles={','.join(approach_roles) if approach_roles else 'none'}",
            role_summary,
            f"boundary_result={str(getattr(boundary_loops, 'boundary_loop_result_id', '') or '')}",
            f"missing_roles={','.join(missing_roles)}" if missing_roles else "",
            "Roundabout ordinary-surface clip and slope handoff boundaries are ready."
            if status == "ready"
            else "Repair missing roundabout approach boundary roles before ordinary surface clipping.",
        ),
        "output_path": "roundabout_boundary_readiness",
    }


def _intersection_slope_face_cell_contract_review_rows(document=None) -> list[dict[str, object]]:
    """Expose generated Intersection Slope Face cell contracts in the Intersections tab."""

    obj = _corridor_build_preview_object(document, "intersection_slope")
    if obj is None:
        return []
    raw_rows = [
        str(value or "")
        for value in list(getattr(obj, "IntersectionSlopeFaceCellAuditRows", []) or [])
        if str(value or "").strip()
    ]
    if not raw_rows:
        return []
    result_id = str(getattr(obj, "IntersectionSlopeFaceCellResultId", "") or "").strip()
    rows: list[dict[str, object]] = []
    for raw in raw_rows:
        parsed = _parse_intersection_slope_face_cell_audit_row(raw)
        if not parsed:
            continue
        open_count = int(parsed.get("open_count", 0) or 0)
        missing_edge_count = int(parsed.get("missing_edge_count", 0) or 0)
        status = _intersection_contract_display_status(str(parsed.get("status", "") or "missing"))
        if open_count or missing_edge_count:
            status = "warning"
        diagnostics = str(parsed.get("diagnostics", "") or "")
        boundary_refs = str(parsed.get("boundary_refs", "") or "")
        rows.append(
            {
                "contract_family": "slope_face_cell",
                "status": status,
                "row_id": str(parsed.get("cell_id", "") or ""),
                "role": str(parsed.get("cell_role", "") or ""),
                "source_refs": result_id,
                "boundary_refs": boundary_refs,
                "source_status": "warning" if diagnostics or open_count or missing_edge_count else "accepted",
                "source_diagnostics": diagnostics,
                "focus_object": "V1CorridorIntersectionSlopeFaceSurfacePreview",
                "notes": _join_review_notes(
                    f"points={int(parsed.get('point_count', 0) or 0)}",
                    f"open={open_count}",
                    f"missing_edges={missing_edge_count}",
                    f"boundary_refs={boundary_refs}" if boundary_refs else "",
                    diagnostics,
                ),
                "output_path": "intersection_slope_face_cell_result",
            }
        )
    return rows


def _intersection_upper_slope_face_panel_contract_review_row(document=None) -> dict[str, object] | None:
    """Expose accepted upper rectangular panel readiness in the Intersections tab."""

    obj = _corridor_build_preview_object(document, "intersection_slope")
    if obj is None:
        return None
    candidate_count = int(getattr(obj, "IntersectionUpperSlopeFacePanelCandidateCount", 0) or 0)
    accepted_count = int(getattr(obj, "IntersectionUpperSlopeFacePanelAcceptedCount", 0) or 0)
    generated_count = int(getattr(obj, "IntersectionUpperSlopeFacePanelGeneratedCount", 0) or 0)
    triangle_count = int(getattr(obj, "IntersectionUpperSlopeFacePanelTriangleCount", 0) or 0)
    suppressed_count = int(getattr(obj, "IntersectionSlopeFaceSuppressedUpperCellCount", 0) or 0)
    if not any((candidate_count, accepted_count, generated_count, triangle_count, suppressed_count)):
        return None
    panel_refs = [
        str(value or "")
        for value in list(getattr(obj, "IntersectionUpperSlopeFacePanelRefs", []) or [])
        if str(value or "").strip()
    ]
    boundary_refs = [
        str(value or "")
        for value in list(getattr(obj, "IntersectionUpperSlopeFacePanelBoundaryRefs", []) or [])
        if str(value or "").strip()
    ]
    suppressed_refs = [
        str(value or "")
        for value in list(getattr(obj, "IntersectionSlopeFaceSuppressedUpperCellRefs", []) or [])
        if str(value or "").strip()
    ]
    generation_mode = str(getattr(obj, "IntersectionUpperSlopeFacePanelGenerationMode", "") or "")
    source_mode = str(getattr(obj, "IntersectionUpperSlopeFacePanelSourceMode", "") or "")
    coverage_status = str(getattr(obj, "IntersectionUpperSlopeFacePanelCoverageStatus", "") or "")
    coverage_summary = str(getattr(obj, "IntersectionUpperSlopeFacePanelCoverageSummary", "") or "")
    expected_group_count = int(getattr(obj, "IntersectionUpperSlopeFacePanelExpectedGroupCount", 0) or 0)
    diagnostic = str(getattr(obj, "IntersectionUpperSlopeFacePanelDiagnostic", "") or "")
    status = "ready" if generated_count > 0 and triangle_count == generated_count * 2 else "warning"
    return {
        "contract_family": "intersection_upper_slope_face_panel",
        "status": status,
        "row_id": "intersection-upper-slope-face-panel",
        "role": "upper_rectangular_panel",
        "source_refs": ", ".join(panel_refs),
        "boundary_refs": ", ".join(boundary_refs),
        "source_status": "accepted" if status == "ready" else "warning",
        "source_diagnostics": diagnostic,
        "focus_object": "V1CorridorIntersectionSlopeFaceSurfacePreview",
        "notes": _join_review_notes(
            f"candidates={candidate_count}",
            f"accepted={accepted_count}",
            f"generated={generated_count}",
            f"triangles={triangle_count}",
            f"suppressed_legacy_upper_cells={suppressed_count}",
            f"mode={generation_mode}" if generation_mode else "",
            f"source={source_mode}" if source_mode else "",
            f"coverage={coverage_status}" if coverage_status else "",
            f"expected_groups={expected_group_count}" if expected_group_count else "",
            coverage_summary,
            f"suppressed_refs={len(suppressed_refs)}",
            diagnostic,
        ),
        "output_path": "intersection_upper_slope_face_panel",
    }


def _intersection_shared_boundary_graph_contract_review_rows(document=None) -> list[dict[str, object]]:
    """Expose canonical shared-boundary graph contracts in the Intersections tab."""

    obj = _corridor_build_preview_object(document, "intersection_slope")
    if obj is None:
        return []
    raw_rows = [
        str(value or "")
        for value in list(getattr(obj, "IntersectionSharedBoundaryGraphAuditRows", []) or [])
        if str(value or "").strip()
    ]
    if not raw_rows:
        return []
    result_id = str(getattr(obj, "IntersectionSharedBoundaryGraphResultId", "") or "").strip()
    rows: list[dict[str, object]] = []
    for raw in raw_rows:
        parsed = _parse_intersection_shared_boundary_graph_audit_row(raw)
        if not parsed:
            continue
        diagnostics = str(parsed.get("diagnostics", "") or "")
        open_count = int(parsed.get("open_count", 0) or 0)
        status = "warning" if diagnostics or open_count else "ready"
        rows.append(
            {
                "contract_family": "shared_boundary_graph",
                "status": status,
                "row_id": str(parsed.get("row_id", "") or ""),
                "role": f"{parsed.get('row_kind', '')}:{parsed.get('role', '')}",
                "source_refs": result_id,
                "boundary_refs": str(parsed.get("refs", "") or ""),
                "source_status": "warning" if status == "warning" else "accepted",
                "source_diagnostics": diagnostics,
                "focus_object": "V1CorridorIntersectionSlopeFaceSurfacePreview",
                "notes": _join_review_notes(
                    f"kind={parsed.get('row_kind', '')}",
                    f"refs={parsed.get('refs', '')}" if parsed.get("refs", "") else "",
                    f"open={open_count}" if open_count else "",
                    diagnostics,
                ),
                "output_path": "intersection_shared_boundary_graph_result",
            }
        )
    return rows


def corridor_intersection_contract_review_summary(document=None, *, include_internal: bool = False) -> dict[str, object]:
    """Return a compact edge-network-first contract summary for Build Parametric."""

    rows = corridor_intersection_contract_review_rows(document, include_internal=include_internal)
    real_rows = [row for row in rows if row.get("row_id")]
    if not real_rows:
        output_path_counts: dict[str, int] = {}
        source_status_counts: dict[str, int] = {}
        for row in rows:
            output_path = str(row.get("output_path", "") or "missing_source")
            output_path_counts[output_path] = output_path_counts.get(output_path, 0) + 1
            source_status = str(row.get("source_status", "") or "missing")
            source_status_counts[source_status] = source_status_counts.get(source_status, 0) + 1
        output_counts = ", ".join(f"{path}={count}" for path, count in sorted(output_path_counts.items()))
        source_status_summary = ", ".join(f"{status}={count}" for status, count in sorted(source_status_counts.items()))
        base_notes = str(rows[0].get("notes", "No intersection contract rows.") if rows else "No intersection contract rows.")
        suffix = _join_review_notes(
            f"source status={source_status_summary}" if source_status_summary else "",
            f"output paths={output_counts}" if output_counts else "",
        )
        notes = f"{base_notes} {suffix}." if suffix else base_notes
        return {
            "status": "missing",
            "row_count": 0,
            "notes": notes,
        }
    error_count = sum(1 for row in real_rows if str(row.get("status", "") or "") == "error")
    warning_count = sum(1 for row in real_rows if str(row.get("status", "") or "") in {"warning", "warn"})
    source_warning_count = sum(
        1
        for row in real_rows
        if str(row.get("source_status", "") or "") not in {"", "accepted", "ready"}
        or str(row.get("source_diagnostics", "") or "")
    )
    family_counts: dict[str, int] = {}
    output_path_counts: dict[str, int] = {}
    source_status_counts: dict[str, int] = {}
    for row in real_rows:
        family = str(row.get("contract_family", "") or "contract")
        family_counts[family] = family_counts.get(family, 0) + 1
        output_path = str(row.get("output_path", "") or "contract_consumed")
        output_path_counts[output_path] = output_path_counts.get(output_path, 0) + 1
        source_status = str(row.get("source_status", "") or "accepted")
        source_status_counts[source_status] = source_status_counts.get(source_status, 0) + 1
    status = "error" if error_count else ("warning" if warning_count else "ready")
    counts = ", ".join(f"{family}={count}" for family, count in sorted(family_counts.items()))
    output_counts = ", ".join(f"{path}={count}" for path, count in sorted(output_path_counts.items()))
    source_status_summary = ", ".join(f"{source_status}={count}" for source_status, count in sorted(source_status_counts.items()))
    return {
        "status": status,
        "row_count": len(real_rows),
        "warning_count": warning_count,
        "error_count": error_count,
        "source_warning_count": source_warning_count,
        "notes": f"Intersection contracts: {counts}; output paths={output_counts}; source status={source_status_summary}; warnings={warning_count}; source warnings={source_warning_count}; errors={error_count}.",
    }


def _intersection_contract_display_status(status: str) -> str:
    text = str(status or "").strip().lower()
    if text == "candidate":
        return "ready"
    if text == "warn":
        return "warning"
    return text or "missing"


def _intersection_contract_source_status(rows: list[object]) -> str:
    statuses = [str(getattr(row, "source_status", "") or "") for row in rows]
    statuses = [status for status in statuses if status]
    if any(status == "error" for status in statuses):
        return "error"
    if any(status == "warning" for status in statuses):
        return "warning"
    return "accepted"


def _intersection_contract_source_diagnostics(rows: list[object]) -> str:
    diagnostics: list[str] = []
    for row in rows:
        for item in tuple(getattr(row, "source_diagnostic_rows", ()) or ()):
            text = str(item or "").strip()
            if text and text not in diagnostics:
                diagnostics.append(text)
    return "; ".join(diagnostics)


def focus_corridor_intersection_contract_review_row(document=None, row_index: int = 0, *, include_internal: bool = False):
    """Create/select a clear 3D highlight for one intersection contract review row."""

    doc = document or (getattr(App, "ActiveDocument", None) if App is not None else None)
    rows = corridor_intersection_contract_review_rows(doc, include_internal=include_internal)
    if row_index < 0 or row_index >= len(rows):
        raise IndexError("Intersection contract review row index is out of range.")
    row = rows[row_index]
    highlight = _create_intersection_contract_review_highlight(
        document=doc,
        row=row,
        row_index=row_index,
    )
    if highlight is not None:
        _set_object_visibility(highlight, True)
        _select_and_fit_object(highlight)
        return highlight
    candidates = [
        str(row.get("focus_object", "") or ""),
        "V1CorridorIntersectionSurfacePreview",
        "V1CorridorIntersectionExclusionZonePreview",
    ]
    for name in candidates:
        obj = doc.getObject(name) if doc is not None and name else None
        if obj is not None:
            _select_and_fit_object(obj)
            return obj
    raise RuntimeError("No 3D review object is available for the selected intersection contract row.")


def _create_intersection_contract_review_highlight(*, document=None, row: dict[str, object], row_index: int = 0):
    """Create a bright linework overlay for selected high-level intersection review rows."""

    if document is None:
        return None
    try:
        import FreeCAD as AppModule
        import Part
    except Exception:
        return None
    family = str(row.get("contract_family", "") or "").strip()
    row_id = str(row.get("row_id", "") or "").strip()
    object_name = "ReviewIntersectionContractHighlight"
    _remove_preview_object(document, object_name)
    context = _intersection_contract_highlight_context(document)
    shapes: list[object] = []
    refs: list[str] = []
    highlight_geometry_source = ""
    highlight_style = _intersection_contract_highlight_style(family)
    if family == "corridor_clip" and row_id:
        shapes.extend(_intersection_contract_patch_boundary_shapes(Part, AppModule, context.get("patch_boundary_result"), refs))
        highlight_geometry_source = "intersection_patch_boundary_result"
    elif family == "shared_boundary_graph" and row_id:
        shapes.extend(
            _intersection_shared_boundary_graph_contract_shapes(
                Part,
                AppModule,
                graph_result=context.get("shared_boundary_graph_result"),
                row=row,
                refs=refs,
                document=document,
            )
        )
        highlight_geometry_source = "intersection_shared_boundary_graph_result"
    else:
        return None
    if not shapes:
        return None
    obj = document.getObject(object_name)
    if obj is None:
        obj = document.addObject("Part::Feature", object_name)
    try:
        obj.Shape = Part.makeCompound(shapes) if len(shapes) > 1 else shapes[0]
        obj.Label = "Intersection Contract Highlight"
    except Exception:
        return obj
    _set_preview_property(obj, "CRRecordKind", "v1_intersection_contract_review_highlight")
    _set_preview_property(obj, "V1ObjectType", "ReviewIssue")
    _set_preview_property(obj, "IssueKind", "intersection_contract")
    _set_preview_property(obj, "ContractFamily", family)
    _set_preview_property(obj, "ContractRowId", row_id)
    _set_preview_integer_property(obj, "ContractRowIndex", int(row_index))
    _set_preview_property(obj, "IntersectionId", str(context.get("intersection_id", "") or ""))
    _set_preview_string_list_property(obj, "HighlightedRefs", _unique_text_values(refs))
    _set_preview_integer_property(obj, "HighlightedShapeCount", len(shapes))
    _set_preview_property(obj, "HighlightColor", _rgb_text(tuple(highlight_style.get("line_color", (1.0, 0.95, 0.0)))))
    _set_preview_property(obj, "HighlightDebugStatus", str(highlight_style.get("debug_status", "") or ""))
    _set_preview_property(obj, "HighlightDebugHint", str(highlight_style.get("debug_hint", "") or ""))
    _set_preview_property(obj, "HighlightGeometrySource", str(highlight_geometry_source or ""))
    try:
        vobj = getattr(obj, "ViewObject", None)
        if vobj is not None:
            vobj.Visibility = True
            vobj.ShapeColor = tuple(highlight_style.get("shape_color", highlight_style.get("line_color", (1.0, 0.95, 0.0))))
            vobj.LineColor = tuple(highlight_style.get("line_color", (1.0, 0.95, 0.0)))
            vobj.PointColor = tuple(highlight_style.get("point_color", highlight_style.get("line_color", (1.0, 0.95, 0.0))))
            vobj.LineWidth = float(highlight_style.get("line_width", 13.0 if family == "slope_face_loop" else 9.0))
            vobj.PointSize = float(highlight_style.get("point_size", 14.0 if family == "slope_face_loop" else 10.0))
            vobj.Transparency = 0
    except Exception:
        pass
    try:
        from freecad.Corridor_Road.objects.obj_project import route_to_v1_tree

        route_to_v1_tree(find_project(document), obj)
    except Exception:
        pass
    try:
        document.recompute()
    except Exception:
        pass
    return obj


def _intersection_contract_highlight_context(document) -> dict[str, object]:
    intersection_model = to_intersection_model(find_v1_intersection_model(document))
    context: dict[str, object] = {
        "intersection_model": intersection_model,
        "intersection_id": "",
        "edge_rows": [],
        "zone_rows": [],
        "boundary_loop_rows": [],
        "boundary_loop_segment_rows": [],
        "loop_rows": [],
        "tie_slope_rows": [],
        "boundary_result": None,
        "patch_boundary_result": None,
        "boundary_loop_result": None,
        "tie_slope_result": None,
        "shared_breakline_result": None,
        "shared_boundary_graph_result": None,
    }
    if intersection_model is None:
        return context
    service = IntersectionEvaluationService()
    try:
        topology = service.evaluate_topology(intersection_model)
        edge_network = service.evaluate_edge_network(intersection_model, topology)
        surface_zones = service.evaluate_surface_zones(intersection_model, edge_network)
        applied = to_applied_section_set(find_v1_applied_section_set(document))
        slope_loops = service.evaluate_slope_face_loops(intersection_model, surface_zones, edge_network, applied)
        boundary_loops = service.evaluate_boundary_loops(intersection_model, surface_zones, edge_network, slope_loops, applied)
        context["intersection_id"] = str(getattr(edge_network, "intersection_id", "") or getattr(topology, "intersection_id", "") or "")
        context["edge_rows"] = list(getattr(edge_network, "edge_rows", []) or [])
        context["zone_rows"] = list(getattr(surface_zones, "zone_rows", []) or [])
        context["boundary_loop_rows"] = list(getattr(boundary_loops, "loop_rows", []) or [])
        context["boundary_loop_segment_rows"] = list(getattr(boundary_loops, "segment_rows", []) or [])
        context["boundary_loop_result"] = boundary_loops
        context["loop_rows"] = list(getattr(slope_loops, "loop_rows", []) or [])
    except Exception:
        pass
    try:
        applied = to_applied_section_set(find_v1_applied_section_set(document))
        applied = _applied_section_set_with_intersection_tie_in_sections(applied, document=document)
        prerequisite = corridor_intersection_patch_prerequisite_result(document)
        if applied is not None and str(getattr(prerequisite, "status", "") or "") != "missing":
            tie_in_result = corridor_intersection_tie_in_edge_result(
                applied,
                prerequisite=prerequisite,
                intersection_model=intersection_model,
            )
            boundary_result = corridor_intersection_boundary_segment_result(
                tie_in_result,
                intersection_model=intersection_model,
            )
            slope_face_boundary_result = corridor_intersection_slope_face_boundary_result(
                applied,
                prerequisite=prerequisite,
                intersection_model=intersection_model,
            )
            tie_slope_result = corridor_intersection_tie_slope_result(
                applied,
                prerequisite=prerequisite,
                intersection_model=intersection_model,
                boundary_segment_result=boundary_result,
                slope_face_boundary_result=slope_face_boundary_result,
            )
            context["boundary_result"] = boundary_result
            context["tie_slope_result"] = tie_slope_result
            context["tie_slope_rows"] = list(getattr(tie_slope_result, "tie_slope_rows", []) or [])
            context["patch_boundary_result"] = corridor_intersection_patch_boundary_result(boundary_result)
            shared_result = corridor_intersection_shared_breakline_result(
                applied,
                prerequisite=prerequisite,
                intersection_model=intersection_model,
                patch_boundary_result=context.get("patch_boundary_result"),
                boundary_segment_result=boundary_result,
                boundary_loop_result=context.get("boundary_loop_result"),
            )
            context["shared_breakline_result"] = shared_result
            context["shared_boundary_graph_result"] = corridor_intersection_shared_boundary_graph_result(
                shared_result,
                intersection_id=str(getattr(prerequisite, "intersection_id", "") or ""),
            )
            if not str(context.get("intersection_id", "") or ""):
                context["intersection_id"] = str(getattr(boundary_result, "intersection_id", "") or "")
    except Exception:
        pass
    return context


def _intersection_contract_edge_by_id(edge_rows: list[object], edge_id: str):
    target = str(edge_id or "").strip()
    for edge in list(edge_rows or []):
        if str(getattr(edge, "edge_id", "") or "") == target:
            return edge
    return None


