def _attach_intersection_tie_slope_highlight_metadata(obj, tie_slope) -> None:
    if obj is None or tie_slope is None:
        return
    edge_refs = [
        str(getattr(tie_slope, "inner_breakline_ref", "") or ""),
        str(getattr(tie_slope, "outer_breakline_ref", "") or ""),
        str(getattr(tie_slope, "start_cap_breakline_ref", "") or ""),
        str(getattr(tie_slope, "end_cap_breakline_ref", "") or ""),
    ]
    edge_refs = _unique_text_values([value for value in edge_refs if value])
    shared_refs = _unique_text_values(
        [
            *edge_refs,
            *[str(value or "") for value in tuple(getattr(tie_slope, "shared_breakline_refs", ()) or ())],
        ]
    )
    diagnostics = tuple(str(value or "") for value in tuple(getattr(tie_slope, "diagnostics", ()) or ()) if str(value or ""))
    _set_preview_property(obj, "TieSlopeId", str(getattr(tie_slope, "tie_slope_id", "") or ""))
    _set_preview_property(obj, "TieSlopeStatus", str(getattr(tie_slope, "status", "") or ""))
    _set_preview_property(obj, "TieSlopeRoadRole", str(getattr(tie_slope, "road_role", "") or ""))
    _set_preview_property(obj, "TieSlopeGapRole", str(getattr(tie_slope, "gap_role", "") or ""))
    _set_preview_property(obj, "TieSlopeSide", str(getattr(tie_slope, "side", "") or ""))
    _set_preview_property(obj, "TieSlopeGenerationStatus", str(getattr(tie_slope, "surface_generation_status", "") or ""))
    _set_preview_integer_property(obj, "TieSlopeClosed", 1 if bool(getattr(tie_slope, "closed_xy", False)) else 0)
    _set_preview_integer_property(obj, "TieSlopeEdgeCount", len(edge_refs))
    _set_preview_integer_property(obj, "TieSlopePointCount", int(getattr(tie_slope, "point_count", 0) or 0))
    _set_preview_property(obj, "TieSlopeLoopAreaXY", f"{float(getattr(tie_slope, 'loop_area_xy', 0.0) or 0.0):.6f}")
    _set_preview_string_list_property(obj, "TieSlopeBreaklineRefs", edge_refs)
    _set_preview_string_list_property(obj, "TieSlopeSharedBreaklineRefs", shared_refs)
    _set_preview_string_list_property(obj, "TieSlopeDiagnostics", list(diagnostics))
    _set_preview_property(obj, "TieSlopeRecommendedAction", str(getattr(tie_slope, "recommended_action", "") or ""))


def _intersection_contract_zone_edge_refs(zone) -> list[str]:
    if zone is None:
        return []
    refs: list[str] = []
    for attr in ("boundary_edge_refs", "source_edge_refs", "inner_edge_refs", "outer_edge_refs", "tie_edge_refs"):
        refs.extend(str(value or "") for value in list(getattr(zone, attr, ()) or ()))
    return _unique_text_values(refs)


def _intersection_contract_loop_edge_refs(loop) -> list[str]:
    if loop is None:
        return []
    refs: list[str] = []
    for attr in ("boundary_edge_refs", "inner_edge_refs", "outer_edge_refs", "tie_edge_refs", "source_edge_network_refs"):
        refs.extend(str(value or "") for value in list(getattr(loop, attr, ()) or ()))
    return _unique_text_values(refs)


def _intersection_contract_loop_highlight_shape(part_module, app_module, loop):
    if loop is None:
        return None
    points = []
    for point in list(getattr(loop, "loop_points_xyz", ()) or ()):
        try:
            if len(point) < 3:
                continue
            points.append((float(point[0]), float(point[1]), float(point[2])))
        except Exception:
            continue
    if len(points) < 2:
        return None
    if len(points) >= 3:
        first = points[0]
        last = points[-1]
        if abs(first[0] - last[0]) > 1.0e-6 or abs(first[1] - last[1]) > 1.0e-6:
            points.append(first)
    return _intersection_contract_polyline_shape(part_module, app_module, points)


def _intersection_contract_edge_highlight_shape(part_module, app_module, edge, *, document=None):
    if edge is None:
        return None
    explicit_points = _intersection_contract_edge_explicit_points(edge)
    if len(explicit_points) >= 2:
        explicit_shapes = _intersection_contract_edge_review_shapes(
            part_module,
            app_module,
            edge,
            explicit_points,
            document=document,
        )
        if len(explicit_shapes) == 1:
            return explicit_shapes[0]
        if len(explicit_shapes) > 1:
            try:
                return part_module.makeCompound(explicit_shapes)
            except Exception:
                return explicit_shapes[0]
        return _intersection_contract_polyline_shape(part_module, app_module, explicit_points)
    alignment_points = _intersection_contract_edge_alignment_points(app_module, document, edge)
    if len(alignment_points) >= 2:
        shapes = []
        for offset in _intersection_contract_edge_offsets(edge):
            offset_points = _intersection_contract_offset_points(app_module, alignment_points, offset)
            offset_xyz = [_vector_xyz_tuple(point) for point in offset_points]
            clipped_shapes = _intersection_contract_clipped_polyline_shapes(
                part_module,
                app_module,
                offset_xyz,
                document=document,
            )
            if clipped_shapes:
                shapes.extend(clipped_shapes)
                continue
            shape = _intersection_contract_polyline_shape(part_module, app_module, offset_xyz)
            if shape is not None:
                shapes.append(shape)
        if len(shapes) == 1:
            return shapes[0]
        if len(shapes) > 1:
            try:
                return part_module.makeCompound(shapes)
            except Exception:
                return shapes[0]
    start = tuple(getattr(edge, "start_xyz", (0.0, 0.0, 0.0)) or (0.0, 0.0, 0.0))
    end = tuple(getattr(edge, "end_xyz", (0.0, 0.0, 0.0)) or (0.0, 0.0, 0.0))
    if _points_same_xyz(start, end):
        return None
    clipped_shapes = _intersection_contract_clipped_polyline_shapes(part_module, app_module, [start, end], document=document)
    if clipped_shapes:
        return clipped_shapes[0] if len(clipped_shapes) == 1 else part_module.makeCompound(clipped_shapes)
    return _intersection_contract_polyline_shape(part_module, app_module, [start, end])


def _intersection_contract_edge_review_shapes(
    part_module,
    app_module,
    edge,
    points: list[tuple[float, float, float]],
    *,
    document=None,
) -> list[object]:
    """Create review-only edge shapes constrained to the intersection neighborhood."""

    if len(points) < 2:
        return []
    return _intersection_contract_clipped_polyline_shapes(
        part_module,
        app_module,
        points,
        document=document,
    )


def _intersection_contract_edge_explicit_points(edge) -> list[tuple[float, float, float]]:
    """Return source/evaluation edge points before any alignment-derived review fallback."""

    if edge is None:
        return []
    for attr in (
        "arc_points_xyz",
        "points_xyz",
        "edge_points_xyz",
        "chord_points_xyz",
        "polyline_points_xyz",
        "boundary_points_xyz",
    ):
        points = _intersection_contract_xyz_points(getattr(edge, attr, ()) or ())
        if len(points) >= 2:
            return points
    start = _intersection_contract_xyz_point(getattr(edge, "start_xyz", ()) or ())
    end = _intersection_contract_xyz_point(getattr(edge, "end_xyz", ()) or ())
    if start is None or end is None or _points_same_xyz(start, end):
        return []
    return [start, end]


def _intersection_contract_edge_review_points(
    edge,
    points: list[tuple[float, float, float]],
    *,
    document=None,
) -> list[tuple[float, float, float]]:
    """Limit leg-edge review overlays to the intersection neighborhood."""

    if len(points) < 2:
        return points
    if str(getattr(edge, "edge_family", "") or "") != "leg_edge":
        return points
    anchor = _intersection_contract_anchor_xyz(document)
    if anchor is None:
        return points
    return _clip_segment_to_anchor_box(points, anchor, half_extent=12.0) or points


def _intersection_contract_clipped_polyline_shapes(
    part_module,
    app_module,
    points: list[tuple[float, float, float]],
    *,
    document=None,
    half_extent: float = 12.0,
) -> list[object]:
    if len(points) < 2:
        return []
    anchor = _intersection_contract_anchor_xyz(document)
    if anchor is None:
        shape = _intersection_contract_polyline_shape(part_module, app_module, points)
        return [shape] if shape is not None else []
    shapes: list[object] = []
    for first, second in zip(points[:-1], points[1:]):
        clipped = _clip_segment_to_anchor_box([first, second], anchor, half_extent=half_extent)
        if len(clipped) < 2:
            continue
        shape = _intersection_contract_polyline_shape(part_module, app_module, clipped)
        if shape is not None:
            shapes.append(shape)
    return shapes


def _intersection_contract_anchor_xyz(document=None) -> tuple[float, float, float] | None:
    if document is None:
        return None
    try:
        intersection_model = to_intersection_model(find_v1_intersection_model(document))
        if intersection_model is None:
            return None
        topology = IntersectionEvaluationService().evaluate_topology(intersection_model)
        anchors = list(getattr(topology, "anchor_rows", []) or [])
        if not anchors:
            return None
        return _intersection_contract_xyz_point(getattr(anchors[0], "point_xyz", ()) or ())
    except Exception:
        return None


def _clip_polyline_points_to_anchor_window(points: list[tuple[float, float, float]], anchor: tuple[float, float, float], *, half_length: float) -> list[tuple[float, float, float]]:
    return clip_polyline_points_to_anchor_window(points, anchor, half_length=half_length)


def _clip_segment_to_anchor_box(points: list[tuple[float, float, float]], anchor: tuple[float, float, float], *, half_extent: float) -> list[tuple[float, float, float]]:
    return clip_segment_to_anchor_box(points, anchor, half_extent=half_extent)


def _intersection_contract_xyz_points(values) -> list[tuple[float, float, float]]:
    points: list[tuple[float, float, float]] = []
    for value in list(values or []):
        point = _intersection_contract_xyz_point(value)
        if point is None:
            continue
        if points and _points_same_xyz(points[-1], point):
            continue
        points.append(point)
    return points


def _intersection_contract_xyz_point(value) -> tuple[float, float, float] | None:
    try:
        if value is None or len(value) < 3:
            return None
        point = (float(value[0]), float(value[1]), float(value[2]))
    except Exception:
        return None
    if not all(math.isfinite(component) for component in point):
        return None
    return point


def _intersection_contract_edge_alignment_points(app_module, document, edge) -> list[object]:
    if app_module is None or document is None or edge is None:
        return []
    alignment_ref = str(getattr(edge, "alignment_ref", "") or "").strip()
    if not alignment_ref:
        return []
    centerline_points = _intersection_contract_edge_centerline3d_points(app_module, document, edge, alignment_ref)
    if len(centerline_points) >= 2:
        return centerline_points
    alignment_model = _intersection_contract_alignment_model_by_ref(document, alignment_ref)
    if alignment_model is None:
        return []
    station_start = float(getattr(edge, "station_start", 0.0) or 0.0)
    station_end = float(getattr(edge, "station_end", 0.0) or 0.0)
    start = min(station_start, station_end)
    end = max(station_start, station_end)
    if abs(end - start) <= 1.0e-9:
        return []
    samples = [start, end]
    step = max((end - start) / 6.0, 1.0)
    value = start + step
    while value < end - 1.0e-9:
        samples.append(value)
        value += step
    points = [
        _intersection_contract_alignment_point_at_station(app_module, alignment_model, station)
        for station in sorted(set(round(value, 6) for value in samples))
    ]
    return [point for point in points if point is not None]


def _intersection_contract_edge_centerline3d_points(app_module, document, edge, alignment_ref: str) -> list[object]:
    centerline_result = _build_corridor_centerline3d_result(document)
    if str(getattr(centerline_result, "status", "") or "") != "ready":
        return []
    rows = _intersection_contract_centerline_rows_for_alignment(centerline_result, alignment_ref)
    if len(rows) < 2:
        return []
    station_start = float(getattr(edge, "station_start", 0.0) or 0.0)
    station_end = float(getattr(edge, "station_end", 0.0) or 0.0)
    start = min(station_start, station_end)
    end = max(station_start, station_end)
    if abs(end - start) <= 1.0e-9:
        return []
    samples = [start, end]
    step = max((end - start) / 6.0, 1.0)
    value = start + step
    while value < end - 1.0e-9:
        samples.append(value)
        value += step
    points = [
        _intersection_contract_centerline_point_at_station(app_module, rows, station)
        for station in sorted(set(round(value, 6) for value in samples))
    ]
    return [point for point in points if point is not None]


def _intersection_contract_centerline_rows_for_alignment(centerline_result, alignment_ref: str) -> list[object]:
    target = str(alignment_ref or "").strip()
    all_rows = list(getattr(centerline_result, "point_rows", []) or [])
    if not target:
        return []
    rows = [
        row
        for row in all_rows
        if str(getattr(row, "source_alignment_ref", "") or getattr(row, "alignment_id", "") or "").strip() == target
    ]
    if len(rows) >= 2:
        return sorted(rows, key=lambda row: float(getattr(row, "station", 0.0) or 0.0))
    result_alignment = str(getattr(centerline_result, "alignment_id", "") or "").strip()
    if result_alignment == target and len(all_rows) >= 2:
        return sorted(all_rows, key=lambda row: float(getattr(row, "station", 0.0) or 0.0))
    return []


def _intersection_contract_centerline_point_at_station(app_module, rows: list[object], station: float):
    if app_module is None or not rows:
        return None
    ordered = sorted(rows, key=lambda row: float(getattr(row, "station", 0.0) or 0.0))
    target = float(station)
    first_station = float(getattr(ordered[0], "station", 0.0) or 0.0)
    last_station = float(getattr(ordered[-1], "station", 0.0) or 0.0)
    if target < first_station - 1.0e-6 or target > last_station + 1.0e-6:
        return None
    for row in ordered:
        row_station = float(getattr(row, "station", 0.0) or 0.0)
        if abs(row_station - target) <= 1.0e-6:
            return app_module.Vector(
                float(getattr(row, "x", 0.0) or 0.0),
                float(getattr(row, "y", 0.0) or 0.0),
                float(getattr(row, "z", 0.0) or 0.0),
            )
    for first, second in zip(ordered[:-1], ordered[1:]):
        first_station = float(getattr(first, "station", 0.0) or 0.0)
        second_station = float(getattr(second, "station", 0.0) or 0.0)
        if target < min(first_station, second_station) - 1.0e-6 or target > max(first_station, second_station) + 1.0e-6:
            continue
        span = second_station - first_station
        ratio = 0.0 if abs(span) <= 1.0e-9 else (target - first_station) / span
        return app_module.Vector(
            float(getattr(first, "x", 0.0) or 0.0) + (float(getattr(second, "x", 0.0) or 0.0) - float(getattr(first, "x", 0.0) or 0.0)) * ratio,
            float(getattr(first, "y", 0.0) or 0.0) + (float(getattr(second, "y", 0.0) or 0.0) - float(getattr(first, "y", 0.0) or 0.0)) * ratio,
            float(getattr(first, "z", 0.0) or 0.0) + (float(getattr(second, "z", 0.0) or 0.0) - float(getattr(first, "z", 0.0) or 0.0)) * ratio,
        )
    return None


def _intersection_contract_alignment_model_by_ref(document, alignment_ref: str):
    target = str(alignment_ref or "").strip()
    if document is None or not target:
        return None
    for obj in list(getattr(document, "Objects", []) or []):
        model = to_alignment_model(obj)
        if model is not None and str(getattr(model, "alignment_id", "") or "") == target:
            return model
    return None


def _intersection_contract_alignment_point_at_station(app_module, alignment_model, station: float):
    if alignment_model is None or app_module is None:
        return None
    target = float(station)
    for element in list(getattr(alignment_model, "geometry_sequence", []) or []):
        start = float(getattr(element, "station_start", 0.0) or 0.0)
        end = float(getattr(element, "station_end", start) or start)
        if target < min(start, end) - 1.0e-6 or target > max(start, end) + 1.0e-6:
            continue
        points = _intersection_contract_alignment_element_points(app_module, element)
        if len(points) < 2:
            continue
        length = max(float(getattr(element, "length", 0.0) or 0.0), abs(end - start))
        local = 0.0 if length <= 1.0e-9 else max(0.0, min(length, target - start))
        return _intersection_contract_point_on_polyline(points, local)
    all_points = []
    for element in list(getattr(alignment_model, "geometry_sequence", []) or []):
        all_points.extend(_intersection_contract_alignment_element_points(app_module, element))
    if not all_points:
        return None
    return all_points[0] if target <= 0.0 else all_points[-1]


def _intersection_contract_alignment_element_points(app_module, element) -> list[object]:
    payload = dict(getattr(element, "geometry_payload", {}) or {})
    points = []
    for x, y in zip(list(payload.get("x_values", []) or []), list(payload.get("y_values", []) or [])):
        try:
            points.append(app_module.Vector(float(x), float(y), 0.0))
        except Exception:
            continue
    return points


def _intersection_contract_point_on_polyline(points: list[object], distance: float):
    remaining = max(float(distance), 0.0)
    for first, second in zip(points[:-1], points[1:]):
        segment = second - first
        length = float(getattr(segment, "Length", 0.0) or 0.0)
        if length <= 1.0e-9:
            continue
        if remaining <= length:
            return first + segment.multiply(remaining / length)
        remaining -= length
    return points[-1] if points else None


def _intersection_contract_edge_offsets(edge) -> tuple[float, ...]:
    role = str(getattr(edge, "edge_role", "") or "")
    side = str(getattr(edge, "side", "") or "").lower()
    base = {
        "lane_edge": 1.75,
        "pavement_edge": 3.5,
        "shoulder_edge": 5.0,
        "curb_edge": 4.0,
        "gutter_edge": 4.2,
        "sidewalk_edge": 6.0,
        "daylight_hinge": 6.5,
    }.get(role, 3.5)
    if side in {"left", "l"}:
        return (base,)
    if side in {"right", "r"}:
        return (-base,)
    if role == "daylight_hinge":
        return (base, -base)
    return (base, -base)


def _intersection_contract_offset_points(app_module, points: list[object], offset: float) -> list[object]:
    if app_module is None or len(points) < 2:
        return list(points or [])
    output = []
    for index, point in enumerate(points):
        if index == 0:
            tangent = points[1] - point
        elif index == len(points) - 1:
            tangent = point - points[index - 1]
        else:
            tangent = points[index + 1] - points[index - 1]
        normal = _intersection_contract_horizontal_left_normal(app_module, tangent)
        output.append(point if normal is None else point + normal.multiply(float(offset)))
    return output


def _intersection_contract_horizontal_left_normal(app_module, vector):
    if app_module is None or vector is None:
        return None
    x = float(getattr(vector, "x", 0.0) or 0.0)
    y = float(getattr(vector, "y", 0.0) or 0.0)
    length = math.hypot(x, y)
    if length <= 1.0e-9:
        return None
    return app_module.Vector(-y / length, x / length, 0.0)


def _vector_xyz_tuple(point) -> tuple[float, float, float]:
    return (
        float(getattr(point, "x", 0.0) or 0.0),
        float(getattr(point, "y", 0.0) or 0.0),
        float(getattr(point, "z", 0.0) or 0.0),
    )


def _points_same_xyz(first: tuple[float, float, float], second: tuple[float, float, float]) -> bool:
    if len(first) < 3 or len(second) < 3:
        return False
    return (
        abs(float(first[0]) - float(second[0])) <= 1.0e-9
        and abs(float(first[1]) - float(second[1])) <= 1.0e-9
        and abs(float(first[2]) - float(second[2])) <= 1.0e-9
    )


def _intersection_contract_edge_fallback_y(edge) -> float:
    role = str(getattr(edge, "edge_role", "") or "")
    family = str(getattr(edge, "edge_family", "") or "")
    leg_role = str(getattr(edge, "leg_role", "") or "")
    if family == "curb_return":
        return 6.0
    if role == "daylight_hinge":
        return 4.0 if "side" not in leg_role else -4.0
    return 2.0 if "side" not in leg_role else -2.0


def _intersection_contract_boundary_segment_shapes(part_module, app_module, boundary_result, refs: list[str], *, document=None) -> list[object]:
    shapes: list[object] = []
    if boundary_result is None:
        return shapes
    for segment in list(getattr(boundary_result, "segment_rows", []) or []):
        points = list(getattr(segment, "chord_points_xyz", ()) or ())
        if len(points) < 2:
            points = [
                tuple(getattr(segment, "start_xyz", (0.0, 0.0, 0.0)) or (0.0, 0.0, 0.0)),
                tuple(getattr(segment, "end_xyz", (0.0, 0.0, 0.0)) or (0.0, 0.0, 0.0)),
            ]
        clipped_shapes = _intersection_contract_clipped_polyline_shapes(part_module, app_module, points, document=document)
        if clipped_shapes:
            shapes.extend(clipped_shapes)
            refs.append(str(getattr(segment, "boundary_segment_id", "") or ""))
    return shapes


def _intersection_slope_face_cell_breakline_shapes(part_module, app_module, *, document=None, row: dict[str, object], refs: list[str]) -> list[object]:
    source_obj = _corridor_build_preview_object(document, "intersection_slope")
    if source_obj is None:
        return []
    boundary_tokens = _intersection_slope_face_cell_boundary_tokens(str(row.get("boundary_refs", "") or ""))
    if not boundary_tokens:
        return []
    segments = [
        parsed
        for parsed in (_parse_shared_breakline_segment_row(raw) for raw in list(getattr(source_obj, "SharedBreaklineSegmentRows", []) or []))
        if parsed is not None
    ]
    matched = [
        segment
        for segment in segments
        if _intersection_slope_face_cell_segment_matches(segment, boundary_tokens)
    ]
    shapes: list[object] = []
    for segment in matched:
        start = tuple(segment.get("start", ()) or ())
        end = tuple(segment.get("end", ()) or ())
        clipped_shapes = _intersection_contract_clipped_polyline_shapes(part_module, app_module, [start, end], document=document)
        if clipped_shapes:
            shapes.extend(clipped_shapes)
            refs.append(str(segment.get("breakline_id", "") or ""))
    return shapes


def _intersection_contract_tie_slope_highlight_shapes(part_module, app_module, tie_slope, *, document=None, refs: list[str]) -> list[object]:
    if tie_slope is None:
        return []
    edge_sources = (
        ("inner", "inner_intersection_edge_xyz", "inner_breakline_ref"),
        ("outer", "outer_applied_section_edge_xyz", "outer_breakline_ref"),
        ("start_cap", "start_cap_edge_xyz", "start_cap_breakline_ref"),
        ("end_cap", "end_cap_edge_xyz", "end_cap_breakline_ref"),
    )
    shapes: list[object] = []
    for _edge_key, point_attr, ref_attr in edge_sources:
        points = [
            _xyz_tuple(point)
            for point in tuple(getattr(tie_slope, point_attr, ()) or ())
            if len(tuple(point or ())) >= 3
        ]
        if len(points) < 2:
            continue
        clipped_shapes = _intersection_contract_clipped_polyline_shapes(
            part_module,
            app_module,
            points,
            document=document,
            half_extent=24.0,
        )
        if clipped_shapes:
            shapes.extend(clipped_shapes)
            refs.append(str(getattr(tie_slope, ref_attr, "") or ""))
    if shapes:
        refs.append(str(getattr(tie_slope, "tie_slope_id", "") or ""))
    return shapes


def _intersection_slope_face_cell_boundary_tokens(boundary_refs: str) -> set[str]:
    tokens: set[str] = set()
    for raw in str(boundary_refs or "").replace(";", ",").split(","):
        text = raw.strip()
        if not text:
            continue
        tokens.add(text)
        tokens.add(text.replace("_", "-"))
        role = text.split(":", 1)[0].strip()
        if role:
            tokens.add(role)
            tokens.add(role.replace("_", "-"))
    return {token for token in tokens if token}


def _intersection_slope_face_cell_segment_matches(segment: dict[str, object], tokens: set[str]) -> bool:
    breakline_id = str(segment.get("breakline_id", "") or "")
    role = str(segment.get("role", "") or "")
    values = {
        breakline_id,
        breakline_id.replace("_", "-"),
        role,
        role.replace("_", "-"),
    }
    for token in tokens:
        if token in values:
            return True
        if token and token in breakline_id:
            return True
        if token and token in role:
            return True
    return False


def _intersection_shared_boundary_graph_contract_shapes(
    part_module,
    app_module,
    *,
    graph_result=None,
    row: dict[str, object],
    refs: list[str],
    document=None,
) -> list[object]:
    if graph_result is None:
        return []
    row_id = str(row.get("row_id", "") or "").strip()
    role = str(row.get("role", "") or "").strip()
    if not row_id:
        return []
    node_by_id = {
        str(getattr(node, "node_id", "") or ""): node
        for node in list(getattr(graph_result, "node_rows", []) or [])
        if str(getattr(node, "node_id", "") or "")
    }
    if role.startswith("cell:"):
        cell = _intersection_shared_boundary_graph_cell_by_id(graph_result, row_id)
        if cell is None:
            return []
        points = _intersection_contract_xyz_points(getattr(cell, "loop_points_xyz", ()) or ())
        if len(points) >= 2:
            if len(points) >= 3 and not _points_same_xy(points[0], points[-1]):
                points.append(points[0])
            if _intersection_shared_boundary_graph_cell_role_should_clip(str(getattr(cell, "cell_role", "") or "")):
                anchor = _intersection_contract_anchor_xyz(document)
                clipped_shapes = _intersection_shared_boundary_graph_cell_clipped_shapes(
                    part_module,
                    app_module,
                    points,
                    anchor=anchor,
                )
                if clipped_shapes:
                    refs.append(row_id)
                    return clipped_shapes
            shape = _intersection_contract_polyline_shape(part_module, app_module, points)
            if shape is not None:
                refs.append(row_id)
                return [shape]
        shapes: list[object] = []
        for edge_ref in tuple(getattr(cell, "boundary_edge_refs", ()) or ()):
            edge = _intersection_shared_boundary_graph_edge_by_id(graph_result, str(edge_ref or ""))
            shape = _intersection_shared_boundary_graph_edge_shape(
                part_module,
                app_module,
                edge,
                node_by_id,
                document=document,
            )
            if shape is not None:
                shapes.append(shape)
                refs.append(str(edge_ref or ""))
        return shapes
    edge = _intersection_shared_boundary_graph_edge_by_id(graph_result, row_id)
    shape = _intersection_shared_boundary_graph_edge_shape(part_module, app_module, edge, node_by_id, document=document)
    if shape is None:
        return []
    refs.append(row_id)
    return [shape]


def _intersection_shared_boundary_graph_edge_by_id(graph_result, edge_id: str):
    target = str(edge_id or "").strip()
    if graph_result is None or not target:
        return None
    for edge in list(getattr(graph_result, "edge_rows", []) or []):
        if str(getattr(edge, "edge_id", "") or "") == target:
            return edge
    return None


def _intersection_shared_boundary_graph_cell_by_id(graph_result, cell_id: str):
    target = str(cell_id or "").strip()
    if graph_result is None or not target:
        return None
    for cell in list(getattr(graph_result, "cell_rows", []) or []):
        if str(getattr(cell, "cell_id", "") or "") == target:
            return cell
    return None


def _intersection_shared_boundary_graph_edge_shape(part_module, app_module, edge, node_by_id: dict[str, object], *, document=None):
    if edge is None:
        return None
    start_node = node_by_id.get(str(getattr(edge, "from_node_ref", "") or ""))
    end_node = node_by_id.get(str(getattr(edge, "to_node_ref", "") or ""))
    start = _intersection_shared_boundary_graph_node_xyz(start_node)
    end = _intersection_shared_boundary_graph_node_xyz(end_node)
    if start is None or end is None or _points_same_xyz(start, end):
        return None
    points = _intersection_shared_boundary_graph_edge_review_points(edge, [start, end], document=document)
    return _intersection_contract_polyline_shape(part_module, app_module, points)


def _intersection_shared_boundary_graph_edge_review_points(
    edge,
    points: list[tuple[float, float, float]],
    *,
    document=None,
) -> list[tuple[float, float, float]]:
    if len(points) < 2:
        return points
    role = str(getattr(edge, "edge_role", "") or "")
    if not _intersection_shared_boundary_graph_role_should_clip(role):
        return points
    anchor = _intersection_contract_anchor_xyz(document)
    if anchor is None:
        return points
    return _clip_segment_to_anchor_box(points, anchor, half_extent=12.0) or points


def _intersection_shared_boundary_graph_role_should_clip(role: str) -> bool:
    role_text = str(role or "")
    return bool(role_text)


def _intersection_shared_boundary_graph_cell_role_should_clip(role: str) -> bool:
    role_text = str(role or "")
    return bool(role_text)


def _intersection_shared_boundary_graph_cell_clipped_shapes(
    part_module,
    app_module,
    points: list[tuple[float, float, float]],
    *,
    anchor: tuple[float, float, float] | None,
) -> list[object]:
    if anchor is None or len(points) < 2:
        return []
    shapes: list[object] = []
    for start, end in zip(points[:-1], points[1:]):
        clipped = _clip_segment_to_anchor_box([start, end], anchor, half_extent=12.0)
        if not clipped:
            continue
        if len(clipped) < 2 or _points_same_xyz(clipped[0], clipped[-1]):
            continue
        shape = _intersection_contract_polyline_shape(part_module, app_module, clipped)
        if shape is not None:
            shapes.append(shape)
    return shapes


def _intersection_shared_boundary_graph_node_xyz(node) -> tuple[float, float, float] | None:
    if node is None:
        return None
    try:
        point = (
            float(getattr(node, "x", 0.0) or 0.0),
            float(getattr(node, "y", 0.0) or 0.0),
            float(getattr(node, "z", 0.0) or 0.0),
        )
    except Exception:
        return None
    if not all(math.isfinite(component) for component in point):
        return None
    return point


def _points_same_xy(first: tuple[float, float, float], second: tuple[float, float, float]) -> bool:
    if len(first) < 2 or len(second) < 2:
        return False
    return (
        abs(float(first[0]) - float(second[0])) <= 1.0e-9
        and abs(float(first[1]) - float(second[1])) <= 1.0e-9
    )


def _intersection_contract_patch_boundary_shapes(part_module, app_module, patch_boundary_result, refs: list[str]) -> list[object]:
    if patch_boundary_result is None:
        return []
    grouped: dict[str, list[object]] = {}
    for point in list(getattr(patch_boundary_result, "point_rows", []) or []):
        ring_id = str(getattr(point, "ring_id", "") or "outer")
        grouped.setdefault(ring_id, []).append(point)
    shapes: list[object] = []
    for ring_id, points in sorted(grouped.items()):
        ordered = sorted(points, key=lambda item: int(getattr(item, "order_index", 0) or 0))
        xyz = [
            (
                float(getattr(point, "x", 0.0) or 0.0),
                float(getattr(point, "y", 0.0) or 0.0),
                float(getattr(point, "z", 0.0) or 0.0),
            )
            for point in ordered
        ]
        if len(xyz) >= 3:
            xyz.append(xyz[0])
        shape = _intersection_contract_polyline_shape(part_module, app_module, xyz)
        if shape is not None:
            shapes.append(shape)
            refs.append(ring_id)
    return shapes


def _intersection_contract_polygon_face(
    part_module,
    app_module,
    points_xyz: list[tuple[float, float, float]],
    *,
    z_offset: float = INTERSECTION_CONTRACT_HIGHLIGHT_Z_OFFSET,
):
    wire = _intersection_contract_polyline_shape(part_module, app_module, points_xyz, z_offset=z_offset)
    if wire is None:
        return None
    try:
        return part_module.Face(wire)
    except Exception:
        return None


def _intersection_contract_polyline_shape(
    part_module,
    app_module,
    points_xyz: list[tuple[float, float, float]],
    *,
    z_offset: float = INTERSECTION_CONTRACT_HIGHLIGHT_Z_OFFSET,
):
    vectors = []
    for point in list(points_xyz or []):
        if len(point) < 3:
            continue
        try:
            vectors.append(
                app_module.Vector(
                    float(point[0]),
                    float(point[1]),
                    float(point[2]) + float(z_offset),
                )
            )
        except Exception:
            continue
    if len(vectors) < 2:
        return None
    try:
        if len(vectors) == 2:
            if vectors[0].distanceToPoint(vectors[1]) <= 1.0e-9:
                return None
            return part_module.makeLine(vectors[0], vectors[1])
        return part_module.makePolygon(vectors)
    except Exception:
        return None


def corridor_drainage_flow_review_rows(document=None) -> list[dict[str, object]]:
    """Return Flow Route review rows for Build Corridor Guided Review."""

    doc = document or (getattr(App, "ActiveDocument", None) if App is not None else None)
    drainage_model = to_drainage_model(find_v1_drainage_model(doc))
    if drainage_model is None:
        _remove_preview_object(doc, "ReviewIssueDrainageFlowRoutes")
        return [
            {
                "flow_route_id": "",
                "status": "missing",
                "from_element": "",
                "to_element": "",
                "outlet": "",
                "structure_refs": "",
                "station_start": "",
                "station_end": "",
                "notes": "DrainageModel is required before Drainage Flow review.",
            }
        ]
    if _is_intersection_preset_drainage_model(drainage_model):
        _remove_preview_object(doc, "ReviewIssueDrainageFlowRoutes")
        return [
            {
                "flow_route_id": "",
                "status": "missing",
                "from_element": "",
                "to_element": "",
                "outlet": "",
                "structure_refs": "",
                "station_start": "",
                "station_end": "",
                "notes": "Intersection preset drainage is source-stage handoff metadata, not a Drainage Flow highlight source.",
            }
        ]
    element_by_id = {
        str(getattr(row, "drainage_element_id", "") or ""): row
        for row in list(getattr(drainage_model, "element_rows", []) or [])
    }
    structure_model = to_structure_model(find_v1_structure_model(doc))
    structure_by_id = {
        str(getattr(row, "structure_id", "") or ""): row
        for row in list(getattr(structure_model, "structure_rows", []) or [])
    } if structure_model is not None else {}
    rows: list[dict[str, object]] = []
    for flow_row in list(getattr(drainage_model, "flow_route_rows", []) or []):
        connected_elements = _drainage_flow_connected_elements(flow_row, element_by_id)
        structure_refs = _drainage_flow_structure_refs(flow_row, connected_elements)
        station_range = _drainage_flow_station_range(flow_row, connected_elements, structure_by_id)
        route_id = str(getattr(flow_row, "flow_route_id", "") or "")
        from_ref = str(getattr(flow_row, "from_element_ref", "") or "")
        to_ref = str(getattr(flow_row, "to_element_ref", "") or "")
        outlet_ref = str(getattr(flow_row, "outlet_ref", "") or "")
        chain_values = [value for value in (from_ref, to_ref, outlet_ref) if value]
        missing_refs = [
            ref
            for ref in (from_ref, to_ref)
            if ref and ref.startswith("drainage:") and ref not in element_by_id
        ]
        if missing_refs:
            status = "missing"
            notes = "Broken Flow Route element refs: " + ", ".join(_display_source_ref(ref) for ref in missing_refs)
        elif not chain_values:
            status = "missing"
            notes = "Flow Route has no From, To, or Outlet refs."
        elif not structure_refs:
            status = "warn"
            notes = f"Route {' -> '.join(_display_source_ref(value) for value in chain_values)} has no linked Structure ref."
        else:
            status = "ready"
            notes = (
                f"Route {' -> '.join(_display_source_ref(value) for value in chain_values)}; "
                f"structures={', '.join(_display_source_ref(ref) for ref in structure_refs)}"
            )
        rows.append(
            {
                "flow_route_id": route_id,
                "status": status,
                "from_element": from_ref,
                "to_element": to_ref,
                "outlet": outlet_ref,
                "structure_refs": ", ".join(structure_refs),
                "station_start": "" if station_range is None else station_range[0],
                "station_end": "" if station_range is None else station_range[1],
                "highlight_mode": _drainage_flow_row_highlight_mode(doc, route_id),
                "notes": notes,
            }
        )
    if not rows:
        _remove_preview_object(doc, "ReviewIssueDrainageFlowRoutes")
        return [
            {
                "flow_route_id": "",
                "status": "missing",
                "from_element": "",
                "to_element": "",
                "outlet": "",
                "structure_refs": "",
                "station_start": "",
                "station_end": "",
                "notes": "No Drainage Flow Route rows.",
            }
        ]
    return rows


def _is_intersection_preset_drainage_model(drainage_model) -> bool:
    drainage_model_id = str(getattr(drainage_model, "drainage_model_id", "") or "")
    if drainage_model_id.startswith("drainage:intersection-preset-"):
        return True
    source_refs = [str(value or "") for value in list(getattr(drainage_model, "source_refs", []) or [])]
    if any(value.startswith("intersection:") for value in source_refs):
        flow_rows = list(getattr(drainage_model, "flow_route_rows", []) or [])
        return all(
            str(getattr(row, "flow_route_id", "") or "").startswith("flow-route:intersection-")
            for row in flow_rows
        )
    return False


def corridor_drainage_flow_review_summary(document=None) -> dict[str, object]:
    """Return a compact Flow Route readiness summary for Guided Review."""

    rows = corridor_drainage_flow_review_rows(document)
    real_rows = [row for row in rows if row.get("flow_route_id")]
    if not real_rows:
        return {
            "status": "missing",
            "route_count": 0,
            "structure_count": 0,
            "focus": "Drainage Flow",
            "notes": str(rows[0].get("notes", "No Drainage Flow Route rows.") if rows else "No Drainage Flow Route rows."),
        }
    ready = sum(1 for row in real_rows if row.get("status") == "ready")
    warn = sum(1 for row in real_rows if row.get("status") == "warn")
    missing = sum(1 for row in real_rows if row.get("status") == "missing")
    structure_refs = sorted(
        {
            ref.strip()
            for row in real_rows
            for ref in str(row.get("structure_refs", "") or "").split(",")
            if ref.strip()
        }
    )
    route_labels = [_display_source_ref(row.get("flow_route_id", "")) for row in real_rows]
    if missing:
        status = "missing"
        notes = f"{missing} Flow Route row(s) have broken or empty route refs."
    elif warn:
        status = "warn"
        notes = f"{warn} Flow Route row(s) have no linked Structure ref."
    else:
        status = "ready"
        notes = f"Flow Routes: {len(real_rows)}; structures: {', '.join(_display_source_ref(ref) for ref in structure_refs) or '-'}."
    return {
        "status": status,
        "route_count": len(real_rows),
        "ready_count": ready,
        "warn_count": warn,
        "missing_count": missing,
        "structure_count": len(structure_refs),
        "focus": ", ".join(route_labels[:3]) + ("..." if len(route_labels) > 3 else ""),
        "notes": notes,
    }


def corridor_drainage_review_rows(document=None) -> list[dict[str, object]]:
    """Return station-level drainage source diagnostics from Applied Sections."""

    doc = document or (getattr(App, "ActiveDocument", None) if App is not None else None)
    applied = to_applied_section_set(find_v1_applied_section_set(doc))
    if applied is None:
        return [
            {
                "station": "",
                "section_id": "",
                "context": "roadside_drainage",
                "context_label": "Roadside Drainage",
                "status": "missing",
                "ditch_point_count": 0,
                "left_count": 0,
                "right_count": 0,
                "notes": "Applied Sections are required before drainage review.",
            }
        ]
    sections = {
        str(getattr(section, "applied_section_id", "") or ""): section
        for section in list(getattr(applied, "sections", []) or [])
    }
    region_model = to_region_model(find_v1_region_model(doc))
    drainage_model = to_drainage_model(find_v1_drainage_model(doc))
    output: list[dict[str, object]] = []
    for row in sorted(list(getattr(applied, "station_rows", []) or []), key=lambda item: float(getattr(item, "station", 0.0) or 0.0)):
        section_id = str(getattr(row, "applied_section_id", "") or "")
        section = sections.get(section_id)
        station = float(getattr(row, "station", 0.0) or 0.0)
        active_ditch_rows = _active_ditch_drainage_rows(
            drainage_model,
            region_model=region_model,
            station=station,
        )
        if section is None:
            output.append(
                {
                    "station": station,
                    "section_id": section_id,
                    "context": "roadside_drainage",
                    "context_label": "Roadside Drainage",
                    "status": "missing",
                    "ditch_point_count": 0,
                    "left_count": 0,
                    "right_count": 0,
                    "marker_object": _drainage_review_marker_name(len(output)),
                    "x": "",
                    "y": "",
                    "z": "",
                    "notes": "Applied section row is missing.",
                }
            )
            continue
        ditch_points = [
            point
            for point in list(getattr(section, "point_rows", []) or [])
            if str(getattr(point, "point_role", "") or "") == "ditch_surface"
        ]
        left_count = sum(1 for point in ditch_points if _drainage_point_side(point) == "L")
        right_count = sum(1 for point in ditch_points if _drainage_point_side(point) == "R")
        mismatch_notes = _drainage_source_surface_mismatch_notes(active_ditch_rows, ditch_points)
        if active_ditch_rows and any(note.startswith("missing_side=") for note in mismatch_notes):
            status = "missing"
            notes = "Active Drainage ditch row has no matching ditch_surface side. " + " ".join(mismatch_notes)
        elif not ditch_points:
            status = "missing"
            notes = "No ditch_surface point rows from Assembly/Applied Sections."
            if active_ditch_rows:
                notes += " " + " ".join(mismatch_notes)
        elif mismatch_notes:
            status = "warn"
            notes = "Drainage source/result mismatch. " + " ".join(mismatch_notes)
        elif left_count and right_count:
            status = "ready"
            notes = "Left and right ditch surface points available."
        else:
            status = "warn"
            notes = "Only one side has ditch surface points."
        marker_point = _drainage_review_marker_point(section, ditch_points)
        output.append(
            {
                "station": station,
                "section_id": section_id,
                "context": "roadside_drainage",
                "context_label": "Roadside Drainage",
                "status": status,
                "ditch_point_count": len(ditch_points),
                "left_count": left_count,
                "right_count": right_count,
                "marker_object": _drainage_review_marker_name(len(output)),
                "x": f"{marker_point[0]:.6f}",
                "y": f"{marker_point[1]:.6f}",
                "z": f"{marker_point[2]:.6f}",
                "notes": notes,
            }
        )
    if not output:
        output = [
            {
                "station": "",
                "section_id": "",
                "context": "roadside_drainage",
                "context_label": "Roadside Drainage",
                "status": "missing",
                "ditch_point_count": 0,
                "left_count": 0,
                "right_count": 0,
                "notes": "No Applied Section station rows.",
            }
        ]
    if output and output[0].get("station", "") == "":
        return output
    output.extend(corridor_intersection_drainage_review_rows(doc, marker_start_index=len(output)))
    return output


def corridor_intersection_drainage_review_rows(document=None, *, marker_start_index: int = 0) -> list[dict[str, object]]:
    """Return intersection low-point and Drainage Element coverage diagnostics."""

    doc = document or (getattr(App, "ActiveDocument", None) if App is not None else None)
    applied = to_applied_section_set(find_v1_applied_section_set(doc))
    if applied is None:
        return []
    applied = _applied_section_set_with_intersection_tie_in_sections(
        applied,
        document=doc,
    )
    prerequisite = corridor_intersection_patch_prerequisite_result(doc)
    if str(getattr(prerequisite, "status", "") or "") != "ready":
        return []
    patch_points = _intersection_patch_fg_points(applied, prerequisite)
    if not patch_points:
        return []
    low_point = min(patch_points, key=lambda item: float(item.get("z", 0.0) or 0.0))
    low_z = float(low_point.get("z", 0.0) or 0.0)
    low_points = [point for point in patch_points if abs(float(point.get("z", 0.0) or 0.0) - low_z) <= 0.001]
    drainage_model = to_drainage_model(find_v1_drainage_model(doc))
    intersection_id = str(getattr(prerequisite, "intersection_id", "") or "")
    control_refs = list(getattr(prerequisite, "control_region_refs", ()) or ())
    coverage = _intersection_drainage_coverage(
        drainage_model,
        prerequisite,
        low_point_station=float(low_point.get("station", 0.0) or 0.0),
    )
    coverage_rows = list(coverage.get("ready_rows", []) or [])
    candidate_rows = list(coverage.get("candidate_rows", []) or [])
    coverage_diagnostics = list(coverage.get("diagnostics", []) or [])
    coverage_refs = [
        str(getattr(row, "drainage_element_id", "") or "")
        for row in coverage_rows
        if str(getattr(row, "drainage_element_id", "") or "").strip()
    ]
    if coverage_rows:
        status = "ready"
        notes = (
            f"Intersection drainage handoff ready. low_point_z={low_z:.3f}; "
            f"Drainage Elements={', '.join(_display_source_ref(ref) for ref in coverage_refs[:4])}."
        )
    elif candidate_rows:
        status = "warn"
        candidate_refs = [
            str(getattr(row, "drainage_element_id", "") or "")
            for row in candidate_rows
            if str(getattr(row, "drainage_element_id", "") or "").strip()
        ]
        notes = (
            f"Intersection Drainage Elements are linked, but none cover the low-point station. "
            f"low_point_station={float(low_point.get('station', 0.0) or 0.0):.3f}; "
            f"candidates={', '.join(_display_source_ref(ref) for ref in candidate_refs[:4]) or '-'}."
        )
    else:
        status = "missing"
        notes = (
            f"Intersection low-point candidate has no Drainage Element coverage. low_point_z={low_z:.3f}; "
            f"control_regions={', '.join(_display_source_ref(ref) for ref in control_refs) or '-'}."
        )
    return [
        {
            "review_kind": "intersection_drainage",
            "context": "intersection_drainage",
            "context_label": "Intersection Drainage",
            "intersection_id": intersection_id,
            "station": float(low_point.get("station", 0.0) or 0.0),
            "section_id": "",
            "status": status,
            "ditch_point_count": len(patch_points),
            "left_count": "-",
            "right_count": "-",
            "marker_object": _drainage_review_marker_name(int(marker_start_index or 0)),
            "marker_label": f"Suggested Inlet - {intersection_id or 'intersection'}",
            "marker_kind": "suggested_inlet",
            "x": f"{float(low_point.get('x', 0.0) or 0.0):.6f}",
            "y": f"{float(low_point.get('y', 0.0) or 0.0):.6f}",
            "z": f"{low_z:.6f}",
            "low_point_count": len(low_points),
            "drainage_element_refs": ",".join(coverage_refs),
            "drainage_candidate_refs": ",".join(
                str(getattr(row, "drainage_element_id", "") or "")
                for row in candidate_rows
                if str(getattr(row, "drainage_element_id", "") or "").strip()
            ),
            "control_region_refs": ",".join(control_refs),
            "diagnostics": "; ".join(coverage_diagnostics),
            "notes": notes,
        }
    ]


def corridor_drainage_review_summary(document=None) -> dict[str, object]:
    """Return a compact drainage readiness summary for Build Corridor review."""

    rows = corridor_drainage_review_rows(document)
    real_rows = [row for row in rows if row.get("station") != ""]
    ready = sum(1 for row in real_rows if row.get("status") == "ready")
    warn = sum(1 for row in real_rows if row.get("status") == "warn")
    missing = sum(1 for row in real_rows if row.get("status") == "missing")
    point_count = sum(int(row.get("ditch_point_count", 0) or 0) for row in real_rows)
    if not real_rows:
        status = "missing"
        notes = str(rows[0].get("notes", "No drainage rows.") if rows else "No drainage rows.")
    elif missing:
        status = "missing"
        intersection_missing = sum(
            1 for row in real_rows
            if row.get("status") == "missing" and row.get("review_kind") == "intersection_drainage"
        )
        if intersection_missing:
            notes = f"{intersection_missing} intersection(s) without Drainage Element coverage."
        else:
            notes = f"{missing} station(s) without ditch_surface points."
    elif warn:
        status = "warn"
        notes = f"{warn} station(s) have one-sided ditch points."
    else:
        status = "ready"
        notes = "Drainage source points available at all reviewed stations."
    return {
        "status": status,
        "station_count": len(real_rows),
        "ready_count": ready,
        "warn_count": warn,
        "missing_count": missing,
        "ditch_point_count": point_count,
        "notes": notes,
    }


def corridor_region_boundary_rows(document=None) -> list[dict[str, object]]:
    """Return Build Corridor Region rows with boundary continuity diagnostics."""

    doc = document or (getattr(App, "ActiveDocument", None) if App is not None else None)
    applied = to_applied_section_set(find_v1_applied_section_set(doc))
    if applied is None:
        return [
            {
                "alignment_id": "",
                "region_id": "",
                "station_start": "",
                "station_end": "",
                "assembly": "",
                "structure": "",
                "drainage": "",
                "surface_status": "missing",
                "boundary_status": "missing",
                "diagnostics": "Applied Sections are required before Region boundary review.",
            }
        ]
    sections = _station_ordered_applied_sections(applied)
    if not sections:
        return [
            {
                "alignment_id": "",
                "region_id": "",
                "station_start": "",
                "station_end": "",
                "assembly": "",
                "structure": "",
                "drainage": "",
                "surface_status": "missing",
                "boundary_status": "missing",
                "diagnostics": "No Applied Section station rows are available.",
            }
        ]
    region_models = _document_region_models(doc)
    region_model = region_models[0] if region_models else None
    structure_model = to_structure_model(find_v1_structure_model(doc))
    drainage_model = to_drainage_model(find_v1_drainage_model(doc))
    intersection_model = to_intersection_model(find_v1_intersection_model(doc))
    source_region_groups = [
        (model, _region_source_rows(model))
        for model in region_models
        if _region_source_rows(model)
    ]
    if source_region_groups:
        rows: list[dict[str, object]] = []
        for model, source_rows in source_region_groups:
            alignment_sections = _sections_for_region_model(sections, model)
            rows.extend(
                _region_boundary_rows_from_source_regions(
                    source_rows,
                    alignment_sections,
                    document=doc,
                    region_model=model,
                    structure_model=structure_model,
                    drainage_model=drainage_model,
                    intersection_model=intersection_model,
                )
            )
        return rows
    groups = _contiguous_region_groups(sections)
    rows: list[dict[str, object]] = []
    for index, group in enumerate(groups):
        group_sections = list(group.get("sections", []) or [])
        first = group_sections[0]
        last = group_sections[-1]
        diagnostics: list[dict[str, str]] = []
        if index > 0:
            diagnostics.extend(_region_boundary_diagnostics(groups[index - 1]["sections"][-1], first, boundary_side="start"))
        if index < len(groups) - 1:
            diagnostics.extend(_region_boundary_diagnostics(last, groups[index + 1]["sections"][0], boundary_side="end"))
        boundary_status = _region_boundary_status(diagnostics)
        row = {
            "alignment_id": _unique_join(_section_text_values(group_sections, "alignment_id")),
            "region_id": str(group.get("region_id", "") or ""),
            "station_start": float(group.get("station_start", 0.0) or 0.0),
            "station_end": float(group.get("station_end", 0.0) or 0.0),
            "assembly": _unique_join(_section_text_values(group_sections, "assembly_id")),
            "structure": _region_group_structure_summary(
                group_sections,
                region_model=region_model,
                structure_model=structure_model,
            ),
            "drainage": _region_group_drainage_summary(
                group_sections,
                region_model=region_model,
                drainage_model=drainage_model,
            ),
            "intersection": _region_group_intersection_summary(None, group_sections, intersection_model=intersection_model),
            "surface_status": _region_group_surface_status(group_sections),
            "boundary_status": boundary_status,
            "diagnostics": _region_boundary_diagnostic_summary(diagnostics),
            "diagnostic_count": len(diagnostics),
        }
        row.update(_region_generated_object_summary(doc, row))
        rows.append(row)
    return rows


def show_corridor_build_review_object(document=None, row_index: int = 0):
    """Select and fit one Build Corridor review object by review-table row index."""

    doc = document or (getattr(App, "ActiveDocument", None) if App is not None else None)
    rows = corridor_build_review_rows(doc)
    if row_index < 0 or row_index >= len(rows):
        raise IndexError("Build Corridor review row index is out of range.")
    row = rows[row_index]
    object_name = str(row.get("object_name", "") or "")
    obj = doc.getObject(object_name) if doc is not None and object_name else None
    if obj is None:
        raise RuntimeError(f"{row.get('result', 'Result')} has not been built yet.")
    _select_and_fit_object(obj)
    return obj


def focus_corridor_region_boundary_row(document=None, row_index: int = 0):
    """Select the built 3D Region surface object for one Region row in Build Corridor."""

    doc = document or (getattr(App, "ActiveDocument", None) if App is not None else None)
    rows = corridor_region_boundary_rows(doc)
    if row_index < 0 or row_index >= len(rows):
        raise IndexError("Region boundary row index is out of range.")
    row = rows[row_index]
    region_id = str(row.get("region_id", "") or "")
    if not region_id:
        raise RuntimeError("No Region row is available to display.")
    _remove_legacy_region_display_objects(doc)
    objects = _corridor_region_preview_objects(doc, region_id, row=row)
    if not objects:
        raise RuntimeError("Region object set has not been built yet. Rebuild Corridor first.")
    set_all_corridor_build_preview_visibility(doc, False, include_issue_markers=True)
    if set_corridor_build_preview_visibility(doc, "design", True) is None:
        set_corridor_build_preview_visibility(doc, "centerline", True)
    for obj in objects:
        _set_object_visibility(obj, True)
        _style_region_preview_object(obj, selected=True)
    try:
        doc.recompute()
    except Exception:
        pass
    _select_and_fit_objects(objects)
    return objects[0]


def corridor_surface_transition_rows(document=None) -> list[dict[str, object]]:
    """Return Build Corridor rows for user-selected Surface Transition ranges."""

    doc = document or (getattr(App, "ActiveDocument", None) if App is not None else None)
    transition_model = to_surface_transition_model(find_v1_surface_transition_model(doc))
    if transition_model is None:
        return []
    applied = to_applied_section_set(find_v1_applied_section_set(doc))
    region_surface_contexts = _surface_transition_region_surface_contexts(applied)
    region_rows = corridor_region_boundary_rows(doc)
    validation = SurfaceTransitionValidationService().validate(
        transition_model,
        known_region_refs=_surface_transition_known_region_refs(region_rows),
        boundary_stations=_surface_transition_boundary_stations(region_rows),
    )
    diagnostics_by_source: dict[str, list[object]] = {}
    for diagnostic in list(validation.diagnostic_rows or []):
        diagnostics_by_source.setdefault(str(getattr(diagnostic, "source_ref", "") or ""), []).append(diagnostic)

    rows: list[dict[str, object]] = []
    for transition in list(getattr(transition_model, "transition_ranges", []) or []):
        transition_id = str(getattr(transition, "transition_id", "") or "")
        diagnostics = diagnostics_by_source.get(transition_id, [])
        generation_diagnostics = _surface_transition_generation_diagnostics(
            applied,
            transition_model,
            transition_id=transition_id,
            target_surface_kinds=list(getattr(transition, "target_surface_kinds", []) or []),
        )
        row_status = _surface_transition_row_status(transition, diagnostics)
        if generation_diagnostics and row_status in {"active", "approved", "draft"}:
            row_status = "warn"
        station_start = float(getattr(transition, "station_start", 0.0) or 0.0)
        station_end = float(getattr(transition, "station_end", 0.0) or 0.0)
        sample_interval = float(getattr(transition, "sample_interval", SURFACE_TRANSITION_DEFAULT_SAMPLE_INTERVAL) or SURFACE_TRANSITION_DEFAULT_SAMPLE_INTERVAL)
        rows.append(
            {
                "transition_id": transition_id,
                "enabled": bool(getattr(transition, "enabled", True)),
                "station_start": station_start,
                "station_end": station_end,
                "boundary_station": (station_start + station_end) * 0.5,
                "sample_interval": sample_interval,
                "sample_count": _surface_transition_sample_count(station_start, station_end, sample_interval),
                "from_region_ref": str(getattr(transition, "from_region_ref", "") or ""),
                "to_region_ref": str(getattr(transition, "to_region_ref", "") or ""),
                "from_surface": region_surface_contexts.get(str(getattr(transition, "from_region_ref", "") or ""), ""),
                "to_surface": region_surface_contexts.get(str(getattr(transition, "to_region_ref", "") or ""), ""),
                "target_surfaces": _unique_join(list(getattr(transition, "target_surface_kinds", []) or [])),
                "transition_mode": str(getattr(transition, "transition_mode", "") or ""),
                "approval_status": str(getattr(transition, "approval_status", "") or ""),
                "status": row_status,
                "diagnostics": _surface_transition_review_diagnostic_summary(diagnostics, generation_diagnostics),
                "generation_diagnostic_count": len(generation_diagnostics),
            }
        )
    return rows


def corridor_surface_transition_boundary_options(document=None, region_id: str = "") -> list[dict[str, object]]:
    """Return station combo options for the selected Region's Surface Transition editing."""

    doc = document or (getattr(App, "ActiveDocument", None) if App is not None else None)
    applied = to_applied_section_set(find_v1_applied_section_set(doc))
    if applied is None:
        return []
    region_rows = corridor_region_boundary_rows(doc)
    sections = _station_ordered_applied_sections(applied)
    selected_region = str(region_id or "").strip()
    if selected_region:
        sections = [section for section in sections if _section_region_id(section) == selected_region]
    station_candidates = [
        (_section_station(section), _section_region_id(section))
        for section in sections
    ]
    station_candidates.extend(_region_boundary_station_candidates(region_rows, selected_region))
    if not station_candidates:
        return []
    transition_model = to_surface_transition_model(find_v1_surface_transition_model(doc))
    transitions_by_id = {
        str(getattr(row, "transition_id", "") or ""): row
        for row in list(getattr(transition_model, "transition_ranges", []) or []) if transition_model is not None
    }
    options: list[dict[str, object]] = []
    seen_keys: set[tuple[str, float, str, str]] = set()
    for station, section_region in sorted(station_candidates, key=lambda row: (float(row[0]), str(row[1]))):
        boundary = _surface_transition_context_for_region_station(region_rows, section_region, station)
        from_region = str(boundary["from_region_ref"])
        to_region = str(boundary["to_region_ref"])
        key = (section_region, round(float(station), 6), from_region, to_region)
        if key in seen_keys:
            continue
        seen_keys.add(key)
        transition_id = _surface_transition_id(from_region, to_region, station)
        transition = transitions_by_id.get(transition_id)
        interval = (
            float(getattr(transition, "sample_interval", SURFACE_TRANSITION_DEFAULT_SAMPLE_INTERVAL) or SURFACE_TRANSITION_DEFAULT_SAMPLE_INTERVAL)
            if transition is not None
            else SURFACE_TRANSITION_DEFAULT_SAMPLE_INTERVAL
        )
        label_context = f"{from_region} -> {to_region}" if from_region != to_region else section_region
        options.append(
            {
                "boundary_index": len(options),
                "boundary_station": float(station),
                "station": float(station),
                "region_ref": section_region,
                "from_region_ref": from_region,
                "to_region_ref": to_region,
                "transition_id": transition_id,
                "sample_interval": interval,
                "transition_exists": transition is not None,
                "label": f"STA {float(station):.3f} | {label_context}",
            }
        )
    return options


def create_corridor_surface_transition_from_region_boundary(
    document=None,
    row_index: int = 0,
    *,
    half_length: float = SURFACE_TRANSITION_DEFAULT_HALF_LENGTH,
    sample_interval: float = SURFACE_TRANSITION_DEFAULT_SAMPLE_INTERVAL,
):
    """Create or replace a SurfaceTransitionRange around a selected Region boundary."""

    doc = document or (getattr(App, "ActiveDocument", None) if App is not None else None)
    if doc is None:
        raise RuntimeError("No active document.")
    region_rows = corridor_region_boundary_rows(doc)
    boundary = _surface_transition_boundary_from_region_row(region_rows, int(row_index))
    applied = to_applied_section_set(find_v1_applied_section_set(doc))
    project = find_project(doc)
    existing = to_surface_transition_model(find_v1_surface_transition_model(doc))
    if existing is None:
        existing = SurfaceTransitionModel(
            schema_version=1,
            project_id=_project_id(project),
            transition_model_id="surface-transitions:main",
            corridor_ref=str(getattr(applied, "corridor_id", "") or "corridor:main"),
        )
    transition_id = _surface_transition_id(
        boundary["from_region_ref"],
        boundary["to_region_ref"],
        float(boundary["boundary_station"]),
    )
    station_start = float(boundary["boundary_station"]) - max(0.001, float(half_length))
    station_end = float(boundary["boundary_station"]) + max(0.001, float(half_length))
    new_range = SurfaceTransitionRange(
        transition_id=transition_id,
        station_start=station_start,
        station_end=station_end,
        from_region_ref=str(boundary["from_region_ref"]),
        to_region_ref=str(boundary["to_region_ref"]),
        transition_mode="interpolate_matching_roles",
        sample_interval=max(0.1, float(sample_interval or SURFACE_TRANSITION_DEFAULT_SAMPLE_INTERVAL)),
        enabled=True,
        approval_status="active",
        source_ref="build-corridor:region-boundary",
        notes="Created from Build Corridor Region boundary review.",
    )
    rows = [
        row
        for row in list(getattr(existing, "transition_ranges", []) or [])
        if str(getattr(row, "transition_id", "") or "") != transition_id
    ]
    rows.append(new_range)
    updated = SurfaceTransitionModel(
        schema_version=int(getattr(existing, "schema_version", 1) or 1),
        project_id=str(getattr(existing, "project_id", "") or _project_id(project)),
        transition_model_id=str(getattr(existing, "transition_model_id", "") or "surface-transitions:main"),
        corridor_ref=str(getattr(existing, "corridor_ref", "") or getattr(applied, "corridor_id", "") or "corridor:main"),
        label=str(getattr(existing, "label", "") or "Surface Transitions"),
        transition_ranges=sorted(rows, key=lambda row: (float(row.station_start), float(row.station_end), str(row.transition_id))),
    )
    return create_or_update_v1_surface_transition_model_object(
        document=doc,
        project=project,
        transition_model=updated,
    )


def create_or_update_corridor_surface_transition_for_boundary(
    document=None,
    boundary_index: int = 0,
    *,
    sample_interval: float = SURFACE_TRANSITION_DEFAULT_SAMPLE_INTERVAL,
    region_id: str = "",
):
    """Create or update one station-owned Surface Transition with a station-specific interval."""

    doc = document or (getattr(App, "ActiveDocument", None) if App is not None else None)
    if doc is None:
        raise RuntimeError("No active document.")
    options = corridor_surface_transition_boundary_options(doc, region_id=region_id)
    index = int(boundary_index)
    if index < 0 or index >= len(options):
        raise IndexError("Surface Transition station index is out of range.")
    return _create_or_update_corridor_surface_transition_from_station_option(
        doc,
        options[index],
        sample_interval=float(sample_interval or SURFACE_TRANSITION_DEFAULT_SAMPLE_INTERVAL),
    )


def _create_or_update_corridor_surface_transition_from_station_option(
    document,
    option: dict[str, object],
    *,
    half_length: float = SURFACE_TRANSITION_DEFAULT_HALF_LENGTH,
    sample_interval: float = SURFACE_TRANSITION_DEFAULT_SAMPLE_INTERVAL,
):
    """Persist one SurfaceTransitionRange from a Region station combo option."""

    doc = document or (getattr(App, "ActiveDocument", None) if App is not None else None)
    if doc is None:
        raise RuntimeError("No active document.")
    applied = to_applied_section_set(find_v1_applied_section_set(doc))
    project = find_project(doc)
    existing = to_surface_transition_model(find_v1_surface_transition_model(doc))
    if existing is None:
        existing = SurfaceTransitionModel(
            schema_version=1,
            project_id=_project_id(project),
            transition_model_id="surface-transitions:main",
            corridor_ref=str(getattr(applied, "corridor_id", "") or "corridor:main"),
        )
    station = float(option.get("station", option.get("boundary_station", 0.0)) or 0.0)
    from_region = str(option.get("from_region_ref", "") or "")
    to_region = str(option.get("to_region_ref", "") or "")
    if not from_region or not to_region:
        region_ref = str(option.get("region_ref", "") or "")
        from_region = from_region or region_ref
        to_region = to_region or region_ref
    transition_id = _surface_transition_id(from_region, to_region, station)
    station_start = station - max(0.001, float(half_length))
    station_end = station + max(0.001, float(half_length))
    source_ref = "build-corridor:region-boundary" if from_region != to_region else "build-corridor:region-station"
    new_range = SurfaceTransitionRange(
        transition_id=transition_id,
        station_start=station_start,
        station_end=station_end,
        from_region_ref=from_region,
        to_region_ref=to_region,
        transition_mode="interpolate_matching_roles",
        sample_interval=max(0.1, float(sample_interval or SURFACE_TRANSITION_DEFAULT_SAMPLE_INTERVAL)),
        enabled=True,
        approval_status="active",
        source_ref=source_ref,
        notes="Created from Build Corridor Region station review.",
    )
    rows = [
        row
        for row in list(getattr(existing, "transition_ranges", []) or [])
        if str(getattr(row, "transition_id", "") or "") != transition_id
    ]
    rows.append(new_range)
    updated = SurfaceTransitionModel(
        schema_version=int(getattr(existing, "schema_version", 1) or 1),
        project_id=str(getattr(existing, "project_id", "") or _project_id(project)),
        transition_model_id=str(getattr(existing, "transition_model_id", "") or "surface-transitions:main"),
        corridor_ref=str(getattr(existing, "corridor_ref", "") or getattr(applied, "corridor_id", "") or "corridor:main"),
        label=str(getattr(existing, "label", "") or "Surface Transitions"),
        transition_ranges=sorted(rows, key=lambda row: (float(row.station_start), float(row.station_end), str(row.transition_id))),
    )
    return create_or_update_v1_surface_transition_model_object(
        document=doc,
        project=project,
        transition_model=updated,
    )


