def _intersection_tie_slope_bbox_diagonal(points: list[tuple[float, float, float]]) -> float:
    if not points:
        return 0.0
    xs = [float(point[0]) for point in points]
    ys = [float(point[1]) for point in points]
    return ((max(xs) - min(xs)) ** 2 + (max(ys) - min(ys)) ** 2) ** 0.5


def _intersection_tie_slope_unsafe_loop_diagnostics(
    loop_points: tuple[tuple[float, float, float], ...],
    *,
    inner_edge: tuple[tuple[float, float, float], ...],
    outer_edge: tuple[tuple[float, float, float], ...],
    start_cap_edge: tuple[tuple[float, float, float], ...],
    end_cap_edge: tuple[tuple[float, float, float], ...],
    loop_area_xy: float,
) -> tuple[str, ...]:
    diagnostics: list[str] = []
    points = [tuple(point) for point in tuple(loop_points or ())]
    if len(points) < 5:
        return ("intersection_tie_slope_open_loop",)
    if not _intersection_slope_face_points_close_xy(points[0], points[-1]):
        diagnostics.append("intersection_tie_slope_open_loop")
    polygon = list(points[:-1])
    if len(polygon) < 4:
        diagnostics.append("intersection_tie_slope_loop_too_few_unique_points")
    if len(polygon) >= 4 and _xy_xyz_polygon_self_crossing(polygon):
        diagnostics.append("intersection_tie_slope_loop_self_crossing")

    area = abs(float(loop_area_xy or 0.0))
    if area <= 1.0e-6:
        diagnostics.append("intersection_tie_slope_loop_zero_area")

    inner_len = _xy_distance(inner_edge[0], inner_edge[1]) if len(tuple(inner_edge or ())) >= 2 else 0.0
    outer_len = _xy_distance(outer_edge[0], outer_edge[1]) if len(tuple(outer_edge or ())) >= 2 else 0.0
    start_cap_len = _xy_distance(start_cap_edge[0], start_cap_edge[1]) if len(tuple(start_cap_edge or ())) >= 2 else 0.0
    end_cap_len = _xy_distance(end_cap_edge[0], end_cap_edge[1]) if len(tuple(end_cap_edge or ())) >= 2 else 0.0
    edge_scale = max(inner_len, outer_len, 1.0)
    cap_scale = max(start_cap_len, end_cap_len, 1.0)
    bbox_diag = _intersection_tie_slope_bbox_diagonal(polygon)
    xs = [float(point[0]) for point in polygon]
    ys = [float(point[1]) for point in polygon]
    bbox_area = max(0.0, max(xs) - min(xs)) * max(0.0, max(ys) - min(ys)) if xs and ys else 0.0
    fill_ratio = area / bbox_area if bbox_area > 1.0e-9 else 0.0

    if bbox_diag > max(30.0, edge_scale * 8.0, cap_scale * 8.0):
        diagnostics.append(f"intersection_tie_slope_long_fan_rejected:bbox={bbox_diag:.3f}")
    if cap_scale > max(18.0, edge_scale * 6.0):
        diagnostics.append(f"intersection_tie_slope_long_fan_rejected:cap={cap_scale:.3f}")
    if bbox_area > 1.0e-9 and fill_ratio < 0.05 and bbox_diag > edge_scale * 4.0:
        diagnostics.append(f"intersection_tie_slope_long_fan_rejected:fill_ratio={fill_ratio:.3f}")

    return tuple(_unique_text_values(diagnostics))


def _intersection_tie_slope_contact_match(
    contact_segment,
    *,
    contact_ref: str,
    alignment_ref: str,
    side: str,
) -> tuple[str, tuple[str, ...], tuple[str, ...]]:
    diagnostics: list[str] = []
    contact_ref = str(contact_ref or "").strip()
    if not contact_ref:
        return "missing", (), ("intersection_tie_slope_intersection_contact_ref_missing",)
    if contact_segment is None:
        return "missing", (), (f"intersection_tie_slope_intersection_contact_missing:{contact_ref}",)

    segment_kind = str(getattr(contact_segment, "segment_kind", "") or "").strip()
    if segment_kind != "tie_in":
        diagnostics.append(f"intersection_tie_slope_intersection_contact_not_tie_in:{contact_ref}:{segment_kind or 'unknown'}")
    segment_alignment = str(getattr(contact_segment, "alignment_ref", "") or "").strip()
    if segment_alignment != str(alignment_ref or "").strip():
        diagnostics.append(
            "intersection_tie_slope_intersection_contact_alignment_mismatch:"
            f"{contact_ref}:{segment_alignment or 'unknown'}!={alignment_ref or 'unknown'}"
        )
    segment_side = str(getattr(contact_segment, "side", "") or "").strip()
    if segment_side != str(side or "").strip():
        diagnostics.append(
            f"intersection_tie_slope_intersection_contact_side_mismatch:{contact_ref}:{segment_side or 'unknown'}!={side or 'unknown'}"
        )
    segment_status = str(getattr(contact_segment, "status", "") or "").strip().lower()
    if segment_status in {"", "missing", "error"}:
        diagnostics.append(f"intersection_tie_slope_intersection_contact_status_blocked:{contact_ref}:{segment_status or 'unknown'}")
    start_xyz = _xyz_tuple(getattr(contact_segment, "start_xyz", (0.0, 0.0, 0.0)))
    end_xyz = _xyz_tuple(getattr(contact_segment, "end_xyz", (0.0, 0.0, 0.0)))
    if _xy_distance(start_xyz, end_xyz) <= 1.0e-6:
        diagnostics.append(f"intersection_tie_slope_intersection_contact_degenerate:{contact_ref}")

    if diagnostics:
        return "warning", (contact_ref,), tuple(_unique_text_values(diagnostics))
    return "accepted", (contact_ref,), ()


def _intersection_tie_slope_contact_inner_points(contact_segment) -> tuple[tuple[float, float, float], ...]:
    if contact_segment is None:
        return ()
    start_xyz = _xyz_tuple(getattr(contact_segment, "start_xyz", (0.0, 0.0, 0.0)))
    end_xyz = _xyz_tuple(getattr(contact_segment, "end_xyz", (0.0, 0.0, 0.0)))
    if _xy_distance(start_xyz, end_xyz) <= 1.0e-6:
        return ()
    return (start_xyz, end_xyz)


def _intersection_tie_slope_closed_loop_edges(
    inner_points: tuple[tuple[float, float, float], ...],
    outer_points: tuple[tuple[float, float, float], ...],
) -> tuple[
    tuple[tuple[float, float, float], ...],
    tuple[tuple[float, float, float], ...],
    tuple[tuple[float, float, float], ...],
    tuple[tuple[float, float, float], ...],
    tuple[tuple[float, float, float], ...],
    float,
    tuple[str, ...],
]:
    diagnostics: list[str] = []
    if len(inner_points) < 2:
        diagnostics.append("intersection_tie_slope_loop_inner_edge_missing")
        return (), (), (), (), (), 0.0, tuple(diagnostics)
    if len(outer_points) < 2:
        diagnostics.append("intersection_tie_slope_loop_outer_edge_missing")
        return (), (), (), (), (), 0.0, tuple(diagnostics)

    inner_start, inner_end = _intersection_tie_slope_endpoint_pair(inner_points)
    outer_start, outer_end = _intersection_tie_slope_endpoint_pair(outer_points)
    forward_cost = _xy_distance(inner_start, outer_start) + _xy_distance(inner_end, outer_end)
    reversed_cost = _xy_distance(inner_start, outer_end) + _xy_distance(inner_end, outer_start)
    if reversed_cost < forward_cost:
        outer_start, outer_end = outer_end, outer_start

    inner_edge = (inner_start, inner_end)
    outer_edge = (outer_start, outer_end)
    start_cap_edge = (inner_start, outer_start)
    end_cap_edge = (inner_end, outer_end)
    if _xy_distance(inner_start, inner_end) <= 1.0e-6:
        diagnostics.append("intersection_tie_slope_loop_inner_edge_degenerate")
    if _xy_distance(outer_start, outer_end) <= 1.0e-6:
        diagnostics.append("intersection_tie_slope_loop_outer_edge_degenerate")
    if _xy_distance(start_cap_edge[0], start_cap_edge[1]) <= 1.0e-6:
        diagnostics.append("intersection_tie_slope_loop_start_cap_degenerate")
    if _xy_distance(end_cap_edge[0], end_cap_edge[1]) <= 1.0e-6:
        diagnostics.append("intersection_tie_slope_loop_end_cap_degenerate")

    loop = [inner_start, inner_end, outer_end, outer_start, inner_start]
    simplified = tuple(_intersection_slope_face_simplified_closed_loop(loop))
    closed_xy = bool(simplified) and _intersection_slope_face_points_close_xy(simplified[0], simplified[-1])
    if not closed_xy:
        diagnostics.append("intersection_tie_slope_loop_not_closed")
    unique_xy = {
        (round(float(point[0]), 6), round(float(point[1]), 6))
        for point in simplified[:-1]
    }
    if len(unique_xy) < 4:
        diagnostics.append("intersection_tie_slope_loop_too_few_unique_points")
    area = abs(_xy_polygon_area([(float(point[0]), float(point[1])) for point in simplified[:-1]])) if len(simplified) >= 4 else 0.0
    if area <= 1.0e-6:
        diagnostics.append("intersection_tie_slope_loop_zero_area")
    return (
        simplified,
        inner_edge,
        outer_edge,
        start_cap_edge,
        end_cap_edge,
        area,
        tuple(_unique_text_values(diagnostics)),
    )


def _intersection_tie_slope_has_four_edges(row) -> bool:
    return all(
        len(tuple(getattr(row, field_name, ()) or ())) >= 2
        for field_name in (
            "inner_intersection_edge_xyz",
            "outer_applied_section_edge_xyz",
            "start_cap_edge_xyz",
            "end_cap_edge_xyz",
        )
    )


def _intersection_tie_slope_road_role(
    alignment_ref: str,
    *,
    intersection_model=None,
    intersection_id: str = "",
) -> str:
    source_row = _intersection_row_by_id(intersection_model, intersection_id) if intersection_model is not None else None
    primary_ref = str(getattr(source_row, "primary_alignment_ref", "") or "").strip() if source_row is not None else ""
    if primary_ref and str(alignment_ref or "").strip() == primary_ref:
        return "primary"
    return "secondary"


def _intersection_tie_slope_gap_specs(
    applied_section_set,
    *,
    prerequisite: IntersectionPatchPrerequisiteResult,
    intersection_model=None,
) -> list[dict[str, object]]:
    intersection_id = str(getattr(prerequisite, "intersection_id", "") or "").strip()
    source_row = _intersection_row_by_id(intersection_model, intersection_id) if intersection_model is not None else None
    primary_ref = str(getattr(source_row, "primary_alignment_ref", "") or "").strip() if source_row is not None else ""
    alignment_refs = [
        str(value or "").strip()
        for value in list(getattr(prerequisite, "alignment_refs", []) or [])
        if str(value or "").strip()
    ]
    if not primary_ref and alignment_refs:
        primary_ref = alignment_refs[0]
    secondary_refs = [
        str(value or "").strip()
        for value in list(getattr(source_row, "secondary_alignment_refs", []) or [])
        if str(value or "").strip()
    ] if source_row is not None else []
    if not secondary_refs:
        secondary_refs = [ref for ref in alignment_refs if ref and ref != primary_ref]

    specs: list[dict[str, object]] = []
    target_specs: list[tuple[str, str, str]] = []
    if primary_ref:
        target_specs.append((primary_ref, "primary", "entry"))
        target_specs.append((primary_ref, "primary", "exit"))
    intersection_kind = str(getattr(source_row, "intersection_kind", "") or getattr(prerequisite, "intersection_kind", "") or "")
    for secondary_ref in secondary_refs:
        target_specs.append((secondary_ref, "secondary", "entry"))
        if intersection_kind == "cross_intersection":
            target_specs.append((secondary_ref, "secondary", "exit"))

    for alignment_ref, road_role, gap_role in target_specs:
        for side in ("left", "right"):
            station_span = _intersection_tie_slope_transition_station_span(
                applied_section_set,
                intersection_model,
                intersection_id=intersection_id,
                alignment_ref=alignment_ref,
                road_role=road_role,
                gap_role=gap_role,
            )
            terminal_section = _intersection_tie_slope_terminal_section_for_gap(
                applied_section_set,
                alignment_ref=alignment_ref,
                intersection_id=intersection_id,
                target_station=float(station_span.get("transition_outer_sta", 0.0) or 0.0),
                gap_role=gap_role,
                side=side,
            )
            specs.append(
                {
                    "alignment_ref": alignment_ref,
                    "road_role": road_role,
                    "gap_role": gap_role,
                    "side": side,
                    "terminal_section": terminal_section,
                    "leg_ref": _intersection_tie_slope_leg_ref(
                        source_row,
                        alignment_ref,
                        road_role=road_role,
                    ),
                    "control_area_ref": _intersection_tie_slope_control_area_ref(
                        intersection_model,
                        intersection_id,
                        alignment_ref,
                        source_row=source_row,
                    ),
                    "station_span": station_span,
                }
            )
    return specs


def _intersection_tie_slope_transition_station_span(
    applied_section_set,
    intersection_model,
    *,
    intersection_id: str,
    alignment_ref: str,
    road_role: str,
    gap_role: str,
) -> dict[str, object]:
    """Return the separated Region/control-area and Applied Section intersection STA pair."""

    alignment_id = str(alignment_ref or "").strip()
    role = str(road_role or "").strip().lower()
    gap = str(gap_role or "").strip().lower()
    diagnostics: list[str] = []
    region_range = _intersection_tie_slope_region_station_range(
        intersection_model,
        intersection_id=intersection_id,
        alignment_ref=alignment_id,
    )
    if region_range is None:
        region_range = _intersection_tie_slope_leg_station_range(
            intersection_model,
            intersection_id=intersection_id,
            alignment_ref=alignment_id,
        )
    if region_range is None:
        diagnostics.append("intersection_tie_slope_region_boundary_missing")
        region_range = _intersection_tie_slope_alignment_section_station_range(
            applied_section_set,
            alignment_ref=alignment_id,
        )
    intersection_range = _intersection_tie_slope_applied_intersection_station_range(
        applied_section_set,
        intersection_id=intersection_id,
        alignment_ref=alignment_id,
    )
    if intersection_range is None:
        diagnostics.append("intersection_tie_slope_intersection_station_boundary_missing")
        target = _intersection_tie_slope_target_station(intersection_model, intersection_id, alignment_id)
        if target is not None:
            intersection_range = (float(target), float(target))
    region_start, region_end = _ordered_station_range(region_range)
    intersection_start, intersection_end = _ordered_station_range(intersection_range)
    transition_span_role = f"{role or 'road'}:{gap or 'gap'}"
    if region_range is None or intersection_range is None:
        transition_outer_sta = 0.0
        transition_inner_sta = 0.0
        transition_window_start_sta = 0.0
        transition_window_end_sta = 0.0
        transition_window_kind = "missing"
    elif gap == "exit":
        transition_outer_sta = float(region_end)
        transition_inner_sta = float(intersection_end)
        transition_window_start_sta = float(intersection_end)
        transition_window_end_sta = float(region_end)
        transition_window_kind = "primary_intersection_end_to_region_end" if role == "primary" else "secondary_intersection_end_to_region_end"
    else:
        transition_outer_sta = float(region_start)
        transition_inner_sta = float(intersection_start)
        transition_window_start_sta = float(region_start)
        transition_window_end_sta = float(intersection_start)
        transition_window_kind = "primary_region_start_to_intersection_start" if role == "primary" else "secondary_region_start_to_intersection_start"
    transition_span_length = abs(float(transition_outer_sta) - float(transition_inner_sta))
    if transition_span_length <= 1.0e-6:
        diagnostics.append("intersection_tie_slope_transition_span_too_short")
    else:
        diagnostics.append("intersection_tie_slope_transition_span_diagnostic_ready")
        diagnostics.append("intersection_tie_slope_transition_outer_edge_selector_ready")
        diagnostics.append("intersection_tie_slope_transition_inner_edge_selector_window_ready")
        if transition_window_kind == "primary_region_start_to_intersection_start":
            diagnostics.append("intersection_tie_slope_primary_entry_window_ready")
        elif transition_window_kind == "primary_intersection_end_to_region_end":
            diagnostics.append("intersection_tie_slope_primary_exit_window_ready")
        elif transition_window_kind == "secondary_region_start_to_intersection_start":
            diagnostics.append("intersection_tie_slope_secondary_entry_window_ready")
        elif transition_window_kind == "secondary_intersection_end_to_region_end":
            diagnostics.append("intersection_tie_slope_secondary_exit_window_ready")
    return {
        "region_start_sta": float(region_start),
        "region_end_sta": float(region_end),
        "intersection_start_sta": float(intersection_start),
        "intersection_end_sta": float(intersection_end),
        "transition_outer_sta": float(transition_outer_sta),
        "transition_inner_sta": float(transition_inner_sta),
        "transition_window_start_sta": float(transition_window_start_sta),
        "transition_window_end_sta": float(transition_window_end_sta),
        "transition_span_length": float(transition_span_length),
        "transition_span_role": transition_span_role,
        "transition_window_kind": transition_window_kind,
        "diagnostics": tuple(_unique_text_values(diagnostics)),
    }


def _ordered_station_range(station_range) -> tuple[float, float]:
    if station_range is None:
        return (0.0, 0.0)
    try:
        start, end = tuple(station_range)[:2]
    except Exception:
        return (0.0, 0.0)
    start_value = float(start or 0.0)
    end_value = float(end or 0.0)
    return (min(start_value, end_value), max(start_value, end_value))


def _intersection_tie_slope_region_station_range(
    intersection_model,
    *,
    intersection_id: str,
    alignment_ref: str,
) -> tuple[float, float] | None:
    ranges: list[tuple[float, float]] = []
    for area in list(getattr(intersection_model, "control_area_rows", []) or []):
        if str(getattr(area, "intersection_id", "") or "").strip() != str(intersection_id or "").strip():
            continue
        if str(alignment_ref or "").strip() and str(getattr(area, "alignment_ref", "") or "").strip() != str(alignment_ref or "").strip():
            continue
        for station_range in list(getattr(area, "station_ranges", []) or []):
            start, end = _ordered_station_range(station_range)
            if abs(end - start) > 1.0e-9:
                ranges.append((start, end))
    if not ranges:
        return None
    return (min(start for start, _end in ranges), max(end for _start, end in ranges))


def _intersection_tie_slope_leg_station_range(
    intersection_model,
    *,
    intersection_id: str,
    alignment_ref: str,
) -> tuple[float, float] | None:
    source_row = _intersection_row_by_id(intersection_model, intersection_id) if intersection_model is not None else None
    for leg in list(getattr(source_row, "leg_rows", []) or []):
        if str(alignment_ref or "").strip() and str(getattr(leg, "alignment_ref", "") or "").strip() != str(alignment_ref or "").strip():
            continue
        start = float(getattr(leg, "approach_station_start", 0.0) or 0.0)
        end = float(getattr(leg, "approach_station_end", 0.0) or 0.0)
        if abs(end - start) > 1.0e-9:
            return _ordered_station_range((start, end))
    return None


def _intersection_tie_slope_alignment_section_station_range(
    applied_section_set,
    *,
    alignment_ref: str,
) -> tuple[float, float] | None:
    stations = [
        _section_station(section)
        for section in _station_ordered_applied_sections(applied_section_set)
        if str(getattr(section, "alignment_id", "") or "").strip() == str(alignment_ref or "").strip()
    ]
    if not stations:
        return None
    return (min(stations), max(stations))


def _intersection_tie_slope_applied_intersection_station_range(
    applied_section_set,
    *,
    intersection_id: str,
    alignment_ref: str,
) -> tuple[float, float] | None:
    stations = [
        _section_station(section)
        for section in _station_ordered_applied_sections(applied_section_set)
        if str(getattr(section, "alignment_id", "") or "").strip() == str(alignment_ref or "").strip()
        and str(getattr(section, "active_intersection_id", "") or "").strip() == str(intersection_id or "").strip()
    ]
    if not stations:
        return None
    return (min(stations), max(stations))


def _intersection_tie_slope_terminal_section_for_gap(
    applied_section_set,
    *,
    alignment_ref: str,
    intersection_id: str,
    target_station: float | None,
    gap_role: str,
    side: str,
):
    alignment_id = str(alignment_ref or "").strip()
    if applied_section_set is None or not alignment_id:
        return None
    sections = [
        section
        for section in _station_ordered_applied_sections(applied_section_set)
        if str(getattr(section, "alignment_id", "") or "").strip() == alignment_id
        and _intersection_tie_slope_terminal_road_edge(section, side=side)
    ]
    if not sections:
        return None
    if target_station is None:
        outside_sections = [
            section
            for section in sections
            if str(getattr(section, "active_intersection_id", "") or "").strip() != str(intersection_id or "").strip()
        ]
        return outside_sections[0] if outside_sections else sections[0]

    before_or_at = [
        section for section in sections
        if float(getattr(section, "station", 0.0) or 0.0) <= float(target_station) + 1.0e-9
    ]
    after_or_at = [
        section for section in sections
        if float(getattr(section, "station", 0.0) or 0.0) >= float(target_station) - 1.0e-9
    ]
    if str(gap_role or "").strip().lower() == "exit":
        preferred = after_or_at
        return min(preferred or sections, key=lambda section: abs(_section_station(section) - float(target_station)))
    preferred = before_or_at
    return min(preferred or sections, key=lambda section: abs(_section_station(section) - float(target_station)))


def _applied_section_kind_map(applied_section_set) -> dict[str, str]:
    if applied_section_set is None:
        return {}
    return {
        str(getattr(row, "applied_section_id", "") or ""): str(getattr(row, "kind", "") or "")
        for row in list(getattr(applied_section_set, "station_rows", []) or [])
        if str(getattr(row, "applied_section_id", "") or "")
    }


def _applied_section_is_supplemental(section, *, kind_by_section_id: dict[str, str] | None = None) -> bool:
    if section is None:
        return False
    section_id = str(getattr(section, "applied_section_id", "") or "")
    kind_text = str((kind_by_section_id or {}).get(section_id, "") or "").strip().lower()
    if "supplemental" in kind_text:
        return True
    searchable_values = [
        section_id,
        str(getattr(section, "kind", "") or ""),
        str(getattr(section, "source_kind", "") or ""),
        str(getattr(section, "section_kind", "") or ""),
        str(getattr(section, "sampling_kind", "") or ""),
        str(getattr(getattr(section, "frame", None), "source_mode", "") or ""),
        str(getattr(getattr(section, "frame", None), "notes", "") or ""),
        " ".join(str(value or "") for value in list(getattr(section, "active_intersection_source_stage_rows", []) or [])),
        " ".join(str(value or "") for value in list(getattr(section, "intersection_diagnostic_rows", []) or [])),
    ]
    return any("supplemental" in str(value or "").lower() for value in searchable_values)


def _intersection_tie_slope_supplemental_extent_diagnostics(
    applied_section_set,
    *,
    alignment_ref: str,
    intersection_id: str,
    side: str,
    selected_endpoint_section=None,
    pair_index: int = 0,
    pair_count: int = 0,
) -> tuple[str, ...]:
    alignment_id = str(alignment_ref or "").strip()
    target_intersection = str(intersection_id or "").strip()
    if applied_section_set is None or not alignment_id or not target_intersection:
        return ("intersection_tie_slope_supplemental_extent_context_missing",)
    kind_by_section_id = _applied_section_kind_map(applied_section_set)
    active_sections = [
        section
        for section in _station_ordered_applied_sections(applied_section_set)
        if str(getattr(section, "alignment_id", "") or "").strip() == alignment_id
        and str(getattr(section, "active_intersection_id", "") or "").strip() == target_intersection
        and _intersection_tie_slope_terminal_road_edge(section, side=side)
    ]
    if not active_sections:
        return ("intersection_tie_slope_supplemental_extent_active_sections_missing",)
    supplemental_sections = [
        section
        for section in active_sections
        if _applied_section_is_supplemental(section, kind_by_section_id=kind_by_section_id)
    ]
    first_section = active_sections[0]
    last_section = active_sections[-1]
    diagnostics = [
        (
            "info:intersection_tie_slope_first_active_section:"
            f"{str(getattr(first_section, 'applied_section_id', '') or '')}:sta={_section_station(first_section):.3f}"
        ),
        (
            "info:intersection_tie_slope_last_active_section:"
            f"{str(getattr(last_section, 'applied_section_id', '') or '')}:sta={_section_station(last_section):.3f}"
        ),
        f"info:intersection_tie_slope_supplemental_section_count:{len(supplemental_sections)}",
        f"info:intersection_tie_slope_supplemental_pair_index:{int(pair_index or 0)}/{int(pair_count or 0)}",
    ]
    if not supplemental_sections:
        diagnostics.append("intersection_tie_slope_supplemental_endpoint_missing")
        return tuple(_unique_text_values(diagnostics))
    if selected_endpoint_section is None:
        diagnostics.append("info:intersection_tie_slope_supplemental_endpoint_pending")
        return tuple(_unique_text_values(diagnostics))
    endpoint_ref = str(getattr(selected_endpoint_section, "applied_section_id", "") or "")
    endpoint_station = _section_station(selected_endpoint_section)
    diagnostics.append(f"info:intersection_tie_slope_supplemental_endpoint_selected:{endpoint_ref}:sta={endpoint_station:.3f}")
    if not _applied_section_is_supplemental(selected_endpoint_section, kind_by_section_id=kind_by_section_id):
        diagnostics.append(f"intersection_tie_slope_supplemental_endpoint_fallback_non_supplemental:{endpoint_ref}")
    return tuple(_unique_text_values(diagnostics))


def _intersection_tie_slope_applied_section_window_rows(
    applied_section_set,
    *,
    prerequisite: IntersectionPatchPrerequisiteResult,
    intersection_model=None,
) -> list[dict[str, object]]:
    """Return Tie Slope candidate windows from Applied Section intersection-context transitions."""

    rows: list[dict[str, object]] = []
    kind_by_section_id = _applied_section_kind_map(applied_section_set)
    for spec in _intersection_tie_slope_gap_specs(
        applied_section_set,
        prerequisite=prerequisite,
        intersection_model=intersection_model,
    ):
        alignment_ref = str(spec.get("alignment_ref", "") or "")
        gap_role = str(spec.get("gap_role", "") or "")
        side = str(spec.get("side", "") or "")
        station_span = dict(spec.get("station_span", {}) or {})
        span_length = float(station_span.get("transition_span_length", 0.0) or 0.0)
        if span_length <= 1.0e-6:
            intersection_kind = str(getattr(prerequisite, "intersection_kind", "") or "").strip().lower()
            if intersection_kind == "cross_intersection":
                start_section = _intersection_tie_slope_intersection_boundary_section_for_gap(
                    applied_section_set,
                    alignment_ref=alignment_ref,
                    intersection_id=str(getattr(prerequisite, "intersection_id", "") or ""),
                    gap_role=gap_role,
                    side=side,
                )
                approach_pairs = _intersection_tie_slope_curb_return_approach_section_pairs(
                    applied_section_set,
                    alignment_ref=alignment_ref,
                    intersection_id=str(getattr(prerequisite, "intersection_id", "") or ""),
                    gap_role=gap_role,
                    side=side,
                    start_section=start_section,
                )
                for approach_index, approach_pair in enumerate(approach_pairs, start=1):
                    supplemental_extent_role = (
                        "supplemental_endpoint_pair"
                        if approach_index == len(approach_pairs)
                        else "intersection_supplemental_pair"
                    )
                    rows.append(
                        _intersection_tie_slope_applied_section_window_row(
                            spec,
                            prerequisite=prerequisite,
                            outer_section=approach_pair[0],
                            inner_section=approach_pair[1],
                            cell_role="curb_return_approach_pair",
                            kind_by_section_id=kind_by_section_id,
                            supplemental_extent_role=supplemental_extent_role,
                            supplemental_endpoint_section=approach_pair[1] if approach_index == len(approach_pairs) else None,
                            extra_diagnostics=_intersection_tie_slope_supplemental_extent_diagnostics(
                                applied_section_set,
                                alignment_ref=alignment_ref,
                                intersection_id=str(getattr(prerequisite, "intersection_id", "") or ""),
                                side=side,
                                selected_endpoint_section=approach_pair[1] if approach_index == len(approach_pairs) else None,
                                pair_index=approach_index,
                                pair_count=len(approach_pairs),
                            ),
                        )
                    )
            else:
                transition_pair = _intersection_tie_slope_zero_span_transition_section_pair_for_gap(
                    applied_section_set,
                    alignment_ref=alignment_ref,
                    intersection_id=str(getattr(prerequisite, "intersection_id", "") or ""),
                    gap_role=gap_role,
                    side=side,
                )
                if transition_pair is not None:
                    rows.append(
                        _intersection_tie_slope_applied_section_window_row(
                            spec,
                            prerequisite=prerequisite,
                            outer_section=transition_pair[0],
                            inner_section=transition_pair[1],
                            cell_role="transition_pair",
                            kind_by_section_id=kind_by_section_id,
                        )
                    )
            continue
        transition_pair = _intersection_tie_slope_transition_section_pair_for_gap(
            applied_section_set,
            alignment_ref=alignment_ref,
            intersection_id=str(getattr(prerequisite, "intersection_id", "") or ""),
            gap_role=gap_role,
            side=side,
            station_span=station_span,
        )
        if transition_pair is None:
            outer_section = _intersection_tie_slope_terminal_section_for_gap(
                applied_section_set,
                alignment_ref=alignment_ref,
                intersection_id=str(getattr(prerequisite, "intersection_id", "") or ""),
                target_station=float(station_span.get("transition_outer_sta", 0.0) or 0.0),
                gap_role=gap_role,
                side=side,
            )
            inner_section = _intersection_tie_slope_terminal_section_for_gap(
                applied_section_set,
                alignment_ref=alignment_ref,
                intersection_id=str(getattr(prerequisite, "intersection_id", "") or ""),
                target_station=float(station_span.get("transition_inner_sta", 0.0) or 0.0),
                gap_role=gap_role,
                side=side,
            )
        else:
            outer_section, inner_section = transition_pair
        rows.append(
            _intersection_tie_slope_applied_section_window_row(
                spec,
                prerequisite=prerequisite,
                outer_section=outer_section,
                inner_section=inner_section,
                cell_role="transition_pair",
                kind_by_section_id=kind_by_section_id,
            )
        )
        intersection_kind = str(getattr(prerequisite, "intersection_kind", "") or "").strip().lower()
        if intersection_kind != "cross_intersection":
            next_pair = _intersection_tie_slope_next_intersection_section_pair(
                applied_section_set,
                alignment_ref=alignment_ref,
                intersection_id=str(getattr(prerequisite, "intersection_id", "") or ""),
                gap_role=gap_role,
                side=side,
                outer_section=outer_section,
                inner_section=inner_section,
            )
            if next_pair is not None:
                rows.append(
                    _intersection_tie_slope_applied_section_window_row(
                        spec,
                        prerequisite=prerequisite,
                        outer_section=next_pair[0],
                        inner_section=next_pair[1],
                        cell_role="intersection_adjacent_pair",
                        kind_by_section_id=kind_by_section_id,
                    )
                )
        if intersection_kind == "cross_intersection":
            approach_pairs = _intersection_tie_slope_curb_return_approach_section_pairs(
                applied_section_set,
                alignment_ref=alignment_ref,
                intersection_id=str(getattr(prerequisite, "intersection_id", "") or ""),
                gap_role=gap_role,
                side=side,
                start_section=inner_section,
            )
            for approach_index, approach_pair in enumerate(approach_pairs, start=1):
                supplemental_extent_role = (
                    "supplemental_endpoint_pair"
                    if approach_index == len(approach_pairs)
                    else "intersection_supplemental_pair"
                )
                row = _intersection_tie_slope_applied_section_window_row(
                    spec,
                    prerequisite=prerequisite,
                    outer_section=approach_pair[0],
                    inner_section=approach_pair[1],
                    cell_role="curb_return_approach_pair",
                    kind_by_section_id=kind_by_section_id,
                    supplemental_extent_role=supplemental_extent_role,
                    supplemental_endpoint_section=approach_pair[1] if approach_index == len(approach_pairs) else None,
                    extra_diagnostics=_intersection_tie_slope_supplemental_extent_diagnostics(
                        applied_section_set,
                        alignment_ref=alignment_ref,
                        intersection_id=str(getattr(prerequisite, "intersection_id", "") or ""),
                        side=side,
                        selected_endpoint_section=approach_pair[1] if approach_index == len(approach_pairs) else None,
                        pair_index=approach_index,
                        pair_count=len(approach_pairs),
                    ),
                )
                rows.append(row)
    return rows


def _intersection_tie_slope_applied_section_window_row(
    spec: dict[str, object],
    *,
    prerequisite: IntersectionPatchPrerequisiteResult,
    outer_section,
    inner_section,
    cell_role: str,
    forced_status: str = "",
    extra_diagnostics: tuple[str, ...] = (),
    kind_by_section_id: dict[str, str] | None = None,
    supplemental_extent_role: str = "",
    supplemental_endpoint_section=None,
) -> dict[str, object]:
    span = dict(spec.get("station_span", {}) or {})
    side = str(spec.get("side", "") or "")
    legacy_outer_edge = _intersection_tie_slope_terminal_road_edge(outer_section, side=side)
    legacy_inner_edge = _intersection_tie_slope_terminal_road_edge(inner_section, side=side)
    outer_edge = legacy_outer_edge
    inner_edge = legacy_inner_edge
    outer_edge_source_mode = "legacy_slope_breakline"
    inner_edge_source_mode = "legacy_slope_breakline"
    outer_edge_diagnostics = ()
    inner_edge_diagnostics = ()
    diagnostics: list[str] = []
    diagnostics.extend(str(value or "") for value in tuple(outer_edge_diagnostics or ()) if str(value or ""))
    diagnostics.extend(str(value or "") for value in tuple(inner_edge_diagnostics or ()) if str(value or ""))
    if len(tuple(outer_edge or ())) < 2:
        diagnostics.append("intersection_tie_slope_window_outer_edge_missing")
    if len(tuple(inner_edge or ())) < 2:
        diagnostics.append("intersection_tie_slope_window_inner_edge_missing")
    loop_points: tuple[tuple[float, float, float], ...] = ()
    start_cap_edge: tuple[tuple[float, float, float], ...] = ()
    end_cap_edge: tuple[tuple[float, float, float], ...] = ()
    loop_area_xy = 0.0
    if not diagnostics:
        (
            loop_points,
            inner_edge,
            outer_edge,
            start_cap_edge,
            end_cap_edge,
            loop_area_xy,
            loop_diagnostics,
        ) = _intersection_tie_slope_closed_loop_edges(tuple(inner_edge), tuple(outer_edge))
        diagnostics.extend(str(value or "") for value in tuple(loop_diagnostics or ()) if str(value or ""))
        diagnostics.extend(
            str(value or "")
            for value in _intersection_tie_slope_unsafe_loop_diagnostics(
                tuple(loop_points or ()),
                inner_edge=tuple(inner_edge or ()),
                outer_edge=tuple(outer_edge or ()),
                start_cap_edge=tuple(start_cap_edge or ()),
                end_cap_edge=tuple(end_cap_edge or ()),
                loop_area_xy=float(loop_area_xy or 0.0),
            )
            if str(value or "")
        )
    if len(tuple(loop_points or ())) < 4:
        diagnostics.append("intersection_tie_slope_window_loop_open")
    if float(loop_area_xy or 0.0) <= 1.0e-6:
        diagnostics.append("intersection_tie_slope_window_loop_zero_area")
    diagnostics.extend(str(value or "") for value in tuple(extra_diagnostics or ()) if str(value or ""))
    outer_control_area_ref = str(getattr(outer_section, "active_intersection_control_area_id", "") or "")
    inner_control_area_ref = str(getattr(inner_section, "active_intersection_control_area_id", "") or "")
    control_area_transition_allowed = bool(
        outer_control_area_ref
        and inner_control_area_ref
        and outer_control_area_ref != inner_control_area_ref
    )
    if control_area_transition_allowed:
        diagnostics.append(
            "info:intersection_tie_slope_control_area_transition_allowed:"
            f"{outer_control_area_ref}->{inner_control_area_ref}"
        )
    blocking_diagnostics = [
        value for value in diagnostics
        if _intersection_tie_slope_window_diagnostic_blocks_surface(value)
    ]
    status = str(forced_status or "").strip() or ("accepted" if not blocking_diagnostics else "warning")
    row = {
        "intersection_id": str(getattr(prerequisite, "intersection_id", "") or ""),
        "intersection_kind": str(getattr(prerequisite, "intersection_kind", "") or ""),
        "alignment_ref": str(spec.get("alignment_ref", "") or ""),
        "road_role": str(spec.get("road_role", "") or ""),
        "gap_role": str(spec.get("gap_role", "") or ""),
        "side": str(spec.get("side", "") or ""),
        "cell_role": str(cell_role or ""),
        "transition_window_start_sta": float(span.get("transition_window_start_sta", 0.0) or 0.0),
        "transition_window_end_sta": float(span.get("transition_window_end_sta", 0.0) or 0.0),
        "transition_window_kind": str(span.get("transition_window_kind", "") or ""),
        "outer_section": outer_section,
        "inner_section": inner_section,
        "outer_applied_section_ref": str(getattr(outer_section, "applied_section_id", "") or ""),
        "inner_applied_section_ref": str(getattr(inner_section, "applied_section_id", "") or ""),
        "outer_control_area_ref": outer_control_area_ref,
        "inner_control_area_ref": inner_control_area_ref,
        "control_area_transition_allowed": control_area_transition_allowed,
        "outer_is_supplemental": _applied_section_is_supplemental(
            outer_section,
            kind_by_section_id=kind_by_section_id,
        ),
        "inner_is_supplemental": _applied_section_is_supplemental(
            inner_section,
            kind_by_section_id=kind_by_section_id,
        ),
        "supplemental_extent_role": str(supplemental_extent_role or ""),
        "supplemental_endpoint_ref": str(getattr(supplemental_endpoint_section, "applied_section_id", "") or ""),
        "supplemental_endpoint_station": (
            _section_station(supplemental_endpoint_section)
            if supplemental_endpoint_section is not None
            else 0.0
        ),
        "outer_station": _section_station(outer_section) if outer_section is not None else 0.0,
        "inner_station": _section_station(inner_section) if inner_section is not None else 0.0,
        "outer_legacy_edge_xyz": tuple(legacy_outer_edge or ()),
        "inner_legacy_edge_xyz": tuple(legacy_inner_edge or ()),
        "outer_tie_boundary_edge_xyz": tuple(outer_edge or ()),
        "inner_tie_boundary_edge_xyz": tuple(inner_edge or ()),
        "outer_edge_source_mode": str(outer_edge_source_mode or ""),
        "inner_edge_source_mode": str(inner_edge_source_mode or ""),
        "outer_edge_xyz": tuple(outer_edge or ()),
        "inner_edge_xyz": tuple(inner_edge or ()),
        "start_cap_edge_xyz": tuple(start_cap_edge or ()),
        "end_cap_edge_xyz": tuple(end_cap_edge or ()),
        "loop_points_xyz": tuple(loop_points or ()),
        "loop_area_xy": float(loop_area_xy or 0.0),
        "point_count": len(tuple(loop_points or ())),
        "status": status,
        "diagnostics": tuple(_unique_text_values(diagnostics)),
        "source_mode": "applied_section_context_transition_window",
    }
    ownership_class, ownership_notes = _intersection_tie_slope_window_ownership(row)
    row["ownership_class"] = ownership_class
    row["ownership_notes"] = ownership_notes
    return row


def _intersection_tie_slope_window_ownership(row: dict[str, object]) -> tuple[str, str]:
    """Classify which surface family owns an Applied Section tie-slope window."""

    diagnostics = tuple(str(value or "") for value in tuple(row.get("diagnostics", ()) or ()) if str(value or ""))
    blocking = [value for value in diagnostics if _intersection_tie_slope_window_diagnostic_blocks_surface(value)]
    if blocking:
        return "unowned_gap", "Rejected until Applied Section side-slope edges form a valid closed cell."
    intersection_kind = str(row.get("intersection_kind", "") or "").strip().lower()
    cell_role = str(row.get("cell_role", "") or "").strip().lower()
    if intersection_kind == "cross_intersection" and cell_role == "intersection_adjacent_pair":
        return "unowned_gap", "Cross intersection adjacent-pair rows are suppressed to avoid non-adjacent fan patches."
    if cell_role in {"transition_pair", "curb_return_approach_pair"}:
        outer_ref = str(row.get("outer_applied_section_ref", "") or "")
        inner_ref = str(row.get("inner_applied_section_ref", "") or "")
        side = str(row.get("side", "") or "")
        alignment_ref = str(row.get("alignment_ref", "") or "")
        if outer_ref and inner_ref and side and alignment_ref:
            return "tie_slope_candidate", "Owned by Intersection Tie Slope because adjacent Applied Section side-slope edges are available."
    return "unowned_gap", "No accepted surface owner was derived from the Applied Section window contract."


def _intersection_tie_slope_window_diagnostic_blocks_surface(value: object) -> bool:
    """Return True when a window diagnostic invalidates Tie Slope surface geometry."""

    text = str(value or "").strip()
    if not text or text.startswith("info:"):
        return False
    non_blocking = {
        "intersection_tie_slope_supplemental_endpoint_missing",
        "info:intersection_tie_slope_supplemental_endpoint_pending",
    }
    return text not in non_blocking


def _intersection_tie_slope_window_surface_row_enabled(row: dict[str, object]) -> bool:
    """Return whether an Applied Section window row should create Tie Slope surface triangles."""

    if str(row.get("ownership_class", "") or "").strip().lower() != "tie_slope_candidate":
        return False
    intersection_kind = str(row.get("intersection_kind", "") or "").strip().lower()
    cell_role = str(row.get("cell_role", "") or "").strip().lower()
    if intersection_kind == "cross_intersection" and cell_role == "intersection_adjacent_pair":
        return False
    return True


def _intersection_tie_slope_applied_section_window_display_row(row: dict[str, object]) -> str:
    diagnostics = tuple(str(value or "") for value in tuple(row.get("diagnostics", ()) or ()) if str(value or ""))
    return "|".join(
        [
            str(row.get("intersection_id", "") or ""),
            str(row.get("alignment_ref", "") or ""),
            str(row.get("road_role", "") or ""),
            str(row.get("gap_role", "") or ""),
            str(row.get("side", "") or ""),
            str(row.get("cell_role", "") or ""),
            str(row.get("supplemental_extent_role", "") or ""),
            f"outer_supplemental={int(bool(row.get('outer_is_supplemental', False)))}",
            f"inner_supplemental={int(bool(row.get('inner_is_supplemental', False)))}",
            str(row.get("supplemental_endpoint_ref", "") or ""),
            str(row.get("ownership_class", "") or ""),
            str(row.get("status", "") or ""),
            str(row.get("outer_applied_section_ref", "") or ""),
            str(row.get("inner_applied_section_ref", "") or ""),
            f"{float(row.get('outer_station', 0.0) or 0.0):.3f}",
            f"{float(row.get('inner_station', 0.0) or 0.0):.3f}",
            f"area={float(row.get('loop_area_xy', 0.0) or 0.0):.3f}",
            f"points={int(row.get('point_count', 0) or 0)}",
            ";".join(diagnostics),
        ]
    )


def _intersection_tie_slope_window_diagnostics(rows: list[dict[str, object]]) -> list[str]:
    diagnostics: list[str] = []
    for row in list(rows or []):
        diagnostics.extend(
            str(value or "")
            for value in tuple(row.get("diagnostics", ()) or ())
            if str(value or "")
        )
    return _unique_text_values(diagnostics)


def _intersection_tie_slope_window_summary_note(rows: list[dict[str, object]]) -> str:
    row_list = list(rows or [])
    accepted = [
        row for row in row_list
        if str(row.get("status", "") or "") == "accepted"
    ]
    warnings = [
        row for row in row_list
        if str(row.get("status", "") or "") != "accepted"
    ]
    cell_roles = [
        str(row.get("cell_role", "") or "")
        for row in row_list
        if str(row.get("cell_role", "") or "")
    ]
    alignments = [
        str(row.get("alignment_ref", "") or "")
        for row in row_list
        if str(row.get("alignment_ref", "") or "")
    ]
    sides = [
        str(row.get("side", "") or "")
        for row in row_list
        if str(row.get("side", "") or "")
    ]
    ownership_classes = [
        str(row.get("ownership_class", "") or "")
        for row in row_list
        if str(row.get("ownership_class", "") or "")
    ]
    diagnostics = _intersection_tie_slope_window_diagnostics(row_list)
    role_counts = {
        role: sum(1 for value in cell_roles if value == role)
        for role in _unique_text_values(cell_roles)
    }
    for known_role in ("transition_pair", "intersection_adjacent_pair", "curb_return_approach_pair"):
        role_counts.setdefault(known_role, 0)
    supplemental_endpoint_count = sum(
        1 for row in row_list
        if str(row.get("supplemental_extent_role", "") or "") == "supplemental_endpoint_pair"
    )
    supplemental_inner_count = sum(1 for row in row_list if bool(row.get("inner_is_supplemental", False)))
    control_area_transition_count = sum(
        1 for row in row_list
        if bool(row.get("control_area_transition_allowed", False))
    )
    role_text = ",".join(f"{role}={count}" for role, count in role_counts.items())
    ownership_counts = {
        ownership: sum(1 for value in ownership_classes if value == ownership)
        for ownership in _unique_text_values(ownership_classes)
    }
    ownership_text = ",".join(f"{ownership}={count}" for ownership, count in ownership_counts.items())
    parts = [
        f"Applied Section window candidates: rows={len(row_list)}",
        f"accepted={len(accepted)}",
        f"warnings={len(warnings)}",
        "source=applied_section_context_transition_window",
        f"supplemental_inner={supplemental_inner_count}",
        f"supplemental_endpoints={supplemental_endpoint_count}",
        f"control_area_transitions={control_area_transition_count}",
    ]
    if role_text:
        parts.append(role_text)
    if ownership_text:
        parts.append("ownership=" + ownership_text)
    endpoint_by_road = _intersection_tie_slope_window_endpoint_summary_by_road(row_list)
    if endpoint_by_road and endpoint_by_road != "not_evaluated":
        parts.append("supplemental_endpoint_by_road=" + endpoint_by_road)
    if alignments:
        parts.append("alignments=" + ",".join(_unique_text_values(alignments)))
    if sides:
        parts.append("sides=" + ",".join(_unique_text_values(sides)))
    if diagnostics:
        parts.append("diagnostics=" + "; ".join(diagnostics[:4]))
    return "; ".join(parts)


def _intersection_tie_slope_window_ownership_summary(rows: list[dict[str, object]]) -> str:
    """Return a compact count of Tie Slope window ownership classes."""

    values = [
        str(row.get("ownership_class", "") or "")
        for row in list(rows or [])
        if str(row.get("ownership_class", "") or "")
    ]
    if not values:
        return "not_evaluated"
    counts = {
        value: sum(1 for item in values if item == value)
        for value in _unique_text_values(values)
    }
    return ",".join(f"{key}={value}" for key, value in counts.items())


def _intersection_tie_slope_window_endpoint_summary_by_road(rows: list[dict[str, object]]) -> str:
    """Return accepted supplemental endpoint window counts by road role."""

    accepted_endpoint_rows = [
        row for row in list(rows or [])
        if str(row.get("status", "") or "") == "accepted"
        and str(row.get("ownership_class", "") or "") == "tie_slope_candidate"
        and str(row.get("supplemental_extent_role", "") or "") == "supplemental_endpoint_pair"
    ]
    road_roles = [
        str(row.get("road_role", "") or "")
        for row in accepted_endpoint_rows
        if str(row.get("road_role", "") or "")
    ]
    if not road_roles:
        return "not_evaluated"
    counts = {
        role: sum(1 for row in accepted_endpoint_rows if str(row.get("road_role", "") or "") == role)
        for role in _unique_text_values(road_roles)
    }
    return ",".join(f"{role}={count}" for role, count in counts.items())


def _intersection_tie_slope_transition_section_pair_for_gap(
    applied_section_set,
    *,
    alignment_ref: str,
    intersection_id: str,
    gap_role: str,
    side: str,
    station_span: dict[str, object],
) -> tuple[object, object] | None:
    """Return the adjacent Applied Section pair where ordinary context changes to intersection context.

    The highlight is intentionally based on the source/evaluated Applied Section context transition,
    not on a nearest STA lookup or any generated intersection mesh.
    """

    alignment_id = str(alignment_ref or "").strip()
    target_intersection = str(intersection_id or "").strip()
    if applied_section_set is None or not alignment_id or not target_intersection:
        return None
    sections = [
        section
        for section in _station_ordered_applied_sections(applied_section_set)
        if str(getattr(section, "alignment_id", "") or "").strip() == alignment_id
        and _intersection_tie_slope_terminal_road_edge(section, side=side)
    ]
    if len(sections) < 2:
        return None
    gap = str(gap_role or "").strip().lower()
    window_start = min(
        float(station_span.get("transition_window_start_sta", 0.0) or 0.0),
        float(station_span.get("transition_window_end_sta", 0.0) or 0.0),
    )
    window_end = max(
        float(station_span.get("transition_window_start_sta", 0.0) or 0.0),
        float(station_span.get("transition_window_end_sta", 0.0) or 0.0),
    )
    candidates: list[tuple[float, object, object]] = []
    for first, second in zip(sections, sections[1:]):
        first_station = _section_station(first)
        second_station = _section_station(second)
        pair_start = min(first_station, second_station)
        pair_end = max(first_station, second_station)
        if pair_end < window_start - 1.0e-6 or pair_start > window_end + 1.0e-6:
            continue
        first_is_intersection = str(getattr(first, "active_intersection_id", "") or "").strip() == target_intersection
        second_is_intersection = str(getattr(second, "active_intersection_id", "") or "").strip() == target_intersection
        if first_is_intersection == second_is_intersection:
            continue
        midpoint = (first_station + second_station) * 0.5
        target_midpoint = (window_start + window_end) * 0.5
        score = abs(midpoint - target_midpoint)
        if gap == "exit":
            if first_is_intersection and not second_is_intersection:
                candidates.append((score, second, first))
        else:
            if not first_is_intersection and second_is_intersection:
                candidates.append((score, first, second))
    if not candidates:
        return None
    _score, outer_section, inner_section = min(candidates, key=lambda item: item[0])
    return outer_section, inner_section


def _intersection_tie_slope_zero_span_transition_section_pair_for_gap(
    applied_section_set,
    *,
    alignment_ref: str,
    intersection_id: str,
    gap_role: str,
    side: str,
) -> tuple[object, object] | None:
    """Return the nearest ordinary/intersection Applied Section pair for zero-span transition windows."""

    alignment_id = str(alignment_ref or "").strip()
    target_intersection = str(intersection_id or "").strip()
    if applied_section_set is None or not alignment_id or not target_intersection:
        return None
    sections = [
        section
        for section in _station_ordered_applied_sections(applied_section_set)
        if str(getattr(section, "alignment_id", "") or "").strip() == alignment_id
        and _intersection_tie_slope_terminal_road_edge(section, side=side)
    ]
    if len(sections) < 2:
        return None
    transition_pairs: list[tuple[float, object, object]] = []
    for first, second in zip(sections, sections[1:]):
        first_is_intersection = str(getattr(first, "active_intersection_id", "") or "").strip() == target_intersection
        second_is_intersection = str(getattr(second, "active_intersection_id", "") or "").strip() == target_intersection
        if first_is_intersection == second_is_intersection:
            continue
        first_station = _section_station(first)
        second_station = _section_station(second)
        score = abs(second_station - first_station)
        if str(gap_role or "").strip().lower() == "exit":
            if first_is_intersection and not second_is_intersection:
                transition_pairs.append((score, second, first))
        else:
            if not first_is_intersection and second_is_intersection:
                transition_pairs.append((score, first, second))
    if not transition_pairs:
        return None
    _score, outer_section, inner_section = min(transition_pairs, key=lambda item: item[0])
    return outer_section, inner_section


def _intersection_tie_slope_next_intersection_section_pair(
    applied_section_set,
    *,
    alignment_ref: str,
    intersection_id: str,
    gap_role: str,
    side: str,
    outer_section,
    inner_section,
) -> tuple[object, object] | None:
    """Return one additional Applied Section pair in the intersection direction."""

    alignment_id = str(alignment_ref or "").strip()
    target_intersection = str(intersection_id or "").strip()
    if (
        applied_section_set is None
        or not alignment_id
        or not target_intersection
        or outer_section is None
        or inner_section is None
    ):
        return None
    sections = [
        section
        for section in _station_ordered_applied_sections(applied_section_set)
        if str(getattr(section, "alignment_id", "") or "").strip() == alignment_id
        and _intersection_tie_slope_terminal_road_edge(section, side=side)
    ]
    if len(sections) < 3:
        return None
    inner_id = str(getattr(inner_section, "applied_section_id", "") or "")
    inner_index = next(
        (
            index
            for index, section in enumerate(sections)
            if str(getattr(section, "applied_section_id", "") or "") == inner_id
        ),
        None,
    )
    if inner_index is None:
        return None
    direction = 1
    if str(gap_role or "").strip().lower() == "exit":
        direction = -1
    next_index = inner_index + direction
    if next_index < 0 or next_index >= len(sections):
        return None
    next_section = sections[next_index]
    if str(getattr(next_section, "active_intersection_id", "") or "").strip() != target_intersection:
        return None
    if str(getattr(next_section, "applied_section_id", "") or "") == str(getattr(outer_section, "applied_section_id", "") or ""):
        return None
    return inner_section, next_section


def _intersection_tie_slope_intersection_boundary_section_for_gap(
    applied_section_set,
    *,
    alignment_ref: str,
    intersection_id: str,
    gap_role: str,
    side: str,
):
    """Return the first or last intersection Applied Section for a Tie Slope approach window."""

    alignment_id = str(alignment_ref or "").strip()
    target_intersection = str(intersection_id or "").strip()
    if applied_section_set is None or not alignment_id or not target_intersection:
        return None
    sections = [
        section
        for section in _station_ordered_applied_sections(applied_section_set)
        if str(getattr(section, "alignment_id", "") or "").strip() == alignment_id
        and str(getattr(section, "active_intersection_id", "") or "").strip() == target_intersection
        and _intersection_tie_slope_terminal_road_edge(section, side=side)
    ]
    if not sections:
        return None
    if str(gap_role or "").strip().lower() == "exit":
        return sections[-1]
    return sections[0]


def _intersection_tie_slope_curb_return_approach_section_pairs(
    applied_section_set,
    *,
    alignment_ref: str,
    intersection_id: str,
    gap_role: str,
    side: str,
    start_section,
    max_pair_count: int = 0,
) -> list[tuple[object, object]]:
    """Return Cross Tie Slope pairs from the transition toward the supplemental Applied Section endpoint."""

    alignment_id = str(alignment_ref or "").strip()
    target_intersection = str(intersection_id or "").strip()
    if applied_section_set is None or not alignment_id or not target_intersection or start_section is None:
        return []
    sections = [
        section
        for section in _station_ordered_applied_sections(applied_section_set)
        if str(getattr(section, "alignment_id", "") or "").strip() == alignment_id
        and str(getattr(section, "active_intersection_id", "") or "").strip() == target_intersection
        and _intersection_tie_slope_terminal_road_edge(section, side=side)
    ]
    if len(sections) < 2:
        return []
    start_id = str(getattr(start_section, "applied_section_id", "") or "")
    start_index = next(
        (
            index
            for index, section in enumerate(sections)
            if str(getattr(section, "applied_section_id", "") or "") == start_id
        ),
        None,
    )
    if start_index is None:
        return []
    direction = -1 if str(gap_role or "").strip().lower() == "exit" else 1
    kind_by_section_id = _applied_section_kind_map(applied_section_set)
    walkable_indices: list[int] = []
    probe_index = start_index
    while True:
        next_index = probe_index + direction
        if next_index < 0 or next_index >= len(sections):
            break
        walkable_indices.append(next_index)
        probe_index = next_index
    supplemental_indices = [
        index for index in walkable_indices
        if _applied_section_is_supplemental(sections[index], kind_by_section_id=kind_by_section_id)
    ]
    endpoint_index = supplemental_indices[-1] if supplemental_indices else None
    safety_pair_count = int(max_pair_count or 0)
    if safety_pair_count <= 0:
        safety_pair_count = len(walkable_indices) if supplemental_indices else min(3, len(walkable_indices))
    pairs: list[tuple[object, object]] = []
    current_index = start_index
    while len(pairs) < max(0, safety_pair_count):
        next_index = current_index + direction
        if next_index < 0 or next_index >= len(sections):
            break
        outer_section = sections[current_index]
        inner_section = sections[next_index]
        pairs.append((outer_section, inner_section))
        current_index = next_index
        if endpoint_index is not None and current_index == endpoint_index:
            break
    return pairs


def _intersection_tie_slope_terminal_road_edge(section, *, side: str) -> tuple[tuple[float, float, float], ...]:
    if section is None:
        return ()
    points = _slope_face_applied_section_breakline_points(section, side_label=str(side or "").strip().lower())
    edge = tuple(_xyz_tuple(point) for point in points)
    if len(edge) < 2:
        return ()
    first, last = _intersection_tie_slope_endpoint_pair(edge)
    if _xy_distance(first, last) <= 1.0e-6:
        section_edge = _applied_section_slope_face_edge_points(
            section,
            side_label=str(side or "").strip().lower(),
            fallback_band_width=6.0,
            fallback_band_slope=0.33,
        )
        if section_edge is not None:
            inner, outer = section_edge
            fallback_edge = (_xyz_tuple(inner), _xyz_tuple(outer))
            if _xy_distance(fallback_edge[0], fallback_edge[1]) > 1.0e-6:
                return fallback_edge
        return ()
    return edge


def _intersection_tie_slope_target_station(intersection_model, intersection_id: str, alignment_ref: str) -> float | None:
    source_row = _intersection_row_by_id(intersection_model, intersection_id) if intersection_model is not None else None
    alignment_id = str(alignment_ref or "").strip()
    if source_row is None or not alignment_id:
        return None
    primary_ref = str(getattr(source_row, "primary_alignment_ref", "") or "").strip()
    if alignment_id == primary_ref:
        return float(getattr(source_row, "primary_station", 0.0) or 0.0)
    secondary_stations = dict(getattr(source_row, "secondary_station_refs", {}) or {})
    if alignment_id in secondary_stations:
        return float(secondary_stations.get(alignment_id) or 0.0)
    return None


def _intersection_tie_slope_leg_ref(source_row, alignment_ref: str, *, road_role: str) -> str:
    if source_row is None:
        return ""
    alignment_id = str(alignment_ref or "").strip()
    target_role = str(road_role or "").strip().lower()
    fallback = ""
    for leg in list(getattr(source_row, "leg_rows", []) or []):
        if str(getattr(leg, "alignment_ref", "") or "").strip() != alignment_id:
            continue
        leg_id = str(getattr(leg, "leg_id", "") or "").strip()
        leg_role = str(getattr(leg, "leg_role", "") or "").strip().lower()
        fallback = fallback or leg_id
        if target_role == "primary" and leg_role.startswith("primary"):
            return leg_id
        if target_role == "secondary" and not leg_role.startswith("primary"):
            return leg_id
    return fallback


def _intersection_tie_slope_control_area_ref(intersection_model, intersection_id: str, alignment_ref: str, *, source_row=None) -> str:
    alignment_id = str(alignment_ref or "").strip()
    areas = list(getattr(intersection_model, "control_area_rows", []) or []) if intersection_model is not None else []
    for area in areas:
        if str(getattr(area, "intersection_id", "") or "").strip() != str(intersection_id or "").strip():
            continue
        if alignment_id and str(getattr(area, "alignment_ref", "") or "").strip() != alignment_id:
            continue
        area_id = str(getattr(area, "control_area_id", "") or "").strip()
        if area_id:
            return area_id
    legs = list(getattr(source_row, "leg_rows", []) or []) if source_row is not None else []
    for leg in legs:
        if alignment_id and str(getattr(leg, "alignment_ref", "") or "").strip() == alignment_id:
            return str(getattr(leg, "region_ref", "") or "").strip()
    return ""


def _intersection_tie_slope_terminal_applied_sections(
    applied_section_set,
    source_refs: tuple[str, ...],
    *,
    alignment_ref: str,
    intersection_id: str,
    side: str,
) -> tuple[object, ...]:
    source_ref_set = {str(value or "") for value in tuple(source_refs or ()) if str(value or "")}
    alignment_sections = [
        section
        for section in list(getattr(applied_section_set, "sections", []) or [])
        if str(getattr(section, "alignment_id", "") or "").strip() == str(alignment_ref or "").strip()
    ]
    source_sections = [
        section for section in alignment_sections
        if str(getattr(section, "applied_section_id", "") or "") in source_ref_set
    ] if source_ref_set else []
    active_sections = [
        section for section in alignment_sections
        if (
            not intersection_id
            or str(getattr(section, "active_intersection_id", "") or "").strip() == str(intersection_id or "").strip()
            or str(getattr(section, "active_intersection_control_area_id", "") or "").strip()
        )
    ]
    preferred = source_sections or active_sections or alignment_sections
    valid_sections = [
        section for section in preferred
        if _applied_section_slope_face_edge_points(
            section,
            side_label=side,
            fallback_band_width=6.0,
            fallback_band_slope=0.33,
        ) is not None
    ]
    valid_sections = sorted(valid_sections, key=lambda section: float(getattr(section, "station", 0.0) or 0.0))
    if len(valid_sections) <= 2:
        return tuple(valid_sections)
    return (valid_sections[0], valid_sections[-1])


def _intersection_tie_slope_terminal_outer_points(
    terminal_sections: tuple[object, ...],
    *,
    side: str,
) -> tuple[tuple[float, float, float], ...]:
    outer_points: list[tuple[float, float, float]] = []
    for section in tuple(terminal_sections or ()):
        edge = _applied_section_slope_face_edge_points(
            section,
            side_label=side,
            fallback_band_width=6.0,
            fallback_band_slope=0.33,
        )
        if edge is None:
            continue
        _inner, outer = edge
        outer_xyz = _xyz_tuple(outer)
        if outer_points and _xy_distance(outer_points[-1], outer_xyz) <= 1.0e-6:
            continue
        outer_points.append(outer_xyz)
    return tuple(outer_points)


def _intersection_tie_slope_loop_points(
    inner_points: tuple[tuple[float, float, float], ...],
    outer_points: tuple[tuple[float, float, float], ...],
) -> tuple[tuple[float, float, float], ...]:
    if len(inner_points) < 2 or len(outer_points) < 2:
        return ()
    loop = [*_intersection_tie_slope_endpoint_pair(inner_points), *reversed(_intersection_tie_slope_endpoint_pair(outer_points))]
    if loop and not _intersection_slope_face_points_close_xy(loop[0], loop[-1]):
        loop.append(loop[0])
    return tuple(_intersection_slope_face_simplified_closed_loop(loop))


def _intersection_tie_slope_endpoint_pair(
    points: tuple[tuple[float, float, float], ...],
) -> tuple[tuple[float, float, float], tuple[float, float, float]]:
    return (_xyz_tuple(points[0]), _xyz_tuple(points[-1]))


def _intersection_tie_in_strip_polygon(rows: list[IntersectionBoundarySegmentRow]) -> list[tuple[float, float, float]] | None:
    return IntersectionPatchTriangulationService().tie_in_strip_polygon(rows)


def _normalize_intersection_tie_in_strip_polygon(
    points: list[tuple[float, float, float]],
    *,
    tolerance: float = 1.0e-6,
) -> list[tuple[float, float, float]] | None:
    return IntersectionPatchTriangulationService().normalize_tie_in_strip_polygon(
        points,
        tolerance=tolerance,
    )


def _xy_polygon_union_outer_boundary(
    polygons: list[list[tuple[float, float, float]]],
) -> list[tuple[float, float, float]]:
    return xyz_polygon_union_outer_boundary(polygons)


def _ordered_outer_boundary_from_segments(
    segments: list[tuple[tuple[float, float, float], tuple[float, float, float]]],
) -> list[tuple[float, float, float]]:
    return xyz_ordered_outer_boundary_from_segments(segments)


def _xy_polygon_exterior_hull_boundary(
    polygons: list[list[tuple[float, float, float]]],
) -> list[tuple[float, float, float]]:
    return xyz_exterior_convex_hull(polygons)


def _xy_key(point: tuple[float, float, float]) -> tuple[float, float]:
    return (round(float(point[0]), 6), round(float(point[1]), 6))


def _xy_segment_intersection_point(
    a1: tuple[float, float, float],
    a2: tuple[float, float, float],
    b1: tuple[float, float, float],
    b2: tuple[float, float, float],
) -> tuple[float, float, float] | None:
    return xyz_segment_intersection_point(a1, a2, b1, b2)


def _xy_point_on_segment(point: tuple[float, float], start: tuple[float, float], end: tuple[float, float]) -> bool:
    return xy_point_on_segment(point, start, end)


def _xy_segment_parameter(point: tuple[float, float], start: tuple[float, float], end: tuple[float, float]) -> float:
    return xy_segment_parameter_clamped(point, start, end)


def _xy_point_in_polygon_strict(point: tuple[float, float], polygon: list[tuple[float, float]]) -> bool:
    return xy_point_in_polygon_strict(point, polygon)


def _xyz_closed_edges(points: list[tuple[float, float, float]]) -> list[tuple[tuple[float, float, float], tuple[float, float, float]]]:
    return [(points[index], points[(index + 1) % len(points)]) for index in range(len(points))]


def _xy_area_from_xyz_points(points: list[tuple[float, float, float]]) -> float:
    return xy_polygon_signed_area(points)


def _xy_xyz_polygon_self_crossing(points: list[tuple[float, float, float]]) -> bool:
    return xy_polygon_self_intersects(points)


def _xyz_tuple(point) -> tuple[float, float, float]:
    return xyz_point(point)


def _resample_xyz_polyline(points, target_count: int) -> list[tuple[float, float, float]]:
    ordered = [_xyz_tuple(point) for point in list(points or [])]
    if not ordered:
        return []
    if len(ordered) == 1 or int(target_count or 0) <= 1:
        return [ordered[0]]
    target_count = max(2, int(target_count))
    cumulative_lengths = [0.0]
    total = 0.0
    for first, second in zip(ordered, ordered[1:]):
        total += math.sqrt(
            (float(second[0]) - float(first[0])) ** 2
            + (float(second[1]) - float(first[1])) ** 2
            + (float(second[2]) - float(first[2])) ** 2
        )
        cumulative_lengths.append(total)
    if total <= 1.0e-9:
        return [ordered[0] for _index in range(target_count)]
    output: list[tuple[float, float, float]] = []
    for index in range(target_count):
        distance = total * (float(index) / float(target_count - 1))
        output.append(_interpolate_xyz_polyline_at_distance(ordered, cumulative_lengths, distance))
    return output


def _interpolate_xyz_polyline_at_distance(
    points: list[tuple[float, float, float]],
    cumulative_lengths: list[float],
    distance: float,
) -> tuple[float, float, float]:
    if not points:
        return (0.0, 0.0, 0.0)
    if distance <= 0.0:
        return points[0]
    if distance >= float(cumulative_lengths[-1] if cumulative_lengths else 0.0):
        return points[-1]
    for index in range(1, len(points)):
        start_distance = float(cumulative_lengths[index - 1])
        end_distance = float(cumulative_lengths[index])
        if distance > end_distance:
            continue
        span = end_distance - start_distance
        ratio = 0.0 if span <= 1.0e-9 else (float(distance) - start_distance) / span
        first = points[index - 1]
        second = points[index]
        return (
            float(first[0]) + (float(second[0]) - float(first[0])) * ratio,
            float(first[1]) + (float(second[1]) - float(first[1])) * ratio,
            float(first[2]) + (float(second[2]) - float(first[2])) * ratio,
        )
    return points[-1]


def _intersection_patch_boundary_has_self_crossing(point_rows: list[IntersectionPatchBoundaryPointRow]) -> bool:
    points = [(float(row.x), float(row.y)) for row in point_rows]
    return xy_polygon_self_intersects(points)


def _intersection_patch_boundary_rings_intersect(
    first: list[IntersectionPatchBoundaryPointRow],
    second: list[IntersectionPatchBoundaryPointRow],
) -> bool:
    first_points = [(float(row.x), float(row.y)) for row in first]
    second_points = [(float(row.x), float(row.y)) for row in second]
    return xy_polygon_boundaries_intersect(first_points, second_points)


def _xy_segments_intersect(
    a1: tuple[float, float],
    a2: tuple[float, float],
    b1: tuple[float, float],
    b2: tuple[float, float],
) -> bool:
    return xy_segments_intersect(a1, a2, b1, b2)


def _intersection_curb_return_policy_for(intersection_model, intersection_id: str):
    target = str(intersection_id or "").strip()
    rows = list(getattr(intersection_model, "curb_return_policy_rows", []) or []) if intersection_model is not None else []
    for row in rows:
        if str(getattr(row, "intersection_id", "") or "") == target and str(getattr(row, "status", "") or "active") != "disabled":
            return row
    return None


def _diagnostics_include_error(diagnostics: list[str] | tuple[str, ...]) -> bool:
    for value in list(diagnostics or []):
        text = str(value or "").strip().lower()
        if text and not text.startswith("warning:"):
            return True
    return False


def _safe_id_fragment(value: str) -> str:
    text = str(value or "").strip()
    for token in (":", "/", "\\", " ", "|"):
        text = text.replace(token, "-")
    return text.strip("-") or "unknown"


def _intersection_patch_sections(applied_section_set, prerequisite: IntersectionPatchPrerequisiteResult) -> list[object]:
    control_refs = set(str(value or "") for value in list(getattr(prerequisite, "control_region_refs", ()) or ()) if str(value or ""))
    intersection_id = str(getattr(prerequisite, "intersection_id", "") or "")
    return [
        section for section in _station_ordered_applied_sections(applied_section_set)
        if (
            (intersection_id and str(getattr(section, "active_intersection_id", "") or "") == intersection_id)
            or (str(getattr(section, "region_id", "") or "") in control_refs)
        )
    ]


def _intersection_drainage_element_rows(drainage_model, prerequisite: IntersectionPatchPrerequisiteResult) -> list[object]:
    return list(_intersection_drainage_coverage(drainage_model, prerequisite).get("candidate_rows", []) or [])


def _intersection_drainage_coverage(
    drainage_model,
    prerequisite: IntersectionPatchPrerequisiteResult,
    *,
    low_point_station: float | None = None,
) -> dict[str, object]:
    if drainage_model is None:
        return {"candidate_rows": [], "ready_rows": [], "diagnostics": ["drainage_model_missing"]}
    intersection_id = str(getattr(prerequisite, "intersection_id", "") or "").strip()
    control_refs = set(str(value or "") for value in list(getattr(prerequisite, "control_region_refs", ()) or ()) if str(value or ""))
    candidate_rows: list[object] = []
    ready_rows: list[object] = []
    diagnostics: list[str] = []
    for row in list(getattr(drainage_model, "element_rows", []) or []):
        row_intersection = str(getattr(row, "intersection_ref", "") or "").strip()
        row_region = str(getattr(row, "region_ref", "") or "").strip()
        owns_intersection = bool(intersection_id and row_intersection == intersection_id)
        owns_control_region = bool(row_region and row_region in control_refs)
        if not (owns_intersection or owns_control_region):
            continue
        candidate_rows.append(row)
        if low_point_station is None or _drainage_element_covers_station(row, float(low_point_station)):
            ready_rows.append(row)
        else:
            diagnostics.append(
                "drainage_element_outside_low_point_station_range:"
                f"{str(getattr(row, 'drainage_element_id', '') or '')}:"
                f"{float(getattr(row, 'station_start', 0.0) or 0.0):.3f}-"
                f"{float(getattr(row, 'station_end', 0.0) or 0.0):.3f}"
            )
    if candidate_rows and not ready_rows and low_point_station is not None:
        diagnostics.append(f"intersection_low_point_station_uncovered:{float(low_point_station):.3f}")
    if not candidate_rows:
        diagnostics.append("intersection_drainage_element_missing")
    return {"candidate_rows": candidate_rows, "ready_rows": ready_rows, "diagnostics": diagnostics}


def _drainage_element_covers_station(row, station: float, *, tolerance: float = 1.0e-6) -> bool:
    start = float(getattr(row, "station_start", 0.0) or 0.0)
    end = float(getattr(row, "station_end", 0.0) or 0.0)
    return min(start, end) - tolerance <= float(station) <= max(start, end) + tolerance


def _active_ditch_drainage_rows(drainage_model, *, region_model, station: float) -> list[object]:
    if drainage_model is None:
        return []
    if region_model is not None:
        try:
            context = StationContextResolver().resolve(
                region_model=region_model,
                drainage_model=drainage_model,
                station=float(station),
            )
            rows = list(getattr(context, "active_drainage_elements", []) or [])
            return [row for row in rows if _is_ditch_drainage_element(row)]
        except Exception:
            pass
    output: list[object] = []
    for row in list(getattr(drainage_model, "element_rows", []) or []):
        if not _is_ditch_drainage_element(row):
            continue
        try:
            start = float(getattr(row, "station_start", 0.0) or 0.0)
            end = float(getattr(row, "station_end", 0.0) or 0.0)
        except Exception:
            continue
        if min(start, end) <= float(station) <= max(start, end):
            output.append(row)
    return output


def _is_ditch_drainage_element(row) -> bool:
    kind = str(getattr(row, "element_kind", "") or "").strip().lower()
    return kind in {"ditch", "lined_ditch", "lined-ditch", "gutter", "swale", "channel"}


def _drainage_source_surface_mismatch_notes(active_ditch_rows: list[object], ditch_points: list[object]) -> list[str]:
    if not active_ditch_rows:
        return []
    point_data = _ditch_point_context_by_side(ditch_points)
    notes: list[str] = []
    for row in active_ditch_rows:
        drainage_ref = str(getattr(row, "drainage_element_id", "") or "").strip()
        subassembly_ref = str(getattr(row, "subassembly_ref", "") or "").strip()
        for side in _drainage_row_sides(row):
            data = point_data.get(side, {})
            point_count = int(data.get("point_count", 0) or 0)
            drainage_refs = set(data.get("drainage_refs", []) or [])
            subassembly_refs = set(data.get("subassembly_refs", []) or [])
            if point_count <= 0:
                notes.append(f"missing_side={side};drainage_ref={drainage_ref or '-'}")
                continue
            if drainage_ref and drainage_ref not in drainage_refs:
                notes.append(f"missing_drainage_ref={drainage_ref};side={side}")
            if subassembly_ref and subassembly_ref not in subassembly_refs:
                notes.append(f"subassembly_mismatch={subassembly_ref};side={side}")
    return _unique_refs(notes)


def _ditch_point_context_by_side(ditch_points: list[object]) -> dict[str, dict[str, object]]:
    output: dict[str, dict[str, object]] = {}
    for point in list(ditch_points or []):
        side = _long_drainage_side(_drainage_point_side(point))
        if side not in {"left", "right"}:
            continue
        data = output.setdefault(side, {"point_count": 0, "drainage_refs": [], "subassembly_refs": []})
        data["point_count"] = int(data.get("point_count", 0) or 0) + 1
        drainage_ref = str(getattr(point, "drainage_ref", "") or "").strip()
        subassembly_ref = str(getattr(point, "subassembly_ref", "") or "").strip()
        if drainage_ref:
            data.setdefault("drainage_refs", []).append(drainage_ref)
        if subassembly_ref:
            data.setdefault("subassembly_refs", []).append(subassembly_ref)
    for data in output.values():
        data["drainage_refs"] = _unique_refs(list(data.get("drainage_refs", []) or []))
        data["subassembly_refs"] = _unique_refs(list(data.get("subassembly_refs", []) or []))
    return output


def _drainage_row_sides(row) -> list[str]:
    side = str(getattr(row, "side", "") or "").strip().lower()
    if side == "both":
        return ["left", "right"]
    if side in {"left", "right"}:
        return [side]
    ref_text = " ".join(
        [
            str(getattr(row, "drainage_element_id", "") or ""),
            str(getattr(row, "subassembly_ref", "") or ""),
        ]
    ).lower()
    if "left" in ref_text or ":l" in ref_text or "-l" in ref_text:
        return ["left"]
    if "right" in ref_text or ":r" in ref_text or "-r" in ref_text:
        return ["right"]
    return []


def _long_drainage_side(side: str) -> str:
    text = str(side or "").strip().lower()
    if text in {"l", "left"}:
        return "left"
    if text in {"r", "right"}:
        return "right"
    return text


def _drainage_review_marker_point(section, ditch_points: list[object]) -> tuple[float, float, float]:
    points = list(ditch_points or [])
    if points:
        return (
            sum(float(getattr(point, "x", 0.0) or 0.0) for point in points) / len(points),
            sum(float(getattr(point, "y", 0.0) or 0.0) for point in points) / len(points),
            sum(float(getattr(point, "z", 0.0) or 0.0) for point in points) / len(points),
        )
    frame = getattr(section, "frame", None)
    if frame is not None:
        return (
            float(getattr(frame, "x", 0.0) or 0.0),
            float(getattr(frame, "y", 0.0) or 0.0),
            float(getattr(frame, "z", 0.0) or 0.0),
        )
    return (0.0, 0.0, 0.0)


def _drainage_review_marker_name(row_index: int) -> str:
    return f"ReviewIssueDrainageStation{max(0, int(row_index)) + 1:03d}"


def _drainage_flow_connected_elements(flow_row, element_by_id: dict[str, object]) -> list[object]:
    elements: list[object] = []
    seen: set[str] = set()
    for ref in (
        str(getattr(flow_row, "from_element_ref", "") or ""),
        str(getattr(flow_row, "to_element_ref", "") or ""),
        str(getattr(flow_row, "outlet_ref", "") or ""),
    ):
        if not ref or ref in seen:
            continue
        seen.add(ref)
        element = element_by_id.get(ref)
        if element is not None:
            elements.append(element)
    return elements


def _drainage_flow_structure_refs(flow_row, connected_elements: list[object]) -> list[str]:
    refs: list[str] = []
    for element in list(connected_elements or []):
        ref = str(getattr(element, "structure_ref", "") or "").strip()
        if ref:
            refs.append(ref)
    outlet_ref = str(getattr(flow_row, "outlet_ref", "") or "").strip()
    if outlet_ref.startswith("structure:"):
        refs.append(outlet_ref)
    return _unique_text_values(refs)


def _drainage_flow_station_range(
    flow_row,
    connected_elements: list[object],
    structure_by_id: dict[str, object],
) -> tuple[float, float] | None:
    stations: list[float] = []
    for element in list(connected_elements or []):
        stations.extend(
            [
                float(getattr(element, "station_start", 0.0) or 0.0),
                float(getattr(element, "station_end", 0.0) or 0.0),
            ]
        )
    for ref in _drainage_flow_structure_refs(flow_row, connected_elements):
        structure = structure_by_id.get(ref)
        placement = getattr(structure, "placement", None)
        if placement is None:
            continue
        stations.extend(
            [
                float(getattr(placement, "station_start", 0.0) or 0.0),
                float(getattr(placement, "station_end", 0.0) or 0.0),
            ]
        )
    if not stations:
        return None
    return min(stations), max(stations)


def _drainage_flow_row_highlight_mode(document, route_ref: str) -> str:
    if document is None or not str(route_ref or ""):
        return "missing"
    applied = to_applied_section_set(find_v1_applied_section_set(document))
    sections = _station_ordered_applied_sections(applied)
    segments = _drainage_flow_connection_point_segments(
        document,
        sections,
        {"flow_route_id": str(route_ref or "")},
    )
    return "connection_point_pipe" if segments else "station_span"


def _unique_text_values(values: list[str]) -> list[str]:
    output: list[str] = []
    seen: set[str] = set()
    for value in list(values or []):
        text = str(value or "").strip()
        if not text or text in seen:
            continue
        seen.add(text)
        output.append(text)
    return output


def _display_source_ref(value: object) -> str:
    text = str(value or "").strip()
    if ":" not in text:
        return text
    return text.split(":", 1)[1]


def _create_drainage_flow_review_highlight(*, document=None, rows: list[dict[str, object]] | None = None):
    if document is None:
        return None
    try:
        import FreeCAD as AppModule
        import Part
    except Exception:
        return None
    applied = to_applied_section_set(find_v1_applied_section_set(document))
    sections = sorted(list(getattr(applied, "sections", []) or []), key=lambda section: _section_station(section)) if applied is not None else []
    shapes: list[object] = []
    route_refs: list[str] = []
    structure_refs: list[str] = []
    connection_point_refs: list[str] = []
    pipe_segment_count = 0
    station_span_count = 0
    for row in list(rows or []):
        route_ref = str(row.get("flow_route_id", "") or "")
        if route_ref:
            route_refs.append(route_ref)
        for ref in str(row.get("structure_refs", "") or "").split(","):
            if ref.strip():
                structure_refs.append(ref.strip())
        point_segments = _drainage_flow_connection_point_segments(document, sections, row)
        if point_segments:
            for segment in point_segments:
                first, second, first_ref, second_ref, radius = segment
                connection_point_refs.extend([first_ref, second_ref])
                try:
                    shapes.append(_make_drainage_pipe_segment_shape(Part, AppModule, first, second, radius))
                    pipe_segment_count += 1
                except Exception:
                    try:
                        shapes.append(Part.makeLine(AppModule.Vector(*first), AppModule.Vector(*second)))
                        pipe_segment_count += 1
                    except Exception:
                        pass
            continue
        start, end = _drainage_flow_row_station_range(row)
        if start is None or end is None:
            continue
        points = _drainage_flow_highlight_points(sections, start, end)
        for first, second in zip(points[:-1], points[1:]):
            try:
                shapes.append(Part.makeLine(AppModule.Vector(*first), AppModule.Vector(*second)))
                station_span_count += 1
            except Exception:
                pass
    if not shapes:
        return None
    obj = document.getObject("ReviewIssueDrainageFlowRoutes")
    if obj is None:
        obj = document.addObject("Part::Feature", "ReviewIssueDrainageFlowRoutes")
    try:
        obj.Shape = Part.makeCompound(shapes)
        obj.Label = "Drainage Flow Highlight"
    except Exception:
        return obj
    _set_preview_property(obj, "CRRecordKind", "v1_review_issue")
    _set_preview_property(obj, "V1ObjectType", "ReviewIssue")
    _set_preview_property(obj, "IssueKind", "drainage_flow")
    display_mode = "drainage_flow_pipe_segments" if pipe_segment_count else "drainage_flow_station_span"
    _set_preview_property(obj, "DisplayMode", display_mode)
    _set_preview_string_list_property(obj, "FlowRouteRefs", _unique_text_values(route_refs))
    _set_preview_string_list_property(obj, "StructureRefs", _unique_text_values(structure_refs))
    _set_preview_string_list_property(obj, "ConnectionPointRefs", _unique_text_values(connection_point_refs))
    _set_preview_integer_property(obj, "MarkerCount", len(shapes))
    _set_preview_integer_property(obj, "PipeSegmentCount", pipe_segment_count)
    _set_preview_integer_property(obj, "StationSpanCount", station_span_count)
    try:
        vobj = getattr(obj, "ViewObject", None)
        if vobj is not None:
            vobj.Visibility = True
            vobj.ShapeColor = (1.00, 0.68, 0.10)
            vobj.PointColor = (1.00, 0.68, 0.10)
            vobj.LineColor = (1.00, 0.68, 0.10)
            vobj.LineWidth = 7.0
            vobj.PointSize = 9.0
            vobj.Transparency = 0
    except Exception:
        pass
    try:
        from freecad.Corridor_Road.objects.obj_project import route_to_v1_tree

        route_to_v1_tree(find_project(document), obj)
    except Exception:
        pass
    return obj


def _drainage_flow_row_station_range(row: dict[str, object]) -> tuple[float | None, float | None]:
    try:
        start = float(row.get("station_start", "") if row.get("station_start", "") != "" else "")
        end = float(row.get("station_end", "") if row.get("station_end", "") != "" else "")
        return min(start, end), max(start, end)
    except Exception:
        return None, None


def _drainage_flow_connection_point_segments(
    document,
    sections: list[object],
    row: dict[str, object],
) -> list[tuple[tuple[float, float, float], tuple[float, float, float], str, str, float]]:
    drainage_model = to_drainage_model(find_v1_drainage_model(document))
    structure_model = to_structure_model(find_v1_structure_model(document))
    if drainage_model is None or structure_model is None:
        return []
    route_ref = str(row.get("flow_route_id", "") or "")
    flow_row = next(
        (
            candidate
            for candidate in list(getattr(drainage_model, "flow_route_rows", []) or [])
            if str(getattr(candidate, "flow_route_id", "") or "") == route_ref
        ),
        None,
    )
    if flow_row is None:
        return []
    element_by_id = {
        str(getattr(element, "drainage_element_id", "") or ""): element
        for element in list(getattr(drainage_model, "element_rows", []) or [])
    }
    point_by_id = {
        str(getattr(point, "connection_point_id", "") or ""): point
        for point in list(getattr(structure_model, "connection_point_rows", []) or [])
    }
    points_by_structure: dict[str, list[object]] = {}
    for point in list(getattr(structure_model, "connection_point_rows", []) or []):
        structure_ref = str(getattr(point, "structure_ref", "") or "")
        if structure_ref:
            points_by_structure.setdefault(structure_ref, []).append(point)
    chain_refs = [
        str(getattr(flow_row, "from_element_ref", "") or ""),
        str(getattr(flow_row, "to_element_ref", "") or ""),
        str(getattr(flow_row, "outlet_ref", "") or ""),
    ]
    chain_refs = [ref for ref in chain_refs if ref]
    if len(chain_refs) < 2:
        return []
    resolved: list[tuple[object, str]] = []
    for index, ref in enumerate(chain_refs):
        direction = "out" if index == 0 else "in"
        point = _drainage_flow_chain_connection_point(
            ref,
            element_by_id=element_by_id,
            point_by_id=point_by_id,
            points_by_structure=points_by_structure,
            direction=direction,
        )
        if point is None:
            return []
        resolved.append((point, str(getattr(point, "connection_point_id", "") or "")))
    segments: list[tuple[tuple[float, float, float], tuple[float, float, float], str, str, float]] = []
    for (first_point, first_ref), (second_point, second_ref) in zip(resolved[:-1], resolved[1:]):
        first_xyz = _drainage_connection_point_xyz(sections, first_point)
        second_xyz = _drainage_connection_point_xyz(sections, second_point)
        if first_xyz is None or second_xyz is None:
            continue
        radius = _drainage_pipe_segment_radius(first_point, second_point)
        segments.append((first_xyz, second_xyz, first_ref, second_ref, radius))
    return segments


def _drainage_flow_chain_connection_point(
    ref: str,
    *,
    element_by_id: dict[str, object],
    point_by_id: dict[str, object],
    points_by_structure: dict[str, list[object]],
    direction: str,
):
    text = str(ref or "").strip()
    if not text:
        return None
    if text.startswith("connection:"):
        return point_by_id.get(text)
    if text.startswith("structure:"):
        return _preferred_structure_connection_point(text, points_by_structure, direction=direction)
    element = element_by_id.get(text)
    if element is None:
        return None
    point_ref = str(getattr(element, "connection_point_ref", "") or "").strip()
    if point_ref:
        point = point_by_id.get(point_ref)
        if point is not None:
            return point
    structure_ref = str(getattr(element, "structure_ref", "") or "").strip()
    if structure_ref:
        return _preferred_structure_connection_point(structure_ref, points_by_structure, direction=direction)
    return None


def _preferred_structure_connection_point(
    structure_ref: str,
    points_by_structure: dict[str, list[object]],
    *,
    direction: str,
):
    points = list(points_by_structure.get(str(structure_ref or ""), []) or [])
    if not points:
        return None
    role_priority = (
        ["pipe_out", "downstream", "discharge", "outlet", "inlet", "pipe_in", "upstream"]
        if direction == "out"
        else ["pipe_in", "upstream", "inlet", "pipe_out", "downstream", "discharge", "outlet"]
    )
    by_role = {str(getattr(point, "point_role", "") or "").strip().lower(): point for point in points}
    for role in role_priority:
        if role in by_role:
            return by_role[role]
    return sorted(points, key=lambda point: int(getattr(point, "connection_order", 0) or 0))[0]


def _drainage_connection_point_xyz(
    sections: list[object],
    point,
    *,
    z_offset: float = 1.15,
) -> tuple[float, float, float] | None:
    station = float(getattr(point, "station", 0.0) or 0.0)
    frame = _drainage_flow_station_frame(sections, station)
    if frame is None:
        return None
    try:
        import math as _math

        offset = float(getattr(point, "offset", 0.0) or 0.0)
        angle_rad = _math.radians(float(getattr(frame, "tangent_direction_deg", 0.0) or 0.0))
        x = float(getattr(frame, "x", 0.0) or 0.0) - _math.sin(angle_rad) * offset
        y = float(getattr(frame, "y", 0.0) or 0.0) + _math.cos(angle_rad) * offset
        z = float(getattr(frame, "z", 0.0) or 0.0) + float(z_offset or 0.0)
        return x, y, z
    except Exception:
        return (
            float(getattr(frame, "x", 0.0) or 0.0),
            float(getattr(frame, "y", 0.0) or 0.0),
            float(getattr(frame, "z", 0.0) or 0.0) + float(z_offset or 0.0),
        )


def _drainage_flow_station_frame(sections: list[object], station: float):
    if not sections:
        return None
    ordered = sorted(list(sections or []), key=lambda section: _section_station(section))
    for index in range(len(ordered) - 1):
        first = ordered[index]
        second = ordered[index + 1]
        first_station = _section_station(first)
        second_station = _section_station(second)
        if min(first_station, second_station) - 1.0e-9 <= float(station) <= max(first_station, second_station) + 1.0e-9:
            first_frame = getattr(first, "frame", None)
            second_frame = getattr(second, "frame", None)
            if first_frame is None:
                return second_frame
            if second_frame is None:
                return first_frame
            ratio = 0.0 if abs(second_station - first_station) <= 1.0e-9 else (float(station) - first_station) / (second_station - first_station)
            return replace(
                first_frame,
                station=float(station),
                x=_lerp_value(getattr(first_frame, "x", 0.0), getattr(second_frame, "x", 0.0), ratio),
                y=_lerp_value(getattr(first_frame, "y", 0.0), getattr(second_frame, "y", 0.0), ratio),
                z=_lerp_value(getattr(first_frame, "z", 0.0), getattr(second_frame, "z", 0.0), ratio),
                tangent_direction_deg=_lerp_value(
                    getattr(first_frame, "tangent_direction_deg", 0.0),
                    getattr(second_frame, "tangent_direction_deg", 0.0),
                    ratio,
                ),
            )
    nearest = min(ordered, key=lambda section: abs(_section_station(section) - float(station)))
    return getattr(nearest, "frame", None)


def _drainage_pipe_segment_radius(first_point, second_point) -> float:
    diameters = [
        float(getattr(point, "diameter", 0.0) or 0.0)
        for point in (first_point, second_point)
        if float(getattr(point, "diameter", 0.0) or 0.0) > 0.0
    ]
    if diameters:
        return max(0.08, min(sum(diameters) / len(diameters) * 0.5, 1.5))
    sizes = [
        max(float(getattr(point, "width", 0.0) or 0.0), float(getattr(point, "height", 0.0) or 0.0))
        for point in (first_point, second_point)
    ]
    size = max(sizes or [0.0])
    return max(0.12, min(float(size or 0.6) * 0.18, 1.0))


def _make_drainage_pipe_segment_shape(part_module, app_module, first: tuple[float, float, float], second: tuple[float, float, float], radius: float):
    start = app_module.Vector(*first)
    end = app_module.Vector(*second)
    vector = end.sub(start)
    length = float(getattr(vector, "Length", 0.0) or 0.0)
    if length <= 1.0e-6:
        return part_module.makeSphere(float(radius or 0.2), start)
    return part_module.makeCylinder(float(radius or 0.2), length, start, vector)


def _drainage_flow_highlight_points(sections: list[object], station_start: float, station_end: float) -> list[tuple[float, float, float]]:
    stations = [float(station_start)]
    for section in list(sections or []):
        station = _section_station(section)
        if min(station_start, station_end) < station < max(station_start, station_end):
            stations.append(station)
    stations.append(float(station_end))
    points = [
        point
        for point in (_drainage_flow_station_point(sections, station) for station in stations)
        if point is not None
    ]
    output: list[tuple[float, float, float]] = []
    for point in points:
        if not output or point != output[-1]:
            output.append(point)
    return output


def _drainage_flow_station_point(sections: list[object], station: float, *, z_offset: float = 1.05) -> tuple[float, float, float] | None:
    return _surface_transition_span_marker_point(sections, float(station), z_offset=z_offset)


def _create_drainage_review_marker(*, document=None, row: dict[str, object] | None = None, object_name: str = ""):
    if document is None or row is None:
        return None
    try:
        point = (
            float(row.get("x", 0.0) or 0.0),
            float(row.get("y", 0.0) or 0.0),
            float(row.get("z", 0.0) or 0.0),
        )
    except Exception:
        point = (0.0, 0.0, 0.0)
    name = object_name or str(row.get("marker_object", "") or "ReviewIssueDrainageStation001")
    status = str(row.get("status", "") or "")
    color = {
        "ready": (0.05, 0.65, 1.00),
        "warn": (1.00, 0.72, 0.10),
        "missing": (1.00, 0.16, 0.12),
    }.get(status, (0.05, 0.65, 1.00))
    ditch_points = _drainage_review_row_ditch_points(document, row)
    if ditch_points:
        obj = _create_drainage_review_highlight_compound(
            document=document,
            object_name=name,
            label=f"Drainage Highlight - STA {float(row.get('station', 0.0) or 0.0):.3f}" if row.get("station", "") != "" else "Drainage Highlight",
            ditch_points=ditch_points,
            color=color,
        )
    else:
        is_suggested_inlet = str(row.get("marker_kind", "") or "") == "suggested_inlet"
        marker_label = str(row.get("marker_label", "") or "").strip()
        obj = _create_drainage_review_point_marker(
            document=document,
            object_name=name,
            label=marker_label or (f"Drainage Diagnostic - STA {float(row.get('station', 0.0) or 0.0):.3f}" if row.get("station", "") != "" else "Drainage Diagnostic"),
            point=point,
            color=color,
            suggested_inlet=is_suggested_inlet,
        )
    if obj is None:
        return None
    issue_kind = "intersection_suggested_inlet" if str(row.get("marker_kind", "") or "") == "suggested_inlet" else "drainage_diagnostic"
    _set_preview_property(obj, "IssueKind", issue_kind)
    _set_preview_property(obj, "IssueStation", "" if row.get("station", "") == "" else f"{float(row.get('station', 0.0) or 0.0):.3f}")
    _set_preview_property(obj, "IssueStatus", status)
    _set_preview_property(obj, "IssueReason", str(row.get("notes", "") or ""))
    if issue_kind == "intersection_suggested_inlet":
        _set_preview_property(obj, "SuggestedInletReviewOnly", "Yes")
        _set_preview_property(obj, "IntersectionId", str(row.get("intersection_id", "") or ""))
        _set_preview_property(obj, "ControlRegionRefs", str(row.get("control_region_refs", "") or ""))
        _set_preview_float_property(obj, "SuggestedInletX", point[0])
        _set_preview_float_property(obj, "SuggestedInletY", point[1])
        _set_preview_float_property(obj, "SuggestedInletZ", point[2])
    try:
        from freecad.Corridor_Road.objects.obj_project import route_to_v1_tree

        route_to_v1_tree(find_project(document), obj)
    except Exception:
        pass
    return obj


def _drainage_review_row_ditch_points(document, row: dict[str, object]) -> list[object]:
    applied = to_applied_section_set(find_v1_applied_section_set(document))
    if applied is None:
        return []
    section_id = str(row.get("section_id", "") or "")
    sections = {
        str(getattr(section, "applied_section_id", "") or ""): section
        for section in list(getattr(applied, "sections", []) or [])
    }
    section = sections.get(section_id)
    if section is None:
        return []
    return [
        point
        for point in list(getattr(section, "point_rows", []) or [])
        if str(getattr(point, "point_role", "") or "") == "ditch_surface"
    ]


def _create_drainage_review_highlight_compound(
    *,
    document,
    object_name: str,
    label: str,
    ditch_points: list[object],
    color: tuple[float, float, float],
):
    try:
        import Part
        import FreeCAD as AppModule
    except Exception:
        return None
    obj = document.getObject(object_name)
    shapes = []
    for side in ("L", "R", ""):
        points = [
            point
            for point in list(ditch_points or [])
            if _drainage_point_side(point) == side
        ]
        points.sort(key=lambda point: float(getattr(point, "lateral_offset", 0.0) or 0.0))
        if len(points) >= 2:
            vectors = [
                AppModule.Vector(
                    float(getattr(point, "x", 0.0) or 0.0),
                    float(getattr(point, "y", 0.0) or 0.0),
                    float(getattr(point, "z", 0.0) or 0.0),
                )
                for point in points
            ]
            for start, end in zip(vectors[:-1], vectors[1:]):
                shapes.append(Part.makeLine(start, end))
        elif len(points) == 1:
            shapes.extend(_drainage_point_cross_shapes(Part, AppModule, points[0], radius=0.25))
    if not shapes:
        return None
    if obj is None:
        obj = document.addObject("Part::Feature", object_name)
    try:
        obj.Shape = Part.makeCompound(shapes)
        obj.Label = label
    except Exception:
        return obj
    _set_preview_property(obj, "CRRecordKind", "v1_review_issue")
    _set_preview_property(obj, "V1ObjectType", "ReviewIssue")
    _set_preview_property(obj, "IssueKind", "drainage_diagnostic")
    _set_preview_property(obj, "DisplayMode", "drainage_highlight")
    _set_preview_integer_property(obj, "MarkerCount", len(list(ditch_points or [])))
    try:
        vobj = getattr(obj, "ViewObject", None)
        if vobj is not None:
            vobj.Visibility = True
            vobj.ShapeColor = color
            vobj.PointColor = color
            vobj.LineColor = color
            vobj.LineWidth = 8.0
            vobj.PointSize = 8.0
            vobj.Transparency = 0
    except Exception:
        pass
    return obj


def _create_drainage_review_point_marker(
    *,
    document,
    object_name: str,
    label: str,
    point: tuple[float, float, float],
    color: tuple[float, float, float],
    suggested_inlet: bool = False,
):
    try:
        import Part
        import FreeCAD as AppModule
    except Exception:
        return None
    obj = document.getObject(object_name)
    if suggested_inlet:
        shapes = _point_sphere_marker_shapes(Part, AppModule, point, radius=0.45)
    else:
        shapes = _point_cross_shapes(Part, AppModule, point, radius=0.35)
    if not shapes:
        return None
    if obj is None:
        obj = document.addObject("Part::Feature", object_name)
    try:
        obj.Shape = Part.makeCompound(shapes)
        obj.Label = label
    except Exception:
        return obj
    _set_preview_property(obj, "CRRecordKind", "v1_review_issue")
    _set_preview_property(obj, "V1ObjectType", "ReviewIssue")
    _set_preview_property(obj, "IssueKind", "intersection_suggested_inlet" if suggested_inlet else "drainage_diagnostic")
    _set_preview_property(obj, "DisplayMode", "suggested_inlet_marker" if suggested_inlet else "drainage_point_marker")
    _set_preview_integer_property(obj, "MarkerCount", 1)
    try:
        vobj = getattr(obj, "ViewObject", None)
        if vobj is not None:
            vobj.Visibility = True
            vobj.ShapeColor = color
            vobj.PointColor = color
            vobj.LineColor = color
            vobj.LineWidth = 5.0
            vobj.PointSize = 7.0
            vobj.Transparency = 5 if suggested_inlet else 0
    except Exception:
        pass
    return obj


def _point_sphere_marker_shapes(Part, AppModule, point: tuple[float, float, float], *, radius: float) -> list[object]:
    x, y, z = point
    r = max(float(radius or 0.0), 0.05)
    center = AppModule.Vector(float(x), float(y), float(z) + r)
    shapes = []
    try:
        shapes.append(Part.makeSphere(r, center))
    except Exception:
        pass
    try:
        base = AppModule.Vector(float(x), float(y), float(z))
        top = AppModule.Vector(float(x), float(y), float(z) + (r * 1.8))
        shapes.append(Part.makeLine(base, top))
    except Exception:
        pass
    if not shapes:
        return _point_cross_shapes(Part, AppModule, point, radius=r)
    return shapes


def _drainage_point_cross_shapes(Part, AppModule, point, *, radius: float) -> list[object]:
    return _point_cross_shapes(
        Part,
        AppModule,
        (
            float(getattr(point, "x", 0.0) or 0.0),
            float(getattr(point, "y", 0.0) or 0.0),
            float(getattr(point, "z", 0.0) or 0.0),
        ),
        radius=radius,
    )


def _point_cross_shapes(Part, AppModule, point: tuple[float, float, float], *, radius: float) -> list[object]:
    x, y, z = point
    r = max(float(radius or 0.0), 0.05)
    center = AppModule.Vector(float(x), float(y), float(z))
    vectors = [
        (AppModule.Vector(float(x) - r, float(y), float(z)), AppModule.Vector(float(x) + r, float(y), float(z))),
        (AppModule.Vector(float(x), float(y) - r, float(z)), AppModule.Vector(float(x), float(y) + r, float(z))),
        (AppModule.Vector(float(x), float(y), float(z) - r), AppModule.Vector(float(x), float(y), float(z) + r)),
    ]
    shapes = []
    for start, end in vectors:
        try:
            shapes.append(Part.makeLine(start, end))
        except Exception:
            pass
    if not shapes:
        try:
            shapes.append(Part.Vertex(center))
        except Exception:
            pass
    return shapes


def _with_applied_section_review_summary(row: dict[str, object], summary: dict[str, object]) -> dict[str, object]:
    output = dict(row or {})
    output["applied_section_summary"] = str(summary.get("summary", "") or "")
    output["applied_section_diagnostics"] = str(summary.get("diagnostics", "") or "")
    output["applied_section_status"] = str(summary.get("status", "") or "")
    return output


def _surface_id(surface_model, surface_kind: str) -> str:
    for row in list(getattr(surface_model, "surface_rows", []) or []):
        if str(getattr(row, "surface_kind", "") or "") == surface_kind:
            return str(getattr(row, "surface_id", "") or "")
    return ""


def _roundabout_ownership_boundary_spec(document=None) -> dict[str, object] | None:
    """Return the source-policy roundabout ownership circle for guardrail diagnostics."""

    model = to_intersection_model(find_v1_intersection_model(document))
    if model is None:
        return None
    intersection_row = None
    for row in list(getattr(model, "intersection_rows", []) or []):
        if str(getattr(row, "intersection_kind", "") or "").strip().lower() == "roundabout":
            intersection_row = row
            break
    if intersection_row is None:
        return None
    intersection_id = str(getattr(intersection_row, "intersection_id", "") or "")
    center_x = float(getattr(intersection_row, "intersection_point_x", 0.0) or 0.0)
    center_y = float(getattr(intersection_row, "intersection_point_y", 0.0) or 0.0)
    center_z = float(getattr(intersection_row, "intersection_point_z", 0.0) or 0.0)
    for anchor in list(getattr(model, "anchor_rows", []) or []):
        if intersection_id and str(getattr(anchor, "intersection_id", "") or "") != intersection_id:
            continue
        center_x = float(getattr(anchor, "point_x", center_x) or center_x)
        center_y = float(getattr(anchor, "point_y", center_y) or center_y)
        center_z = float(getattr(anchor, "point_z", center_z) or center_z)
        break

    outer_radius = 0.0
    apron_width = 0.0
    connector_length = 0.0
    for policy in list(getattr(model, "edge_policy_rows", []) or []):
        if intersection_id and str(getattr(policy, "intersection_id", "") or "") != intersection_id:
            continue
        if str(getattr(policy, "edge_family_intent", "") or "").strip().lower() != "roundabout":
            continue
        rule = str(getattr(policy, "offset_rule", "") or "")
        value = float(getattr(policy, "offset_value", 0.0) or 0.0)
        if rule == "roundabout_circulatory_outer_radius":
            outer_radius = max(outer_radius, value)
        elif rule == "roundabout_outer_apron_width":
            apron_width = max(apron_width, value)
        elif rule == "roundabout_approach_connector_length":
            connector_length = max(connector_length, value)
    if outer_radius <= 0.0:
        for policy in list(getattr(model, "curb_return_policy_rows", []) or []):
            if intersection_id and str(getattr(policy, "intersection_id", "") or "") != intersection_id:
                continue
            outer_radius = max(outer_radius, float(getattr(policy, "radius", 0.0) or 0.0))
    if outer_radius <= 0.0:
        return None
    ownership_radius = max(outer_radius + apron_width, outer_radius)
    return {
        "intersection_id": intersection_id,
        "center": (center_x, center_y, center_z),
        "outer_radius": outer_radius,
        "apron_width": apron_width,
        "connector_length": connector_length,
        "ownership_radius": ownership_radius,
        "source": "intersection_roundabout_source_policy",
    }


def _roundabout_ownership_intrusion_summary(tin_surface: TINSurface | None, document=None) -> dict[str, object]:
    spec = _roundabout_ownership_boundary_spec(document)
    if tin_surface is None or spec is None:
        return {
            "status": "not_applicable",
            "tested": 0,
            "intrusion_count": 0,
            "intrusion_refs": [],
            "spec": spec,
        }
    center_x, center_y, _center_z = tuple(spec.get("center", (0.0, 0.0, 0.0)))
    radius = float(spec.get("ownership_radius", 0.0) or 0.0)
    vertex_map = tin_surface.vertex_map()
    tested = 0
    intrusion_refs: list[str] = []
    for triangle in list(getattr(tin_surface, "triangle_rows", []) or []):
        vertices = [vertex_map.get(str(ref or "")) for ref in (triangle.v1, triangle.v2, triangle.v3)]
        if any(vertex is None for vertex in vertices):
            continue
        tested += 1
        centroid_x = sum(float(getattr(vertex, "x", 0.0) or 0.0) for vertex in vertices if vertex is not None) / 3.0
        centroid_y = sum(float(getattr(vertex, "y", 0.0) or 0.0) for vertex in vertices if vertex is not None) / 3.0
        distance = math.hypot(centroid_x - center_x, centroid_y - center_y)
        if distance <= radius + 1.0e-6:
            intrusion_refs.append(str(getattr(triangle, "triangle_id", "") or ""))
    return {
        "status": "warning" if intrusion_refs else "ready",
        "tested": tested,
        "intrusion_count": len(intrusion_refs),
        "intrusion_refs": intrusion_refs,
        "spec": spec,
    }


def _roundabout_ownership_quality_value(tin_surface: TINSurface | None, kind: str, default=0):
    if tin_surface is None:
        return default
    target = str(kind or "")
    for row in list(getattr(tin_surface, "quality_rows", []) or []):
        if str(getattr(row, "kind", "") or "") == target:
            return getattr(row, "value", default)
    return default


def _roundabout_boundary_loop_result_for_clipping(document=None, *, applied_section_set=None) -> IntersectionBoundaryLoopResult | None:
    model = to_intersection_model(find_v1_intersection_model(document))
    if model is None:
        return None
    try:
        service = IntersectionEvaluationService()
        topology = service.evaluate_topology(model)
        if str(getattr(topology, "intersection_kind", "") or "").strip().lower() != "roundabout":
            return None
        edge_network = service.evaluate_edge_network(model, topology)
        surface_zones = service.evaluate_surface_zones(model, edge_network)
        slope_loops = None
        if applied_section_set is not None:
            try:
                slope_loops = service.evaluate_slope_face_loops(
                    model,
                    surface_zones,
                    edge_network,
                    applied_section_set,
                )
            except Exception:
                slope_loops = None
        return service.evaluate_boundary_loops(
            model,
            surface_zone_result=surface_zones,
            edge_network_result=edge_network,
            slope_face_loop_result=slope_loops,
            applied_section_set=applied_section_set,
            intersection_id=str(getattr(topology, "intersection_id", "") or ""),
        )
    except Exception:
        return None


def _roundabout_clip_boundary_role_for_surface(surface_role: str) -> str:
    text = str(surface_role or "").strip().lower()
    if text == "subgrade_surface":
        return "roundabout_subgrade_clip_boundary"
    if text in {"slope_face_surface", "daylight_surface", "daylight"}:
        return "roundabout_slope_handoff_boundary"
    return "roundabout_approach_clip_boundary"


def _roundabout_actual_clip_boundary_roles_for_surface(surface_role: str) -> set[str]:
    """Return accepted source boundary roles that may remove ordinary corridor geometry."""

    text = str(surface_role or "").strip().lower()
    if text in {"design_surface", "subgrade_surface", "slope_face_surface", "daylight_surface", "daylight"}:
        return {"roundabout_outer_ownership_boundary"}
    return {"roundabout_outer_ownership_boundary"}


def _roundabout_clip_boundary_contract_summary(
    document=None,
    *,
    applied_section_set=None,
    surface_role: str,
) -> dict[str, object]:
    boundary_result = _roundabout_boundary_loop_result_for_clipping(
        document,
        applied_section_set=applied_section_set,
    )
    boundary_role = _roundabout_clip_boundary_role_for_surface(surface_role)
    if boundary_result is None:
        return {
            "status": "missing",
            "boundary_role": boundary_role,
            "surface_role": str(surface_role or ""),
            "boundary_result_id": "",
            "loop_count": 0,
            "segment_count": 0,
            "loop_refs": [],
            "segment_refs": [],
            "diagnostics": ["roundabout_clip_missing_boundary"],
        }
    loops = [
        row
        for row in list(getattr(boundary_result, "loop_rows", []) or [])
        if str(getattr(row, "loop_role", "") or "") == boundary_role
        and str(getattr(row, "status", "") or "") == "ready"
        and bool(getattr(row, "closed", False))
    ]
    loop_bboxes = [
        ",".join(f"{float(value):.3f}" for value in tuple(getattr(row, "bbox_xy", ()) or ()))
        for row in loops
        if tuple(getattr(row, "bbox_xy", ()) or ())
    ]
    loop_areas = [
        f"{float(getattr(row, 'area_xy', 0.0) or 0.0):.3f}"
        for row in loops
    ]
    approach_refs = _unique_text_values(
        [
            str(ref or "")
            for row in loops
            for ref in tuple(getattr(row, "source_refs", ()) or ())
            if str(ref or "").startswith("intersection-roundabout-approach-leg:")
        ]
    )
    approach_roles = _roundabout_approach_roles_from_refs(approach_refs)
    segment_refs = [
        str(segment_ref or "")
        for row in loops
        for segment_ref in list(getattr(row, "segment_refs", ()) or ())
        if str(segment_ref or "")
    ]
    diagnostics = []
    if not loops:
        diagnostics.append(f"roundabout_clip_boundary_role_missing:{boundary_role}")
    diagnostic_key = {
        "roundabout_approach_clip_boundary": "roundabout_design_clip_ready",
        "roundabout_subgrade_clip_boundary": "roundabout_subgrade_clip_ready",
        "roundabout_slope_handoff_boundary": "roundabout_slope_clip_ready",
    }.get(boundary_role, "roundabout_clip_ready")
    return {
        "status": "ready" if loops else "warning",
        "diagnostic_key": diagnostic_key,
        "boundary_role": boundary_role,
        "surface_role": str(surface_role or ""),
        "boundary_result_id": str(getattr(boundary_result, "boundary_loop_result_id", "") or ""),
        "loop_count": len(loops),
        "segment_count": len(segment_refs),
        "loop_refs": [str(getattr(row, "loop_id", "") or "") for row in loops],
        "loop_bboxes": loop_bboxes,
        "loop_areas": loop_areas,
        "segment_refs": segment_refs,
        "approach_leg_count": len(approach_roles),
        "approach_leg_roles": approach_roles,
        "approach_leg_source": "roundabout_approach_leg_contract" if approach_roles else "",
        "diagnostics": diagnostics,
    }


def _roundabout_clip_boundary_polygons(
    document=None,
    *,
    applied_section_set=None,
    surface_role: str,
) -> list[list[tuple[float, float]]]:
    boundary_result = _roundabout_boundary_loop_result_for_clipping(
        document,
        applied_section_set=applied_section_set,
    )
    if boundary_result is None:
        return []
    accepted_roles = _roundabout_actual_clip_boundary_roles_for_surface(surface_role)
    polygons: list[list[tuple[float, float]]] = []
    for row in list(getattr(boundary_result, "loop_rows", []) or []):
        if str(getattr(row, "loop_role", "") or "") not in accepted_roles:
            continue
        if str(getattr(row, "status", "") or "") != "ready" or not bool(getattr(row, "closed", False)):
            continue
        points_xyz = list(getattr(row, "loop_points_xyz", ()) or ())
        if len(points_xyz) >= 2 and _intersection_slope_face_points_close_xy(points_xyz[0], points_xyz[-1]):
            points_xyz = points_xyz[:-1]
        polygon = [(float(point[0]), float(point[1])) for point in points_xyz if len(point) >= 2]
        if len(polygon) < 3 or abs(_xy_polygon_area(polygon)) <= 1.0e-6:
            continue
        polygons.append(polygon)
    return polygons


def _clip_tin_surface_by_roundabout_ownership(
    tin_surface: TINSurface | None,
    document=None,
    *,
    applied_section_set=None,
    surface_role: str,
) -> TINSurface | None:
    """Resolve source context and invoke the typed roundabout TIN clip service."""

    boundary_loop_result = _roundabout_boundary_loop_result_for_clipping(
        document,
        applied_section_set=applied_section_set,
    )
    return clip_tin_surface_by_roundabout_ownership(
        tin_surface,
        ownership_spec=_roundabout_ownership_boundary_spec(document),
        boundary_loop_result=boundary_loop_result,
        boundary_summary=_roundabout_clip_boundary_contract_summary(
            boundary_loop_result,
            surface_role=surface_role,
        ),
        boundary_clip_polygons=_roundabout_clip_boundary_polygons(
            boundary_loop_result,
            surface_role=surface_role,
        ),
        surface_role=surface_role,
    )


