def _build_intersection_tie_slope_surface(
    tie_slope_result: IntersectionTieSlopeResult,
    *,
    window_rows: list[dict[str, object]] | None = None,
    project_id: str = "",
    shared_breakline_result=None,
) -> TINSurface:
    """Build visible TIN triangles from source-owned Intersection Tie Slope loops."""

    intersection_id = str(getattr(tie_slope_result, "intersection_id", "") or "main")
    surface_id = f"intersection-tie-slope:{_safe_id_fragment(intersection_id)}"
    vertices: list[TINVertex] = []
    triangles: list[TINTriangle] = []
    boundary_refs: list[str] = []
    diagnostics: list[str] = []
    consumed_rows = 0
    rejected_rows = 0
    suppressed_rows = 0
    suppressed_refs: list[str] = []
    geometry_source = "intersection_tie_slope_result_rows"
    window_row_list = list(window_rows or [])
    if window_row_list:
        geometry_source = "accepted_applied_section_window_rows"
        for row_index, row in enumerate(window_row_list, start=1):
            row_id = (
                f"intersection-tie-slope-window:"
                f"{_safe_id_fragment(str(row.get('intersection_id', '') or intersection_id))}:"
                f"{_safe_id_fragment(str(row.get('alignment_ref', '') or 'alignment'))}:"
                f"{_safe_id_fragment(str(row.get('gap_role', '') or 'gap'))}:"
                f"{_safe_id_fragment(str(row.get('side', '') or 'side'))}:"
                f"{_safe_id_fragment(str(row.get('cell_role', '') or 'cell'))}:"
                f"{row_index}"
            )
            if not _intersection_tie_slope_window_surface_row_enabled(row):
                suppressed_rows += 1
                suppressed_refs.append(row_id)
                ownership_class = str(row.get("ownership_class", "") or "unowned_gap")
                diagnostics.append(f"intersection_tie_slope_window_suppressed_by_ownership:{ownership_class}:{row_id}")
                continue
            row_blocking_diagnostics = [
                str(value or "")
                for value in tuple(row.get("diagnostics", ()) or ())
                if _intersection_tie_slope_window_diagnostic_blocks_surface(value)
            ]
            if str(row.get("status", "") or "") != "accepted" or row_blocking_diagnostics:
                rejected_rows += 1
                diagnostics.append(f"intersection_tie_slope_window_row_not_accepted:{row_id}")
                continue
            loop_points = [_xyz_tuple(point) for point in tuple(row.get("loop_points_xyz", ()) or ())]
            if len(loop_points) >= 2 and _intersection_slope_face_points_close_xy(loop_points[0], loop_points[-1]):
                loop_points = loop_points[:-1]
            loop_points = _intersection_tie_slope_oriented_ring_points(loop_points)
            if len(loop_points) < 4:
                rejected_rows += 1
                diagnostics.append(f"intersection_tie_slope_window_loop_points_too_few:{row_id}")
                continue
            area = abs(_xy_polygon_area([(float(point[0]), float(point[1])) for point in loop_points]))
            if area <= 1.0e-6:
                rejected_rows += 1
                diagnostics.append(f"intersection_tie_slope_window_loop_zero_area:{row_id}")
                continue
            base_vertex_index = len(vertices) + 1
            vertex_ids: list[str] = []
            for point_index, point in enumerate(loop_points, start=1):
                vertex_id = f"{surface_id}:v{base_vertex_index + point_index - 1}"
                vertex_ids.append(vertex_id)
                vertices.append(
                    TINVertex(
                        vertex_id=vertex_id,
                        x=float(point[0]),
                        y=float(point[1]),
                        z=float(point[2]),
                        source_point_ref=f"{row_id}:p{point_index}",
                        notes="Intersection Tie Slope Applied Section window vertex.",
                    )
                )
            for tri_index in range(1, len(vertex_ids) - 1):
                triangles.append(
                    TINTriangle(
                        triangle_id=f"{surface_id}:tri:{len(triangles) + 1}",
                        v1=vertex_ids[0],
                        v2=vertex_ids[tri_index],
                        v3=vertex_ids[tri_index + 1],
                        triangle_kind="intersection_tie_slope_window",
                        quality_ref=row_id,
                        notes=f"Intersection Tie Slope triangle from Applied Section window row {row_id}.",
                    )
                )
            consumed_rows += 1
            window_breakline_roles = _intersection_tie_slope_window_breakline_roles_for_row(row)
            boundary_refs.extend(
                [
                    row_id,
                    str(row.get("outer_applied_section_ref", "") or ""),
                    str(row.get("inner_applied_section_ref", "") or ""),
                    *[f"{row_id}:{role.replace('_', '-')}" for role in window_breakline_roles],
                ]
            )
        if window_row_list:
            shared_breakline_refs = [
                value for value in _unique_text_values(boundary_refs)
                if "intersection-tie-slope-window-" in str(value or "")
                or "intersection-tie-slope-approach-" in str(value or "")
                or "intersection-tie-slope-to-curb-return-approach" in str(value or "")
                or "intersection-tie-slope-supplemental-" in str(value or "")
                ]
        quality_rows = [
            TINQualityRow(f"{surface_id}:intersection_tie_slope_row_count", "intersection_tie_slope_row_count", int(getattr(tie_slope_result, "tie_slope_count", 0) or 0), "count"),
            TINQualityRow(f"{surface_id}:intersection_tie_slope_window_row_count", "intersection_tie_slope_window_row_count", len(window_row_list), "count"),
            TINQualityRow(
                f"{surface_id}:intersection_tie_slope_window_supplemental_endpoint_count",
                "intersection_tie_slope_window_supplemental_endpoint_count",
                sum(
                    1 for row in window_row_list
                    if str(row.get("supplemental_extent_role", "") or "") == "supplemental_endpoint_pair"
                    and str(row.get("status", "") or "") == "accepted"
                ),
                "count",
            ),
            TINQualityRow(
                f"{surface_id}:intersection_tie_slope_window_supplemental_inner_count",
                "intersection_tie_slope_window_supplemental_inner_count",
                sum(1 for row in window_row_list if bool(row.get("inner_is_supplemental", False))),
                "count",
            ),
            TINQualityRow(
                f"{surface_id}:intersection_tie_slope_window_accepted_count",
                "intersection_tie_slope_window_accepted_count",
                sum(1 for row in window_row_list if str(row.get("status", "") or "") == "accepted"),
                "count",
            ),
            TINQualityRow(
                f"{surface_id}:intersection_tie_slope_window_suppressed_count",
                "intersection_tie_slope_window_suppressed_count",
                suppressed_rows,
                "count",
            ),
            TINQualityRow(
                f"{surface_id}:intersection_tie_slope_window_suppressed_refs",
                "intersection_tie_slope_window_suppressed_refs",
                ",".join(_unique_text_values(suppressed_refs)),
            ),
            TINQualityRow(
                f"{surface_id}:intersection_tie_slope_window_ownership_summary",
                "intersection_tie_slope_window_ownership_summary",
                _intersection_tie_slope_window_ownership_summary(window_row_list),
            ),
            TINQualityRow(
                f"{surface_id}:intersection_tie_slope_window_supplemental_endpoint_by_road",
                "intersection_tie_slope_window_supplemental_endpoint_by_road",
                _intersection_tie_slope_window_endpoint_summary_by_road(window_row_list),
            ),
            TINQualityRow(f"{surface_id}:intersection_tie_slope_consumed_row_count", "intersection_tie_slope_consumed_row_count", consumed_rows, "count"),
            TINQualityRow(f"{surface_id}:intersection_tie_slope_rejected_row_count", "intersection_tie_slope_rejected_row_count", rejected_rows, "count"),
            TINQualityRow(f"{surface_id}:intersection_tie_slope_triangle_count", "intersection_tie_slope_triangle_count", len(triangles), "count"),
            TINQualityRow(f"{surface_id}:intersection_tie_slope_shared_breakline_count", "intersection_tie_slope_shared_breakline_count", len(shared_breakline_refs), "count"),
            TINQualityRow(f"{surface_id}:intersection_tie_slope_shared_breakline_refs", "intersection_tie_slope_shared_breakline_refs", ",".join(shared_breakline_refs)),
            TINQualityRow(f"{surface_id}:intersection_tie_slope_geometry_source", "intersection_tie_slope_geometry_source", geometry_source),
            TINQualityRow(f"{surface_id}:intersection_tie_slope_diagnostics", "intersection_tie_slope_diagnostics", "; ".join(_unique_text_values(diagnostics))),
        ]
        surface = TINSurface(
            schema_version=int(getattr(tie_slope_result, "schema_version", 1) or 1),
            project_id=str(project_id or getattr(tie_slope_result, "project_id", "") or ""),
            surface_id=surface_id,
            surface_kind="intersection_tie_slope_surface",
            label=f"Intersection Tie Slope - intersection:{intersection_id}",
            vertex_rows=vertices,
            triangle_rows=triangles,
            boundary_refs=_unique_text_values(boundary_refs),
            quality_rows=quality_rows,
            source_refs=[str(getattr(tie_slope_result, "tie_slope_result_id", "") or ""), "applied_section_window_rows"],
        )
        if shared_breakline_result is not None:
            surface = _tin_surface_with_shared_breakline_metadata(
                surface,
                shared_breakline_result,
                consumer_ref="intersection_tie_slope",
            )
        return surface
    for row_index, row in enumerate(list(getattr(tie_slope_result, "tie_slope_rows", []) or []), start=1):
        row_id = str(getattr(row, "tie_slope_id", "") or f"tie-slope:{row_index}")
        if str(getattr(row, "status", "") or "") != "ready" or not bool(getattr(row, "closed_xy", False)):
            rejected_rows += 1
            diagnostics.append(f"intersection_tie_slope_row_not_ready:{row_id}")
            continue
        loop_points = [_xyz_tuple(point) for point in tuple(getattr(row, "loop_points_xyz", ()) or ())]
        if len(loop_points) >= 2 and _intersection_slope_face_points_close_xy(loop_points[0], loop_points[-1]):
            loop_points = loop_points[:-1]
        loop_points = _intersection_tie_slope_oriented_ring_points(loop_points)
        if len(loop_points) < 4:
            rejected_rows += 1
            diagnostics.append(f"intersection_tie_slope_loop_points_too_few:{row_id}")
            continue
        area = abs(_xy_polygon_area([(float(point[0]), float(point[1])) for point in loop_points]))
        if area <= 1.0e-6:
            rejected_rows += 1
            diagnostics.append(f"intersection_tie_slope_loop_zero_area:{row_id}")
            continue
        base_vertex_index = len(vertices) + 1
        vertex_ids: list[str] = []
        for point_index, point in enumerate(loop_points, start=1):
            vertex_id = f"{surface_id}:v{base_vertex_index + point_index - 1}"
            vertex_ids.append(vertex_id)
            vertices.append(
                TINVertex(
                    vertex_id=vertex_id,
                    x=float(point[0]),
                    y=float(point[1]),
                    z=float(point[2]),
                    source_point_ref=f"{row_id}:p{point_index}",
                    notes="Intersection Tie Slope loop vertex.",
                )
            )
        for tri_index in range(1, len(vertex_ids) - 1):
            tri_vertices = (vertex_ids[0], vertex_ids[tri_index], vertex_ids[tri_index + 1])
            triangles.append(
                TINTriangle(
                    triangle_id=f"{surface_id}:tri:{len(triangles) + 1}",
                    v1=tri_vertices[0],
                    v2=tri_vertices[1],
                    v3=tri_vertices[2],
                    triangle_kind="intersection_tie_slope",
                    quality_ref=row_id,
                    notes=f"Intersection Tie Slope triangle from {row_id}.",
                )
            )
        consumed_rows += 1
        boundary_refs.extend(
            [
                row_id,
                str(getattr(row, "inner_breakline_ref", "") or ""),
                str(getattr(row, "outer_breakline_ref", "") or ""),
                str(getattr(row, "start_cap_breakline_ref", "") or ""),
                str(getattr(row, "end_cap_breakline_ref", "") or ""),
            ]
        )
    shared_breakline_refs = [
        value for value in _unique_text_values(boundary_refs)
        if "intersection-tie-slope-" in str(value or "")
    ]
    quality_rows = [
        TINQualityRow(f"{surface_id}:intersection_tie_slope_row_count", "intersection_tie_slope_row_count", int(getattr(tie_slope_result, "tie_slope_count", 0) or 0), "count"),
        TINQualityRow(f"{surface_id}:intersection_tie_slope_consumed_row_count", "intersection_tie_slope_consumed_row_count", consumed_rows, "count"),
        TINQualityRow(f"{surface_id}:intersection_tie_slope_rejected_row_count", "intersection_tie_slope_rejected_row_count", rejected_rows, "count"),
        TINQualityRow(f"{surface_id}:intersection_tie_slope_triangle_count", "intersection_tie_slope_triangle_count", len(triangles), "count"),
        TINQualityRow(f"{surface_id}:intersection_tie_slope_shared_breakline_count", "intersection_tie_slope_shared_breakline_count", len(shared_breakline_refs), "count"),
        TINQualityRow(f"{surface_id}:intersection_tie_slope_shared_breakline_refs", "intersection_tie_slope_shared_breakline_refs", ",".join(shared_breakline_refs)),
        TINQualityRow(f"{surface_id}:intersection_tie_slope_geometry_source", "intersection_tie_slope_geometry_source", geometry_source),
        TINQualityRow(f"{surface_id}:intersection_tie_slope_diagnostics", "intersection_tie_slope_diagnostics", "; ".join(_unique_text_values(diagnostics))),
    ]
    surface = TINSurface(
        schema_version=int(getattr(tie_slope_result, "schema_version", 1) or 1),
        project_id=str(project_id or getattr(tie_slope_result, "project_id", "") or ""),
        surface_id=surface_id,
        surface_kind="intersection_tie_slope_surface",
        label=f"Intersection Tie Slope - intersection:{intersection_id}",
        vertex_rows=vertices,
        triangle_rows=triangles,
        boundary_refs=_unique_text_values(boundary_refs),
        quality_rows=quality_rows,
        source_refs=[str(getattr(tie_slope_result, "tie_slope_result_id", "") or "")],
    )
    if shared_breakline_result is not None:
        surface = _tin_surface_with_shared_breakline_metadata(
            surface,
            shared_breakline_result,
            consumer_ref="intersection_tie_slope",
        )
    return surface


def _intersection_tie_slope_unique_ring_points(
    points: list[tuple[float, float, float]],
) -> list[tuple[float, float, float]]:
    output: list[tuple[float, float, float]] = []
    for point in list(points or []):
        xyz = _xyz_tuple(point)
        if output and _intersection_slope_face_points_close_xy(output[-1], xyz):
            continue
        output.append(xyz)
    if len(output) >= 2 and _intersection_slope_face_points_close_xy(output[0], output[-1]):
        output = output[:-1]
    return output


def _intersection_tie_slope_oriented_ring_points(
    points: list[tuple[float, float, float]],
) -> list[tuple[float, float, float]]:
    """Return a de-duplicated tie-slope ring with consistent top-facing winding."""

    output = _intersection_tie_slope_unique_ring_points(points)
    if len(output) < 3:
        return output
    area = _xy_polygon_area([(float(point[0]), float(point[1])) for point in output])
    if area < 0.0:
        output = list(reversed(output))
    return output


def _build_intersection_slope_face_surface_from_ready_loops(
    loop_result: IntersectionSlopeFaceLoopResult,
    *,
    project_id: str,
    boundary_result: IntersectionSlopeFaceBoundaryResult | None = None,
    boundary_segment_result: IntersectionBoundarySegmentResult | None = None,
    applied_section_set=None,
    shared_breakline_result: SharedBreaklineResult | None = None,
):
    """Compatibility wrapper for the typed slope-face TIN builder."""

    return build_intersection_slope_face_surface_from_ready_loops(
        loop_result,
        project_id=project_id,
        boundary_result=boundary_result,
        boundary_segment_result=boundary_segment_result,
        applied_section_set=applied_section_set,
        shared_breakline_result=shared_breakline_result,
    )


def _intersection_slope_face_loop_surface_generation_ready(row) -> bool:
    if row is None:
        return False
    return (
        str(getattr(row, "status", "") or "") == "ready"
        and str(getattr(row, "surface_generation_role", "") or "") == "surface_candidate"
        and str(getattr(row, "surface_generation_status", "") or "") == "ready"
        and _intersection_slope_face_loop_has_dedicated_perimeter_source(row)
        and bool(getattr(row, "closed_xy", False))
        and not bool(getattr(row, "self_crossing", False))
        and len(_intersection_slope_face_loop_simple_ring_points(row)) >= 3
    )


def _attach_intersection_boundary_loop_transition_qa_metadata(obj) -> None:
    if obj is None:
        return
    coverage_status = str(getattr(obj, "IntersectionBoundaryLoopGraphCoverageStatus", "") or "")
    consumer_coverage_summary = str(getattr(obj, "IntersectionBoundaryLoopGraphConsumerCoverageSummary", "") or "")
    consumer_missing_summary = str(getattr(obj, "IntersectionBoundaryLoopGraphConsumerMissingSummary", "") or "")
    edge_count = int(getattr(obj, "IntersectionBoundaryLoopGraphEdgeCount", 0) or 0)
    consumer_edge_count = int(getattr(obj, "IntersectionBoundaryLoopGraphConsumerEdgeCount", 0) or 0)
    filled_edge_count = int(getattr(obj, "IntersectionBoundaryLoopGraphFilledEdgeCount", 0) or 0)
    missing_edge_count = int(getattr(obj, "IntersectionBoundaryLoopGraphMissingEdgeCount", 0) or 0)
    non_consumer_edge_count = int(getattr(obj, "IntersectionBoundaryLoopGraphNonConsumerEdgeCount", 0) or 0)
    transition_triangle_count = int(getattr(obj, "IntersectionBoundaryLoopTransitionTriangleCount", 0) or 0)
    transition_corner_count = int(getattr(obj, "IntersectionBoundaryLoopTransitionCornerFillCount", 0) or 0)
    transition_role_summary = str(getattr(obj, "IntersectionBoundaryLoopTransitionRoleSummary", "") or "")
    transition_width_summary = str(getattr(obj, "IntersectionBoundaryLoopTransitionWidthSummary", "") or "")
    transition_rows = list(getattr(obj, "IntersectionBoundaryLoopTransitionRows", []) or [])
    metadata_transition_count = sum(1 for row in transition_rows if "mode=metadata_only" in str(row or ""))
    diagnostics: list[str] = []
    if coverage_status != "ready":
        diagnostics.append(f"coverage={coverage_status or 'missing'}")
    if edge_count <= 0:
        diagnostics.append("boundary_loop_graph_edges_missing")
    if consumer_edge_count != edge_count:
        diagnostics.append(f"consumer_edges={consumer_edge_count}/{edge_count}")
    if filled_edge_count != edge_count:
        diagnostics.append(f"filled_edges={filled_edge_count}/{edge_count}")
    if missing_edge_count:
        diagnostics.append(f"missing_edges={missing_edge_count}")
    if non_consumer_edge_count:
        diagnostics.append(f"non_consumer_edges={non_consumer_edge_count}")
    if not transition_rows:
        diagnostics.append("transition_metadata_rows_missing")
    status = "ready" if not diagnostics else "warning"
    _set_preview_property(obj, "IntersectionBoundaryLoopTransitionQAStatus", status)
    _set_preview_property(
        obj,
        "IntersectionBoundaryLoopTransitionQANotes",
        (
            f"coverage={coverage_status or 'missing'}; edges={edge_count}; "
            f"consumers={consumer_edge_count}; filled={filled_edge_count}; "
            f"missing={missing_edge_count}; non_consumer={non_consumer_edge_count}; "
            f"transition_triangles={transition_triangle_count}; corner_fill={transition_corner_count}; "
            f"metadata_rows={metadata_transition_count}; "
            f"consumer_coverage={consumer_coverage_summary or 'none'}; "
            f"consumer_missing={consumer_missing_summary or 'none'}; "
            f"roles={transition_role_summary or 'none'}; widths={transition_width_summary or 'none'}; "
            f"diagnostics={';'.join(diagnostics) if diagnostics else 'none'}"
        ),
    )
    _set_preview_property(
        obj,
        "IntersectionBoundaryLoopTransitionRecommendedAction",
        (
            "Inspect dedicated slope-face cell and adjacent ordinary surface ownership if a visual gap remains."
            if status == "ready"
            else "Rebuild boundary loop shared graph and transition bands before judging visual surface gaps."
        ),
    )


_INTERSECTION_BOUNDARY_LOOP_AUDIT_CONSUMERS = (
    "intersection_surface",
    "design_surface",
    "intersection_slope_face_surface",
    "slope_face_surface",
    "intersection_tie_slope_surface",
)


def intersection_shared_boundary_graph_audit(
    graph_result: IntersectionSharedBoundaryGraphResult | None,
) -> dict[str, object]:
    """Compatibility wrapper for typed shared-boundary graph audit."""

    return _service_intersection_shared_boundary_graph_audit(graph_result)


def _intersection_shared_boundary_graph_audit_rows(graph_result: IntersectionSharedBoundaryGraphResult | None) -> list[str]:
    if graph_result is None:
        return []
    rows: list[str] = []
    graph_audit = intersection_shared_boundary_graph_audit(graph_result)
    for edge in list(getattr(graph_result, "edge_rows", []) or []):
        diagnostics = ",".join(str(value or "") for value in tuple(getattr(edge, "diagnostics", ()) or ()) if str(value or ""))
        consumers = ",".join(str(value or "") for value in tuple(getattr(edge, "consumer_refs", ()) or ()) if str(value or ""))
        source_refs = ",".join(str(value or "") for value in tuple(getattr(edge, "source_refs", ()) or ()) if str(value or ""))
        rows.append(
            "|".join(
                [
                    "edge",
                    _audit_field(str(getattr(edge, "edge_id", "") or "")),
                    _audit_field(str(getattr(edge, "edge_role", "") or "")),
                    _audit_field(str(getattr(edge, "from_node_ref", "") or "")),
                    _audit_field(str(getattr(edge, "to_node_ref", "") or "")),
                    _audit_field(consumers),
                    _audit_field(diagnostics),
                    _audit_field(source_refs),
                ]
            )
        )
    for cell in list(getattr(graph_result, "cell_rows", []) or []):
        diagnostics = ",".join(str(value or "") for value in tuple(getattr(cell, "diagnostics", ()) or ()) if str(value or ""))
        boundary_refs = ",".join(str(value or "") for value in tuple(getattr(cell, "boundary_edge_refs", ()) or ()) if str(value or ""))
        rows.append(
            "|".join(
                [
                    "cell",
                    _audit_field(str(getattr(cell, "cell_id", "") or "")),
                    _audit_field(str(getattr(cell, "cell_role", "") or "")),
                    "1" if bool(getattr(cell, "closed", False)) else "0",
                    _audit_field(str(getattr(cell, "owner_surface_ref", "") or "")),
                    _audit_field(boundary_refs),
                    _audit_field(diagnostics),
                    "",
                ]
            )
        )
    for diagnostic in list(graph_audit.get("diagnostic_rows", []) or []):
        rows.append("|".join(["graph", _audit_field(str(diagnostic or "")), "", "", "", "", ""]))
    return rows


def _audit_field(value: object) -> str:
    return str(value or "").replace("|", "/").replace(";;", ";").strip()


def _parse_intersection_slope_face_cell_audit_row(raw: object) -> dict[str, object] | None:
    parts = str(raw or "").split("|")
    if len(parts) < 8:
        return None
    try:
        open_count = int(parts[3] or 0)
    except Exception:
        open_count = 0
    try:
        missing_edge_count = int(parts[4] or 0)
    except Exception:
        missing_edge_count = 0
    try:
        point_count = int(parts[5] or 0)
    except Exception:
        point_count = 0
    return {
        "cell_id": parts[0],
        "cell_role": parts[1],
        "status": parts[2] or "missing",
        "open_count": open_count,
        "missing_edge_count": missing_edge_count,
        "point_count": point_count,
        "boundary_refs": parts[6],
        "diagnostics": parts[7],
    }


def _parse_intersection_shared_boundary_graph_audit_row(raw: object) -> dict[str, object] | None:
    parts = str(raw or "").split("|")
    if len(parts) < 7:
        return None
    row_kind = parts[0] or ""
    if row_kind == "edge":
        return {
            "row_kind": "edge",
            "row_id": parts[1],
            "role": parts[2],
            "from_node_ref": parts[3],
            "to_node_ref": parts[4],
            "refs": parts[5],
            "diagnostics": parts[6],
            "source_refs": parts[7] if len(parts) > 7 else "",
            "open_count": 0,
        }
    if row_kind == "cell":
        closed = str(parts[3] or "") == "1"
        return {
            "row_kind": "cell",
            "row_id": parts[1],
            "role": parts[2],
            "closed": closed,
            "owner_surface_ref": parts[4],
            "refs": parts[5],
            "diagnostics": parts[6],
            "source_refs": parts[7] if len(parts) > 7 else "",
            "open_count": 0 if closed else 1,
        }
    if row_kind == "graph":
        return {
            "row_kind": "graph",
            "row_id": parts[1],
            "role": "shared_boundary_graph",
            "refs": "",
            "diagnostics": parts[1],
            "source_refs": "",
            "open_count": 0,
        }
    return None


def _intersection_boundary_loop_source_refs(source_refs: str) -> list[str]:
    return [
        value.strip()
        for value in str(source_refs or "").split(",")
        if value.strip()
        and (
            "intersection-boundary-loop" in value.strip()
            or "intersection-boundary-loops" in value.strip()
        )
    ]


def _intersection_boundary_owner_source_refs(source_refs: str) -> list[str]:
    return [
        value.strip()
        for value in str(source_refs or "").split(",")
        if value.strip().startswith("intersection-boundary-owner:")
    ]


def _intersection_boundary_owner_consumer_summary(owner_refs: list[str], consumers: str) -> str:
    owners = [str(value or "").strip() for value in list(owner_refs or []) if str(value or "").strip()]
    consumer_refs = [
        str(value or "").strip()
        for value in str(consumers or "").split(",")
        if str(value or "").strip()
    ]
    if not owners or not consumer_refs:
        return ""
    consumer_text = "+".join(_unique_text_values(consumer_refs))
    return ",".join(f"{owner}->{consumer_text}" for owner in _unique_text_values(owners))


def _intersection_boundary_owner_missing_consumer_summary(owner_refs: list[str], role: str, consumers: str) -> str:
    owners = [str(value or "").strip() for value in list(owner_refs or []) if str(value or "").strip()]
    expected = INTERSECTION_SHARED_BOUNDARY_EXPECTED_CONSUMERS.get(str(role or ""), ())
    if not owners or not expected:
        return ""
    consumer_refs = {
        str(value or "").strip()
        for value in str(consumers or "").split(",")
        if str(value or "").strip()
    }
    missing = [str(value or "") for value in tuple(expected or ()) if str(value or "") and str(value or "") not in consumer_refs]
    if not missing:
        return ""
    missing_text = "+".join(_unique_text_values(missing))
    return ",".join(f"{owner}->{missing_text}" for owner in _unique_text_values(owners))


def _intersection_shared_boundary_graph_segment_rows(graph_result: IntersectionSharedBoundaryGraphResult | None) -> list[str]:
    if graph_result is None:
        return []
    node_by_id = {
        str(getattr(node, "node_id", "") or ""): node
        for node in list(getattr(graph_result, "node_rows", []) or [])
        if str(getattr(node, "node_id", "") or "")
    }
    rows: list[str] = []
    for edge in list(getattr(graph_result, "edge_rows", []) or []):
        from_ref = str(getattr(edge, "from_node_ref", "") or "")
        to_ref = str(getattr(edge, "to_node_ref", "") or "")
        from_node = node_by_id.get(from_ref)
        to_node = node_by_id.get(to_ref)
        if from_node is None or to_node is None:
            continue
        consumers = ",".join(str(value or "") for value in tuple(getattr(edge, "consumer_refs", ()) or ()) if str(value or ""))
        rows.append(
            "|".join(
                [
                    _audit_field(str(getattr(edge, "edge_id", "") or "")),
                    _audit_field(str(getattr(edge, "edge_role", "") or "")),
                    _audit_field(from_ref),
                    _audit_field(to_ref),
                    f"{float(getattr(from_node, 'x', 0.0) or 0.0):.9f}",
                    f"{float(getattr(from_node, 'y', 0.0) or 0.0):.9f}",
                    f"{float(getattr(from_node, 'z', 0.0) or 0.0):.9f}",
                    f"{float(getattr(to_node, 'x', 0.0) or 0.0):.9f}",
                    f"{float(getattr(to_node, 'y', 0.0) or 0.0):.9f}",
                    f"{float(getattr(to_node, 'z', 0.0) or 0.0):.9f}",
                    _audit_field(consumers),
                ]
            )
        )
    return rows


def _parse_intersection_shared_boundary_graph_segment_row(raw: object) -> dict[str, object] | None:
    parts = str(raw or "").split("|")
    if len(parts) < 11:
        return None
    try:
        return {
            "edge_id": parts[0],
            "edge_role": parts[1],
            "from_node_ref": parts[2],
            "to_node_ref": parts[3],
            "start": (float(parts[4]), float(parts[5]), float(parts[6])),
            "end": (float(parts[7]), float(parts[8]), float(parts[9])),
            "consumers": parts[10],
        }
    except Exception:
        return None


def _parse_intersection_exclusion_near_boundary_kept_triangle_row(raw: object) -> dict[str, object] | None:
    parts = str(raw or "").split("|")
    if len(parts) < 5:
        return None
    try:
        return {
            "triangle_id": parts[0],
            "centroid": (float(parts[1]), float(parts[2]), float(parts[3])),
            "distance": float(parts[4]),
        }
    except Exception:
        return None


def _intersection_slope_face_loop_has_dedicated_perimeter_source(row) -> bool:
    """Only generate dedicated surfaces from intersection-owned perimeter loops."""

    refs = [
        *[str(value or "") for value in tuple(getattr(row, "boundary_edge_refs", ()) or ())],
        *[str(value or "") for value in tuple(getattr(row, "source_edge_network_refs", ()) or ())],
    ]
    text = " ".join(refs).lower()
    if "curb-return-to-slope-face" in text or "curb_return_to_slope_face" in text:
        return True
    if "curb-return-outer" in text or "curb_return_outer" in text:
        return True
    if _intersection_slope_face_loop_has_applied_section_boundary_source(row):
        return True
    return False


def _intersection_slope_face_loop_has_applied_section_boundary_source(row) -> bool:
    """Allow Applied Section-completed intersection slope loops to become dedicated surface output."""

    boundary_refs = [
        str(value or "").lower()
        for value in tuple(getattr(row, "boundary_edge_refs", ()) or ())
        if str(value or "")
    ]
    if not any("applied-section-boundary" in ref or "applied_section_boundary" in ref for ref in boundary_refs):
        return False
    source_applied_refs = tuple(
        str(value or "")
        for value in tuple(getattr(row, "source_applied_section_refs", ()) or ())
        if str(value or "")
    )
    if not source_applied_refs:
        return False
    notes = str(getattr(row, "notes", "") or "").lower()
    return "applied_section_boundary_completion=used" in notes


def _intersection_slope_face_loop_simple_ring_points(row) -> list[tuple[float, float, float]]:
    if row is None:
        return []
    raw_points = list(getattr(row, "loop_points_xyz", ()) or ())
    points: list[tuple[float, float, float]] = []
    for point in raw_points:
        xyz = _preview_xyz_tuple(point)
        if points and _preview_same_xy(points[-1], xyz):
            continue
        points.append(xyz)
    if len(points) >= 2 and _preview_same_xy(points[0], points[-1]):
        points = points[:-1]
    if len(points) < 3:
        return []
    return points


def _intersection_slope_face_boundary_row_family(row) -> str:
    notes = str(getattr(row, "notes", "") or "")
    for part in notes.split(";"):
        text = part.strip()
        if text.startswith("boundary_family="):
            return text.split("=", 1)[1].strip()
    return ""


def _intersection_slope_face_visible_transition_boundary_ids(
    boundary_result: IntersectionSlopeFaceBoundaryResult | None,
    boundary_segment_result: IntersectionBoundarySegmentResult | None,
) -> set[str]:
    rows = [
        row
        for row in list(getattr(boundary_result, "boundary_rows", []) or [])
        if _intersection_slope_face_boundary_row_family(row) == "main_transition_strip"
    ]
    if not rows:
        return set()
    curb_points = _intersection_curb_return_reference_points(boundary_segment_result)
    if not curb_points:
        return {str(getattr(row, "boundary_id", "") or "") for row in rows}

    def score(row) -> float:
        points = [_preview_xyz_tuple(point) for point in list(getattr(row, "outer_points_xyz", ()) or ())]
        if not points:
            points = [_preview_xyz_tuple(point) for point in list(getattr(row, "inner_points_xyz", ()) or ())]
        if not points:
            return -1.0
        mid = (
            sum(point[0] for point in points) / len(points),
            sum(point[1] for point in points) / len(points),
        )
        return min(_xy_distance(mid, (point[0], point[1])) for point in curb_points)

    selected = max(rows, key=score)
    selected_id = str(getattr(selected, "boundary_id", "") or "")
    return {selected_id} if selected_id else set()


def _intersection_curb_return_reference_points(boundary_segment_result) -> list[tuple[float, float, float]]:
    points: list[tuple[float, float, float]] = []
    for row in list(getattr(boundary_segment_result, "segment_rows", []) or []):
        if str(getattr(row, "segment_role", "") or "") != "curb_return":
            continue
        for point in list(getattr(row, "chord_points_xyz", ()) or ()):
            try:
                if len(tuple(point or ())) >= 3:
                    points.append(_preview_xyz_tuple(point))
            except Exception:
                continue
    return points


def _intersection_slope_face_boundary_strip_suppressed_stats(
    boundary_result: IntersectionSlopeFaceBoundaryResult | None,
) -> dict[str, object]:
    """Report boundary rows without turning pavement tie-in rows into visible slope-face strips."""

    if boundary_result is None:
        return {
            "generation_mode": "missing_boundary_result",
            "strip_count": 0,
            "triangle_count": 0,
            "boundary_refs": [],
            "diagnostics": ["intersection_slope_face_boundary_result_missing"],
        }
    ready_rows = [
        row for row in list(getattr(boundary_result, "boundary_rows", []) or [])
        if str(getattr(row, "status", "") or "") == "ready"
    ]
    return {
        "generation_mode": "suppressed_pavement_tie_in_boundary",
        "strip_count": 0,
        "triangle_count": 0,
        "boundary_refs": [
            str(getattr(row, "boundary_id", "") or "") for row in ready_rows
            if str(getattr(row, "boundary_id", "") or "")
        ],
        "diagnostics": [
            "intersection_slope_face_boundary_strip_suppressed:pavement_tie_in_is_not_curb_return_outer_boundary"
        ],
    }


def _preview_xyz_tuple(value) -> tuple[float, float, float]:
    try:
        seq = tuple(value or ())
    except Exception:
        seq = ()
    x = float(seq[0]) if len(seq) > 0 else 0.0
    y = float(seq[1]) if len(seq) > 1 else 0.0
    z = float(seq[2]) if len(seq) > 2 else 0.0
    return (x, y, z)


def _preview_same_xy(a: tuple[float, float, float], b: tuple[float, float, float], tolerance: float = 1.0e-6) -> bool:
    return abs(float(a[0]) - float(b[0])) <= tolerance and abs(float(a[1]) - float(b[1])) <= tolerance


