def _tin_surface_triangle_kind_count(surface, triangle_kind: str) -> int:
    expected = str(triangle_kind or "")
    if not expected:
        return 0
    return sum(
        1
        for triangle in list(getattr(surface, "triangle_rows", []) or [])
        if str(getattr(triangle, "triangle_kind", "") or "") == expected
    )


