def _create_intersection_exclusion_near_boundary_highlight(
    *,
    document=None,
    source_obj=None,
    rows: list[dict[str, object]] | None = None,
):
    if document is None:
        return None
    try:
        import FreeCAD as AppModule
        import Part
    except Exception:
        return None
    shapes: list[object] = []
    row_refs: list[str] = []
    marker_size = 0.35
    z_lift = 0.12
    for row in list(rows or []):
        try:
            centroid = tuple(float(value) for value in row.get("centroid", ()))
            if len(centroid) != 3:
                continue
            x, y, z = centroid
            z += z_lift
            shapes.append(Part.makeLine(AppModule.Vector(x - marker_size, y, z), AppModule.Vector(x + marker_size, y, z)))
            shapes.append(Part.makeLine(AppModule.Vector(x, y - marker_size, z), AppModule.Vector(x, y + marker_size, z)))
            row_refs.append(str(row.get("triangle_id", "") or ""))
        except Exception:
            continue
    if not shapes:
        return None
    object_name = "ReviewIntersectionExclusionNearBoundaryKeptHighlight"
    obj = document.getObject(object_name)
    if obj is None:
        obj = document.addObject("Part::Feature", object_name)
    try:
        obj.Shape = Part.makeCompound(shapes) if len(shapes) > 1 else shapes[0]
        obj.Label = "Intersection Exclusion Near-Boundary Kept Highlight"
    except Exception:
        return obj
    _set_preview_property(obj, "CRRecordKind", "v1_intersection_exclusion_near_boundary_kept_highlight")
    _set_preview_property(obj, "V1ObjectType", "ReviewDiagnostic")
    _set_preview_property(obj, "DiagnosticKind", "intersection_exclusion_near_boundary_kept_highlight")
    _set_preview_property(obj, "SourceObject", str(getattr(source_obj, "Name", "") or ""))
    _set_preview_property(obj, "SourceObjectLabel", str(getattr(source_obj, "Label", "") or ""))
    _set_preview_integer_property(obj, "IntersectionExclusionNearBoundaryKeptTriangleCount", len(rows or []))
    _set_preview_string_list_property(
        obj,
        "IntersectionExclusionNearBoundaryKeptTriangleRows",
        list(getattr(source_obj, "IntersectionExclusionNearBoundaryKeptTriangleRows", []) or []),
    )
    _set_preview_string_list_property(obj, "IntersectionExclusionNearBoundaryKeptTriangleRefs", _unique_text_values(row_refs))
    try:
        vobj = getattr(obj, "ViewObject", None)
        if vobj is not None:
            vobj.Visibility = True
            vobj.ShapeColor = (1.0, 0.45, 0.05)
            vobj.LineColor = (1.0, 0.45, 0.05)
            vobj.PointColor = (1.0, 0.45, 0.05)
            vobj.LineWidth = 5.0
            vobj.PointSize = 6.0
    except Exception:
        pass
    try:
        document.recompute()
    except Exception:
        pass
    return obj


def _create_intersection_shared_boundary_graph_highlight(
    *,
    document=None,
    source_obj=None,
    rows: list[dict[str, object]] | None = None,
    edge_refs: list[str] | None = None,
    highlight_kind: str = "",
):
    if document is None:
        return None
    try:
        import FreeCAD as AppModule
        import Part
    except Exception:
        return None
    shapes: list[object] = []
    refs: list[str] = []
    z_lift = 0.055
    for row in list(rows or []):
        try:
            start = tuple(float(value) for value in row.get("start", ()))
            end = tuple(float(value) for value in row.get("end", ()))
            if len(start) != 3 or len(end) != 3:
                continue
            start_vec = AppModule.Vector(start[0], start[1], start[2] + z_lift)
            end_vec = AppModule.Vector(end[0], end[1], end[2] + z_lift)
            shapes.append(Part.makeLine(start_vec, end_vec))
            refs.append(str(row.get("edge_id", "") or ""))
        except Exception:
            continue
    if not shapes:
        return None
    kind = str(highlight_kind or "").strip()
    object_name = "ReviewIntersectionSharedBoundaryGraphInternalSeamHighlight" if kind == "internal_seam" else "ReviewIntersectionSharedBoundaryGraphHighlight"
    obj = document.getObject(object_name)
    if obj is None:
        obj = document.addObject("Part::Feature", object_name)
    try:
        obj.Shape = Part.makeCompound(shapes) if len(shapes) > 1 else shapes[0]
        obj.Label = "Intersection Shared Boundary Graph Internal Seam Highlight" if kind == "internal_seam" else "Intersection Shared Boundary Graph Highlight"
    except Exception:
        return obj
    _set_preview_property(obj, "CRRecordKind", "v1_intersection_shared_boundary_graph_highlight")
    _set_preview_property(obj, "V1ObjectType", "ReviewDiagnostic")
    _set_preview_property(obj, "DiagnosticKind", "intersection_shared_boundary_graph_internal_seam_highlight" if kind == "internal_seam" else "intersection_shared_boundary_graph_highlight")
    _set_preview_property(obj, "IntersectionSharedBoundaryGraphHighlightKind", kind or "boundary_graph")
    _set_preview_property(obj, "SourceObject", str(getattr(source_obj, "Name", "") or ""))
    _set_preview_property(obj, "SourceObjectLabel", str(getattr(source_obj, "Label", "") or ""))
    _set_preview_property(obj, "IntersectionSharedBoundaryGraphResultId", str(getattr(source_obj, "IntersectionSharedBoundaryGraphResultId", "") or ""))
    _set_preview_string_list_property(obj, "IntersectionSharedBoundaryGraphRefs", _unique_text_values(refs or list(edge_refs or [])))
    _set_preview_integer_property(obj, "IntersectionSharedBoundaryGraphSegmentCount", len(shapes))
    try:
        vobj = getattr(obj, "ViewObject", None)
        if vobj is not None:
            vobj.Visibility = True
            if kind == "internal_seam":
                vobj.ShapeColor = (1.0, 0.8, 0.05)
                vobj.LineColor = (1.0, 0.8, 0.05)
                vobj.PointColor = (1.0, 0.8, 0.05)
                vobj.LineWidth = 8.0
                vobj.PointSize = 6.0
            else:
                vobj.ShapeColor = (0.0, 0.95, 1.0)
                vobj.LineColor = (0.0, 0.95, 1.0)
                vobj.PointColor = (0.0, 0.95, 1.0)
                vobj.LineWidth = 13.0
                vobj.PointSize = 8.0
    except Exception:
        pass
    try:
        from freecad.Corridor_Road.objects.obj_project import route_to_v1_tree

        route_to_v1_tree(find_project(document), obj)
    except Exception:
        pass
    try:
        document.recompute()
    except Exception:
        pass
    return obj


def _create_shared_breakline_highlight(
    *,
    document=None,
    source_obj=None,
    rows: list[dict[str, object]] | None = None,
    role_filter: str = "",
    material_filter: str = "",
    consumer_filter: str = "",
    clip_to_source_bounds: bool = False,
):
    if document is None:
        return None
    try:
        import FreeCAD as AppModule
        import Part
    except Exception:
        return None
    shapes: list[object] = []
    refs: list[str] = []
    z_lift = 0.02
    for row in list(rows or []):
        try:
            start = tuple(float(value) for value in row.get("start", ()))
            end = tuple(float(value) for value in row.get("end", ()))
            if len(start) != 3 or len(end) != 3:
                continue
            start_vec = AppModule.Vector(start[0], start[1], start[2] + z_lift)
            end_vec = AppModule.Vector(end[0], end[1], end[2] + z_lift)
            shapes.append(Part.makeLine(start_vec, end_vec))
            refs.append(str(row.get("breakline_id", "") or ""))
        except Exception:
            continue
    if not shapes:
        return None
    object_name = "ReviewSharedBreaklineHighlight"
    obj = document.getObject(object_name)
    if obj is None:
        obj = document.addObject("Part::Feature", object_name)
    try:
        obj.Shape = Part.makeCompound(shapes) if len(shapes) > 1 else shapes[0]
        obj.Label = "Shared Breakline Highlight"
    except Exception:
        return obj
    _set_preview_property(obj, "CRRecordKind", "v1_shared_breakline_highlight")
    _set_preview_property(obj, "V1ObjectType", "ReviewDiagnostic")
    _set_preview_property(obj, "DiagnosticKind", "shared_breakline_highlight")
    _set_preview_property(obj, "SourceObject", str(getattr(source_obj, "Name", "") or ""))
    _set_preview_property(obj, "SourceObjectLabel", str(getattr(source_obj, "Label", "") or ""))
    _set_preview_property(obj, "SharedBreaklineResultId", str(getattr(source_obj, "SharedBreaklineResultId", "") or ""))
    _set_preview_property(obj, "SharedBreaklineAuditStatus", str(getattr(source_obj, "SharedBreaklineAuditStatus", "") or ""))
    _set_preview_property(obj, "SharedBreaklineRoleFilter", str(role_filter or ""))
    _set_preview_property(obj, "SharedBreaklineMaterialFilter", str(material_filter or ""))
    _set_preview_property(obj, "SharedBreaklineConsumerFilter", str(consumer_filter or ""))
    _set_preview_property(obj, "SharedBreaklineClipToSourceBounds", "Yes" if bool(clip_to_source_bounds) else "No")
    _set_preview_string_list_property(obj, "SharedBreaklineRefs", _unique_text_values(refs))
    _set_preview_integer_property(obj, "SharedBreaklineSegmentCount", len(shapes))
    highlight_color = _shared_breakline_highlight_color(role_filter=role_filter, material_filter=material_filter)
    _set_preview_property(
        obj,
        "SharedBreaklineHighlightColor",
        ",".join(f"{float(value):.3f}" for value in highlight_color),
    )
    try:
        vobj = getattr(obj, "ViewObject", None)
        if vobj is not None:
            vobj.Visibility = True
            vobj.ShapeColor = highlight_color
            vobj.LineColor = highlight_color
            vobj.PointColor = highlight_color
            vobj.LineWidth = 11.0
            vobj.PointSize = 6.0
    except Exception:
        pass
    try:
        from freecad.Corridor_Road.objects.obj_project import route_to_v1_tree

        route_to_v1_tree(find_project(document), obj)
    except Exception:
        pass
    try:
        document.recompute()
    except Exception:
        pass
    return obj


def _shared_breakline_highlight_color(*, role_filter: str = "", material_filter: str = "") -> tuple[float, float, float]:
    material = str(material_filter or "").strip().lower()
    role = str(role_filter or "").strip().lower()
    if role in {"lane_to_lane", "lane-to-lane"}:
        return (1.00, 0.88, 0.05)
    if role in {"lane_to_shoulder", "lane-to-shoulder", "shoulder_edge", "shoulder-edge"}:
        return (0.65, 1.00, 0.35)
    if role in {"shoulder_to_side_slope", "shoulder-to-side-slope", "side_slope_to_daylight", "side-slope-to-daylight"}:
        return (0.05, 0.95, 0.25)
    if role in {"corridor_gutter_handoff", "corridor-gutter-handoff", "corridor_ditch_handoff", "corridor-ditch-handoff"}:
        return (0.10, 0.55, 1.00)
    if material in {"pavement", "design_surface"}:
        return (1.00, 0.88, 0.05)
    if material == "shoulder":
        return (0.65, 1.00, 0.35)
    if material in {"side_slope", "slope_face_surface"}:
        return (0.05, 0.95, 0.25)
    if material == "drainage_surface" or "gutter" in role or "ditch" in role:
        return (0.10, 0.55, 1.00)
    if material == "curb_return" or "curb_return" in role or "curb-return" in role:
        return (1.00, 0.52, 0.05)
    if "patch_to_design" in role or "patch-to-design" in role:
        return (1.00, 0.88, 0.05)
    if "patch_to_slope_face" in role or "patch-to-slope-face" in role:
        return (0.05, 0.95, 0.25)
    return (0.00, 0.95, 1.00)


def _attach_shared_breakline_audit_preview_metadata(obj, audit) -> None:
    if obj is None or audit is None:
        return
    presentation = SharedBreaklineAuditPresentationMapper().map(audit)
    _set_preview_property(obj, "SharedBreaklineAuditStatus", presentation.status)
    _set_preview_integer_property(obj, "SharedBreaklineMissingConsumerCount", presentation.missing_consumer_count)
